#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

// Define DataPacket structure
typedef struct {
    int packet_id;
    time_t timestamp;
    size_t data_size;
} DataPacket;

// Define DataPool structure
typedef struct {
    DataPacket *packets;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DataPool;

// Initialize DataPool
void dp_init(DataPool *pool, size_t initial_capacity) {
    pool->capacity = initial_capacity;
    pool->size = 0;
    pool->packets = (DataPacket *)malloc(initial_capacity * sizeof(DataPacket));
    if (!pool->packets) {
        perror("Failed to allocate memory for DataPool");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&pool->mutex, NULL);
}

// Resize DataPool
void dp_resize(DataPool *pool, size_t new_capacity) {
    DataPacket *new_packets = (DataPacket *)realloc(pool->packets, new_capacity * sizeof(DataPacket));
    if (!new_packets) {
        perror("Failed to resize DataPool");
        exit(EXIT_FAILURE);
    }
    pool->packets = new_packets;
    pool->capacity = new_capacity;
}

// Add packet to DataPool
void dp_add_packet(DataPool *pool, int packet_id, time_t timestamp, size_t data_size) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->size == pool->capacity) {
        dp_resize(pool, pool->capacity * 2);
    }
    pool->packets[pool->size].packet_id = packet_id;
    pool->packets[pool->size].timestamp = timestamp;
    pool->packets[pool->size].data_size = data_size;
    pool->size++;
    pthread_mutex_unlock(&pool->mutex);
}

// Retrieve packet from DataPool
DataPacket *dp_get_packet(DataPool *pool, int packet_id) {
    for (size_t i = 0; i < pool->size; i++) {
        if (pool->packets[i].packet_id == packet_id) {
            return &pool->packets[i];
        }
    }
    return NULL;
}

// Clean up DataPool
void dp_cleanup(DataPool *pool) {
    pthread_mutex_lock(&pool->mutex);
    free(pool->packets);
    pool->packets = NULL;
    pool->capacity = 0;
    pool->size = 0;
    pthread_mutex_unlock(&pool->mutex);
    pthread_mutex_destroy(&pool->mutex);
}

// Example usage
int main() {
    DataPool pool;
    dp_init(&pool, 10);

    // Simulate adding packets from REST API
    for (int i = 0; i < 20; i++) {
        dp_add_packet(&pool, i, time(NULL), i * 100);
    }

    // Retrieve and print a packet
    DataPacket *packet = dp_get_packet(&pool, 5);
    if (packet) {
        printf("Packet found: ID=%d, Timestamp=%ld, Size=%zu\n", packet->packet_id, packet->timestamp, packet->data_size);
    } else {
        printf("Packet not found\n");
    }

    dp_cleanup(&pool);
    return 0;
}
