    printf(".SH SYNOPSIS\nprogram [-h] [-m] [-i <input_file>] [-o <output_file>]\n");
    printf(".SH DESCRIPTION\nFetches configuration settings from the external REST API and processes input files.\n");
    printf(".SH OPTIONS\n");
    printf(".TP\n-h, --help\tDisplay this help message\n");
    printf(".TP\n-m, --man-page\tGenerate man page for this program\n");
    printf(".TP\n-i <input_file>, --input-file=<input_file>\tSpecify input file to process\n");
    printf(".TP\n-o <output_file>, --output-file=<output_file>\tSpecify output file for processed data\n");
}

void fetch_data_async(ProgramOptions* options, void (*callback)(const char*)) {
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, API_URL);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, (void*)callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, options->output_file);
        res = curl_easy_perform(curl);
        if(res != CURLE_OK)
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
}

void process_data(ProgramOptions* options) {
    // Implement data processing logic here
}

int main(int argc, char *argv[]) {
    ProgramOptions options = {NULL, DEFAULT_OUTPUT, 0, 0};

    int opt;
    while ((opt = getopt(argc, argv, "hmi:o:")) != -1) {
        switch (opt) {
            case 'h':
                options.show_usage = 1;
                break;
            case 'm':
                options.generate_man_page = 1;
                break;
            case 'i':
                options.input_file = optarg;
                break;
            case 'o':
                options.output_file = optarg;
                break;
