#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_LOG_SIZE 1024

typedef enum {
    LOG_DEBUG,
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR
} LogLevel;

typedef struct {
    char message[MAX_LOG_SIZE];
    LogLevel level;
} LogEntry;

typedef struct {
    FILE *file;
    pthread_mutex_t lock;
    char *log_file_path;
} Logger;

Logger logger;

void init_logger(const char *log_file_path) {
    logger.file = fopen(log_file_path, "a");
    if (!logger.file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&logger.lock, NULL);
}

void destroy_logger() {
    fclose(logger.file);
    pthread_mutex_destroy(&logger.lock);
}

void write_log(const LogEntry *entry) {
    pthread_mutex_lock(&logger.lock);
    fprintf(logger.file, "[%s] %s\n", 
            entry->level == LOG_DEBUG ? "DEBUG" : 
            entry->level == LOG_INFO  ? "INFO"  : 
            entry->level == LOG_WARNING ? "WARNING" : "ERROR",
            entry->message);
    fflush(logger.file);
    pthread_mutex_unlock(&logger.lock);
}

void *log_thread(void *arg) {
    char buffer[MAX_LOG_SIZE];
    while (1) {
        // Read from shared log queue
        // For simplicity, we assume a blocking read here
        fgets(buffer, MAX_LOG_SIZE, stdin);

        LogEntry entry;
        memset(&entry, 0, sizeof(LogEntry));
        strcpy(entry.message, buffer);
        entry.level = LOG_INFO; // Default log level

        write_log(&entry);
    }
    return NULL;
}

int main() {
    init_logger("app.log");

    pthread_t log_thread_id;
    pthread_create(&log_thread_id, NULL, log_thread, NULL);

    // Simulate concurrent logging
    for (int i = 0; i < 10; i++) {
        LogEntry entry;
        memset(&entry, 0, sizeof(LogEntry));
        snprintf(entry.message, MAX_LOG_SIZE, "Log entry %d", i);
        entry.level = LOG_INFO;

        write_log(&entry);
    }

    pthread_join(log_thread_id, NULL);

    destroy_logger();
    return 0;
}
```

