#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <pthread.h>
#include <arpa/inet.h>

// Define constants for file descriptors and buffer sizes
#define MAX_FD 1024
#define BUFFER_SIZE 1024

// Structure to hold data related to a single file descriptor
typedef struct {
    int fd;
    pthread_mutex_t lock;
} FileDescriptor;

// Function to read integers from a file descriptor and update the largest integer found
void* process_file(void* arg) {
    FileDescriptor* fd_info = (FileDescriptor*)arg;
    int buffer[BUFFER_SIZE];
    ssize_t bytes_read;
    int largest = INT_MIN;

    while ((bytes_read = read(fd_info->fd, buffer, sizeof(buffer))) > 0) {
        for (ssize_t i = 0; i < bytes_read / sizeof(int); i++) {
            pthread_mutex_lock(&fd_info->lock);
            if (buffer[i] > largest) {
                largest = buffer[i];
            }
            pthread_mutex_unlock(&fd_info->lock);
        }
    }

    // Report the largest integer found
    printf("Largest integer in fd %d: %d\n", fd_info->fd, largest);

    return NULL;
}

// Function to connect to an external data processing service
int connect_to_service(const char* host, int port) {
    struct sockaddr_in server_addr;
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("Socket creation failed");
        return -1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);

    if (inet_pton(AF_INET, host, &server_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sock);
        return -1;
    }

    if (connect(sock, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("Connection failed");
        close(sock);
        return -1;
    }

    return sock;
}

// Function to send data to the external service
int send_to_service(int sockfd, const char* data, size_t length) {
    ssize_t bytes_sent = send(sockfd, data, length, 0);
    if (bytes_sent < 0) {
        perror("Send failed");
        return -1;
    }
    return 0;
}

// Function to receive data from the external service
int receive_from_service(int sockfd, char* buffer, size_t max_length) {
    ssize_t bytes_received = recv(sockfd, buffer, max_length, 0);
    if (bytes_received < 0) {
        perror("Receive failed");
        return -1;
    }
    return bytes_received;
}

// Main function to demonstrate the library's usage
int main() {
    FileDescriptor fd_list[MAX_FD];
    pthread_t threads[MAX_FD];
    int service_sock = connect_to_service("service_host", 12345);

    if (service_sock < 0) {
        fprintf(stderr, "Failed to connect to external service\n");
        return EXIT_FAILURE;
    }

    // Initialize file descriptors and start processing in separate threads
    for (int i = 0; i < MAX_FD; i++) {
        fd_list[i].fd = open("file%d.txt", i); // Replace with actual file opening logic
        if (fd_list[i].fd < 0) {
            fprintf(stderr, "Failed to open file descriptor %d\n", i);
            return EXIT_FAILURE;
        }
        pthread_mutex_init(&fd_list[i].lock, NULL);
        pthread_create(&threads[i], NULL, process_file, &fd_list[i]);
    }

    // Join threads and clean up
    for (int i = 0; i < MAX_FD; i++) {
        pthread_join(threads[i], NULL);
        close(fd_list[i].fd);
        pthread_mutex_destroy(&fd_list[i].lock);
    }

    close(service_sock);

    return EXIT_SUCCESS;
}
