#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <json-c/json.h>

#define MAX_LOG_QUEUE_SIZE 1024
#define DEFAULT_LOG_LEVEL "INFO"
#define DEFAULT_LOG_DESTINATION "LOCAL"

typedef enum {
    LOG_LOCAL,
    LOG_EXTERNAL
} LogDestination;

typedef struct {
    char *message;
    char *level;
    char *timestamp;
} LogMessage;

typedef struct {
    pthread_mutex_t queue_lock;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
    LogMessage queue[MAX_LOG_QUEUE_SIZE];
    int front, rear;
    int count;
} LogQueue;

typedef struct {
    LogDestination destination;
    union {
        FILE *local_file;
        int external_socket;
    } data;
} LogConfig;

LogQueue log_queue;
pthread_mutex_t logging_lock;
LogConfig current_config;

void initialize_log_queue() {
    pthread_mutex_init(&log_queue.queue_lock, NULL);
    pthread_cond_init(&log_queue.not_full, NULL);
    pthread_cond_init(&log_queue.not_empty, NULL);
    log_queue.front = 0;
    log_queue.rear = -1;
    log_queue.count = 0;
}

void initialize_logging() {
    pthread_mutex_init(&logging_lock, NULL);
    current_config.destination = LOG_LOCAL;
    current_config.data.local_file = fopen("app.log", "a");
    initialize_log_queue();
}

void enqueue_log_message(LogMessage *message) {
    pthread_mutex_lock(&log_queue.queue_lock);
    while (log_queue.count == MAX_LOG_QUEUE_SIZE) {
        pthread_cond_wait(&log_queue.not_full, &log_queue.queue_lock);
    }
    log_queue.rear = (log_queue.rear + 1) % MAX_LOG_QUEUE_SIZE;
    log_queue.queue[log_queue.rear] = *message;
    log_queue.count++;
    pthread_cond_signal(&log_queue.not_empty);
    pthread_mutex_unlock(&log_queue.queue_lock);
}

void dequeue_log_message(LogMessage *message) {
    pthread_mutex_lock(&log_queue.queue_lock);
    while (log_queue.count == 0) {
        pthread_cond_wait(&log_queue.not_empty, &log_queue.queue_lock);
    }
    *message = log_queue.queue[log_queue.front];
    log_queue.front = (log_queue.front + 1) % MAX_LOG_QUEUE_SIZE;
    log_queue.count--;
    pthread_cond_signal(&log_queue.not_full);
    pthread_mutex_unlock(&log_queue.queue_lock);
}

void log_message(const char *level, const char *message) {
    LogMessage log_msg;
    log_msg.level = strdup(level);
    log_msg.message = strdup(message);
    log_msg.timestamp = strdup("2023-04-10T12:34:56Z"); // TODO: Get current timestamp

    pthread_mutex_lock(&logging_lock);
    enqueue_log_message(&log_msg);
    pthread_mutex_unlock(&logging_lock);

    if (current_config.destination == LOG_EXTERNAL) {
        send_external_log(log_msg);
    } else {
        local_log(log_msg);
    }
}

void *log_worker(void *arg) {
    LogMessage message;
    while (1) {
        dequeue_log_message(&message);
        if (current_config.destination == LOG_EXTERNAL) {
            send_external_log(message);
        } else {
            local_log(message);
        }
        free(message.level);
        free(message.message);
        free(message.timestamp);
    }
    return NULL;
}

void start_logging_worker() {
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, log_worker, NULL);
}

void set_log_destination(LogDestination destination) {
    current_config.destination = destination;
}

void set_local_log_file(const char *filename) {
    if (current_config.data.local_file != stdout && current_config.data.local_file != stderr) {
        fclose(current_config.data.local_file);
    }
    current_config.data.local_file = fopen(filename, "a");
}

void send_external_log(LogMessage message) {
    // TODO: Implement external logging using socket or other method
}

void local_log(LogMessage message) {
    fprintf(current_config.data.local_file, "[%s] [%s] %s\n", message.timestamp, message.level, message.message);
    fflush(current_config.data.local_file);
}

int main() {
    initialize_logging();
    start_logging_worker();

    log_message("INFO", "Application started");
    sleep(10);
    log_message("ERROR", "An error occurred");

    return 0;
}
