#include <openssl/evp.h>
#include <openssl/kdf.h>
#include <aws/kms/kms_client.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    const EVP_CIPHER *cipher;
    unsigned char key[32];
    unsigned char iv[16];
} CryptoContext;

CryptoContext* create_crypto_context(const char *key_id, int cipher_type) {
    CryptoContext *ctx = (CryptoContext*)malloc(sizeof(CryptoContext));
    ctx->ctx = EVP_CIPHER_CTX_new();
    // Initialize key and IV from secure storage
    if (!AWS_KMS_GetKey(key_id, ctx->key, sizeof(ctx->key))) {
        free(ctx);
        return NULL;
    }
    switch (cipher_type) {
        case 0: // DES ECB
            ctx->cipher = EVP_des_ecb();
            break;
        case 1: // AES CBC
            ctx->cipher = EVP_aes_256_cbc();
            break;
        default:
            free(ctx);
            return NULL;
    }
    return ctx;
}

void encrypt_data(CryptoContext *ctx, unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext) {
    if (!EVP_EncryptInit_ex(ctx->ctx, ctx->cipher, NULL, ctx->key, ctx->iv)) {
        // Handle error
    }
    EVP_EncryptUpdate(ctx->ctx, ciphertext, &ciphertext_len, plaintext, plaintext_len);
    EVP_EncryptFinal_ex(ctx->ctx, ciphertext + ciphertext_len, &ciphertext_len);
}

void decrypt_data(CryptoContext *ctx, unsigned char *ciphertext, int ciphertext_len, unsigned char *plaintext) {
    if (!EVP_DecryptInit_ex(ctx->ctx, ctx->cipher, NULL, ctx->key, ctx->iv)) {
        // Handle error
    }
    EVP_DecryptUpdate(ctx->ctx, plaintext, &plaintext_len, ciphertext, ciphertext_len);
    EVP_DecryptFinal_ex(ctx->ctx, plaintext + plaintext_len, &plaintext_len);
}

void free_crypto_context(CryptoContext *ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx);
}
