public class PokemonWeaknessEvaluator {
    private static final String API_URL = "https://api.pokemon.com/v2/pokemon/";
    private static final int MAX_RETRIES = 5;
    private static final Duration RETRY_DELAY = Duration.ofMillis(100);
    private static final long CACHE_DURATION = TimeUnit.MINUTES.toMillis(10);
    private static final HttpClient HTTP_CLIENT = HttpClient.newBuilder().build();
    private static final ConcurrentHashMap<String, PokemonData> cache = new ConcurrentHashMap<>();

    public String getWeaknesses(String pokemonName) {
        try {
            return getCachedPokemonData(pokemonName).orElseGet(() -> fetchPokemonData(pokemonName));
        } catch (IOException | InterruptedException e) {
            // Handle exceptions and fallback logic
            return "Unknown";
        }
    }

    private Optional<PokemonData> getCachedPokemonData(String pokemonName) {
        return Optional.ofNullable(cache.get(pokemonName))
                .filter(data -> data.expiryTime > System.currentTimeMillis());
    }

    private String fetchPokemonData(String pokemonName) throws IOException, InterruptedException {
        for (int i = 0; i < MAX_RETRIES; i++) {
            try {
                HttpResponse<String> response = HTTP_CLIENT.send(HttpRequest.newBuilder()
                        .uri(URI.create(API_URL + pokemonName))
                        .timeout(Duration.ofSeconds(5))
                        .build(), HttpResponse.BodyHandlers.ofString());

                if (response.statusCode() == 200) {
                    PokemonData data = parseResponse(response.body());
                    cache.put(pokemonName, new PokemonData(data.name, data.types, System.currentTimeMillis() + CACHE_DURATION));
                    return evaluateWeaknesses(data);
                } else {
                    Thread.sleep(RETRY_DELAY.toMillis() * (1 << i));
                }
            } catch (IOException | InterruptedException e) {
                // Handle exceptions and retry
            }
        }
        // Fallback logic in case of all retries failing
        return "Unknown";
    }

    private PokemonData parseResponse(String responseBody) {
        // Parse JSON response and extract necessary data
        return new PokemonData("Pikachu", List.of("Electric"));
    }

    private String evaluateWeaknesses(PokemonData data) {
        // Evaluate weaknesses based on the data
        return "Water";
    }

