import threading
import time
import json
from pika import BlockingConnection, ConnectionParameters

class SemaphoreManager:
    def __init__(self, config_file):
        self.semaphores = {}
        with open(config_file, 'r') as file:
            config = json.load(file)
            for key, value in config.items():
                self.semaphores[key] = threading.Semaphore(value)

    def acquire(self, resource):
        if resource not in self.semaphores:
            raise ValueError(f"Resource '{resource}' not found")
        self.semaphores[resource].acquire()

    def release(self, resource):
        if resource not in self.semaphores:
            raise ValueError(f"Resource '{resource}' not found")
        self.semaphores[resource].release()

class MessageBrokerClient:
    def __init__(self, host='localhost', port=5672, username='guest', password='guest'):
        self.connection = BlockingConnection(ConnectionParameters(host, port, username, password))
        self.channel = self.connection.channel()
        self.channel.queue_declare(queue='file_transfer_queue')

    def send_message(self, message):
        try:
            self.channel.basic_publish(exchange='',
                                      routing_key='file_transfer_queue',
                                      body=message)
        except Exception as e:
            print(f"Error sending message: {e}")
            # Fallback mechanism
            self.reconnect()

    def reconnect(self):
        try:
            self.connection.close()
            self.connection = BlockingConnection(ConnectionParameters('localhost', 5672, 'guest', 'guest'))
            self.channel = self.connection.channel()
            self.channel.queue_declare(queue='file_transfer_queue')
        except Exception as e:
            print(f"Failed to reconnect: {e}")

class FileTransferSystem:
    def __init__(self, config_file):
        self.semaphore_manager = SemaphoreManager(config_file)
        self.broker_client = MessageBrokerClient()

    def produce(self, resource, message):
        try:
            self.semaphore_manager.acquire(resource)
            self.broker_client.send_message(message)
        finally:
            self.semaphore_manager.release(resource)

if __name__ == "__main__":
    system = FileTransferSystem('config.json')
    for i in range(10):
        threading.Thread(target=system.produce, args=('resource1', f"Message {i}")).start()

```

This code provides a basic framework for a semaphore-based concurrency control system integrated with an existing message broker service. The `SemaphoreManager` class manages semaphores based on configuration, the `MessageBrokerClient` class handles communication with the message broker, and the `FileTransferSystem` class integrates these components to control access to shared resources and send messages. Error handling is implemented for message sending failures with a fallback mechanism to reconnect to the broker.']

