// Main CLI tool entry point
fn main() -> io::Result<()> {
    // Setup command line arguments
    let matches = App::new("LLVM IR Generator")
        .arg(Arg::with_name("input")
             .short('i')
             .long("input")
             .value_name("FILE")
             .takes_value(true)
             .required(true))
        .arg(Arg::with_name("output")
             .short('o')
             .long("output")
             .value_name("FILE")
             .takes_value(true))
        .get_matches();

    // Read input file
    let mut file = File::open(matches.value_of("input").unwrap())?;
    let mut contents = String::new();
    file.read_to_string(&mut contents)?;

    // Parse grammar and generate IR
    let parsed_code = parse_grammar(&matches.value_of("input").unwrap())?;
    let ir_code = generate_ir(&parsed_code);

    // Store IR in database
    let db_connection = Arc::new(Mutex::new(Database::new()));
    thread::spawn(move || {
        store_in_database(ir_code.clone(), db_connection.clone());
    });

    // Write output file
    if let Some(output_file) = matches.value_of("output") {
        let mut file = File::create(output_file)?;
        file.write_all(ir_code.as_bytes())?;
    }

    Ok(())
}

