#include <forward_list>
#include <string>
#include <mutex>
#include <unordered_set>

class ILoggingService {
public:
    virtual void logAsync(const std::string& message) = 0;
};

void insertAfterOrLog(std::forward_list<std::string>& lst, const std::string& target, const std::string& value, ILoggingService& logger) {
    static std::mutex cacheMutex;
    static std::unordered_set<std::string> cache;

    std::lock_guard<std::mutex> lock(cacheMutex);

    auto it = std::find_if(lst.begin(), lst.end(), [&target](const std::string& s) {
        return cache.count(s) > 0 || s == target;
    });

    if (it != lst.end()) {
        if (!cache.count(*it)) {
            cache.insert(*it);
        }
        lst.insert_after(it, value);
    } else {
        logger.logAsync("Target string not found, appending to the end.");
        lst.push_back(value);
    }
}
