namespace RandomGenerator {
    class MersenneTwister {
    public:
        explicit MersenneTwister(unsigned long seed) : rng(seed), lock() {}

        ~MersenneTwister() = default;

        static std::mt19937 global_rng;

        unsigned long GetNextValue() {
            std::lock_guard<std::mutex> guard(lock);
            return global_rng();
        }

    private:
        std::mt19937 rng;
        static std::mutex lock;
    };

    std::mt19937 MersenneTwister::global_rng = std::mt19937(0); // Initialize with a default seed
}

// Example usage in a microservice
#include <iostream>
#include <thread>
#include <vector>

void GenerateRandomNumbers() {
    RandomGenerator::MersenneTwister rng(std::random_device{}());
    for (int i = 0; i < 10; ++i) {
        std::cout << rng.GetNextValue() << " ";
    }
    std::cout << std::endl;
}

int main() {
    const int numThreads = 4;
    std::vector<std::thread> threads;

    for (int i = 0; i < numThreads; ++i) {
        threads.emplace_back(GenerateRandomNumbers);
    }

    for (auto& thread : threads) {
        thread.join();
    }

    return 0;
}
