    public async Task<DataTable> ExecuteDynamicQueryAsync(string dynamicSql, List<KeyValuePair<string, object>> parameters, string connectionString, QuerySettings settings)
    {
        ValidateConnectionString(connectionString);
        var sqlCommand = BuildSqlCommand(dynamicSql, parameters);

        using (var connection = new SqlConnection(connectionString))
        {
            await connection.OpenAsync();
            if (settings.EnableCaching && IsCacheValid(settings.CacheKey))
            {
                return GetCachedResult(settings.CacheKey);
            }

            using (var command = connection.CreateCommand())
            {
                command.CommandText = sqlCommand;
                command.CommandType = CommandType.Text;

                if (parameters != null)
                {
                    foreach (var param in parameters)
                    {
                        command.Parameters.AddWithValue(param.Key, param.Value);
                    }
                }

                var dataTable = new DataTable();
                using (var reader = await command.ExecuteReaderAsync())
                {
                    dataTable.Load(reader);
                    if (settings.EnableCaching)
