        _logger = logger;
    }

    public async Task<WeatherData> GetWeatherAsync(string location)
    {
        var cacheKey = $"weather_{location}";
        if (_cache.TryGetValue(cacheKey, out WeatherData weather))
        {
            return weather;
        }

        try
        {
            var response = await _httpClient.GetAsync($"https://api.weatherapi.com/v1/current.json?key=YOUR_API_KEY&q={location}");
            response.EnsureSuccessStatusCode();
            var content = await response.Content.ReadAsStringAsync();
            weather = JsonConvert.DeserializeObject<WeatherData>(content);
            _cache.Set(cacheKey, weather, new MemoryCacheEntryOptions
            {
                AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(10)
            });
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to fetch weather data for location: {Location}", location);
            throw;
        }

        return weather;
    }
}

public class WeatherData
{
    public string Location { get; set; }
    public double TemperatureC { get; set; }
    public double Humidity { get; set; }
    // Add other relevant properties as needed
}
