from flask import Flask, request, jsonify
from sqlalchemy import create_engine, Column, Integer, String
from sqlalchemy.ext.declarative import declarative_base
from sqlalchemy.orm import sessionmaker
from functools import wraps
import time

app = Flask(__name__)
Base = declarative_base()
engine = create_engine('sqlite:///resources.db')
Session = sessionmaker(bind=engine)
session = Session()

class Resource(Base):
    __tablename__ = 'resources'
    id = Column(Integer, primary_key=True)
    name = Column(String)

Base.metadata.create_all(engine)

def rate_limiter(limit=10, period=60):
    def decorator(func):
        func.calls = 0
        func.last_reset = time.time()
        @wraps(func)
        def wrapper(*args, **kwargs):
            current_time = time.time()
            if current_time - func.last_reset >= period:
                func.calls = 1
                func.last_reset = current_time
            else:
                func.calls += 1
                if func.calls > limit:
                    return jsonify({'error': 'Too many requests'}), 429
            return func(*args, **kwargs)
        return wrapper
    return decorator

@app.route('/resource/<int:resource_id>', methods=['PUT', 'DELETE'])
@rate_limiter()
def resource_endpoint(resource_id):
    if request.method == 'PUT':
        data = request.get_json()
        try:
            new_resource = Resource(id=resource_id, name=data['name'])
            session.query(Resource).filter_by(id=resource_id).update({'name': data['name']}, synchronize_session=False)
            session.commit()
            return jsonify({'message': 'Resource updated successfully'}), 200
        except Exception as e:
            session.rollback()
            return jsonify({'error': str(e)}), 500

    elif request.method == 'DELETE':
        try:
            session.query(Resource).filter_by(id=resource_id).delete(synchronize_session=False)
            session.commit()
            return jsonify({'message': 'Resource deleted successfully'}), 200
        except Exception as e:
            session.rollback()
            return jsonify({'error': str(e)}), 500

if __name__ == '__main__':
    app.run(ssl_context='adhoc')
```

This code provides a basic implementation of the described web API endpoint using Flask, SQLAlchemy, and SQLite. It includes rate limiting, error handling, and secure communication with HTTPS. The resource cleanup and feedback to users are minimal in this example but can be expanded based on specific requirements."]

