            return Response.status(Response.Status.BAD_REQUEST).entity(new ErrorResponse("Name and email are required")).build();
        }

        CircuitBreaker.decorateSupplier(circuitBreaker, () -> verifyUserPermissions(id, request.getUserToken())).join();

        User user = userRepository.findById(id);
