const fs = require('fs');
const path = require('path');
const axios = require('axios');
const Bull = require('bull');

// Configuration
const directoryToMonitor = '/path/to/directory';
const loggingServiceUrl = 'https://logging-service.example.com/log';
const queueName = 'fileChangeLogs';

// Create a Bull queue for log events
const fileChangeQueue = new Bull(queueName, {
  redis: {
    host: 'localhost',
    port: 6379,
  },
});

// Function to handle file system events
function handleFileEvent(eventType, filePath) {
  const logData = {
    eventType,
    filePath,
    timestamp: new Date().toISOString(),
  };

  // Add event to the queue for logging
  fileChangeQueue.add(logData);
}

// Watch directory for changes
fs.watch(directoryToMonitor, { persistent: true }, (eventType, filename) => {
  if (filename) {
    const fullPath = path.join(directoryToMonitor, filename);
    handleFileEvent(eventType, fullPath);
  }
});

// Process events in the queue and send to logging service
fileChangeQueue.process(async ({ eventType, filePath }) => {
  try {
    await axios.post(loggingServiceUrl, { eventType, filePath });
    console.log(`Logged: ${eventType} - ${filePath}`);
  } catch (error) {
    if (error.response && error.response.status === 429) {
      // Rate limit exceeded, retry later
      fileChangeQueue.add({ eventType, filePath }, { delay: 1000 * 60 });
    } else {
      console.error('Failed to log event:', error);
      // Retry with exponential backoff
      const attempts = Math.min(5, (this.attemptsMade || 0) + 1);
      fileChangeQueue.add({ eventType, filePath }, { delay: 1000 * Math.pow(2, attempts) });
    }
  }
});

// Monitoring and recovery
fileChangeQueue.on('completed', () => {
  console.log('All events logged successfully.');
});

fileChangeQueue.on('failed', (job, err) => {
  console.error(`Failed to log event ${job.data.eventType} - ${job.data.filePath}:`, err);
  // Optionally requeue job with increased delay or notify admin
});

// Unit tests and integration tests should be added here
