async function runAsyncTests(modulePath, testCases, logger) {
    try {
        const module = await loadModule(modulePath);
        let blueslipState = null;

        for (const testCase of testCases) {
            if (testCase.priority > 0) {
                prioritizeTest(testCase);
            }

            try {
                const startTime = Date.now();
                const result = await executeTest(testCase, module, blueslipState);
                const duration = Date.now() - startTime;
                logTestResult(logger, testCase.name, 'pass', duration);
                if (result.shouldResetBlueslip) {
                    blueslipState = null;
                } else {
                    blueslipState = result.blueslipState;
                }
            } catch (error) {
                const duration = Date.now() - startTime;
                logTestResult(logger, testCase.name, 'fail', duration);
            }

            manageSharedResources(blueslipState);
        }

        handleConcurrency(config.concurrencyLevel);

    } catch (error) {
        handleError(error);
    }
}

