// Define the main function to render the footer with scripts
function renderWebPageFooter(scripts) {
    const scriptContainer = document.getElementById('script-container');
    const metadataCache = new Map();
    const apiBaseUrl = 'https://api.example.com/scripts/';

    // Helper function to safely execute a script
    async function executeScript(scriptId, scriptContent) {
        return new Promise((resolve, reject) => {
            try {
                eval(scriptContent);
                resolve();
            } catch (error) {
                console.error(`Error executing script ${scriptId}:`, error);
                resolve(); // Ignore errors for demonstration purposes
            }
        });
    }

    // Helper function to fetch metadata and cache results
    async function fetchMetadata(scriptId) {
        if (!metadataCache.has(scriptId)) {
            try {
                const response = await fetch(`${apiBaseUrl}${scriptId}`);
                if (response.ok) {
                    const metadata = await response.json();
                    metadataCache.set(scriptId, metadata);
                } else {
                    console.error(`Failed to fetch metadata for script ${scriptId}:`, response.status);
                }
            } catch (error) {
                console.error(`Error fetching metadata for script ${scriptId}:`, error);
            }
        }
    }

    // Function to render a single script
    async function renderScript(scriptId, scriptContent) {
        await fetchMetadata(scriptId); // Fetch metadata and cache
        const scriptElement = document.createElement('script');
        scriptElement.id = `dynamic-script-${scriptId}`;
        scriptElement.text = scriptContent;
        scriptContainer.appendChild(scriptElement);
        await executeScript(scriptId, scriptContent);
    }

    // Main logic to process all scripts concurrently
    async function renderAllScripts() {
        const scriptPromises = scripts.map(async (script) => renderScript(script.id, script.content));
        await Promise.all(scriptPromises);
    }

    return renderAllScripts();
}

// Example usage:
const sampleScripts = [
    { id: '1', content: 'console.log("Hello from script 1");' },
    { id: '2', content: 'alert("This is a test alert.");' }
];

renderWebPageFooter(sampleScripts).then(() => {
    console.log('All scripts rendered and executed.');
}).catch((error) => {
    console.error('Failed to render or execute scripts:', error);
});
```

