import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class IntegerSubsetProcessor {

    private UnionFind unionFind;
    private ExecutorService executorService;
    private int maxProcessingTimeMillis;

    public IntegerSubsetProcessor(int maxProcessingTimeMillis) {
        this.unionFind = new UnionFind();
        this.executorService = Executors.newCachedThreadPool();
        this.maxProcessingTimeMillis = maxProcessingTimeMillis;
    }

    public Map<Integer, Long> processBatch(String apiUrl, long timeoutMillis) throws Exception {
        // Fetch data from the external API
        int[] dataset = fetchDataFromApi(apiUrl, timeoutMillis);

        // Process the batch using Union-Find with a timeout check
        return executorService.submit(() -> {
            try (Timer timer = new Timer(maxProcessingTimeMillis)) {
                Map<Integer, Long> subsets = new HashMap<>();
                for (int num : dataset) {
                    unionFind.makeSet(num);
                    int root = unionFind.find(num);
                    if (!subsets.containsKey(root)) {
                        subsets.put(root, System.currentTimeMillis());
                    }
                }
                return subsets;
            } catch (TimeoutException e) {
                // Handle the timeout
                throw new RuntimeException("Subset check exceeded maximum processing time", e);
            }
        }).get();
    }

    private int[] fetchDataFromApi(String apiUrl, long timeoutMillis) throws Exception {
        // Placeholder for API call logic
        return new int[0]; // Replace with actual API call implementation
    }

    private class UnionFind {
        Map<Integer, Integer> parent = new HashMap<>();
        Map<Integer, Integer> rank = new HashMap<>();

        public void makeSet(int i) {
            parent.put(i, i);
            rank.put(i, 0);
        }

        public int find(int x) {
            if (parent.get(x) != x) {
                parent.put(x, find(parent.get(x)));
            }
            return parent.get(x);
        }

        public void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX == rootY) return;

            if (rank.get(rootX) > rank.get(rootY)) {
                parent.put(rootY, rootX);
            } else {
                parent.put(rootX, rootY);
                if (rank.get(rootX).equals(rank.get(rootY))) {
                    rank.put(rootY, rank.get(rootY) + 1);
                }
            }
        }
    }

    private static class Timer implements AutoCloseable {
        private final long maxTimeMillis;
        private final long startTime;

        public Timer(long maxTimeMillis) {
            this.maxTimeMillis = maxTimeMillis;
            this.startTime = System.currentTimeMillis();
        }

        @Override
        public void close() throws TimeoutException {
            if (System.currentTimeMillis() - startTime > maxTimeMillis) {
                throw new TimeoutException("Operation exceeded maximum time");
            }
        }
    }

    // Unit tests and other utility methods can be added here
}
