use reqwest::{Client, Error, Method};
use std::collections::HashMap;
use std::time::{Duration, Instant};

struct HttpClient {
    client: Client,
    api_limits: HashMap<String, ApiLimit>,
}

impl HttpClient {
    fn new() -> Self {
        HttpClient {
            client: Client::new(),
            api_limits: Default::default(),
        }
    }

    fn add_api_limit(&mut self, url: &str, limit: ApiLimit) {
        self.api_limits.insert(url.to_string(), limit);
    }

    async fn request(
        &self,
        method: Method,
        url: &str,
        body: Option<&str>,
    ) -> Result<String, Error> {
        let api_limit = self.api_limits.get(url).unwrap_or(&ApiLimit::default());
        if Instant::now() < api_limit.next_request_time {
            tokio::time::sleep(api_limit.backoff_duration()).await;
        }

        let response = match method {
            Method::GET => self.client.get(url).send().await?,
            Method::POST => self.client.post(url).body(body.unwrap_or("")).send().await?,
            _ => unimplemented!(),
        };

        api_limit.update(response.status(), Instant::now());
        if response.status() == 503 {
            return Err(Error::from_str("Service Unavailable"));
        }

        response.text().await
    }
}

struct ApiLimit {
    next_request_time: Instant,
    backoff_duration: Duration,
}

impl ApiLimit {
    fn default() -> Self {
        ApiLimit {
            next_request_time: Instant::now(),
            backoff_duration: Duration::from_secs(1),
        }
    }

    fn update(&mut self, status: reqwest::StatusCode, now: Instant) {
        if status.is_success() {
            self.next_request_time = now + Duration::from_secs(self.backoff_duration.as_secs());
        } else if status == 503 {
            let jitter = rand::random::<u64>() % self.backoff_duration.as_secs();
            self.backoff_duration *= 2;
            self.next_request_time = now + Duration::from_secs(self.backoff_duration.as_secs() + jitter);
        }
    }
}

#[tokio::main]
async fn main() {
    let mut client = HttpClient::new();
    client.add_api_limit("https://api.example.com/data", ApiLimit {
        backoff_duration: Duration::from_secs(2),
        ..Default::default()
    });

    match client.request(Method::GET, "https://api.example.com/data", None).await {
        Ok(response) => println!("Response: {}", response),
        Err(e) => eprintln!("Error: {:?}", e),
    }
}
```

This code provides a basic structure for an HTTP client library in Rust that supports GET and POST requests with rate limiting, retries, and logging. The `HttpClient` struct manages the API limits and makes requests using the `reqwest` crate. The `ApiLimit` struct handles rate limiting logic, including exponential backoff for 503 errors. The example demonstrates how to use the client to make a GET request and handle potential errors.']

