// C-based resource manager with POSIX semaphores

#include <stdio.h>
#include <stdlib.h>
#include <semaphore.h>

sem_t *sem;

void init_semaphore(int initial_value) {
    sem = sem_open("/clinic_semaphore", O_CREAT, 0644, initial_value);
    if (sem == SEM_FAILED) {
        perror("Failed to initialize semaphore");
        exit(EXIT_FAILURE);
    }
}

void acquire_semaphore() {
    if (sem_wait(sem) != 0) {
        perror("Failed to acquire semaphore");
        exit(EXIT_FAILURE);
    }
}

void release_semaphore() {
    if (sem_post(sem) != 0) {
        perror("Failed to release semaphore");
        exit(EXIT_FAILURE);
    }
}

void destroy_semaphore() {
    if (sem_close(sem) != 0) {
        perror("Failed to close semaphore");
        exit(EXIT_FAILURE);
    }
    if (sem_unlink("/clinic_semaphore") != 0) {
        perror("Failed to unlink semaphore");
        exit(EXIT_FAILURE);
    }
}
