<?php

header('Content-Type: application/json');

// PHP RESTful API endpoint for clinic status updates

use Psr\Http\Message\ResponseInterface as Response;
use Psr\Http\Message\ServerRequestInterface as Request;
use Slim\Factory\AppFactory;

require __DIR__ . '/vendor/autoload.php';

$app = AppFactory::create();

$app->post('/update_status', function (Request $request, Response $response) {
    $data = json_decode($request->getBody(), true);

    // Validate input data
    if (!isset($data['clinic_id']) || !isset($data['new_status']) || !isset($data['last_modified_ip']) || !isset($data['last_modified_date'])) {
        return $response->withJson(['error' => 'Invalid request data'], 400);
    }

    // Enforce business rules and check authorization
    if (!$this->isAuthorizedUser()) {
        return $response->withJson(['error' => 'Unauthorized access'], 403);
    }

    // Update clinic status in database
    try {
        $db = new PDO('mysql:host=localhost;dbname=clinics', 'username', 'password');
        $db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

        $stmt = $db->prepare("UPDATE clinics SET status = :status, last_modified_ip = :ip, last_modified_date = :date WHERE clinic_id = :id");
        $stmt->bindParam(':status', $data['new_status']);
        $stmt->bindParam(':ip', $data['last_modified_ip']);
        $stmt->bindParam(':date', $data['last_modified_date']);
        $stmt->bindParam(':id', $data['clinic_id']);

        if ($stmt->execute()) {
            return $response->withJson(['message' => 'Clinic status updated successfully'], 200);
        } else {
            return $response->withJson(['error' => 'Failed to update clinic status'], 500);
        }
    } catch (PDOException $e) {
        return $response->withJson(['error' => 'Database error: ' . $e->getMessage()], 500);
    }
});

$app->run();
?>
