// Database connection pooling and prepared statements

use PDO;

class ClinicDB {
    private static $instance = null;
    private $pdo;

    private function __construct() {
        $this->pdo = new PDO('mysql:host=localhost;dbname=clinics', 'username', 'password');
        $this->pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
    }

    public static function getInstance() {
        if (self::$instance === null) {
            self::$instance = new ClinicDB();
        }
        return self::$instance;
    }

    public function updateStatus($clinicId, $newStatus, $lastModifiedIP, $lastModifiedDate) {
        $stmt = $this->pdo->prepare("UPDATE clinics SET status = :status, last_modified_ip = :ip, last_modified_date = :date WHERE clinic_id = :id");
        $stmt->bindParam(':status', $newStatus);
        $stmt->bindParam(':ip', $lastModifiedIP);
        $stmt->bindParam(':date', $lastModifiedDate);
        $stmt->bindParam(':id', $clinicId);

        return $stmt->execute();
    }
}
