// Caching layer using APCu

use ApcuIterator;

function getClinicStatus($clinicId) {
    if (apcu_exists('clinic_' . $clinicId)) {
        return apcu_fetch('clinic_' . $clinicId);
    } else {
        $db = ClinicDB::getInstance();
        $status = $db->getClinicStatus($clinicId);

        if ($status !== false) {
            apcu_store('clinic_' . $clinicId, $status, 3600); // Cache for 1 hour
        }

        return $status;
    }
}

function updateClinicStatus($clinicId, $newStatus, $lastModifiedIP, $lastModifiedDate) {
    $db = ClinicDB::getInstance();
    $result = $db->updateStatus($clinicId, $newStatus, $lastModifiedIP, $lastModifiedDate);

    if ($result) {
        apcu_delete('clinic_' . $clinicId); // Invalidate cache
    }

    return $result;
}
?>
