CREATE PROCEDURE GetEmployeeDetailsBySupervisorID (
    @SupervisorID INT,
    @CityFilter NVARCHAR(100) = NULL,
    @RetryAttempts INT = 3,
    @RetryDelay INT = 5 -- in seconds
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @ErrorNumber INT;
    DECLARE @ErrorMessage NVARCHAR(2048);
    DECLARE @CurrentAttempt INT = 1;

    WHILE @CurrentAttempt <= @RetryAttempts
    BEGIN
        BEGIN TRY
            BEGIN TRANSACTION;

                SELECT 
                    e.Name,
                    e.City,
                    e.Address,
                    d.DepartmentName
                INTO #EmployeeDetails
                FROM Employees e
                JOIN Departments d ON e.DepartmentID = d.DepartmentID
                WHERE e.SupervisorID = @SupervisorID
                  AND (e.City IS NULL OR e.City LIKE '%' + @CityFilter + '%')
                  AND DATEDIFF(year, e.HireDate, GETDATE()) >= 1;

                SELECT 
                    COUNT(*) AS TotalRecords,
                    Name,
                    City,
                    Address,
                    DepartmentName
                FROM #EmployeeDetails
                ORDER BY Name;

            COMMIT TRANSACTION;
            BREAK; -- Exit the loop if successful
        END TRY
        BEGIN CATCH
            ROLLBACK TRANSACTION;
            SET @ErrorNumber = ERROR_NUMBER();
            SET @ErrorMessage = ERROR_MESSAGE();

            IF @CurrentAttempt < @RetryAttempts
            BEGIN
                WAITFOR DELAY '00:00:' + CAST(@RetryDelay AS NVARCHAR(2));
            END
            ELSE
            BEGIN
                RAISERROR (@ErrorMessage, @ErrorNumber, 1);
                BREAK; -- Exit the loop after all retries fail
            END
        END CATCH

        SET @CurrentAttempt = @CurrentAttempt + 1;
    END
END
