public class PasswordUpdateService {

    private static final String ENCRYPTION_ALGORITHM = "AES";
    private static final int KEY_SIZE = 256;
    private SecretKey secretKey;
    private Lock lock;

    public PasswordUpdateService() {
        initializeEncryptionKey();
        this.lock = new ReentrantLock();
    }

    private void initializeEncryptionKey() {
        try {
            KeyGenerator keyGen = KeyGenerator.getInstance(ENCRYPTION_ALGORITHM);
            keyGen.init(KEY_SIZE);
            secretKey = keyGen.generateKey();
        } catch (Exception e) {
            throw new RuntimeException("Failed to generate encryption key", e);
        }
    }

    public void updatePassword(String userId, String newPassword) {
        try {
            lock.lock();
            String encryptedPassword = encrypt(newPassword);
            updateInDatabase(userId, encryptedPassword);
            notifyExternalServices(userId, encryptedPassword);
        } catch (Exception e) {
            handleUpdateFailure(e);
        } finally {
            lock.unlock();
        }
    }

    private String encrypt(String data) throws Exception {
        Cipher cipher = Cipher.getInstance(ENCRYPTION_ALGORITHM);
        cipher.init(Cipher.ENCRYPT_MODE, secretKey);
        byte[] encryptedBytes = cipher.doFinal(data.getBytes());
        return Base64.getEncoder().encodeToString(encryptedBytes);
    }

