#include <stdexcept>

class Transaction {
    // Define the transaction structure here
};

class TransactionProcessor {
private:
    std::queue<std::shared_ptr<Transaction>> transactions;
    std::mutex queueMutex;
    std::condition_variable notEmpty;
    bool stopProcessing;

    void workerThread() {
        while (true) {
            std::unique_lock<std::mutex> lock(queueMutex);
            notEmpty.wait(lock, [this] { return !transactions.empty() || stopProcessing; });

            if (stopProcessing && transactions.empty()) {
                break;
            }

            auto transaction = transactions.front();
            transactions.pop();

            lock.unlock();

            try {
                // Deserialize the transaction
                // Apply filters and process the transaction
            } catch (const std::exception& e) {
                std::cerr << "Deserialization error: " << e.what() << std::endl;
                continue; // Fall back to default state without compromising ongoing processes
            }
        }
    }

public:
    TransactionProcessor(int numThreads = 4) : stopProcessing(false) {
        for (int i = 0; i < numThreads; ++i) {
            threads.emplace_back(&TransactionProcessor::workerThread, this);
        }
    }

    ~TransactionProcessor() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            stopProcessing = true;
        }
        notEmpty.notify_all();
        for (auto& thread : threads) {
            thread.join();
        }
    }

    void enqueue(const Transaction& transaction) {
        {
            std::lock_guard<std::mutex> lock(queueMutex);
            transactions.push(std::make_shared<Transaction>(transaction));
        }
        notEmpty.notify_one();
    }

    bool isProcessing() const {
        std::lock_guard<std::mutex> lock(queueMutex);
        return !transactions.empty() || !stopProcessing;
    }

private:
    std::vector<std::thread> threads;
};
