class Attack {
public:
    virtual void execute() = 0;
    virtual ~Attack() {}
};

class PhysicalAttack : public Attack {
public:
    void execute() override {
        std::cout << "Executing physical attack!" << std::endl;
    }
};

class MagicAttack : public Attack {
public:
    void execute() override {
        std::cout << "Executing magic attack!" << std::endl;
    }
};

class Character {
private:
    std::vector<std::unique_ptr<Attack>> attacks;
    std::vector<int> cooldowns;
    int currentHealth;
    std::mutex mtx;
    std::ofstream logFile;

public:
    Character() : currentHealth(100) {
        // Initialize attack types and cooldowns
        attacks.push_back(std::make_unique<PhysicalAttack>());
        attacks.push_back(std::make_unique<MagicAttack>());
        cooldowns = {5, 3}; // Cooldowns in turns

        logFile.open("attack_log.txt", std::ios::app);
    }

    ~Character() {
        logFile.close();
    }

    void executeAttack(int attackIndex) {
        std::lock_guard<std::mutex> lock(mtx);

        if (currentHealth <= 0) {
            std::cerr << "Character is out of health!" << std::endl;
            return;
        }

        if (turnsSinceLastAttack(attackIndex) < cooldowns[attackIndex]) {
            std::cout << "Cooldown for attack " << attackIndex << " not yet over." << std::endl;
            return;
        }

        attacks[attackIndex]->execute();
        logFile << "Attack " << attackIndex << " executed at turn " << currentTurn() << std::endl;

        // Simulate cooldown
        setCooldown(attackIndex);
    }

private:
    int currentTurn() {
        static int turn = 0;
        return ++turn;
    }

    void setCooldown(int attackIndex) {
        cooldowns[attackIndex] = cooldowns[attackIndex] * 2; // Increase cooldown for demonstration
    }

    int turnsSinceLastAttack(int attackIndex) {
        // Simulate logic to calculate turns since last attack
        return rand() % 5;
    }
};

int main() {
    srand(static_cast<unsigned int>(time(nullptr)));

    Character player;
    player.executeAttack(0); // Execute physical attack

    return 0;
}
