using System;
using System.Collections.Concurrent;
using System.Diagnostics;
using System.Net.Http;
using System.Threading.Tasks;

public class RandomValueGenerator
{
    private readonly ConcurrentDictionary<string, Range> _ranges = new ConcurrentDictionary<string, Range>();
    private readonly HttpClient _httpClient;
    private readonly ILogger _logger;

    public RandomValueGenerator(HttpClient httpClient, ILogger logger)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public void SetSeed(long seed)
    {
        Random.Shared = new Random(seed);
    }

    public int GetRandomInt(string rangeName, bool inclusive = false)
    {
        var range = _ranges.GetOrAdd(rangeName, r => LoadRangeFromExternalSource(r));
        if (range == null) throw new InvalidOperationException("Failed to load range from external source.");

        return inclusive
            ? Random.Shared.Next(range.MinValue, range.MaxValue + 1)
            : Random.Shared.Next(range.MinValue, range.MaxValue);
    }

    public float GetRandomFloat(string rangeName, bool inclusive = false)
    {
        var range = _ranges.GetOrAdd(rangeName, r => LoadRangeFromExternalSource(r));
        if (range == null) throw new InvalidOperationException("Failed to load range from external source.");

        return inclusive
            ? Random.Shared.Next((int)(range.MinValue * 100), (int)((range.MaxValue + 1) * 100)) / 100.0f
            : Random.Shared.Next((int)(range.MinValue * 100), (int)(range.MaxValue * 100)) / 100.0f;
    }

    public void UpdateRange(string rangeName, double minValue, double maxValue)
    {
        _ranges[rangeName] = new Range(minValue, maxValue);
    }

    private async Task<Range> LoadRangeFromExternalSource(string rangeName)
    {
        try
        {
            var response = await _httpClient.GetAsync($"https://api.example.com/range/{rangeName}");
            response.EnsureSuccessStatusCode();
            var rangeData = await response.Content.ReadAsStringAsync();

            // Parse the range data and create a new Range object
            var rangeParts = rangeData.Split(',');
            if (rangeParts.Length != 2)
                throw new FormatException("Invalid range format received from external source.");

            double minValue = double.Parse(rangeParts[0]);
            double maxValue = double.Parse(rangeParts[1]);

            return new Range(minValue, maxValue);
        }
        catch (HttpRequestException ex)
        {
            _logger.LogError(ex, "Failed to load range from external source.");
            throw;
        }
    }

    private class Range
    {
        public double MinValue { get; set; }
        public double MaxValue { get; set; }

        public Range(double minValue, double maxValue)
        {
            if (minValue >= maxValue) throw new ArgumentException("Min value must be less than max value.");

            MinValue = minValue;
            MaxValue = maxValue;
        }
    }

    // Add necessary interfaces and encapsulate complex logic
}
