#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>

// Define a structure to represent a resource bundle
typedef struct {
    char *data;
    size_t size;
} ResourceBundle;

// Function to load a resource from a file
ResourceBundle* load_resource(const char *file_path) {
    FILE *file = fopen(file_path, "rb");
    if (!file) return NULL;

    fseek(file, 0, SEEK_END);
    size_t size = ftell(file);
    fseek(file, 0, SEEK_SET);

    ResourceBundle *bundle = (ResourceBundle *)malloc(sizeof(ResourceBundle));
    bundle->data = malloc(size);
    fread(bundle->data, 1, size, file);
    fclose(file);

    bundle->size = size;
    return bundle;
}

// Function to free a resource
void free_resource(ResourceBundle *bundle) {
    if (!bundle) return;
    free(bundle->data);
    free(bundle);
}

int main() {
    const char *file_path = "example.txt";
    ResourceBundle *bundle = load_resource(file_path);
    if (bundle) {
        printf("Resource loaded successfully, size: %zu\n", bundle->size);
        // Process the resource here
        free_resource(bundle);
    } else {
        printf("Failed to load resource.\n");
    }
    return 0;
}
```

