    pthread_mutex_lock(&mutex);

    PathInfo info;
    resolveCallback(resolvedPath, &info);

    replaceConsecutiveSlashes(info.resolvedPath);
    appendTrailingSlashIfNeeded(info.resolvedPath, includeTrailingSlash);

    pthread_mutex_unlock(&mutex);

    return info.resolvedPath;
}
