#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_FILENAME_LENGTH 256
#define MAX_IDENTIFIER_LENGTH 255

typedef struct {
    char whitelist[10][8];
    int sequence_numbers[MAX_FILENAME_LENGTH];
    pthread_mutex_t mutex;
} LogIdentifierGenerator;

void init_log_identifier_generator(LogIdentifierGenerator *generator, const char *whitelist[]) {
    for (int i = 0; i < 10; i++) {
        strncpy(generator->whitelist[i], whitelist[i], sizeof(generator->whitelist[i]) - 1);
        generator->sequence_numbers[i] = 0;
    }
    pthread_mutex_init(&generator->mutex, NULL);
}

int is_extension_allowed(LogIdentifierGenerator *generator, const char *filename) {
    for (int i = 0; i < 10; i++) {
        if (strcmp(filename + strlen(filename) - 4, generator->whitelist[i]) == 0) {
            return 1;
        }
    }
    return 0;
}

unsigned int hash_filename(const char *filename) {
    unsigned int hash = 5381;
    int c;
    while ((c = *filename++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash;
}

int generate_log_identifier(LogIdentifierGenerator *generator, const char *filename, char *identifier) {
    if (!is_extension_allowed(generator, filename)) {
        printf("Warning: Invalid file extension\n");
        return -1;
    }

    unsigned int hash = hash_filename(filename);
    pthread_mutex_lock(&generator->mutex);
    generator->sequence_numbers[hash % MAX_FILENAME_LENGTH]++;
    int sequence_number = generator->sequence_numbers[hash % MAX_FILENAME_LENGTH];
    pthread_mutex_unlock(&generator->mutex);

    snprintf(identifier, MAX_IDENTIFIER_LENGTH, "%s_%d", filename, sequence_number);
    return 0;
}

void test_log_identifier_generator() {
    LogIdentifierGenerator generator;
    const char *whitelist[] = {".log", ".err", ".warn"};
    init_log_identifier_generator(&generator, whitelist);

    char identifier1[256];
    generate_log_identifier(&generator, "example.log", identifier1);
    printf("Generated Identifier: %s\n", identifier1);

    char identifier2[256];
    generate_log_identifier(&generator, "example.err", identifier2);
    printf("Generated Identifier: %s\n", identifier2);

    // Add more tests as needed
}

int main() {
    test_log_identifier_generator();
    return 0;
}
```

