#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/pem.h>
#include <openssl/sha.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>

#define MAX_PASSWORD_LENGTH 128
#define PBKDF2_ITERATIONS 500000
#define SALT_LENGTH 32
#define KEY_LENGTH 32

typedef struct {
    unsigned char salt[SALT_LENGTH];
    unsigned char key[KEY_LENGTH];
} EncryptionContext;

int validate_password_strength(const char *password) {
    // Implement password strength validation logic
    return strlen(password) >= 16;
}

int derive_key_from_password(const char *password, unsigned char *salt, unsigned char *key) {
    if (!validate_password_strength(password)) {
        return -1; // Password too weak
    }

    if (PKCS5_PBKDF2_HMAC_SHA1(password, strlen(password), salt, SALT_LENGTH,
                                PBKDF2_ITERATIONS, EVP_sha1(), KEY_LENGTH, key) != 1) {
        return -1; // Key derivation failed
    }
    return 0;
}

int initialize_aes_cipher(EncryptionContext *ctx, const char *password) {
    if (RAND_bytes(ctx->salt, SALT_LENGTH) != 1) {
        return -1; // Salt generation failed
    }

    if (derive_key_from_password(password, ctx->salt, ctx->key) != 0) {
        return -1; // Key derivation failed
    }
    return 0;
}

void encrypt_data(const EncryptionContext *ctx, const unsigned char *plaintext, int plaintext_len,
                  unsigned char *ciphertext, unsigned char *iv) {
    EVP_CIPHER_CTX *ctx_evp = EVP_CIPHER_CTX_new();
    if (!ctx_evp) {
        fprintf(stderr, "Failed to create cipher context\n");
        return;
    }

    if (1 != EVP_EncryptInit_ex(ctx_evp, EVP_aes_256_cbc(), NULL, ctx->key, iv)) {
        fprintf(stderr, "Error initializing encryption\n");
        EVP_CIPHER_CTX_free(ctx_evp);
        return;
    }

    int len;
    if (1 != EVP_EncryptUpdate(ctx_evp, ciphertext, &len, plaintext, plaintext_len)) {
        fprintf(stderr, "Error encrypting data\n");
        EVP_CIPHER_CTX_free(ctx_evp);
        return;
    }
    int ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx_evp, ciphertext + len, &len)) {
        fprintf(stderr, "Error finalizing encryption\n");
        EVP_CIPHER_CTX_free(ctx_evp);
        return;
    }
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx_evp);
}

void decrypt_data(const EncryptionContext *ctx, const unsigned char *ciphertext, int ciphertext_len,
                  unsigned char *plaintext, unsigned char *iv) {
    EVP_CIPHER_CTX *ctx_evp = EVP_CIPHER_CTX_new();
    if (!ctx_evp) {
        fprintf(stderr, "Failed to create cipher context\n");
        return;
    }

    if (1 != EVP_DecryptInit_ex(ctx_evp, EVP_aes_256_cbc(), NULL, ctx->key, iv)) {
        fprintf(stderr, "Error initializing decryption\n");
        EVP_CIPHER_CTX_free(ctx_evp);
        return;
    }

    int len;
    if (1 != EVP_DecryptUpdate(ctx_evp, plaintext, &len, ciphertext, ciphertext_len)) {
        fprintf(stderr, "Error decrypting data\n");
        EVP_CIPHER_CTX_free(ctx_evp);
        return;
    }
    int plaintext_len = len;

    if (1 != EVP_DecryptFinal_ex(ctx_evp, plaintext + len, &len)) {
        fprintf(stderr, "Error finalizing decryption\n");
        EVP_CIPHER_CTX_free(ctx_evp);
        return;
    }
    plaintext_len += len;

    EVP_CIPHER_CTX_free(ctx_evp);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <password> <data>\n", argv[0]);
        return 1;
    }

    EncryptionContext ctx;
    if (initialize_aes_cipher(&ctx, argv[1]) != 0) {
        fprintf(stderr, "Failed to initialize AES cipher\n");
        return 1;
    }

    unsigned char iv[EVP_MAX_BLOCK_LENGTH];
    if (RAND_bytes(iv, EVP_CIPHER_block_size(EVP_aes_256_cbc())) != 1) {
        fprintf(stderr, "Failed to generate IV\n");
        return 1;
    }

    unsigned char ciphertext[1024];
    encrypt_data(&ctx, argv[2], strlen(argv[2]), ciphertext, iv);

    printf("Ciphertext: ");
    for (int i = 0; i < sizeof(ciphertext); i++) {
        if (ciphertext[i] != '\0') {
            printf("%02x", ciphertext[i]);
        }
    }
    printf("\n");

    unsigned char decrypted_data[1024];
    decrypt_data(&ctx, ciphertext, sizeof(ciphertext), decrypted_data, iv);

    printf("Decrypted data: %s\n", decrypted_data);

    return 0;
}
```

This code snippet provides a basic implementation of an AES-256-CBC cipher initialization and encryption/decryption functions using OpenSSL. It includes password strength validation, PBKDF2 key derivation with adjustable parameters, efficient resource management, and error handling. The main function demonstrates how to use these functions for encrypting and decrypting data with user-provided password and plaintext input.']

