            clock_gettime(CLOCK_MONOTONIC, &start_process);

            if (process_image_data()) {
                clock_gettime(CLOCK_MONOTONIC, &end_process);

                // Save image
                time_t start_save, end_save;
                clock_gettime(CLOCK_MONOTONIC, &start_save);

                if (save_image(task->log_file)) {
                    clock_gettime(CLOCK_MONOTONIC, &end_save);

                    // Log success
                    log_event("Success", start_load, end_load, start_process, end_process, start_save, end_save);
                    break;
                } else {
                    log_event("Save Failed", 0, 0, 0, 0, start_save, end_save);
                }
            } else {
                log_event("Process Failed", 0, 0, start_process, end_process, 0, 0);
