    public FileManagementUtility(String configFilePath) throws IOException {
        // Load configuration from encrypted file or environment variables
        Configuration config = loadConfiguration(configFilePath);

        monitoredDirectory = Paths.get(config.monitoredDirectory);
        fileAgeThresholdInDays = config.fileAgeThresholdInDays;
        commandExecutor = Executors.newFixedThreadPool(10);
        monitoringScheduler = Executors.newScheduledThreadPool(1);
        diskSpaceThresholdInBytes = (long) (config.diskSpaceThresholdPercentage * 0.01 * Files.getFileStore(monitoredDirectory).getTotalSpace());

        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            shutdown();
        }));
    }

    private Configuration loadConfiguration(String configFilePath) throws IOException {
        // Placeholder for actual configuration loading logic
        return new Configuration("path/to/monitored/directory", 7, 15);
    }

    public void startMonitoring() {
        monitoringScheduler.scheduleAtFixedRate(this::monitorDirectory, 0, Duration.ofMinutes(1));
    }

    private void monitorDirectory() {
        try (DirectoryStream<Path> stream = Files.newDirectoryStream(monitoredDirectory)) {
            for (Path file : stream) {
                if (Files.isRegularFile(file) && isOlderThanThreshold(file)) {
                    deleteFile(file);
                }
            }
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error monitoring directory", e);
        }

        checkDiskSpace();
    }

    private boolean isOlderThanThreshold(Path file) throws IOException {
        LocalDateTime lastModifiedTime = Files.getLastModifiedTime(file).toInstant().atZone(ZoneId.systemDefault()).toLocalDateTime();
        return lastModifiedTime.isBefore(LocalDateTime.now().minusDays(fileAgeThresholdInDays));
    }

    private void deleteFile(Path file) {
        try {
            Files.delete(file);
            logger.log(Level.INFO, "Deleted file: " + file);
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error deleting file: " + file, e);
        }
    }

    private void checkDiskSpace() {
        try {
            long freeSpace = Files.getFileStore(monitoredDirectory).getUsableSpace();
            if (freeSpace < diskSpaceThresholdInBytes) {
                logger.log(Level.WARNING, "Low disk space: " + freeSpace / 1024 / 1024 + " MB");
                // Trigger alerts or take other actions
            }
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error checking disk space", e);
        }
    }

    public void executeCommand(String command) {
        if (!isValidCommand(command)) {
            logger.log(Level.WARNING, "Invalid command: " + command);
            return;
        }

        Future<?> future = commandExecutor.submit(() -> runCommand(command));
        future.addListener(() -> {
            try {
                future.get(30, TimeUnit.SECONDS);
            } catch (TimeoutException e) {
                logger.log(Level.SEVERE, "Command execution timed out: " + command);
            } catch (InterruptedException | ExecutionException e) {
                logger.log(Level.SEVERE, "Error executing command: " + command, e);
            }
        }, moreExecutors.directExecutor());
    }

    private boolean isValidCommand(String command) {
        // Placeholder for actual validation logic
        return true;
    }

    private void runCommand(String command) {
        try {
            Process process = Runtime.getRuntime().exec(command);
            int exitCode = process.waitFor();
            logger.log(Level.INFO, "Command executed: " + command + ", Exit code: " + exitCode);
        } catch (IOException | InterruptedException e) {
            logger.log(Level.SEVERE, "Error executing command: " + command, e);
        }
    }

    public void shutdown() {
        commandExecutor.shutdown();
        monitoringScheduler.shutdown();
        try {
            if (!commandExecutor.awaitTermination(60, TimeUnit.SECONDS)) {
                commandExecutor.shutdownNow();
            }
            if (!monitoringScheduler.awaitTermination(60, TimeUnit.SECONDS)) {
                monitoringScheduler.shutdownNow();
            }
        } catch (InterruptedException e) {
            commandExecutor.shutdownNow();
            monitoringScheduler.shutdownNow();
        }
    }

    private static class Configuration {
        final String monitoredDirectory;
        final int fileAgeThresholdInDays;
        final double diskSpaceThresholdPercentage;

        public Configuration(String monitoredDirectory, int fileAgeThresholdInDays, double diskSpaceThresholdPercentage) {
            this.monitoredDirectory = monitoredDirectory;
            this.fileAgeThresholdInDays = fileAgeThresholdInDays;
            this.diskSpaceThresholdPercentage = diskSpaceThresholdPercentage;
        }
    }
}
