public class SensorDataProcessor : IDisposable
{
    private readonly DbConnectionPool _dbConnectionPool;
    private readonly IBinaryDecoder _binaryDecoder;
    private readonly IMessageBroker _messageBroker;
    private readonly ICloudStorageService _cloudStorageService;
    private readonly ILogger _logger;
    private readonly Timer _healthCheckTimer;

    public SensorDataProcessor(DbConnectionPool dbConnectionPool, IBinaryDecoder binaryDecoder, IMessageBroker messageBroker, ICloudStorageService cloudStorageService, ILogger logger)
    {
        _dbConnectionPool = dbConnectionPool ?? throw new ArgumentNullException(nameof(dbConnectionPool));
        _binaryDecoder = binaryDecoder ?? throw new ArgumentNullException(nameof(binaryDecoder));
        _messageBroker = messageBroker ?? throw new ArgumentNullException(nameof(messageBroker));
        _cloudStorageService = cloudStorageService ?? throw new ArgumentNullException(nameof(cloudStorageService));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));

        _healthCheckTimer = new Timer(30000); // Every 30 seconds
        _healthCheckTimer.Elapsed += OnHealthCheckElapsed;
        _healthCheckTimer.Start();
    }

    public void StartProcessing()
    {
        var dataFlowBlockOptions = new ExecutionDataflowBlockOptions { MaxDegreeOfParallelism = Environment.ProcessorCount };

        var sourceBlock = new BroadcastBlock<byte[]>(null, dataFlowBlockOptions);
        var decoderBlock = new TransformBlock<byte[], SensorData>(binary => _binaryDecoder.Decode(binary), dataFlowBlockOptions);
        var dbStorageBlock = new ActionBlock<SensorData>(data =>
        {
            using (var connection = _dbConnectionPool.GetConnection())
            {
                using (var transaction = connection.BeginTransaction())
                {
                    // Store data in database
                    _logger.Log($"Storing data for sensor {data.SensorId}");
                    transaction.Commit();
                }
            }
        }, dataFlowBlockOptions);

        var cloudStorageBlock = new ActionBlock<SensorData>(data =>
        {
            _cloudStorageService.Store(data);
        }, dataFlowBlockOptions);

        sourceBlock.LinkTo(decoderBlock, new DataflowLinkOptions { PropagateCompletion = true });
        decoderBlock.LinkTo(dbStorageBlock, new DataflowLinkOptions { PropagateCompletion = true });
        decoderBlock.LinkTo(cloudStorageBlock, new DataflowLinkOptions { PropagateCompletion = true });

        _messageBroker.Subscribe(new Action<byte[]>(data => sourceBlock.SendAsync(data).Wait()));

        sourceBlock.Completion.ContinueWith(t =>
        {
            if (t.IsFaulted)
            {
                _logger.Log($"Processing failed: {t.Exception}");
            }
            else
            {
                _logger.Log("All data processed successfully.");
            }

            _healthCheckTimer.Stop();
        });
    }

    private void OnHealthCheckElapsed(object sender, ElapsedEventArgs e)
    {
        // Perform health checks and log status
        _logger.Log("Service is healthy.");
    }

    public void Dispose()
    {
        _healthCheckTimer.Dispose();
    }
}

