    private readonly Stack<SqlConnection> _connectionPool = new Stack<SqlConnection>();
    private readonly string _connectionString;

    public DbConnectionPool(string connectionString)
    {
        _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));
    }

    public SqlConnection GetConnection()
    {
        if (_connectionPool.Count > 0)
        {
            return _connectionPool.Pop();
        }
        else
        {
            return new SqlConnection(_connectionString);
        }
    }

    public void ReleaseConnection(SqlConnection connection)
    {
        _connectionPool.Push(connection);
    }
}

