using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using Microsoft.Extensions.Configuration;

public class SecureObjectDeserializer<T>
{
    private readonly ICryptoTransform _decryptor;
    private readonly string _key;
    private readonly string _iv;
    private readonly PaddingMode _paddingMode;

    public SecureObjectDeserializer(string key, string iv, PaddingMode paddingMode)
    {
        _key = key;
        _iv = iv;
        _paddingMode = paddingMode;
        var aes = Aes.Create();
        aes.Key = Convert.FromBase64String(_key);
        aes.IV = Convert.FromBase64String(_iv);
        aes.Padding = _paddingMode;
        _decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
    }

    public T Deserialize(string encryptedData)
    {
        try
        {
            var encryptedBytes = Convert.FromBase64String(encryptedData);
            using (var ms = new MemoryStream(encryptedBytes))
            {
                using (var cs = new CryptoStream(ms, _decryptor, CryptoStreamMode.Read))
                {
                    using (var sr = new StreamReader(cs))
                    {
                        var json = sr.ReadToEnd();
                        return System.Text.Json.JsonSerializer.Deserialize<T>(json);
                    }
                }
            }
        }
        catch (Exception ex)
        {
            // Log the exception
            Console.Error.WriteLine($"Decryption failed: {ex.Message}");
            throw;
        }
    }

    public static void Main(string[] args)
    {
        var config = new ConfigurationBuilder()
            .AddJsonFile("appsettings.json", optional: false, reloadOnChange: true)
            .Build();

        var key = config["EncryptionKey"];
        var iv = config["InitializationVector"];
        var paddingModeString = config["PaddingMode"];
        var paddingMode = (PaddingMode)Enum.Parse(typeof(PaddingMode), paddingModeString);

        var deserializer = new SecureObjectDeserializer<MyCustomObject>(key, iv, paddingMode);
        var encryptedData = "your_encrypted_data_here";
        var customObject = deserializer.Deserialize(encryptedData);
    }
}

public class MyCustomObject
{
    public string Property1 { get; set; }
    public int Property2 { get; set; }
}
