const express = require('express');
const multer = require('multer');
const sharp = require('sharp');
const axios = require('axios');
const redis = require('redis');
const mongoose = require('mongoose');

// Initialize Express app
const app = express();

// Configure Multer for file uploads
const upload = multer({
  storage: multer.memoryStorage(),
  limits: {
    fileSize: 5 * 1024 * 1024 // 5MB limit
  },
  fileFilter: (req, file, cb) => {
    const allowedTypes = ['image/jpeg', 'image/png', 'application/pdf'];
    if (!allowedTypes.includes(file.mimetype)) {
      return cb(new Error('Unsupported file type'));
    }
    cb(null, true);
  }
});

// Connect to MongoDB
mongoose.connect('mongodb://localhost:27017/document_management', { useNewUrlParser: true, useUnifiedTopology: true });

// Define a Mongoose model for storing upload history
const Upload = mongoose.model('Upload', new mongoose.Schema({
  url: String,
  fileSize: Number,
  fileType: String,
  metadata: Object,
  status: String,
  createdAt: Date,
  updatedAt: Date
}));

// Initialize Redis client
const redisClient = redis.createClient();

// Function to handle file upload
async function handleFileUpload(req, res) {
  const { url } = req.body;
  try {
    // Fetch the file from the URL
    const response = await axios.get(url, { responseType: 'stream' });
    const fileSize = parseInt(response.headers['content-length'], 10);
    if (fileSize > 5 * 1024 * 1024) {
      return res.status(400).send('File size exceeds limit');
    }

    // Process the file using Sharp for optimization
    const processedImage = await sharp(response.data)
      .resize(800, 600)
      .toBuffer();

    // Store metadata from external API (example: assuming it's a mock API)
    const metadata = await axios.get('https://api.example.com/metadata', { params: { url } });

    // Save upload to database
    const newUpload = new Upload({
      url,
      fileSize,
      fileType: response.headers['content-type'],
      metadata: metadata.data,
      status: 'processing'
    });
    await newUpload.save();

    // Enqueue the upload for processing
    redisClient.lpush('uploads', JSON.stringify(newUpload));

    res.status(201).send({ message: 'Upload enqueued' });
  } catch (error) {
    console.error(error);
    res.status(500).send('Error uploading file');
  }
}

// Message queue consumer to process uploads
async function processUploads() {
  redisClient.blpop('uploads', 0, async (err, result) => {
    if (result) {
      const upload = JSON.parse(result[1]);
      try {
        // Simulate processing time
        await new Promise(resolve => setTimeout(resolve, Math.random() * 5000));

        // Update upload status
        upload.status = 'completed';
        await Upload.findByIdAndUpdate(upload._id, { $set: upload });

        console.log('Upload processed:', upload);
      } catch (error) {
        console.error(error);
        // Implement retry logic with exponential backoff
      }

      processUploads();
    }
  });
}

// Route to handle file uploads
app.post('/upload', upload.single('file'), handleFileUpload);

// Start processing uploads
processUploads();

// Start the server
app.listen(3000, () => {
  console.log('Server is running on port 3000');
});
