const express = require('express');
const axios = require('axios');
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const bodyParser = require('body-parser');

const app = express();
app.use(bodyParser.json());

const API_URL = 'https://api.example.com/config';
const KICKSTART_FILE_PATH = '/path/to/kickstart.cfg';

async function fetchConfig() {
    try {
        const response = await axios.get(API_URL, { timeout: 5000 });
        return response.data;
    } catch (error) {
        console.error('Error fetching config from API:', error);
        throw error;
    }
}

function updateKickstart(config, password) {
    try {
        let kickstartContent = fs.readFileSync(KICKSTART_FILE_PATH, 'utf8');
        for (const [key, value] of Object.entries(config)) {
            const placeholder = `__${key}__`;
            kickstartContent = kickstartContent.replace(placeholder, value);
        }
        const encryptedPassword = crypto.createCipher('aes-256-cbc', 'secret-key').update(password).final('hex');
        kickstartContent += `\nencrypted_password=${encryptedPassword}`;
        fs.writeFileSync(KICKSTART_FILE_PATH, kickstartContent);
    } catch (error) {
        console.error('Error updating Kickstart file:', error);
        throw error;
    }
}

app.post('/update-config', async (req, res) => {
    try {
        const { config, password } = req.body;
        if (!config || !password) {
            return res.status(400).json({ success: false, message: 'Invalid input' });
        }
        await updateKickstart(config, password);
        res.json({ success: true, message: 'Config updated successfully' });
    } catch (error) {
        console.error('Error updating config:', error);
        res.status(500).json({ success: false, message: 'Internal server error' });
    }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
    console.log(`Server is running on port ${PORT}`);
});
