// main.rs

use clap::{App, Arg};
use serde_json::Value;
use tokio::sync::mpsc;
use reqwest::{Client, Error as ReqwestError};
use std::{error::Error, sync::Arc};

mod config;
mod functions;
mod external_api;

#[tokio::main]
async fn main() -> Result<(), Box<dyn Error>> {
    let matches = App::new("Dynamic Function Executor")
        .version("1.0")
        .author("Your Name <your.email@example.com>")
        .about("A robust Rust application for dynamically loading and executing functions from a JSON configuration file.")
        .arg(
            Arg::with_name("config")
                .short('c')
                .long("config")
                .value_name("FILE")
                .help("Sets the path to the configuration file")
                .takes_value(true)
                .required(true),
        )
        .get_matches();

    let config_path = matches.value_of("config").unwrap();
    let config: Value = serde_json::from_str(&std::fs::read_to_string(config_path)?)?;

    let (tx, mut rx) = mpsc::channel(1000);

    for func_def in config["functions"].as_array().unwrap() {
        let tx = tx.clone();
        tokio::spawn(async move {
            if let Err(e) = functions::execute_function(func_def, tx).await {
                eprintln!("Error executing function: {}", e);
            }
        });
    }

    while let Some(result) = rx.recv().await {
        external_api::process_result(&result).await?;
    }

    Ok(())
}
