// functions.rs

use tokio::sync::mpsc;
use reqwest::{Client, Error as ReqwestError};
use std::error::Error;

pub async fn execute_function(func_def: &serde_json::Value, tx: mpsc::Sender<FunctionResult>) -> Result<(), Box<dyn Error>> {
    // Extract function details from func_def
    let name = func_def["name"].as_str().unwrap();
    let params = func_def["params"].clone();

    if func_def["mode"] == "async" {
        tokio::spawn(async move {
            let result = perform_function_call(name, params).await?;
            tx.send(result).await?;
        });
    } else {
        let result = perform_function_call_sync(name, params)?;
        tx.send(result).await?;
    }

    Ok(())
}

pub async fn perform_function_call(name: &str, params: serde_json::Value) -> Result<FunctionResult, Box<dyn Error>> {
    // Call the function asynchronously and return the result
    let client = Client::new();
    let response = client.post(format!("https://api.example.com/functions/{}", name))
        .json(&params)
        .send()
        .await?
        .text()
        .await?;

    Ok(FunctionResult { data: response })
}

pub fn perform_function_call_sync(name: &str, params: serde_json::Value) -> Result<FunctionResult, Box<dyn Error>> {
    // Call the function synchronously and return the result
    let client = Client::new();
    let response = client.post(format!("https://api.example.com/functions/{}", name))
        .json(&params)
        .send()?;

    Ok(FunctionResult { data: response.text()? })
}

pub struct FunctionResult {
    pub data: String,
}
