// external_api.rs

use reqwest::{Client, Error as ReqwestError};
use std::error::Error;

pub async fn process_result(result: &FunctionResult) -> Result<(), Box<dyn Error>> {
    // Process the result from an external system
    let client = Client::new();
    let response = client.post("https://api.example.com/results")
        .json(&result)
        .send()
        .await?;

    if !response.status().is_success() {
        return Err(ReqwestError::from(response).into());
    }

    Ok(())
}
