// Implement methods for the DirectoryManager struct
impl DirectoryManager {
    pub fn new(config_manager: Box<dyn ConfigManager>) -> Self {
        DirectoryManager {
            config_manager,
            dir_locks: Arc::new(Mutex::new(HashMap::new())),
        }
