    pub async fn create_directory(&self, path: &str) -> Result<(), ManagerError> {
        // Validate directory path
        self.config_manager.validate_path(path)?;

        let mut locks = self.dir_locks.lock().unwrap();
        if !locks.contains_key(path) {
            locks.insert(path.to_string(), tokio::sync::Mutex::new(()));
        }

        let dir_lock = locks.get(path).unwrap().lock().await;
        // Perform directory creation
        info!("Creating directory: {}", path);
        Ok(())
    }

    pub async fn set_env_var(&self, key: &str, value: &str) -> Result<(), ManagerError> {
        // Validate environment variable name and value
        self.config_manager.validate_env_var(key, value)?;

        let dir_lock = self.get_directory_lock("/tmp").await?;
        // Perform environment variable setting
        info!("Setting environment variable: {}={}", key, value);
        Ok(())
    }

    pub async fn cleanup(&self) {
        // Implement cleanup logic here
        warn!("Cleanup not implemented yet");
    }
}

// Define a trait for the ConfigManager to abstract configuration management
