impl ConfigManager for MockConfigManager {
    fn validate_path(&self, path: &str) -> Result<(), ManagerError> {
        // Mock validation logic
        if path.contains("invalid") {
            return Err(ManagerError::new("Invalid directory path"));
        }
        Ok(())
    }

    fn validate_env_var(&self, key: &str, value: &str) -> Result<(), ManagerError> {
        // Mock validation logic
        if key.contains("RESERVED") || value.len() > 1024 {
            return Err(ManagerError::new("Invalid environment variable"));
        }
        Ok(())
    }
}

// Define a custom error type for the module
#[derive(Debug)]
pub struct ManagerError(String);

impl ManagerError {
    pub fn new(msg: &str) -> Self {
        ManagerError(msg.to_string())
    }
}

impl std::fmt::Display for ManagerError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "ManagerError: {}", self.0)
    }
}

impl std::error::Error for ManagerError {}

// Implement a signal handler to ensure graceful termination
fn setup_signal_handler(manager: Arc<DirectoryManager>) {
    let manager = manager.clone();
    tokio::spawn(async move {
        loop {
            tokio::signal::ctrl_c().await.unwrap();
            manager.cleanup().await;
            std::process::exit(0);
        }
    });
}

// Main function to demonstrate the module's usage
#[tokio::main]
async fn main() {
    let config_manager = Box::new(MockConfigManager);
    let manager = Arc::new(DirectoryManager::new(config_manager));

    setup_signal_handler(manager.clone());

    tokio::spawn(async move {
        if let Err(e) = manager.create_directory("/tmp/test_dir").await {
            error!("Error creating directory: {}", e);
        }
    });

    tokio::spawn(async move {
        if let Err(e) = manager.set_env_var("TEST_VAR", "value").await {
            error!("Error setting environment variable: {}", e);
        }
    });

    // Wait for threads to finish
    tokio::time::sleep(Duration::from_secs(5)).await;
}
