import json
from abc import ABC, abstractmethod
import threading
import logging

# Setup basic configuration for logging
logging.basicConfig(level=logging.INFO)

# Define an abstract base class for data source factories
class DataSourceFactory(ABC):
    @abstractmethod
    def create_instance(self, metadata: dict) -> 'DataSource':
        pass

# Define a pluggable registry for data source factories
class FactoryRegistry:
    _registry = {}

    @staticmethod
    def register(factory_name: str, factory_class: type):
        if factory_name in FactoryRegistry._registry:
            raise ValueError(f"Factory '{factory_name}' already exists.")
        FactoryRegistry._registry[factory_name] = factory_class

    @staticmethod
    def get_factory(factory_name: str) -> 'DataSourceFactory':
        if factory_name not in FactoryRegistry._registry:
            raise ValueError(f"Factory '{factory_name}' not found.")
        return FactoryRegistry._registry[factory_name]

# Define an abstract base class for data sources
class DataSource(ABC):
    @abstractmethod
    def load_data(self, stream: 'DataStream') -> dict:
        pass

# Define a class for JSON data streams
class DataStream:
    def __init__(self, content: str):
        self.content = json.loads(content)

    def get_json(self) -> dict:
        return self.content

# Define a concrete implementation of DataSourceFactory for a specific schema version
class Version1DataSourceFactory(DataSourceFactory):
    def create_instance(self, metadata: dict) -> 'Version1DataSource':
        if metadata.get('schema_version') != 1:
            raise ValueError("Invalid schema version.")
        return Version1DataSource(metadata)

# Define a concrete implementation of DataSource for a specific schema version
class Version1DataSource(DataSource):
    def __init__(self, metadata: dict):
        self.metadata = metadata

    def load_data(self, stream: 'DataStream') -> dict:
        # Implement lazy loading and processing logic here
        return stream.get_json()

# Register the factory in the registry
FactoryRegistry.register('v1', Version1DataSourceFactory)

# Example usage
factory = FactoryRegistry.get_factory('v1')
data_source = factory.create_instance({'schema_version': 1})
stream = DataStream('{"key": "value"}')
data = data_source.load_data(stream)
print(data)  # Output: {'key': 'value'}
