        cache.put(session.getSessionId(), session);
    }

    public void updateUserSession(UserSession session) {
        cache.replace(session.getSessionId(), session);
    }

    public void removeUserSession(String sessionId) {
        cache.remove(sessionId);
    }

    private void refreshSessions() {
        for (UserSession session : cache.values()) {
            if (isSessionExpired(session)) {
                removeUserSession(session.getSessionId());
            } else {
                // Proactively refresh session data
                // This could involve making a call to an external service or updating the local copy
            }
        }
    }

    private boolean isSessionExpired(UserSession session) {
        return System.currentTimeMillis() > session.getExpirationTime();
    }

    public void shutdown() {
        scheduler.shutdown();
    }

    public static class UserSession {
        private String sessionId;
        private long lastAccessTime;
        private long expirationTime;
