#include <openssl/evp.h>
#include <aws/kms.h>
#include <vault/vault.h>
#include <redis/redis.h>

typedef enum {
    CIPHER_DES_ECB,
    CIPHER_DES_EDE,
    CIPHER_DES_EDE3,
    CIPHER_AES_CBC,
    CIPHER_CHACHA20
} CipherType;

EVP_CIPHER* select_cipher(CipherType type) {
    switch (type) {
        case CIPHER_DES_ECB:
            return EVP_des_ecb();
        case CIPHER_DES_EDE:
            return EVP_des_ede_cbc();
        case CIPHER_DES_EDE3:
            return EVP_des_ede3_cbc();
        case CIPHER_AES_CBC:
            return EVP_aes_256_cbc();
        case CIPHER_CHACHA20:
            return EVP_chacha20_poly1305();
        default:
            return NULL;
    }
}

int load_key_from_kms(const char* key_id, unsigned char** key) {
    AWS_KMS* kms = aws_kms_create();
    if (!kms) return -1;

    int result = aws_kms_get_secret(kms, key_id, key);
    aws_kms_destroy(kms);
    return result;
}

int load_key_from_vault(const char* path, unsigned char** key) {
    HashiCorp_Vault* vault = hashi_corp_vault_create();
    if (!vault) return -1;

    int result = hashi_corp_vault_get_secret(vault, path, key);
    hashi_corp_vault_destroy(vault);
    return result;
}

int get_cipher_key(const char* key_id, unsigned char** key) {
    int result = load_key_from_kms(key_id, key);
    if (result != 0) {
        result = load_key_from_vault("secret/my-key", key);
    }
    return result;
}

void encrypt_data(const unsigned char* plaintext, int plaintext_len, const unsigned char* iv,
                  const unsigned char* key, int key_len, CipherType type, unsigned char** ciphertext, int* ciphertext_len) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return;

    EVP_EncryptInit_ex(ctx, select_cipher(type), NULL, key, iv);
    EVP_EncryptUpdate(ctx, *ciphertext, &(*ciphertext_len), plaintext, plaintext_len);
    EVP_EncryptFinal_ex(ctx, (*ciphertext) + (*ciphertext_len), &(*ciphertext_len));
    EVP_CIPHER_CTX_free(ctx);
}

void decrypt_data(const unsigned char* ciphertext, int ciphertext_len, const unsigned char* iv,
                  const unsigned char* key, int key_len, CipherType type, unsigned char** plaintext, int* plaintext_len) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return;

    EVP_DecryptInit_ex(ctx, select_cipher(type), NULL, key, iv);
    EVP_DecryptUpdate(ctx, *plaintext, &(*plaintext_len), ciphertext, ciphertext_len);
    EVP_DecryptFinal_ex(ctx, (*plaintext) + (*plaintext_len), &(*plaintext_len));
    EVP_CIPHER_CTX_free(ctx);
}

void rotate_keys() {
