// C Library Code (simplified version)

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct State {
    char *name;
    void (*onEnter)(void);
    void (*onExit)(void);
} State;

typedef struct Transition {
    char *fromStateName;
    char *toStateName;
    void (*action)(void);
} Transition;

typedef struct FiniteStateMachine {
    State **states;
    Transition **transitions;
    int stateCount;
    int transitionCount;
    State *currentState;
    pthread_mutex_t mutex;
} FiniteStateMachine;

FiniteStateMachine* createFsm(int stateCount, int transitionCount) {
    FiniteStateMachine *fsm = (FiniteStateMachine*)malloc(sizeof(FiniteStateMachine));
    fsm->states = (State**)malloc(stateCount * sizeof(State*));
    fsm->transitions = (Transition**)malloc(transitionCount * sizeof(Transition*));
    fsm->stateCount = stateCount;
    fsm->transitionCount = transitionCount;
    pthread_mutex_init(&fsm->mutex, NULL);
    return fsm;
}

void addState(FiniteStateMachine *fsm, char *name, void (*onEnter)(void), void (*onExit)(void)) {
    State *state = (State*)malloc(sizeof(State));
    state->name = name;
    state->onEnter = onEnter;
    state->onExit = onExit;
    fsm->states[fsm->stateCount++] = state;
}

void addTransition(FiniteStateMachine *fsm, char *fromStateName, char *toStateName, void (*action)(void)) {
    Transition *transition = (Transition*)malloc(sizeof(Transition));
    transition->fromStateName = fromStateName;
    transition->toStateName = toStateName;
    transition->action = action;
    fsm->transitions[fsm->transitionCount++] = transition;
}

void setState(FiniteStateMachine *fsm, char *stateName) {
    pthread_mutex_lock(&fsm->mutex);
    for (int i = 0; i < fsm->stateCount; i++) {
        if (strcmp(fsm->states[i]->name, stateName) == 0) {
            if (fsm->currentState != NULL) {
                fsm->currentState->onExit();
            }
            fsm->currentState = fsm->states[i];
            fsm->currentState->onEnter();
            break;
        }
    }
    pthread_mutex_unlock(&fsm->mutex);
}

