#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/hmac.h>
#include <openssl/sha.h>
#include <libconfig.h++>
#include <thread>
#include <mutex>

// Define the structure for AES-256-GCM context
typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[32];
    unsigned char iv[12];
} AES_GCM_CTX;

// Function to derive a secure encryption key using PBKDF2
void derive_key(const char *password, const size_t password_len, const unsigned char *salt,
                const size_t salt_len, const int iterations, unsigned char *key) {
    PKCS5_PBKDF2_HMAC(password, password_len, salt, salt_len, iterations, EVP_sha256(), 32, key);
}

// Function to initialize AES-256-GCM cipher
int init_aes_gcm_ctx(const char *password, const size_t password_len, unsigned char *salt,
                     int iterations, AES_GCM_CTX **ctx) {
    // Validate password strength (pseudo-code)
    if (!validate_password(password)) return -1;

    // Derive the encryption key
    derive_key(password, password_len, salt, sizeof(salt), iterations, (*ctx)->key);

    // Initialize AES-GCM context
    (*ctx)->ctx = EVP_CIPHER_CTX_new();
    if (!(*ctx)->ctx) return -1;
    if (1 != EVP_EncryptInit_ex((*ctx)->ctx, EVP_aes_256_gcm(), NULL, (*ctx)->key, (*ctx)->iv)) {
        EVP_CIPHER_CTX_free((*ctx)->ctx);
        return -1;
    }

    // Set the tag length
    if (1 != EVP_CIPHER_CTX_ctrl((*ctx)->ctx, EVP_CTRL_GCM_SET_TAG_LEN, 16, NULL)) {
        EVP_CIPHER_CTX_free((*ctx)->ctx);
        return -1;
    }

    // Generate a random IV
    if (!RAND_bytes((*ctx)->iv, sizeof((*ctx)->iv))) {
        EVP_CIPHER_CTX_free((*ctx)->ctx);
        return -1;
    }

    return 0;
}

// Function to clean up AES-256-GCM context
void cleanup_aes_gcm_ctx(AES_GCM_CTX *ctx) {
    if (ctx->ctx) EVP_CIPHER_CTX_free(ctx->ctx);
    OPENSSL_cleanse(ctx, sizeof(*ctx));
}

// Example usage in a multi-threaded application
std::mutex aes_mutex;

void encrypt_data(const unsigned char *plaintext, size_t plaintext_len, AES_GCM_CTX *ctx,
                  unsigned char *ciphertext, unsigned char *tag) {
    std::lock_guard<std::mutex> lock(aes_mutex);

    if (1 != EVP_EncryptUpdate(ctx->ctx, ciphertext, &ciphertext_len, plaintext, plaintext_len)) return;
    if (1 != EVP_EncryptFinal_ex(ctx->ctx, ciphertext + ciphertext_len, &ciphertext_len)) return;

    // Finalize the GCM tag
    if (1 != EVP_CIPHER_CTX_ctrl(ctx->ctx, EVP_CTRL_GCM_GET_TAG, 16, tag)) return;
}

int main() {
    AES_GCM_CTX *ctx = new AES_GCM_CTX;
    unsigned char salt[16], ciphertext[256], tag[16];
    const char *password = "secure_password";
    size_t password_len = strlen(password);

    // Initialize the context
    if (init_aes_gcm_ctx(password, password_len, salt, 10000, &ctx) != 0) {
        delete ctx;
        return -1;
    }

    // Encrypt some data
    unsigned char plaintext[] = "Hello, world!";
    encrypt_data(plaintext, strlen((char *)plaintext), ctx, ciphertext, tag);

    // Clean up the context
    cleanup_aes_gcm_ctx(ctx);
    delete ctx;

    return 0;
}
