#include <iostream>
#include <vector>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <memory>

struct Attack {
    std::string name;
    int cooldown;
    // Other attack statistics and descriptions
};

class AttackDatabase {
public:
    virtual std::optional<Attack> getAttackByName(const std::string& name) = 0;
    virtual bool updateCooldown(std::string& name, int newCooldown) = 0;
    // Other database operations
};

class GameCharacter {
private:
    std::unordered_map<std::string, int> attackCooldowns;
    std::mutex cooldownMutex;
    AttackDatabase* db;

public:
    GameCharacter(AttackDatabase* database) : db(database) {}

    std::optional<Attack> selectRandomAttack() {
        std::lock_guard<std::mutex> lock(cooldownMutex);
        std::vector<std::string> availableAttacks;

        // Retrieve all attacks from the database
        for (const auto& [name, cooldown] : attackCooldowns) {
            if (cooldown <= 0) {
                availableAttacks.push_back(name);
            }
        }

        if (availableAttacks.empty()) {
            return std::nullopt;
        }

        // Select a random attack from the available ones
        auto it = availableAttacks.begin();
        std::advance(it, rand() % availableAttacks.size());
        const std::string& selectedAttackName = *it;

        // Retrieve attack details from the database
        Attack selectedAttack = db->getAttackByName(selectedAttackName).value();

        // Update cooldown in memory and database
        int newCooldown = selectedAttack.cooldown;
        if (!db->updateCooldown(selectedAttack.name, newCooldown)) {
            std::cerr << "Failed to update cooldown for attack: " << selectedAttack.name << std::endl;
            return std::nullopt;
        }

        // Update cooldown in memory
        attackCooldowns[selectedAttackName] = newCooldown;

        return selectedAttack;
    }

    void setAttackCooldown(const std::string& name, int cooldown) {
        std::lock_guard<std::mutex> lock(cooldownMutex);
        if (db->updateCooldown(name, cooldown)) {
            attackCooldowns[name] = cooldown;
        } else {
            std::cerr << "Failed to update cooldown for attack: " << name << std::endl;
        }
    }

    void getAttackStatus(const std::string& name) const {
        std::lock_guard<std::mutex> lock(cooldownMutex);
        auto it = attackCooldowns.find(name);
        if (it != attackCooldowns.end()) {
            std::cout << "Attack: " << name << ", Cooldown Remaining: " << it->second << " seconds" << std::endl;
        } else {
            std::cerr << "Attack not found: " << name << std::endl;
        }
    }
};

// Example usage
class InMemoryAttackDatabase : public AttackDatabase {
private:
    std::unordered_map<std::string, Attack> attacks;

public:
    InMemoryAttackDatabase() {
        // Initialize with some example attacks
        Attack attack1 = {"Fireball", 5};
        Attack attack2 = {"Ice Lance", 3};
        attacks["Fireball"] = attack1;
        attacks["Ice Lance"] = attack2;
    }

    std::optional<Attack> getAttackByName(const std::string& name) override {
        auto it = attacks.find(name);
        if (it != attacks.end()) {
            return it->second;
        }
        return std::nullopt;
    }

    bool updateCooldown(std::string& name, int newCooldown) override {
        auto it = attacks.find(name);
        if (it != attacks.end()) {
            it->second.cooldown = newCooldown;
            return true;
        }
        return false;
    }
};

int main() {
    InMemoryAttackDatabase db;
    GameCharacter character(&db);

    while (true) {
        std::optional<Attack> selectedAttack = character.selectRandomAttack();
        if (selectedAttack.has_value()) {
            std::cout << "Selected Attack: " << selectedAttack->name << ", Cooldown: " << selectedAttack->cooldown << " seconds" << std::endl;
        } else {
            std::cerr << "Failed to select an attack!" << std::endl;
        }

        // Simulate cooldown updates and status checks
        character.setAttackCooldown("Fireball", 2);
        character.getAttackStatus("Ice Lance");

        std::this_thread::sleep_for(std::chrono::seconds(1));
    }

    return 0;
}
