#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int id;
    char *state;
} StateMachine;

void *process_state(void *arg) {
    StateMachine *machine = (StateMachine *) arg;
    printf("Processing state %d\n", machine->id);
    // Simulate state transition
    sleep(1);
    pthread_exit(NULL);
}

int initialize_library() {
    pthread_t thread_id;
    StateMachine *machine = malloc(sizeof(StateMachine));
    machine->id = 1;
    strcpy(machine->state, "INIT");

    if (pthread_create(&thread_id, NULL, process_state, (void *) machine) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return -1;
    }

    pthread_detach(thread_id);
    return 0;
}
