    private $logger;
    private $state = 'INIT';

    public function __construct() {
        $this->logger = new Logger('state_manager');
        $this->logger->pushHandler(new StreamHandler(__DIR__ . '/app.log', Logger::DEBUG));
    }

    public function transitionTo($newState) {
        $this->logger->info("Transitioning to state: $newState");
        // Simulate state transition
        sleep(1);
        $this->state = $newState;
        $this->logger->info("State transitioned to: $newState");
    }

    public function getState() {
        return $this->state;
    }
}

$manager = new StateManager();
$manager->transitionTo('RUNNING');

echo "Current state: " . $manager->getState();

?>
