#include <iostream>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <future>
#include <thread>
#include <string>

class ConfigManager {
public:
    void updateConfig(const std::string& key, const std::string& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        config_[key] = value;
        cv_.notify_all();
    }

    std::string getConfig(const std::string& key) {
        std::unique_lock<std::mutex> lock(mutex_);
        cv_.wait(lock, [this, &key]{ return config_.find(key) != config_.end(); });
        return config_[key];
    }

private:
    std::unordered_map<std::string, std::string> config_;
    std::mutex mutex_;
    std::condition_variable cv_;
};

class ConfigCache {
public:
    void updateConfig(const std::string& key, const std::string& value) {
        cache_.store(value, std::memory_order_release);
        invalidate_ = true;
    }

    std::string getConfig() {
        if (invalidate_) {
            fetchFromAPI();
            invalidate_ = false;
        }
        return cache_.load(std::memory_order_acquire);
    }

private:
    void fetchFromAPI() {
        // Simulate fetching from external API
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
        std::string config = "new_config_value";
        cache_.store(config, std::memory_order_release);
    }

    std::atomic<std::string> cache_;
    bool invalidate_ = false;
};

class ConfigService {
public:
    void updateConfig(const std::string& key, const std::string& value) {
        config_manager_.updateConfig(key, value);
