['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <curl/curl.h>

#define MAX_CONCURRENT_REQUESTS 100
#define LOG_LEVEL_DEBUG 3

typedef struct {
    char *data;
    size_t size;
} ResourceBundle;

typedef struct {
    CURL *handle;
    ResourceBundle *bundle;
    int version;
    pthread_mutex_t lock;
    int request_count;
} RequestContext;

typedef struct {
    RequestContext requests[MAX_CONCURRENT_REQUESTS];
    int log_level;
} AsyncResourceLoader;

size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    ResourceBundle *bundle = (ResourceBundle *)userp;
    size_t total_size = size * nmemb;
    bundle->data = realloc(bundle->data, bundle->size + total_size);
    if (bundle->data == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 0;
    }
    memcpy(&(bundle->data[bundle->size]), contents, total_size);
    bundle->size += total_size;
    return total_size;
}

int fetch_resource(AsyncResourceLoader *loader, int version, ResourceBundle *bundle) {
    pthread_mutex_lock(&loader->requests[version].lock);
    if (loader->requests[version].request_count >= MAX_CONCURRENT_REQUESTS) {
        pthread_mutex_unlock(&loader->requests[version].lock);
        fprintf(stderr, "Too many concurrent requests\n");
        return -1;
    }
    loader->requests[version].request_count++;
    pthread_mutex_unlock(&loader->requests[version].lock);

    bundle->data = NULL;
    bundle->size = 0;

    CURL *curl_handle = curl_easy_init();
    if (curl_handle == NULL) {
        fprintf(stderr, "Failed to initialize CURL\n");
        return -1;
    }

    char url[256];
    snprintf(url, sizeof(url), "https://api.example.com/resource?version=%d", version);

    curl_easy_setopt(curl_handle, CURLOPT_URL, url);
    curl_easy_setopt(curl_handle, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl_handle, CURLOPT_WRITEDATA, bundle);
    curl_easy_setopt(curl_handle, CURLOPT_USERAGENT, "AsyncResourceLoader");

    CURLcode res = curl_easy_perform(curl_handle);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to fetch resource: %s\n", curl_easy_strerror(res));
        free(bundle->data);
        bundle->data = NULL;
        bundle->size = 0;
    }

    curl_easy_cleanup(curl_handle);

    pthread_mutex_lock(&loader->requests[version].lock);
    loader->requests[version].request_count--;
    pthread_mutex_unlock(&loader->requests[version].lock);

    return res == CURLE_OK ? bundle->size : -1;
}

void log_message(AsyncResourceLoader *loader, int level, const char *message) {
    if (level >= loader->log_level) {
        printf("LOG [%d] %s\n", level, message);
    }
}

int main() {
    AsyncResourceLoader loader = {0};
    pthread_mutex_init(&loader.requests[0].lock, NULL);

    ResourceBundle bundle;
    int result = fetch_resource(&loader, 1, &bundle);

    if (result >= 0) {
        printf("Number of items: %zu\n", result);
        printf("Size of data buffer: %zu\n", bundle.size);
    } else {
        printf("Failed to fetch resource\n");
    }

    free(bundle.data);
    pthread_mutex_destroy(&loader.requests[0].lock);

    return 0;
}
