char* constructPath(const char* original_path, size_t max_buffer_size, int include_trailing_slash,
                    PathResolverCallback resolver_callback, int timeout, pthread_mutex_t *mutex) {
    // 1. Validate input and check for network availability
    if (original_path == NULL || strlen(original_path) >= max_buffer_size || !networkAvailable()) {
        return NULL;
    }

    char path[max_buffer_size];
    snprintf(path, max_buffer_size, "%s", original_path);

    // 3. Resolve symbolic links, environment variables, and network paths
    int attempts = 0;
    time_t start_time = time(NULL);
    while (attempts < 4) {
        pthread_mutex_lock(mutex);
        char *resolved_path = resolver_callback(path, timeout);
        pthread_mutex_unlock(mutex);

        if (resolved_path != NULL) {
            strncpy(path, resolved_path, max_buffer_size);
            free(resolved_path);
            break;
        }

        attempts++;
        if (attempts < 4) {
            sleep((1 << attempts));
        }
    }

    // 4. Replace consecutive slashes and handle trailing slash
    for (size_t i = 0; i < strlen(path); i++) {
        while (i + 1 < strlen(path) && path[i] == '/' && path[i + 1] == '/') {
            memmove(&path[i], &path[i + 1], strlen(&path[i]));
        }
    }
    if (include_trailing_slash && path[strlen(path) - 1] != '/') {
        strncat(path, "/", max_buffer_size);
    }

    // 6. Implement logging and error handling
    logPathConstruction(path, start_time);

    return strdup(path); // Return a copy of the resolved path
}

