        Key key;
        if (mode == "DES") {
            key.resize(8);
        } else if (mode == "AES") {
            key.resize(16); // AES-128
        } else if (mode == "ChaCha20") {
            key.resize(32);
        }
        RAND_bytes(key.data(), key.size());
        redis_client.set("key", key);
        return key;
    }

    Key getKeyFromStorage(CipherMode mode) {
        // Retrieve key from external storage or Redis
        std::string key_str = "default_key"; // Placeholder
        if (external_storage == ExternalKeyStorage::AWS_KMS) {
            // Implement AWS KMS retrieval
        } else if (external_storage == ExternalKeyStorage::HashiCorp_Vault) {
            // Implement HashiCorp Vault retrieval
        } else if (external_storage == ExternalKeyStorage::Google_Cloud_KMS) {
            // Implement Google Cloud KMS retrieval
        }
        return key_str.empty() ? generateKey(mode) : parseKeyFromRedis(key_str);
    }

    std::string encrypt(const std::string& plaintext, CipherMode mode, Key key, IV iv) {
        EVP_CIPHER* cipher = getCipherByMode(mode);
        if (!cipher) {
            throw std::runtime_error("Unsupported cipher mode");
        }
        unsigned char ciphertext[plaintext.length() + EVP_CIPHER_block_size(cipher)];
        int len;
        int ciphertext_len = 0;

        EVP_EncryptInit_ex(NULL, cipher, NULL, key.data(), iv.data());
        EVP_EncryptUpdate(NULL, ciphertext, &len, (unsigned char*)plaintext.c_str(), plaintext.length());
        ciphertext_len += len;
        EVP_EncryptFinal_ex(NULL, ciphertext + len, &len);
        ciphertext_len += len;

        std::string ret(ciphertext, ciphertext_len);
        redis_client.set("ciphertext", ret);
        return ret;
    }

    std::string decrypt(const std::string& ciphertext, CipherMode mode, Key key, IV iv) {
        EVP_CIPHER* cipher = getCipherByMode(mode);
        if (!cipher) {
            throw std::runtime_error("Unsupported cipher mode");
        }
        unsigned char decryptedtext[ciphertext.length()];
        int len;
        int decryptedtext_len = 0;

        EVP_DecryptInit_ex(NULL, cipher, NULL, key.data(), iv.data());
        EVP_DecryptUpdate(NULL, decryptedtext, &len, (unsigned char*)ciphertext.c_str(), ciphertext.length());
        decryptedtext_len += len;
        EVP_DecryptFinal_ex(NULL, decryptedtext + len, &len);
        decryptedtext_len += len;

        std::string ret(decryptedtext, decryptedtext_len);
        return ret;
    }

private:
    ExternalKeyStorage external_storage;
    redisPlusPlus::Connection redis_client;

    EVP_CIPHER* getCipherByMode(CipherMode mode) {
        if (mode == "DES_ECB") {
            return EVP_des_ecb();
        } else if (mode == "AES_CBC") {
            return EVP_aes_128_cbc();
        } else if (mode == "ChaCha20") {
            return EVP_chacha20_poly1305();
        }
        return nullptr;
    }

    Key parseKeyFromRedis(const std::string& key_str) {
        // Convert Redis string to Key
        Key key(key_str.begin(), key_str.end());
        return key;
    }
};

int main() {
