    EVP_CIPHER_CTX* getEVPContext(const std::string& algorithm, const std::string& mode) {
        // Dynamically select and return an EVP_CIPHER structure based on user-defined parameters
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        if (algorithm == "DES" && mode == "ECB") {
            EVP_EncryptInit_ex(ctx, EVP_des_ecb(), nullptr, nullptr, nullptr);
        } else if (algorithm == "AES" && mode == "CBC") {
            EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), nullptr, nullptr, nullptr);
        }
        // Add support for other algorithms and modes
        return ctx;
    }

    std::vector<unsigned char> encrypt(const EVP_CIPHER_CTX* ctx, const std::string& key, const std::string& data) {
        // Encrypt the data using the provided context and key
        std::vector<unsigned char> encryptedData(data.size() + EVP_CIPHER_block_size(EVP_CIPHER_CTX_cipher(ctx)));
        int len;
        EVP_EncryptUpdate(ctx, encryptedData.data(), &len, reinterpret_cast<const unsigned char*>(data.c_str()), data.size());
        int ciphertext_len = len;
        EVP_EncryptFinal_ex(ctx, encryptedData.data() + len, &len);
        ciphertext_len += len;
        encryptedData.resize(ciphertext_len);
        return encryptedData;
    }

