private:
    void selectCipherMode(const std::string& mode) {
        if (mode == "DES_ECB") {
            cipher = EVP_des_ecb();
        } else if (mode == "AES_CBC") {
            cipher = EVP_aes_256_cbc();
        } // Add other modes as needed
    }

    void fetchKeyFromKeyStore(const std::string& keyId) {
        try {
            auto kmsResponse = kmsClient->GetSecretValue(Aws::KMS::Model::GetSecretValueRequest().WithKeyId(keyId));
            key = kmsResponse.GetResult().GetSecretString();
        } catch (const Aws::Exception& e) {
            std::cerr << "AWS KMS error: " << e.what() << std::endl;
            try {
                auto vaultResponse = vaultClient->Read("secret/data/" + keyId);
                key = vaultResponse.GetData()["data"]["key"];
            } catch (const HashiCorp::Vault::Exception& e) {
                std::cerr << "HashiCorp Vault error: " << e.what() << std::endl;
                // Fallback mechanism
                generateRandomKey();
            }
        }
    }

    void generateRandomKey() {
        if (!RAND_bytes(reinterpret_cast<unsigned char*>(&key), sizeof(key))) {
            throw std::runtime_error("Failed to generate random key");
        }
    }

    EVP_CIPHER* cipher = nullptr;
    std::string key;
    std::shared_ptr<Aws::KMS::KMSClient> kmsClient;
    std::shared_ptr<HashiCorp::Vault::VaultClient> vaultClient;
};

