// C Library Code

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int current_state;
    pthread_mutex_t mutex;
} StateMachine;

void init_state_machine(StateMachine *machine, int initial_state) {
    machine->current_state = initial_state;
    pthread_mutex_init(&machine->mutex, NULL);
}

void update_state(StateMachine *machine, int new_state) {
    pthread_mutex_lock(&machine->mutex);
    machine->current_state = new_state;
    pthread_mutex_unlock(&machine->mutex);
}

int get_current_state(const StateMachine *machine) {
    int state;
    pthread_mutex_lock(&machine->mutex);
    state = machine->current_state;
    pthread_mutex_unlock(&machine->mutex);
    return state;
}
