typedef struct {
    char *access_token;
    int expires_in;
    char *token_type;
    char *refresh_token;
} OAuth2Token;

int validate_token(const OAuth2Token *token) {
    if (strcmp(token->token_type, "Bearer") != 0 || token->expires_in <= 0) {
        return 0;
    }
    // Check for presence of required fields
    return (token->access_token != NULL && token->expires_in > 0 && token->token_type != NULL);
}

void compute_hashes(const char *json, unsigned char *md5_hash, unsigned char *sha256_hash) {
    MD5_CTX md5_ctx;
    SHA256_CTX sha256_ctx;

    MD5_Init(&md5_ctx);
    MD5_Update(&md5_ctx, json, strlen(json));
    MD5_Final(md5_hash, &md5_ctx);

    SHA256_Init(&sha256_ctx);
    SHA256_Update(&sha256_ctx, json, strlen(json));
    SHA256_Final(sha256_hash, &sha256_ctx);
}

void generate_timestamp(char *timestamp) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, 30, "%Y-%m-%d %H:%M:%S", tm_info);
}

int main() {
    OAuth2Token token = {"your_access_token_here", 3600, "Bearer", "optional_refresh_token"};

    if (!validate_token(&token)) {
        printf("Invalid token.\n");
        return 1;
    }

    unsigned char md5_hash[MD5_DIGEST_LENGTH];
    unsigned char sha256_hash[SHA256_DIGEST_LENGTH];
    char timestamp[30];

    compute_hashes("{\"access_token\": \"your_access_token_here\", \"expires_in\": 3600, \"token_type\": \"Bearer\", \"refresh_token\": \"optional_refresh_token\"}", md5_hash, sha256_hash);
    generate_timestamp(timestamp);

    printf("MD5: ");
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        printf("%02x", md5_hash[i]);
    }
    printf("\nSHA-256: ");
    for (int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
        printf("%02x", sha256_hash[i]);
    }
    printf("\nTimestamp: %s\n", timestamp);

    return 0;
}
```

