#include <iostream>
#include <thread>
#include <atomic>
#include <chrono>
#include <unordered_map>
#include <mutex>

class CombatDecisionEngine {
private:
    std::atomic<bool> running;
    std::unordered_map<std::string, int> attackCooldowns;
    std::mutex cooldownMutex;

public:
    CombatDecisionEngine() : running(true) {}

    void startCombat() {
        while (running) {
            // Asynchronously select and execute attacks
            for (const auto& [attackName, _] : attackCooldowns) {
                if (canAttack(attackName)) {
                    executeAttack(attackName);
                }
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }
    }

    bool canAttack(const std::string& attackName) {
        std::lock_guard<std::mutex> lock(cooldownMutex);
        auto it = attackCooldowns.find(attackName);
        if (it != attackCooldowns.end()) {
            return it->second <= 0;
        }
        return true;
    }

    void executeAttack(const std::string& attackName) {
        std::lock_guard<std::mutex> lock(cooldownMutex);
        auto it = attackCooldowns.find(attackName);
        if (it != attackCooldowns.end()) {
            it->second -= 10; // Simulate cooldown reduction
            std::cout << "Executing " << attackName << std::endl;
        }
    }

    void updateCooldown(const std::string& attackName, int newCooldown) {
        std::lock_guard<std::mutex> lock(cooldownMutex);
        attackCooldowns[attackName] = newCooldown;
    }

    void stopCombat() {
        running = false;
    }
};

int main() {
    CombatDecisionEngine engine;
    std::thread combatThread(&CombatDecisionEngine::startCombat, &engine);

    // Simulate cooldown updates
    std::this_thread::sleep_for(std::chrono::seconds(5));
    engine.updateCooldown("BasicSlash", 20);
    engine.updateCooldown("HeavyBlow", 30);

    // Stop combat after 10 seconds
    std::this_thread::sleep_for(std::chrono::seconds(10));
    engine.stopCombat();
    combatThread.join();

    return 0;
}
