#include <openssl/evp.h>
#include <openssl/pbkdf2.h>
#include <openssl/rand.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define PBKDF2_ITERATIONS 100000
#define SALT_LEN 16
#define KEY_LEN 32
#define NONCE_LEN 12

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[KEY_LEN];
    unsigned char salt[SALT_LEN];
} AES_GCM_CTX;

int aes_gcm_init(AES_GCM_CTX **ctx, const char *password) {
    if (strlen(password) < 8) {
        fprintf(stderr, "Password is too weak.\n");
        return -1;
    }

    EVP_CIPHER_CTX *new_ctx = EVP_CIPHER_CTX_new();
    if (!new_ctx) {
        fprintf(stderr, "Failed to create new context.\n");
        return -1;
    }

    unsigned char salt[SALT_LEN];
    if (RAND_bytes(salt, SALT_LEN) != 1) {
        fprintf(stderr, "Failed to generate random salt.\n");
        EVP_CIPHER_CTX_free(new_ctx);
        return -1;
    }

    unsigned char key[KEY_LEN];
    if (!PKCS5_PBKDF2_HMAC(password, strlen(password), salt, SALT_LEN, PBKDF2_ITERATIONS, EVP_sha256(), KEY_LEN, key)) {
        fprintf(stderr, "Failed to derive encryption key.\n");
        EVP_CIPHER_CTX_free(new_ctx);
        return -1;
    }

    *ctx = (AES_GCM_CTX *)malloc(sizeof(AES_GCM_CTX));
    if (!(*ctx)) {
        fprintf(stderr, "Memory allocation failed.\n");
        EVP_CIPHER_CTX_free(new_ctx);
        return -1;
    }
    (*ctx)->ctx = new_ctx;
    memcpy((*ctx)->key, key, KEY_LEN);
    memcpy((*ctx)->salt, salt, SALT_LEN);

    return 0;
}

int aes_gcm_encrypt(AES_GCM_CTX *ctx, const unsigned char *plaintext, int plaintext_len,
                    unsigned char **ciphertext, int *ciphertext_len) {
    if (!EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_gcm(), NULL, ctx->key, NULL)) {
        fprintf(stderr, "Encryption initialization failed.\n");
        return -1;
    }

    if (!EVP_CIPHER_CTX_ctrl(ctx->ctx, EVP_CTRL_GCM_SET_IVLEN, NONCE_LEN, NULL)) {
        fprintf(stderr, "Setting IV length failed.\n");
        return -1;
    }

    unsigned char iv[NONCE_LEN];
    if (RAND_bytes(iv, NONCE_LEN) != 1) {
        fprintf(stderr, "Failed to generate random IV.\n");
        return -1;
    }

    if (!EVP_EncryptInit_ex(ctx->ctx, NULL, NULL, NULL, iv)) {
        fprintf(stderr, "IV initialization failed.\n");
        return -1;
    }

    if (ciphertext_len) *ciphertext_len = plaintext_len + EVP_CIPHER_block_size(EVP_aes_256_gcm());
    *ciphertext = (unsigned char *)malloc(*ciphertext_len);
    if (!*ciphertext) {
        fprintf(stderr, "Memory allocation failed.\n");
        return -1;
    }

    int len;
    if (!EVP_EncryptUpdate(ctx->ctx, *ciphertext, &len, plaintext, plaintext_len)) {
        fprintf(stderr, "Encryption update failed.\n");
        free(*ciphertext);
        return -1;
    }
    memmove(*ciphertext + len, ciphertext, EVP_CIPHER_block_size(EVP_aes_256_gcm()));

    unsigned char tag[EVP_GCM_TAG_LEN];
    if (!EVP_EncryptFinal_ex(ctx->ctx, *ciphertext + len, &len)) {
        fprintf(stderr, "Encryption finalization failed.\n");
        free(*ciphertext);
        return -1;
    }
    memmove(*ciphertext + len, tag, EVP_GCM_TAG_LEN);

    return 0;
}

int aes_gcm_decrypt(AES_GCM_CTX *ctx, const unsigned char *ciphertext, int ciphertext_len,
                    unsigned char **plaintext, int *plaintext_len) {
    if (!EVP_DecryptInit_ex(ctx->ctx, EVP_aes_256_gcm(), NULL, ctx->key, NULL)) {
        fprintf(stderr, "Decryption initialization failed.\n");
        return -1;
    }

    if (!EVP_CIPHER_CTX_ctrl(ctx->ctx, EVP_CTRL_GCM_SET_IVLEN, NONCE_LEN, NULL)) {
        fprintf(stderr, "Setting IV length failed.\n");
        return -1;
    }

    unsigned char iv[NONCE_LEN];
    memcpy(iv, ciphertext + ciphertext_len - EVP_GCM_TAG_LEN - NONCE_LEN, NONCE_LEN);

    if (!EVP_EncryptInit_ex(ctx->ctx, NULL, NULL, NULL, iv)) {
        fprintf(stderr, "IV initialization failed.\n");
        return -1;
    }

    *plaintext = (unsigned char *)malloc(ciphertext_len - EVP_GCM_TAG_LEN);
    if (!*plaintext) {
        fprintf(stderr, "Memory allocation failed.\n");
        return -1;
    }

    int len;
    if (!EVP_DecryptUpdate(ctx->ctx, *plaintext, &len, ciphertext, ciphertext_len - EVP_GCM_TAG_LEN)) {
        fprintf(stderr, "Decryption update failed.\n");
        free(*plaintext);
        return -1;
    }
    memmove(*plaintext + len, ciphertext + ciphertext_len - EVP_GCM_TAG_LEN, EVP_GCM_TAG_LEN);

    unsigned char tag[EVP_GCM_TAG_LEN];
    memcpy(tag, *plaintext + *plaintext_len - EVP_GCM_TAG_LEN, EVP_GCM_TAG_LEN);
    if (!EVP_CIPHER_CTX_ctrl(ctx->ctx, EVP_CTRL_GCM_SET_TAG, EVP_GCM_TAG_LEN, tag)) {
        fprintf(stderr, "Setting tag failed.\n");
        free(*plaintext);
        return -1;
    }

    int result = EVP_DecryptFinal_ex(ctx->ctx, *plaintext + len, &len);
    if (!result) {
        fprintf(stderr, "Decryption finalization failed.\n");
        free(*plaintext);
        return -1;
    }
    *plaintext_len = len;

    return 0;
}

void aes_gcm_cleanup(AES_GCM_CTX *ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx);
}
