#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <iostream>

class CryptoLibrary {
public:
    CryptoLibrary() : stop(false) {}

    ~CryptoLibrary() {
        stop = true;
        cv.notify_all();
        for (auto& thread : threads) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    void addTask(const std::function<void()>& task) {
        {
            std::unique_lock<std::mutex> lock(mutex);
            tasks.push_back(task);
        }
        cv.notify_one();
    }

private:
    bool stop;
    std::vector<std::thread> threads;
    std::queue<std::function<void()>> tasks;
    std::mutex mutex;
    std::condition_variable cv;

    void worker() {
        while (true) {
            std::function<void()> task;
            {
                std::unique_lock<std::mutex> lock(mutex);
                cv.wait(lock, [this]{ return stop || !tasks.empty(); });
                if (stop && tasks.empty()) {
                    return;
                }
                task = std::move(tasks.front());
                tasks.pop();
            }
            task();
        }
    }

    void startWorkers(size_t numThreads) {
        for (size_t i = 0; i < numThreads; ++i) {
            threads.emplace_back(&CryptoLibrary::worker, this);
        }
    }
};

int main() {
    CryptoLibrary library;
    library.startWorkers(10);

    // Add tasks to the library
    library.addTask([](){
        // Example task: AES encryption
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        const unsigned char key[32] = {/* ... */};
        const unsigned char iv[16] = {/* ... */};
        unsigned char plaintext[1024], ciphertext[1024];
        int len, plen;

        EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
        EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, 1024);
        plen = len;
        EVP_EncryptFinal_ex(ctx, ciphertext + len, &len);
        plen += len;

        EVP_CIPHER_CTX_free(ctx);
    });

    // Add more tasks as needed

    return 0;
}
