#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char *data;
    int key;
    int status;
} Entry;

typedef struct {
    Entry **entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} Collection;

Collection* collection_init() {
    Collection *col = (Collection *)malloc(sizeof(Collection));
    if (!col) return NULL;

    col->entries = (Entry **)calloc(16, sizeof(Entry *));
    if (!col->entries) {
        free(col);
        return NULL;
    }

    col->count = 0;
    col->capacity = 16;
    pthread_mutex_init(&col->lock, NULL);

    return col;
}

void collection_free(Collection *col) {
    if (!col) return;

    for (size_t i = 0; i < col->count; i++) {
        free(col->entries[i]->data);
        free(col->entries[i]);
    }

    free(col->entries);
    pthread_mutex_destroy(&col->lock);
    free(col);
}

void collection_add(Collection *col, int key, const char *data) {
    pthread_mutex_lock(&col->lock);

    if (col->count >= col->capacity) {
        size_t new_capacity = col->capacity * 2;
        Entry **new_entries = (Entry **)realloc(col->entries, new_capacity * sizeof(Entry *));
        if (!new_entries) {
            pthread_mutex_unlock(&col->lock);
            return;
        }

        col->entries = new_entries;
        col->capacity = new_capacity;
    }

    Entry *entry = (Entry *)malloc(sizeof(Entry));
    if (!entry) {
        pthread_mutex_unlock(&col->lock);
        return;
    }

    entry->data = strdup(data);
    if (!entry->data) {
        free(entry);
        pthread_mutex_unlock(&col->lock);
        return;
    }

    entry->key = key;
    entry->status = 1;
    col->entries[col->count++] = entry;

    pthread_mutex_unlock(&col->lock);
}

void collection_update(Collection *col, int key, const char *data) {
    pthread_mutex_lock(&col->lock);

    for (size_t i = 0; i < col->count; i++) {
        if (col->entries[i]->key == key) {
            free(col->entries[i]->data);
            col->entries[i]->data = strdup(data);
            break;
        }
    }

    pthread_mutex_unlock(&col->lock);
}

void collection_remove(Collection *col, int key) {
    pthread_mutex_lock(&col->lock);

    for (size_t i = 0; i < col->count; i++) {
        if (col->entries[i]->key == key) {
            free(col->entries[i]->data);
            free(col->entries[i]);

            while (i + 1 < col->count) {
                col->entries[i] = col->entries[i + 1];
                i++;
            }

            col->count--;
            break;
        }
    }

    pthread_mutex_unlock(&col->lock);
}

Entry* collection_get(Collection *col, int key) {
    pthread_mutex_lock(&col->lock);

    for (size_t i = 0; i < col->count; i++) {
        if (col->entries[i]->key == key) {
            return col->entries[i];
        }
    }

    pthread_mutex_unlock(&col->lock);
    return NULL;
}

int main() {
    Collection *col = collection_init();
    if (!col) return 1;

    collection_add(col, 1, "Hello");
    collection_add(col, 2, "World");

    Entry *entry = collection_get(col, 1);
    if (entry) {
        printf("Entry 1: %s\n", entry->data);
    }

    collection_update(col, 1, "Hi");
    entry = collection_get(col, 1);
    if (entry) {
        printf("Updated Entry 1: %s\n", entry->data);
    }

    collection_remove(col, 2);

    collection_free(col);
    return 0;
}
