// Interface for data sources
interface DataSource {
    void fetchData();
}

// Class implementing RESTful APIs integration
class APIIntegration implements DataSource {
    public void fetchData() {
        // Simulate fetching data from multiple REST APIs
        System.out.println("Fetching data from REST APIs...");
    }
}

// Interface for message queues
interface MessageQueue {
    void enqueueData(String data);
    String dequeueData();
}

// Class implementing a simple message queue
class SimpleMessageQueue implements MessageQueue {
    private Queue<String> queue = new ArrayDeque<>();

    public void enqueueData(String data) {
        queue.add(data);
        System.out.println("Enqueued data: " + data);
    }

    public String dequeueData() {
        return queue.poll();
    }
}

// Interface for database operations
interface Database {
    void saveData(String data);
}

// Class implementing database operations
class MySQLDatabase implements Database {
    @Override
    public void saveData(String data) {
        System.out.println("Saving data to MySQL: " + data);
    }
}

// Class representing the processing chain
class ProcessingChain {
    private APIIntegration apiIntegration;
    private DataSource dataSource;
    private MessageQueue messageQueue;
    private Database database;

    public ProcessingChain(APIIntegration apiIntegration, DataSource dataSource, MessageQueue messageQueue, Database database) {
        this.apiIntegration = apiIntegration;
        this.dataSource = dataSource;
        this.messageQueue = messageQueue;
        this.database = database;
    }

    public void startPipeline() {
        // Simulate real-time data processing
        new Thread(() -> {
            while (true) {
                apiIntegration.fetchData();
                String data = messageQueue.dequeueData();
                database.saveData(data);
                try {
                    Thread.sleep(45); // Simulate processing time of 50ms with some overhead
                } catch (InterruptedException e) {
                    e.printStackTrace();
                }
            }
        }).start();
    }
}
