package main

import (
	"context"
	"errors"
	"log"
	"sync/atomic"

	"github.com/go-redis/redis/v8"
)

type ForwardList struct {
	client     *redis.Client
	listName   string
	targetCache map[string]int64
}

func NewForwardList(client *redis.Client, listName string) *ForwardList {
	return &ForwardList{
		client:     client,
		listName:   listName,
		targetCache: make(map[string]int64),
	}
}

func (fl *ForwardList) insertAfterOrLog(ctx context.Context, target, newStr string) error {
	// Check cache for the position of the target
	if pos, ok := fl.targetCache[target]; ok {
		return fl.insertAtPosition(ctx, pos+1, newStr)
	}

	// If not in cache, fetch from Redis and update cache
	pos, err := fl.client.LSearch(ctx, fl.listName, "*", 0).Result()
	if err != nil {
		return err
	}
	for _, item := range pos {
		if item == target {
			atomic.StoreInt64(&fl.targetCache[target], int64(pos.Index))
			return fl.insertAtPosition(ctx, pos.Index+1, newStr)
		}
	}

	// If not found, append to the end
	_, err = fl.client.RPush(ctx, fl.listName, newStr).Result()
	return err
}

func (fl *ForwardList) insertAtPosition(ctx context.Context, pos int64, newStr string) error {
	_, err := fl.client.LInsert(ctx, fl.listName, redis.InsertAfter, pos, newStr).Result()
	return err
}

func main() {
	client := redis.NewClient(&redis.Options{
