    res.status(200).json(response);
  } catch (error) {
    console.error('Error processing transaction:', error);
    res.status(500).json({ message: 'Internal Server Error' });
  }
});

async function sendTransaction(transactionId, transactionData) {
  const gateway = paymentGateways[Object.keys(paymentGateways)[currentGatewayIndex]];
  currentGatewayIndex = (currentGatewayIndex + 1) % Object.keys(paymentGateways).length;

  const circuitBreaker = new CircuitBreaker(() => axios.post(gateway, transactionData), circuitBreakerOptions);

