class UnionFind {
    private final int[] parent;
    private final int[] rank;

    public UnionFind(int size) {
        this.parent = new int[size];
        this.rank = new int[size];
        initialize();
    }

    private void initialize() {
        for (int i = 0; i < parent.length; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    public int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX != rootY) {
            if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    }

    public List<List<Integer>> findDisjointSets() {
        Map<Integer, List<Integer>> disjointSets = new HashMap<>();
        for (int i = 0; i < parent.length; i++) {
            int root = find(i);
            disjointSets.computeIfAbsent(root, k -> new ArrayList<>()).add(i);
        }
        return new ArrayList<>(disjointSets.values());
    }
}
