#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>

// Define state constants
#define STATE_A 0
#define STATE_B 1
#define STATE_C 2

typedef void (*CallbackFunction)(int);

typedef struct {
    int currentState;
    CallbackFunction callbacks[3];
    pthread_mutex_t lock;
} StateManager;

// Initialize the state manager with default states and callbacks
void initStateManager(StateManager *manager) {
    manager->currentState = STATE_A;
    for (int i = 0; i < 3; ++i) {
        manager->callbacks[i] = NULL;
    }
    pthread_mutex_init(&manager->lock, NULL);
}

// Function to transition state with callback
void transitionState(StateManager *manager, int newState) {
    if (newState >= STATE_A && newState <= STATE_C) {
        pthread_mutex_lock(&manager->lock);
        manager->currentState = newState;
        if (manager->callbacks[newState] != NULL) {
            manager->callbacks[newState](newState);
        }
        pthread_mutex_unlock(&manager->lock);
    } else {
        fprintf(stderr, "Invalid state transition\n");
    }
}

// Register a callback function for a specific state
void registerCallback(StateManager *manager, int state, CallbackFunction callback) {
    if (state >= STATE_A && state <= STATE_C) {
        manager->callbacks[state] = callback;
    } else {
        fprintf(stderr, "Invalid state\n");
    }
}

// Example callback function
void exampleCallback(int newState) {
    printf("State transitioned to %d\n", newState);
}

int main() {
    StateManager manager;
    initStateManager(&manager);

    // Register callbacks for each state
    registerCallback(&manager, STATE_A, exampleCallback);
    registerCallback(&manager, STATE_B, exampleCallback);
    registerCallback(&manager, STATE_C, exampleCallback);

    // Simulate state transitions
    transitionState(&manager, STATE_B);
    transitionState(&manager, STATE_C);
    transitionState(&manager, STATE_A);

    return 0;
}
