                .uri(URI.create("https://api.example.com/themes/" + userId + "/" + themeId))
                .GET()
                .build();

        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
        if (response.statusCode() == 200) {
            return parseThemeFromJson(response.body());
        } else {
            throw new IOException("Failed to fetch theme");
        }
    }

