        if response.status_code == 200:
            return self.parse_theme_from_json(response.json())
        else:
            raise Exception("Failed to fetch theme")

    def parse_theme_from_json(self, json_data):
        # Parse JSON and create a Bitmap object
        return None

class CacheManager:
    def __init__(self, max_memory_size):
        self.memory_cache = {}
        self.external_theme_service = ExternalThemeService()
        self.max_memory_size = max_memory_size

    def update_theme(self, user_id, theme_id):
        try:
            bitmap = self.get_cached_theme(theme_id)
            if not bitmap:
                bitmap = self.external_theme_service.fetch_theme(userId, theme_id)
                self.cache_theme(theme_id, bitmap)
            self.apply_theme_to_user(userId, bitmap)
        except Exception as e:
            print(f"Error updating theme: {e}")

    def get_cached_theme(self, theme_id):
        return self.memory_cache.get(theme_id)

    def cache_theme(self, theme_id, bitmap):
        if len(self.memory_cache) >= self.max_memory_size:
            # Evict the least recently used item
            del self.memory_cache[next(iter(self.memory_cache))]
        self.memory_cache[theme_id] = bitmap

