package com.example.configsync.service;

import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Service;
import feign.FeignException;
import org.springframework.retry.annotation.Backoff;
import org.springframework.retry.annotation.Retryable;
import org.springframework.web.client.RestTemplate;

@Service
public class ConfigSyncService {

    private final ConfigurationRepository configRepo;
    private final ExternalSystemConnector externalSysConn;
    private final CircuitBreaker circuitBreaker;

    public ConfigSyncService(ConfigurationRepository configRepo, ExternalSystemConnector externalSysConn, CircuitBreaker circuitBreaker) {
        this.configRepo = configRepo;
        this.externalSysConn = externalSysConn;
        this.circuitBreaker = circuitBreaker;
    }

    @Scheduled(fixedRate = 60000)
    public void syncConfigs() {
        try {
            CircuitBreaker.Result<Boolean> result = circuitBreaker.execute(() -> {
                Configuration latestConfig = fetchLatestConfigFromCloud();
                compareAndApply(latestConfig);
                return true;
            });

            if (result.isSuccessful()) {
                System.out.println("Configuration synchronization successful.");
            } else {
                System.out.println("Configuration synchronization failed.");
            }
        } catch (Exception e) {
            System.err.println("Failed to execute configuration sync: " + e.getMessage());
        }
    }

    @Retryable(
        value = {FeignException.class, RestTemplate.ResourceAccessException.class},
        maxAttempts = 5,
        backoff = @Backoff(delay = 2000)
    )
    private Configuration fetchLatestConfigFromCloud() {
        return cloudApi.fetchConfigs();
    }

    private void compareAndApply(Configuration latestConfig) throws ConfigurationDiscrepancyException {
        Configuration currentConfig = configRepo.getCurrentConfig();
        if (!latestConfig.equals(currentConfig)) {
            // Apply configuration changes
            externalSysConn.applyConfigChanges(latestConfig);
            configRepo.updateCurrentConfig(latestConfig);
        }
    }

    public void triggerManualSync() {
        syncConfigs();
    }

    @CircuitBreaker(
        name = "configSync",
        fallbackMethod = "fallbackSync"
    )
    private Configuration fetchLatestConfigFromCloudWithFallback() {
        try {
            return fetchLatestConfigFromCloud();
        } catch (Exception e) {
            throw new RuntimeException("Failed to fetch config from cloud API", e);
        }
    }

    public Configuration fallbackSync(Exception e) {
        // Fallback logic if the circuit breaker opens
        System.out.println("Circuit breaker open, using cached configuration.");
        return configRepo.getCurrentConfig();
    }
}
