            factor,
            jitter,
        }
    }

    fn next_delay(&self, attempt: u32) -> std::time::Duration {
        let delay = self.base_delay * (self.factor.powi(attempt as i32));
        if self.jitter {
            delay + rand::random::<std::time::Duration>() % (delay / 2)
        } else {
            delay
        }
        .min(self.max_delay)
    }
}

