        return 1;
    }

    // Perform atomic update to token records
    if (sem_wait(sem) == -1) {
        perror("sem_wait");
        sem_close(sem);
        sem_unlink(SEMAPHORE_NAME);
        return 1;
    }
    // Token record update logic here
    if (sem_post(sem) == -1) {
        perror("sem_post");
        sem_close(sem);
        sem_unlink(SEMAPHORE_NAME);
        return 1;
    }

    // Close the semaphore and clean up
    sem_close(sem);
    sem_unlink(SEMAPHORE_NAME);

    return 0;
}
