// Import necessary modules
const express = require('express');
const bodyParser = require('body-parser');
const mongoose = require('mongoose');
const axios = require('axios');

// Initialize Express app
const app = express();
app.use(bodyParser.json());

// Connect to MongoDB
mongoose.connect('mongodb://localhost:27017/dataPipeline', { useNewUrlParser: true, useUnifiedTopology: true });

// Define a Mongoose schema for data records
const DataSchema = new mongoose.Schema({
    source: String,
    data: Object,
    timestamp: Date
});

const DataRecord = mongoose.model('DataRecord', DataSchema);

// Plugin architecture for adding or removing data processors dynamically
const plugins = {};

function loadPlugin(name, path) {
    const plugin = require(path);
    plugins[name] = plugin;
}

function unloadPlugin(name) {
    delete plugins[name];
}

// Middleware to process incoming data
app.post('/data', async (req, res) => {
    const { source, data } = req.body;

    // Create a new data record
    const newDataRecord = new DataRecord({ source, data });
    await newDataRecord.save();

    // Process the data using plugins
    for (const pluginName in plugins) {
        if (plugins.hasOwnProperty(pluginName)) {
            try {
                await plugins[pluginName](data);
            } catch (error) {
                console.error(`Error processing data with ${pluginName}:`, error);
            }
        }
    }

    res.status(200).send('Data processed successfully');
});

// Error handling middleware
app.use((err, req, res, next) => {
    console.error(err.stack);
    res.status(500).send('Something broke!');
});

// Start the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
    console.log(`Server is running on port ${PORT}`);
});
```

This code sets up a basic Node.js service using Express to handle incoming data from multiple sources. It integrates with MongoDB for storing data records and provides a plugin architecture for processing the data. The service includes error handling middleware to ensure continuous operation."]

