class OctreeNode {
public:
    std::vector<GeoPoint> points;
    std::unique_ptr<OctTreeNode> children[8];
    bool isLeaf = true;

    OctreeNode() {}

    void insert(const GeoPoint& point) {
        if (isLeaf && points.size() < 8) {
            points.push_back(point);
        } else {
            if (isLeaf) {
                split();
            }
            auto childIndex = getChildIndex(point);
            children[childIndex]->insert(point);
        }
    }

    bool query(const GeoPoint& point, double radius, std::vector<GeoPoint>& results) const {
        bool withinRadius = false;
        for (const auto& p : points) {
            if (distance(p, point) <= radius) {
                results.push_back(p);
                withinRadius = true;
            }
        }
        if (!isLeaf) {
            for (int i = 0; i < 8; ++i) {
                children[i]->query(point, radius, results);
            }
        }
        return withinRadius;
    }

private:
    void split() {
        // Implement splitting logic
