class LogAggregator {
private:
    std::vector<std::unique_ptr<LogSource>> sources;
    std::unique_ptr<LogProcessor> processor;
    std::unique_ptr<LogStore> store;
    std::atomic<bool> running;

public:
    LogAggregator() : running(false) {}

    void add_source(std::unique_ptr<LogSource> source) {
        sources.push_back(std::move(source));
    }

    void set_processor(std::unique_ptr<LogProcessor> processor) {
        this->processor = std::move(processor);
    }

    void set_store(std::unique_ptr<LogStore> store) {
        this->store = std::move(store);
    }

    void start() {
        running.store(true);
        for (auto& source : sources) {
            source->read_logs([this](const LogEntry& entry) {
                if (running.load()) {
                    processor->process(entry);
                    store->store_log(entry);
                }
            });
        }
    }

    void stop() {
        running.store(false);
        for (auto& source : sources) {
            source->stop();
        }
    }
};

class LogSource {
public:
    virtual void read_logs(std::function<void(const LogEntry&)> callback) = 0;
    virtual void stop() {}
};
