using System;
using System.Collections.Concurrent;
using System.Threading.Tasks;

public class DynamicRandomValueGenerator
{
    private ConcurrentDictionary<string, (Func<float>, Func<int>)> rangeCache = new ConcurrentDictionary<string, (Func<float>, Func<int>)>();
    private readonly string jsonFeedUrl;

    public DynamicRandomValueGenerator(string jsonFeedUrl)
    {
        this.jsonFeedUrl = jsonFeedUrl;
        LoadRangesAsync();
    }

    public float GenerateRandomFloat(string key)
    {
        var range = GetRange(key);
        return range.Item1();
    }

    public int GenerateRandomInt(string key)
    {
        var range = GetRange(key);
        return range.Item2();
    }

    private (Func<float>, Func<int>) GetRange(string key)
    {
        return rangeCache.GetOrAdd(key, LoadRangeFromFeedAsync);
    }

    private async Task<(Func<float>, Func<int>)> LoadRangeFromFeedAsync(string key)
    {
        try
        {
            var json = await FetchJsonAsync(jsonFeedUrl + "/" + key);
            // Assuming JSON format: { "minFloat": 0, "maxFloat": 1, "minInt": 0, "maxInt": 100 }
            var rangeData = Json.Parse(json);
            return (GenerateRandomFloatDelegate(rangeData.MinFloat, rangeData.MaxFloat), GenerateRandomIntDelegate(rangeData.MinInt, rangeData.MaxInt));
        }
        catch
        {
            // Retry mechanism can be implemented here if needed
            throw;
        }
    }

    private Func<float> GenerateRandomFloatDelegate(float min, float max)
    {
        return () => min + (float)new Random().NextDouble() * (max - min);
    }

    private Func<int> GenerateRandomIntDelegate(int min, int max)
    {
        return () => new Random().Next(min, max);
    }

    private async Task<string> FetchJsonAsync(string url)
    {
        // Use a library like HttpClient for fetching JSON from the URL
        using (var client = new System.Net.Http.HttpClient())
        {
            var response = await client.GetAsync(url);
            response.EnsureSuccessStatusCode();
            return await response.Content.ReadAsStringAsync();
        }
    }

    private void LoadRangesAsync()
    {
        // Periodically reload ranges in a separate task to handle dynamic updates
        Task.Run(async () =>
        {
            while (true)
            {
                try
                {
                    var keys = GetActiveKeys(); // Implement method to fetch current active keys from the feed
                    foreach (var key in keys)
                    {
                        rangeCache.TryUpdate(key, LoadRangeFromFeedAsync(key), GetRange(key));
                    }
                }
                catch
                {
                    // Handle errors and retry logic here
                }

                await Task.Delay(TimeSpan.FromSeconds(60)); // Adjust delay based on load and requirements
            }
        });
    }

    private string[] GetActiveKeys()
    {
        // Implement method to fetch current active keys from the feed
        return new string[] { "key1", "key2" }; // Placeholder example
    }
