class Attack {
public:
    int id;
    std::string description;
    int cooldown;

    Attack(int id, const std::string& desc, int cool) : id(id), description(desc), cooldown(cool) {}
};

class DynamicAttackSelector {
private:
    std::vector<Attack> attacks;
    std::unordered_map<int, std::chrono::time_point<std::chrono::system_clock>> lastUsed;
    std::mutex mtx;
    std::condition_variable cv;
    std::random_device rd;
    std::mt19937 gen;

    void updateCooldowns() {
        auto now = std::chrono::system_clock::now();
        for (auto& [id, lastTime] : lastUsed) {
            if (lastTime + std::chrono::seconds(attacks[id].cooldown) < now) {
                cv.notify_all();
            }
        }
    }

public:
    DynamicAttackSelector(const std::vector<Attack>& attacks) : attacks(attacks), gen(rd()) {
        for (int i = 0; i < attacks.size(); ++i) {
            lastUsed[i] = std::chrono::system_clock::time_point::min();
        }
        std::thread t(&DynamicAttackSelector::updateCooldowns, this);
        t.detach();
    }

    void setSeed(unsigned int seed) {
        gen.seed(seed);
    }

    Attack selectAttack() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this]() {
            for (const auto& [id, lastTime] : lastUsed) {
                if (lastTime + std::chrono::seconds(attacks[id].cooldown) <= std::chrono::system_clock::now()) {
                    return true;
                }
            }
            return false;
        });

        int id = gen() % attacks.size();
        while (lastUsed[id] + std::chrono::seconds(attacks[id].cooldown) > std::chrono::system_clock::now()) {
            id = gen() % attacks.size();
        }

        lastUsed[id] = std::chrono::system_clock::now();
        return attacks[id];
    }
};

int main() {
    DynamicAttackSelector selector({
        Attack(1, "Fireball", 3),
        Attack(2, "Ice Lance", 5),
        Attack(3, "Thunder Shock", 7)
    });

    selector.setSeed(42);

    for (int i = 0; i < 10; ++i) {
        std::cout << "Selected Attack: " << selector.selectAttack().description << std::endl;
    }

    return 0;
}
