#define MAX_THREADS 10
#define RETRY_COUNT 5

typedef struct {
    char *image_path;
    int user_id;
} ImageProcessingRequest;

void process_image(ImageProcessingRequest *request) {
    // Simulate image processing
    printf("Processing image for user %d\n", request->user_id);
    sleep(1);
}

int load_image(const char *path) {
    // Simulate loading image from storage service
    return 0; // Success
}

void save_image(const char *path, const char *data) {
    // Simulate saving image to storage service
}

void collect_analytics(ImageProcessingRequest *request, int duration) {
    // Collect analytics data
}

int retry_operation(int (*operation)(const char*), const char *path) {
    for (int i = 0; i < RETRY_COUNT; i++) {
        if (operation(path) == 0) return 0; // Success
        sleep(1 << i); // Exponential backoff
    }
    return -1; // Failure
}

void *thread_function(void *arg) {
    ImageProcessingRequest *request = (ImageProcessingRequest *)arg;
    int start_time = time(NULL);

    if (retry_operation(load_image, request->image_path) == 0) {
        process_image(request);
        retry_operation(save_image, request->image_path);
        collect_analytics(request, time(NULL) - start_time);
    } else {
        printf("Failed to load image for user %d\n", request->user_id);
    }

    free(request);
    return NULL;
}

int main() {
    pthread_t threads[MAX_THREADS];
    ImageProcessingRequest requests[MAX_THREADS];

    // Simulate receiving requests
    for (int i = 0; i < MAX_THREADS; i++) {
        requests[i].image_path = "path/to/image.jpg";
        requests[i].user_id = i;
        pthread_create(&threads[i], NULL, thread_function, &requests[i]);
    }

    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```

