#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <semaphore.h>

#define NUM_WORKERS 10

typedef struct {
    int id;
    sem_t *work_queue_sem;
    pthread_mutex_t *data_lock;
    // Other worker-specific data
} Worker;

typedef struct {
    char *data;
    size_t size;
    // Other batch-specific data
} DataBatch;

Worker workers[NUM_WORKERS];
sem_t work_queue_sem;
pthread_mutex_t data_lock;
DataBatch *batch_queue = NULL;
int queue_size = 0;

void* worker_thread(void* arg) {
    Worker *worker = (Worker*)arg;
    while (1) {
        sem_wait(worker->work_queue_sem);
        pthread_mutex_lock(&data_lock);
        if (queue_size > 0) {
            DataBatch batch = batch_queue[0];
            memmove(batch_queue, batch_queue + 1, --queue_size * sizeof(DataBatch));
            pthread_mutex_unlock(&data_lock);

            // Process the data batch
            printf("Worker %d processing data batch\n", worker->id);
            sleep(2); // Simulate processing time

            // Post-process results to analytics API
            printf("Worker %d posting processed data\n", worker->id);
        } else {
            pthread_mutex_unlock(&data_lock);
        }
    }
}

void add_batch_to_queue(DataBatch batch) {
    sem_wait(&work_queue_sem);
    pthread_mutex_lock(&data_lock);
    if (queue_size < 100) { // Limit the queue size
        batch_queue[queue_size++] = batch;
    }
    pthread_mutex_unlock(&data_lock);
    sem_post(&work_queue_sem);
}

int main() {
    sem_init(&work_queue_sem, 0, 0);
    pthread_mutex_init(&data_lock, NULL);

    for (int i = 0; i < NUM_WORKERS; i++) {
        workers[i].id = i;
        workers[i].work_queue_sem = &work_queue_sem;
        workers[i].data_lock = &data_lock;

        if (pthread_create(&workers[i].thread_id, NULL, worker_thread, &workers[i]) != 0) {
            perror("Failed to create worker thread");
            exit(EXIT_FAILURE);
        }
    }

    // Simulate adding data batches to the queue
    for (int i = 0; i < 10; i++) {
        DataBatch batch;
        batch.data = malloc(1024 * sizeof(char));
        batch.size = 1024;

        add_batch_to_queue(batch);
    }

    // Wait for all workers to finish
    for (int i = 0; i < NUM_WORKERS; i++) {
        pthread_join(workers[i].thread_id, NULL);
    }

    sem_destroy(&work_queue_sem);
    pthread_mutex_destroy(&data_lock);

    return 0;
}
