public class DeploymentManager
{
    private readonly HttpClient _httpClient;
    private string _accessToken;
    private DateTime _tokenExpiryTime;

    public DeploymentManager(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public async Task<DeploymentResult> DeployWebsiteAsync(string directoryPath, string siteName)
    {
        try
        {
            // Validate directory path
            if (!Directory.Exists(directoryPath))
                return new DeploymentResult { StatusCode = 404, Message = "Directory not found" };

            // Check for web.config file
            if (!File.Exists(Path.Combine(directoryPath, "web.config")))
                return new DeploymentResult { StatusCode = 400, Message = "Missing web.config file" };

            // Authenticate with external API
            await AuthenticateAsync();

            // Lock or use distributed transaction to handle concurrent deployments
            lock (this)
            {
                // Optimize resource usage: Cache frequently accessed data if needed
            }

            // Deploy website asynchronously
            var response = await _httpClient.PostAsync("https://api.example.com/deploy", new StringContent(siteName));
            if (response.IsSuccessStatusCode)
            {
                var deploymentId = await response.Content.ReadAsStringAsync();
                return new DeploymentResult { StatusCode = 200, DeploymentId = deploymentId };
            }
            else
            {
                return new DeploymentResult { StatusCode = response.StatusCode, Message = await response.Content.ReadAsStringAsync() };
            }
        }
        catch (Exception ex)
        {
            // Log detailed error information
            Console.Error.WriteLine(ex);
            return new DeploymentResult { StatusCode = 500, Message = "Internal server error" };
        }
    }

    private async Task AuthenticateAsync()
    {
        if (_accessToken == null || DateTime.Now >= _tokenExpiryTime)
        {
            var tokenResponse = await _httpClient.PostAsync("https://api.example.com/auth", new StringContent(""));
            if (tokenResponse.IsSuccessStatusCode)
            {
                _accessToken = await tokenResponse.Content.ReadAsStringAsync();
                _tokenExpiryTime = DateTime.UtcNow.AddHours(1); // Adjust based on actual token expiration
            }
        }
    }
}

public class DeploymentResult
{
    public int StatusCode { get; set; }
    public string Message { get; set; }
    public string DeploymentId { get; set; }
}
