import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.time.Instant;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class FileAndCommandManager {

    private static final int MAX_CONCURRENT_COMMANDS = 15;
    private static final long FILE_AGE_THRESHOLD = TimeUnit.DAYS.toMillis(7);
    private static final double DISK_SPACE_THRESHOLD = 0.15;
    private static final long TIMEOUT_SECONDS = 30;

    private ExecutorService executorService;
    private Path directoryPath;

    public FileAndCommandManager(Path directoryPath) {
        this.directoryPath = directoryPath;
        this.executorService = Executors.newFixedThreadPool(MAX_CONCURRENT_COMMANDS);
    }

    public void startMonitoring() {
        while (true) {
            try {
                for (File file : directoryPath.toFile().listFiles()) {
                    if (file != null && shouldDelete(file)) {
                        deleteFile(file);
                    }
                }
            } catch (IOException e) {
                e.printStackTrace();
            }

            try {
                TimeUnit.SECONDS.sleep(1); // Adjust polling interval as needed
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                return;
            }
        }
    }

    public void executeCommand(String command) {
        if (isDiskSpaceSufficient() && isCommandValid(command)) {
            executorService.submit(() -> {
                try {
                    Process process = Runtime.getRuntime().exec(command);
                    int exitCode = process.waitFor(TIMEOUT_SECONDS, TimeUnit.SECONDS);
                    if (exitCode != 0) {
                        logSuspiciousActivity(command, "Command execution failed with exit code: " + exitCode);
                    }
                } catch (IOException | InterruptedException e) {
                    handleException(e, command);
                }
            });
        } else {
            logSuspiciousActivity(command, "Insufficient disk space or invalid command");
        }
    }

    private boolean shouldDelete(File file) {
        long fileLastModified = file.lastModified();
        Instant now = Instant.now();
        return now.toEpochMilli() - fileLastModified > FILE_AGE_THRESHOLD;
    }

    private void deleteFile(File file) {
        try {
            Files.delete(file.toPath());
        } catch (IOException e) {
            logSuspiciousActivity("deleteFile", "Failed to delete file: " + file.getName());
        }
    }

    private boolean isDiskSpaceSufficient() {
        double freeSpace = (double) Files.getFileStore(directoryPath).getUsableSpace() / Files.getFileStore(directoryPath).getTotalSpace();
        return freeSpace >= DISK_SPACE_THRESHOLD;
    }

    private boolean isCommandValid(String command) {
        // Implement command validation logic to prevent injection attacks
        return true; // Placeholder
    }

    private void logSuspiciousActivity(String source, String message) {
        System.out.println("Suspicious Activity [" + source + "]: " + message);
    }

    private void handleException(Exception e, String command) {
        e.printStackTrace();
        logSuspiciousActivity(command, "Unhandled exception: " + e.getMessage());
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(1, TimeUnit.MINUTES)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }
}
