        archiveChannel = new TPLDataflow.ActionBlock<SensorData>(ArchiveSensorData, new TPLDataflow.UnboundedDataflowBlockOptions());

        ingestChannel.LinkTo(decodeChannel);
        decodeChannel.LinkTo(processChannel);
        processChannel.LinkTo(storeChannel.GetAddMethod());
        storeChannel.Completion.ContinueWith(_ => archiveChannel.Complete());
    }

