using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class SecureDataProcessor
{
    private readonly HttpClient _httpClient;
    private readonly byte[] _encryptionKey;
    private readonly byte[] _initializationVector;
    private readonly ConcurrentQueue<string> _messageQueue = new();
    private readonly object _queueLock = new();

    public SecureDataProcessor(string apiUrl, string encryptionKeyBase64, string ivBase64)
    {
        _httpClient = new HttpClient { BaseAddress = new Uri(apiUrl) };
        _encryptionKey = Convert.FromBase64String(encryptionKeyBase64);
        _initializationVector = Convert.FromBase64String(ivBase64);

        Task.Run(() => ProcessMessagesAsync());
    }

    public async Task AddMessageAsync(string encryptedMessage)
    {
        lock (_queueLock)
        {
            _messageQueue.Enqueue(encryptedMessage);
        }
    }

    private async Task ProcessMessagesAsync()
    {
        while (true)
        {
            if (_messageQueue.TryDequeue(out var message))
            {
                try
                {
                    var decryptedMessage = DecryptMessage(message);
                    var largestNumber = GetLargestNumber(decryptedMessage);
                    // Handle the largest number as needed
                }
                catch (Exception ex)
                {
                    // Log and handle the exception gracefully
                }
            }

            await Task.Delay(10); // Adjust delay based on load and requirements
        }
    }

    private string DecryptMessage(string encryptedBase64)
    {
        var encryptedBytes = Convert.FromBase64String(encryptedBase64);
        using (var tripleDES = new TripleDESCryptoServiceProvider
        {
            Key = _encryptionKey,
            IV = _initializationVector,
            Mode = CipherMode.CBC,
            Padding = PaddingMode.PKCS7
        })
        {
            using (var msDecrypt = new MemoryStream(encryptedBytes))
            {
                using (var csDecrypt = new CryptoStream(msDecrypt, tripleDES.CreateDecryptor(), CryptoStreamMode.Read))
                {
                    using (var srDecrypt = new StreamReader(csDecrypt))
                    {
                        return srDecrypt.ReadToEnd();
                    }
                }
            }
        }
    }

    private int GetLargestNumber(string decryptedMessage)
    {
        var numbers = decryptedMessage.Split(',').Select(int.Parse).ToArray();
        return numbers.Max();
    }
}
