```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using log4net;

public interface ILoggingService
{
    void LogInfo(string message);
    void LogError(string message, Exception ex);
}

public class Md5Hasher : IDisposable
{
    private static readonly ConcurrentDictionary<string, byte[]> _cache = new();
    private readonly ILoggingService _loggingService;
    private bool _disposed;

    public Md5Hasher(ILoggingService loggingService)
    {
        _loggingService = loggingService ?? throw new ArgumentNullException(nameof(loggingService));
    }

    public string ComputeHash(string input)
    {
        if (input == null) throw new ArgumentNullException(nameof(input));
        if (input.Length > 1024 * 1024) throw new ArgumentException("Input is too large.", nameof(input));

        byte[] hash;
        if (_cache.TryGetValue(input, out hash))
        {
            _loggingService.LogInfo($"Hash found in cache: {hash}");
            return Convert.ToBase64String(hash);
        }

        using (MD5 md5 = MD5.Create())
        {
            try
            {
                hash = md5.ComputeHash(Encoding.UTF8.GetBytes(input));
                _cache[input] = hash;
                _loggingService.LogInfo($"Computed new hash: {hash}");
            }
            catch (Exception ex)
            {
                _loggingService.LogError("Error computing hash.", ex);
                throw;
            }
        }

        return Convert.ToBase64String(hash);
    }

    public void Dispose()
    {
        if (_disposed) return;

        _cache.Clear();
        _ disposed = true;
    }
}
