using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using Newtonsoft.Json;

public class SecureDataLibrary
{
    private readonly byte[] _key;
    private readonly byte[] _iv;
    private readonly PaddingMode _paddingMode;

    public SecureDataLibrary(byte[] key, byte[] iv, PaddingMode paddingMode)
    {
        _key = key;
        _iv = iv;
        _paddingMode = paddingMode;
    }

    public T DecryptAndDeserialize<T>(byte[] encryptedData)
    {
        using (var aesGcm = Aes.Create("Aes-GCM"))
        {
            aesGcm.Key = _key;
            aesGcm.IV = _iv;
            aesGcm.Padding = _paddingMode;

            var plaintext = new byte[encryptedData.Length];
            aesGcm.Decrypt(encryptedData, 0, encryptedData.Length, ref plaintext, 0);

            return JsonConvert.DeserializeObject<T>(Encoding.UTF8.GetString(plaintext));
        }
    }

    public byte[] EncryptAndSerialize(object data)
    {
        var json = JsonConvert.SerializeObject(data);
        var plaintextBytes = Encoding.UTF8.GetBytes(json);

        using (var aesGcm = Aes.Create("Aes-GCM"))
        {
            aesGcm.Key = _key;
            aesGcm.IV = _iv;
            aesGcm.Padding = _paddingMode;

            var encryptedData = new byte[plaintextBytes.Length];
            aesGcm.Encrypt(plaintextBytes, 0, plaintextBytes.Length, ref encryptedData, 0);

            return encryptedData;
        }
    }
}

public static class Program
{
    public static void Main()
    {
        var key = Encoding.UTF8.GetBytes("Your256BitKeyHere");
        var iv = Encoding.UTF8.GetBytes("1234567890abcdef");
        var paddingMode = PaddingMode.PKCS7;

        var library = new SecureDataLibrary(key, iv, paddingMode);

        var data = new { Name = "John Doe", Age = 30 };
        var encryptedData = library.EncryptAndSerialize(data);
        Console.WriteLine("Encrypted Data: " + Convert.ToBase64String(encryptedData));

        var decryptedData = library.DecryptAndDeserialize<dynamic>(encryptedData);
        Console.WriteLine($"Decrypted Data - Name: {decryptedData.Name}, Age: {decryptedData.Age}");
    }
}
```

