import java.io.*;
import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;

public class DynamicDeserializer {
    public static <T> T deserialize(byte[] bytes, Class<T> interfaceClass) throws IOException, ClassNotFoundException {
        ByteArrayInputStream bis = new ByteArrayInputStream(bytes);
        ObjectInputStream ois = new ObjectInputStream(bis);
        return interfaceClass.cast(Proxy.newProxyInstance(
            interfaceClass.getClassLoader(),
            new Class<?>[]{interfaceClass},
            (proxy, method, args) -> {
                try {
                    Object obj = ois.readObject();
                    Method implMethod = obj.getClass().getMethod(method.getName(), method.getParameterTypes());
                    return implMethod.invoke(obj, args);
                } catch (Exception e) {
                    throw new RuntimeException("Error during deserialization or method invocation", e);
                }
            }
        ));
    }

    public static void main(String[] args) throws Exception {
        // Example usage
        byte[] serializedBytes = ...; // Obtain serialized bytes from external source
        MyInterface myInstance = deserialize(serializedBytes, MyInterface.class);
        myInstance.someMethod();
    }
}

interface MyInterface {
    void someMethod();
}
