const axios = require('axios');
const redis = require('redis');
const AWS = require('aws-sdk');

// Configuration
const app = express();
const upload = multer({ storage: multer.memoryStorage() });
const s3 = new AWS.S3({
  accessKeyId: 'YOUR_AWS_ACCESS_KEY_ID',
  secretAccessKey: 'YOUR_AWS_SECRET_ACCESS_KEY'
});
const redisClient = redis.createClient();

app.use(express.json());

// Middleware
function authenticateUser(req, res, next) {
  // Implement authentication logic here
  next();
}

function validateFileType(file) {
  const supportedTypes = ['image/jpeg', 'application/pdf', 'application/msword'];
  return supportedTypes.includes(file.mimetype);
}

function checkFileSize(file) {
  const maxSize = 5 * 1024 * 1024; // 5MB
  return file.size <= maxSize;
}

// Route for handling file uploads
app.post('/upload', authenticateUser, upload.single('file'), async (req, res) => {
  if (!validateFileType(req.file)) {
    return res.status(400).send({ message: 'Unsupported file type' });
  }
  if (!checkFileSize(req.file)) {
    return res.status(400).send({ message: 'File size exceeds limit' });
  }

  const uploadPromise = new Promise((resolve, reject) => {
    s3.upload({
      Bucket: 'your-bucket-name',
      Key: req.file.originalname,
      Body: req.file.buffer
    }, (err, data) => {
      if (err) {
        return reject(err);
      }
      resolve(data.Location);
    });
  });

  try {
    const fileUrl = await uploadPromise;
    const metadataPromise = axios.post('https://metadata-api.com/extract', { url: fileUrl });
    const [_, metadata] = await Promise.all([uploadPromise, metadataPromise]);

    // Save file and metadata to database
    res.send({ message: 'File uploaded successfully', fileUrl, metadata });
  } catch (error) {
    console.error(error);
    res.status(500).send({ message: 'Failed to upload file' });
  }
});

// Message Queue for handling concurrent requests
const queue = [];
let processing = false;

function processQueue() {
  if (queue.length === 0 || processing) return;

  processing = true;
  const task = queue.shift();

  task().finally(() => {
    processing = false;
    processQueue();
  });
}

app.post('/upload', authenticateUser, upload.single('file'), async (req, res) => {
  // Validate file type and size
  if (!validateFileType(req.file)) {
    return res.status(400).send({ message: 'Unsupported file type' });
  }
  if (!checkFileSize(req.file)) {
    return res.status(400).send({ message: 'File size exceeds limit' });
  }

  queue.push(async () => {
    try {
      const uploadPromise = new Promise((resolve, reject) => {
        s3.upload({
          Bucket: 'your-bucket-name',
          Key: req.file.originalname,
          Body: req.file.buffer
        }, (err, data) => {
          if (err) {
            return reject(err);
          }
          resolve(data.Location);
        });
      });

      const fileUrl = await uploadPromise;
      const metadataPromise = axios.post('https://metadata-api.com/extract', { url: fileUrl });
      const [_, metadata] = await Promise.all([uploadPromise, metadataPromise]);

      // Save file and metadata to database
      res.send({ message: 'File uploaded successfully', fileUrl, metadata });
    } catch (error) {
      console.error(error);
      res.status(500).send({ message: 'Failed to upload file' });
    }
  });

  processQueue();
});

// Retry logic with exponential backoff
function retryTask(task, retries = 3, delay = 1000) {
  return task().catch(err => {
    if (retries === 0) throw err;
    setTimeout(() => retryTask(task, retries - 1, delay * 2), delay);
  });
}

// Error handling
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).send({ message: 'Something broke!' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
```

