class SchemaMigrator:
    def __init__(self):
        self.version_map = {}

    def add_migration(self, old_version: str, new_version: str, migration_function):
        if old_version in self.version_map:
            raise ValueError(f"Migration from {old_version} already exists.")
        self.version_map[old_version] = migration_function

    def migrate(self, data: dict, target_version: str) -> dict:
        current_version = data.get('version', '0.0')
