NFAPI_CRC_INDICATION_PDU_T *themeCacheManager(int N, const char *log_service_url) {
    NFAPI_CRC_INDICATION_PDU_T *pdu_array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_array) {
        return NULL; // Memory allocation failed
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (int i = 0; i < N; i++) {
        // Generate cryptographically secure random number for CRCFLAG
        unsigned char crcflag;
        FILE *fp = popen("/usr/bin/openssl rand -hex 1", "r");
        if (fp) {
            fscanf(fp, "%2hhx", &crcflag);
            pclose(fp);
        } else {
            // Handle logging failure gracefully
            fprintf(stderr, "Failed to generate random number for CRCFLAG\n");
            return NULL;
        }

