        if (logPDU(&pdu_array[i], log_service_url) != 0) {
            int retries = 2;
            while (retries--) {
                if (logPDU(&pdu_array[i], log_service_url) == 0) {
                    break; // Success after retry
                }
                sleep(1); // Wait before next retry
