class TransactionService {

    @Autowired
    private PaymentGateway paymentGateway;

    @Autowired
    private CurrencyExchangeApi currencyExchangeApi;

    public String process(TransactionRequest request) throws Exception {
        // Validate and process the transaction
        if (!validateTransaction(request)) throw new Exception("Invalid transaction");

        BigDecimal amountInLocalCurrency = convertToLocalCurrency(request);

        boolean isPaymentSuccessful = paymentGateway.charge(amountInLocalCurrency, request.getCardDetails());

        if (isPaymentSuccessful) {
            saveTransactionRecord(request);
            return "Transaction processed successfully";
        } else {
            throw new Exception("Payment failed");
        }
    }

    private boolean validateTransaction(TransactionRequest request) {
        // Implement validation logic
        return true;
    }

    private BigDecimal convertToLocalCurrency(TransactionRequest request) throws Exception {
        BigDecimal exchangeRate = currencyExchangeApi.getExchangeRate(request.getCurrency());
        return request.getAmount().multiply(exchangeRate);
    }

    private void saveTransactionRecord(TransactionRequest request) {
        // Save transaction record to database
    }
}

// Define PaymentGateway and CurrencyExchangeApi interfaces

