#include <pthread.h>
#include <openssl/rand.h>

#define MAX_PDUS 1024
#define DEFAULT_THEME_DIR "/default/theme/directory"

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct ThemeCacheManager {
    NFAPI_CRC_INDICATION_PDU_T *pdus[MAX_PDUS];
    int count;
    pthread_mutex_t lock;
    char *theme_dir;
} ThemeCacheManager;

int themeCacheManager_Init(ThemeCacheManager *manager) {
    manager->count = 0;
    if (pthread_mutex_init(&manager->lock, NULL) != 0) {
        return -1; // Mutex initialization failed
    }
    manager->theme_dir = strdup(DEFAULT_THEME_DIR);
    if (!manager->theme_dir) {
        pthread_mutex_destroy(&manager->lock);
        return -2; // Memory allocation for theme directory failed
    }
    return 0;
}

int themeCacheManager_AddPDU(ThemeCacheManager *manager, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= MAX_PDUS) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // PDUs limit reached
    }
    manager->pdus[manager->count++] = pdu;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void themeCacheManager_Free(ThemeCacheManager *manager) {
    for (int i = 0; i < manager->count; i++) {
        free(manager->pdus[i]);
    }
    free(manager->theme_dir);
    pthread_mutex_destroy(&manager->lock);
}

