import boto3
from elasticsearch import Elasticsearch, helpers
from logstash_async.handler import LogstashHandler
from botocore.exceptions import NoCredentialsError

class LoggingFramework:
    def __init__(self, config):
        self.config = config
        self.es = None
        self.logstash_handler = None

    def setup(self):
        # Initialize Elasticsearch connection
        self.setup_elasticsearch()

        # Initialize Logstash handler
        self.setup_logstash()

    def setup_elasticsearch(self):
        try:
            es_host = self.config['elasticsearch']['host']
            es_port = self.config['elasticsearch']['port']
            self.es = Elasticsearch([{'host': es_host, 'port': es_port}])
        except Exception as e:
            print(f"Failed to connect to Elasticsearch: {e}")

    def setup_logstash(self):
        try:
            logstash_host = self.config['logstash']['host']
            logstash_port = self.config['logstash']['port']
            self.logstash_handler = LogstashHandler(logstash_host, logstash_port)
        except Exception as e:
            print(f"Failed to set up Logstash handler: {e}")

    def log(self, level, message):
        log_entry = {
            '@timestamp': datetime.utcnow(),
            'level': level,
            'message': message
        }

        # Log to Elasticsearch
        if self.es:
            self.es.index(index='logs', body=log_entry)

        # Log to Logstash
        if self.logstash_handler:
            self.logstash_handler.push(log_entry)

    def flush_logs(self):
        if self.logstash_handler:
            self.logstash_handler.flush()

class AWSLoggingAdapter:
    def __init__(self, logger):
        self.logger = logger

    def log(self, level, message):
        try:
            cloudwatch_client = boto3.client('logs')
            log_group_name = '/aws/lambda/my-function'
            log_stream_name = 'my-stream'

            cloudwatch_client.put_log_events(
                logGroupName=log_group_name,
                logStreamName=log_stream_name,
                logEvents=[
                    {
                        'timestamp': int(time.time() * 1000),
                        'message': f'{level} - {message}'
                    }
                ]
            )
        except NoCredentialsError:
            print("AWS credentials not available")
        except Exception as e:
            print(f"Failed to log to AWS CloudWatch: {e}")

    def flush_logs(self):
        pass  # Not needed for simple console logs
```

