#include <iostream>
#include <string>
#include <unordered_map>
#include <thread>
#include <mutex>
#include <condition_variable>

class ConfigurationManager {
public:
    static ConfigurationManager& getInstance() {
        static ConfigurationManager instance;
        return instance;
    }

    void updateConfiguration(const std::string& key, const std::string& value) {
        // Lock the mutex to ensure thread-safe updates
        std::unique_lock<std::mutex> lock(mutex_);

        // Update the configuration in memory
        configMap_[key] = value;

        // Notify waiting threads that a new configuration is available
        cv_.notify_all();
    }

    std::string getConfiguration(const std::string& key) {
        std::unique_lock<std::mutex> lock(mutex_);

        // Wait for the condition variable to be notified of a new configuration
        cv_.wait(lock, [this, &key] { return configMap_.find(key) != configMap_.end(); });

        // Return the configuration value
        return configMap_[key];
    }

private:
    ConfigurationManager() {}

    std::unordered_map<std::string, std::string> configMap_;
    std::mutex mutex_;
    std::condition_variable cv_;
};

int main() {
    ConfigurationManager& manager = ConfigurationManager::getInstance();

    // Simulate configuration updates
    std::thread updateThread([&manager]() {
        for (int i = 0; i < 10; ++i) {
            manager.updateConfiguration("config" + std::to_string(i), "value" + std::to_string(i));
            std::this_thread::sleep_for(std::chrono::milliseconds(500));
        }
    });

    // Simulate configuration retrievals
    for (int i = 0; i < 10; ++i) {
        std::cout << "Configuration for config" << i << ": " << manager.getConfiguration("config" + std::to_string(i)) << std::endl;
        std::this_thread::sleep_for(std::chrono::milliseconds(500));
    }

    updateThread.join();

    return 0;
}
