using System;
using System.Collections.Concurrent;
using System.Net.Http;
using System.Threading.Tasks;
using StackExchange.Redis;

namespace RealTimeDataGenerator
{
    public class DataGeneratorService
    {
        private readonly ConcurrentDictionary<string, RandomValueRange> _ranges = new ConcurrentDictionary<string, RandomValueRange>();
        private readonly ConnectionMultiplexer _redis;
        private readonly HttpClient _httpClient;

        public DataGeneratorService(string redisConnectionString)
        {
            _redis = ConnectionMultiplexer.Connect(redisConnectionString);
            _httpClient = new HttpClient();
        }

        public async Task UpdateRangesAsync(string tenantId, RandomValueRange range)
        {
            _ranges[tenantId] = range;
            await InvalidateCacheForTenant(tenantId);
        }

        public T GenerateRandomValue<T>(string tenantId) where T : struct
        {
            if (_ranges.TryGetValue(tenantId, out var range))
            {
                return GenerateRandomValue(range.MinValue, range.MaxValue);
            }
            throw new InvalidOperationException("No range configured for the given tenant.");
        }

        private static T GenerateRandomValue<T>(T minValue, T maxValue) where T : struct
        {
            Random random = new Random();
            if (typeof(T) == typeof(int))
                return (T)(object)random.Next((int)minValue, (int)maxValue);
            else if (typeof(T) == typeof(float))
                return (T)(object)GenerateRandomFloat(minValue, maxValue);
            else if (typeof(T) == typeof(double))
                return (T)(object)GenerateRandomDouble(minValue, maxValue);
            throw new NotSupportedException("Type not supported.");
        }

        private static T GenerateRandomFloat<T>(T minValue, T maxValue) where T : struct
        {
            Random random = new Random();
            float min = Convert.ToSingle(minValue);
            float max = Convert.ToSingle(maxValue);
            return (T)(object)(min + (max - min) * (float)random.NextDouble());
        }

        private static T GenerateRandomDouble<T>(T minValue, T maxValue) where T : struct
        {
            Random random = new Random();
            double min = Convert.ToDouble(minValue);
            double max = Convert.ToDouble(maxValue);
            return (T)(object)(min + (max - min) * random.NextDouble());
        }

        private async Task InvalidateCacheForTenant(string tenantId)
        {
            IDatabase cache = _redis.GetDatabase();
            await cache.KeyDeleteAsync($"tenant:{tenantId}:range");
        }
    }

    public class RandomValueRange
    {
        public T MinValue { get; set; }
        public T MaxValue { get; set; }
    }
}
