#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <unordered_map>
#include <chrono>

struct NetworkMetricData {
    std::string timestamp;
    double value;
    std::string sourceMetadata;
    std::string type;
};

class LRUCache {
private:
    struct Node {
        std::string key;
        NetworkMetricData data;
        Node* prev, * next;
        Node(const std::string& k, const NetworkMetricData& d) : key(k), data(d), prev(nullptr), next(nullptr) {}
    };

    void moveToHead(Node* node) {
        if (head == node) return;
        node->prev->next = node->next;
        if (node->next != nullptr)
            node->next->prev = node->prev;

        node->next = head;
        node->prev = nullptr;
        head->prev = node;
        head = node;
    }

public:
    LRUCache(size_t capacity) : capacity(capacity), head(nullptr), tail(nullptr) {}

    bool get(const std::string& key, NetworkMetricData& data) {
        auto it = cache.find(key);
        if (it == cache.end()) return false;

        moveToHead(it->second);
        data = it->second->data;
        return true;
    }

    void put(const std::string& key, const NetworkMetricData& data) {
        if (cache.size() >= capacity && head != nullptr) {
            auto last = tail;
            cache.erase(last->key);
            tail = last->prev;
            if (tail != nullptr)
                tail->next = nullptr;
            delete last;
        }

        Node* node = new Node(key, data);
        cache[key] = node;
        if (head == nullptr) {
            head = tail = node;
        } else {
            node->next = head;
            head->prev = node;
            head = node;
        }
    }

private:
    std::unordered_map<std::string, Node*> cache;
    Node* head, *tail;
    size_t capacity;
};

