#include <iostream>
#include <thread>
#include <mutex>
#include <queue>
#include <unordered_map>
#include <condition_variable>
#include <chrono>
#include <openssl/ssl.h>

class NetworkMetricData {
public:
    std::string source;
    std::string type;
    double value;
    std::chrono::system_clock::time_point timestamp;
};

struct LRUQueueNode {
    NetworkMetricData data;
    LRUQueueNode* prev;
    LRUQueueNode* next;
};

class LRUCache {
private:
    std::unordered_map<std::string, LRUQueueNode*> cacheMap;
    LRUQueueNode* head;
    LRUQueueNode* tail;
    int capacity;

    void moveToHead(LRUQueueNode* node) {
        if (node->prev != nullptr) {
            node->prev->next = node->next;
            if (node->next != nullptr) {
                node->next->prev = node->prev;
            } else {
                tail = node->prev;
            }
            node->prev = nullptr;
            node->next = head;
            head->prev = node;
            head = node;
        }
    }

public:
    LRUCache(int capacity) : capacity(capacity), head(nullptr), tail(nullptr) {}

    ~LRUCache() {
        while (head != nullptr) {
            LRUQueueNode* temp = head;
            head = head->next;
            delete temp;
        }
    }

    void put(const std::string& key, NetworkMetricData data) {
        if (cacheMap.find(key) == cacheMap.end()) {
            if (cacheMap.size() >= capacity) {
                cacheMap.erase(tail->data.source);
                LRUQueueNode* toDelete = tail;
                tail = tail->prev;
                if (tail != nullptr) {
                    tail->next = nullptr;
                } else {
                    head = nullptr;
                }
                delete toDelete;
            }
            LRUQueueNode* newNode = new LRUQueueNode{data, nullptr, nullptr};
            cacheMap[key] = newNode;
            if (head == nullptr) {
                head = tail = newNode;
            } else {
                newNode->next = head;
                head->prev = newNode;
                head = newNode;
            }
        } else {
            moveToHead(cacheMap[key]);
        }
    }

    NetworkMetricData get(const std::string& key) {
        if (cacheMap.find(key) != cacheMap.end()) {
            moveToHead(cacheMap[key]);
            return cacheMap[key]->data;
        }
        throw std::runtime_error("Key not found in cache");
    }
};

class networkMetricsLogger {
private:
    std::queue<NetworkMetricData> metricsQueue;
    LRUCache* cache;
    std::mutex queueMutex, cacheMutex;
    std::condition_variable queueCond;
    bool running;

public:
    networkMetricsLogger(int cacheCapacity) : cache(new LRUCache(cacheCapacity)), running(true) {
        // Start a background thread to process metrics
        std::thread([this]() {
            while (running) {
                std::unique_lock<std::mutex> lock(queueMutex);
                queueCond.wait(lock, [this] { return !metricsQueue.empty() || !running; });
                if (!running) break;
                NetworkMetricData metric = metricsQueue.front();
                metricsQueue.pop();
                lock.unlock();

                // Process the metric (e.g., send to telemetry service)
                processMetric(metric);
            }
        }).detach();
    }

    ~networkMetricsLogger() {
        running = false;
        queueCond.notify_all();
    }

    void logMetric(const NetworkMetricData& metric) {
        std::lock_guard<std::mutex> lock(queueMutex);
        metricsQueue.push(metric);
        queueCond.notify_one();
    }

    void processMetric(const NetworkMetricData& metric) {
        // Example: Simulate sending to a telemetry service
        std::unique_lock<std::mutex> cacheLock(cacheMutex);
        cache->put(metric.source, metric);
        cacheLock.unlock();

        // Simulate sending over the network (e.g., using OpenSSL)
        SSL* ssl = SSL_new(SSL_CTX_new(TLS_client_method()));
        // Perform SSL connection and send data
        SSL_free(ssl);
    }
};

int main() {
    networkMetricsLogger logger(100);

    NetworkMetricData metric;
    metric.source = "WiFi";
    metric.type = "Packet Loss";
    metric.value = 0.5;
    metric.timestamp = std::chrono::system_clock::now();

