// C Library Implementation (simplified for demonstration)

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_CONFIGS 100

typedef struct {
    char key[256];
    char value[256];
} Config;

Config configs[MAX_CONFIGS];
int config_count = 0;
pthread_mutex_t lock;

void init_config_library() {
    pthread_mutex_init(&lock, NULL);
}

void update_config(const char* key, const char* value) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < config_count; i++) {
        if (strcmp(configs[i].key, key) == 0) {
            strcpy(configs[i].value, value);
            pthread_mutex_unlock(&lock);
            return;
        }
    }
    configs[config_count].key[0] = '\0';
    strcpy(configs[config_count].key, key);
    strcpy(configs[config_count].value, value);
    config_count++;
    pthread_mutex_unlock(&lock);
}

char* get_config(const char* key) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < config_count; i++) {
        if (strcmp(configs[i].key, key) == 0) {
            char* value_copy = malloc(strlen(configs[i].value) + 1);
            strcpy(value_copy, configs[i].value);
            pthread_mutex_unlock(&lock);
            return value_copy;
        }
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}

void destroy_config_library() {
    pthread_mutex_destroy(&lock);
}
