// Define a simple configuration structure
typedef struct {
    int setting1;
    char* setting2;
} Config;

// Global configuration pointer
Config* config = NULL;
pthread_mutex_t config_lock = PTHREAD_MUTEX_INITIALIZER;

void* update_config(void* data) {
    // Simulate dynamic config update
    pthread_mutex_lock(&config_lock);
    if (config == NULL) {
        config = malloc(sizeof(Config));
    }
    config->setting1++;
    snprintf(config->setting2, 100, "Updated");
    pthread_mutex_unlock(&config_lock);

    return NULL;
}

bool validate_config() {
    // Simple validation logic
    pthread_mutex_lock(&config_lock);
    bool valid = (config != NULL) && (config->setting1 > 0) && (config->setting2 != NULL);
    pthread_mutex_unlock(&config_lock);
    return valid;
}

int main() {
    pthread_t thread_id;

    // Update config in a separate thread
    if (pthread_create(&thread_id, NULL, update_config, NULL) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return EXIT_FAILURE;
    }

    // Wait for thread completion
    pthread_join(thread_id, NULL);

    // Validate updated config
    if (validate_config()) {
        printf("Config updated successfully: setting1 = %d, setting2 = %s\n", config->setting1, config->setting2);
    } else {
        printf("Failed to validate config\n");
    }

    free(config);
    return EXIT_SUCCESS;
}
