import java.io.ObjectInputStream;

public class ByteArrayToObject {

    public static <T> T deserialize(byte[] bytes, Class<T> clazz) {
        try (ByteArrayInputStream bais = new ByteArrayInputStream(bytes);
             ObjectInputStream ois = new ObjectInputStream(bais)) {
            return clazz.cast(ois.readObject());
        } catch (IOException | ClassNotFoundException e) {
            throw new RuntimeException("Deserialization failed: " + e.getMessage(), e);
        }
    }

    public static void main(String[] args) {
        // Example usage
        try {
            byte[] serializedBytes = serialize(new MyClass("example", 42));
            MyClass deserializedObject = deserialize(serializedBytes, MyClass.class);
            System.out.println("Deserialized object: " + deserializedObject.getName() + ", " + deserializedObject.getValue());
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    // Helper method for serialization (not shown)
    private static byte[] serialize(Object obj) throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        ObjectOutputStream oos = new ObjectOutputStream(baos);
        oos.writeObject(obj);
        return baos.toByteArray();
    }
}

