int allocateAndProcessPduArray(size_t size, NFAPI_CRC_INDICATION_PDU_T **array) {
    if (size == 0 || array == NULL) {
        return -EINVAL;
    }

    *array = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*array == NULL) {
        return -ENOMEM;
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    int retry_count = 0;

    for (size_t i = 0; i < size; ++i) {
        if (pthread_mutex_lock(&lock) != 0) {
            free(*array);
            *array = NULL;
            return -EAGAIN;
        }

        (*array)[i].rx_ue_info_tag = (RX_UE_INFORMATION_TAG){};
        (*array)[i].crc_indication_rel8_tag.RNTI = rand() % 65536; // Example RNTI generation
        uint16_t crcFlag;
        while ((rand_r(&crcFlag) & 0x7FF) == 0); // Generate cryptographically secure random number for CRCFLAG

        (*array)[i].crc_indication_rel8_tag.CRCFLAG = crcFlag;

        while (retry_count < MAX_LOG_RETRIES) {
            if (logPduCreation(&(*array)[i]) == 0) {
                break;
            }
            retry_count++;
            usleep(1000); // Wait before retrying
        }

        if (retry_count >= MAX_LOG_RETRIES) {
            pthread_mutex_unlock(&lock);
            free(*array);
            *array = NULL;
            return -EIO;
        }

        pthread_mutex_unlock(&lock);
    }

    return 0;
}

void deallocatePduArray(NFAPI_CRC_INDICATION_PDU_T *array, size_t size) {
    if (array != NULL && size > 0) {
        free(array);
    }
