#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_EVENTS 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pool[MAX_EVENTS];
    int next_index;
    pthread_mutex_t lock;
} NFAPI_CRC_POOL_T;

NFAPI_CRC_POOL_T* create_crc_pool() {
    NFAPI_CRC_POOL_T *pool = malloc(sizeof(NFAPI_CRC_POOL_T));
    if (pool) {
        pool->next_index = 0;
        pthread_mutex_init(&pool->lock, NULL);
    }
    return pool;
}

int allocate_crc_event(NFAPI_CRC_POOL_T *pool, uint32_t RX_UE_INFORMATION_TAG, uint32_t RNTI, int CRCFLAG) {
    if (pool->next_index >= MAX_EVENTS) {
        return -1; // Pool is full
    }
    pthread_mutex_lock(&pool->lock);
    if (pool->next_index >= MAX_EVENTS) {
        pthread_mutex_unlock(&pool->lock);
        return -1; // Pool was full when lock was acquired
    }
    NFAPI_CRC_INDICATION_PDU_T *event = &pool->pool[pool->next_index++];
    event->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    event->RNTI = RNTI;
    event->CRCFLAG = CRCFLAG;
    pthread_mutex_unlock(&pool->lock);
    return 0; // Success
}

void free_crc_pool(NFAPI_CRC_POOL_T *pool) {
    if (pool) {
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}
