#include <thread>
#include <atomic>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <future>
#include <chrono>

// Data structure to represent incoming data from different APIs
struct HeterogeneousData {
    // Define the data fields here based on the requirements of each API
};

class StreamProcessor {
public:
    StreamProcessor(size_t numThreads) : stop(false), numActiveWorkers(0), maxLatencyThreshold(100ms) {}

    void start() {
        for (size_t i = 0; i < numThreads; ++i) {
            workers.emplace_back([this]() { workerThread(); });
        }
    }

    void stopProcessing() {
        std::unique_lock<std::mutex> lock(mutex);
        stop = true;
        condition.notify_all();
        lock.unlock();

        for (std::thread& w : workers) {
            w.join();
        }
    }

    void addData(const HeterogeneousData& data) {
        {
            std::unique_lock<std::mutex> lock(mutex);
            if (!stop) {
                dataQueue.push(data);
                condition.notify_one();
            }
        }
    }

private:
    std::vector<std::thread> workers;
    std::queue<HeterogeneousData> dataQueue;
    std::atomic<bool> stop;
    std::atomic<size_t> numActiveWorkers;
    std::mutex mutex;
    std::condition_variable condition;
    std::chrono::milliseconds maxLatencyThreshold;

    void workerThread() {
        while (true) {
            HeterogeneousData data;
            {
                std::unique_lock<std::mutex> lock(mutex);
                condition.wait(lock, [this]() { return !dataQueue.empty() || stop; });
                if (stop && dataQueue.empty()) break;
                data = dataQueue.front();
                dataQueue.pop();
            }

            // Process the data here
            process(data);

            {
                std::lock_guard<std::mutex> lock(mutex);
                --numActiveWorkers;
                condition.notify_one();
            }
        }
    }

