// Structure to hold batch data and processing result
typedef struct {
    json_object* records;
    int maxBatchSize;
    double timeoutDuration;
    const void* connectionHandle;
    json_object* config;
} BatchData;

// Function to process and persist data
json_object* processAndPersistData(json_object* inputJSON, int maxBatchSize, double timeoutDuration,
                                  const void* connectionHandle, json_object* config) {
    json_object_array_elements_iter iter;
    json_object* record;
    BatchData batch;
    pthread_t threads[maxBatchSize];
    int threadIndex = 0;

    // Initialize batch data
    batch.records = inputJSON;
    batch.maxBatchSize = maxBatchSize;
    batch.timeoutDuration = timeoutDuration;
    batch.connectionHandle = connectionHandle;
    batch.config = config;

    // Process records in batches
    json_object_array_foreach(inputJSON, &iter, record) {
        if (threadIndex >= maxBatchSize) {
            for (int i = 0; i < maxBatchSize; ++i) {
                pthread_join(threads[i], NULL);
            }
            threadIndex = 0;
        }

        // Create thread to process the current batch
        if (pthread_create(&threads[threadIndex], NULL, processBatch, &batch) != 0) {
            logError("Failed to create thread for processing records");
        } else {
            ++threadIndex;
        }
    }

    // Wait for any remaining threads to complete
    while (threadIndex > 0) {
        pthread_join(threads[--threadIndex], NULL);
    }

    return json_object_new_array();
}

// Function to process a batch of records asynchronously
void* processBatch(void* arg) {
    BatchData* batch = (BatchData*)arg;
    json_object_array_elements_iter iter;
    json_object* record;

    json_object_array_foreach(batch->records, &iter, record) {
        if (!validateRecord(record, "schema.json")) {
            logError("Invalid record schema");
            continue;
        }

        if (!persistRecord(record, batch->connectionHandle)) {
            logError("Failed to persist record");
        }
    }

    return NULL;
}

