#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <string.h>

#define MAX_COMMANDS 1000

typedef struct {
    char *command;
    int id;
    sem_t result_ready;
} Command;

Command commands[MAX_COMMANDS];
int command_count = 0;

void* execute_command(void* arg) {
    int thread_id = *(int*)arg;
    while (1) {
        for (int i = 0; i < command_count; i++) {
            if (sem_wait(&commands[i].result_ready) == 0) {
                printf("Thread %d executing command: %s\n", thread_id, commands[i].command);
                // Simulate command execution
                sleep(1);
                printf("Thread %d completed command %s\n", thread_id, commands[i].command);
            }
        }
    }
}

void submit_command(char *command) {
    if (command_count < MAX_COMMANDS) {
        commands[command_count].id = command_count;
        commands[command_count].command = strdup(command);
        sem_init(&commands[command_count].result_ready, 0, 0);
        command_count++;
    } else {
        printf("Command queue is full\n");
    }
}

void cleanup() {
    for (int i = 0; i < command_count; i++) {
        free(commands[i].command);
        sem_destroy(&commands[i].result_ready);
    }
    command_count = 0;
}

int main() {
    pthread_t threads[10];
    int thread_ids[10];

    for (int i = 0; i < 10; i++) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, execute_command, &thread_ids[i]);
    }

    submit_command("ls -l");
    submit_command("pwd");
    submit_command("whoami");

    for (int i = 0; i < command_count; i++) {
        sem_post(&commands[i].result_ready);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    cleanup();

    return 0;
}
