#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_EVENTS 10000
#define NUM_RANs 50

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T data;
    int valid;
} Event;

typedef struct {
    Event pool[MAX_EVENTS];
    sem_t available_slots[NUM_RANs];
    pthread_mutex_t lock;
} NFAPICRCPool;

NFAPICRCPool *create_pool() {
    NFAPICRCPool *pool = (NFAPICRCPool *)malloc(sizeof(NFAPICRCPool));
    if (!pool) {
        return NULL; // Handle memory allocation failure
    }

    pthread_mutex_init(&pool->lock, NULL);
    for (int i = 0; i < NUM_RANs; i++) {
        sem_init(&pool->available_slots[i], 0, MAX_EVENTS);
    }

    return pool;
}

void destroy_pool(NFAPICRCPool *pool) {
    if (!pool) {
        return; // Handle invalid input
    }

    for (int i = 0; i < NUM_RANs; i++) {
        sem_destroy(&pool->available_slots[i]);
    }
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

void submit_event(NFAPICRCPool *pool, int ran_id, NFAPI_CRC_INDICATION_PDU_T data) {
    if (!pool || ran_id < 0 || ran_id >= NUM_RANs) {
        return; // Handle invalid input
    }

    sem_wait(&pool->available_slots[ran_id]);
    pthread_mutex_lock(&pool->lock);

    for (int i = 0; i < MAX_EVENTS; i++) {
        if (!pool->pool[i].valid) {
            pool->pool[i].data = data;
            pool->pool[i].valid = 1;
            break;
        }
    }

    pthread_mutex_unlock(&pool->lock);
}

NFAPI_CRC_INDICATION_PDU_T get_event(NFAPICRCPool *pool, int ran_id) {
    if (!pool || ran_id < 0 || ran_id >= NUM_RANs) {
        NFAPI_CRC_INDICATION_PDU_T dummy;
        return dummy; // Handle invalid input
    }

    sem_wait(&pool->available_slots[ran_id]);
    pthread_mutex_lock(&pool->lock);

    for (int i = 0; i < MAX_EVENTS; i++) {
        if (pool->pool[i].valid) {
            NFAPI_CRC_INDICATION_PDU_T data = pool->pool[i].data;
            pool->pool[i].valid = 0;
            pthread_mutex_unlock(&pool->lock);
            return data;
        }
    }

    pthread_mutex_unlock(&pool->lock);
    NFAPI_CRC_INDICATION_PDU_T dummy;
    return dummy; // Handle no available events
}

int is_event_available(NFAPICRCPool *pool, int ran_id) {
    if (!pool || ran_id < 0 || ran_id >= NUM_RANs) {
        return -1; // Handle invalid input
    }

    sem_getvalue(&pool->available_slots[ran_id], &available);
    return available > 0;
}
