#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <uuid/uuid.h>

// Define record structure
typedef struct Record {
    uuid_t id;
    char type; // 'i' for integer, 's' for string, 'c' for custom structure
    union {
        int intValue;
        char* stringValue;
        void* customValue;
    } data;
    struct Record* next;
} Record;

// Function prototypes
void insertRecord(Record** head, uuid_t id, char type, void* value);
void updateRecord(Record** head, uuid_t id, char type, void* newValue);
void deleteRecord(Record** head, uuid_t id);
Record* queryRecord(Record* head, uuid_t id);

int main() {
    Record* records = NULL;

    // Example usage
    int intValue = 42;
    insertRecord(&records, (uuid_t){0}, 'i', &intValue);

    char stringValue[] = "Hello";
    insertRecord(&records, (uuid_t){1}, 's', stringValue);

    Record* foundRecord = queryRecord(records, (uuid_t){0});
    if (foundRecord) {
        printf("Found record: %d\n", *(int*)foundRecord->data.intValue);
    }

    deleteRecord(&records, (uuid_t){0});

    return 0;
}

// Function definitions
void insertRecord(Record** head, uuid_t id, char type, void* value) {
    Record* newRecord = (Record*)malloc(sizeof(Record));
    if (!newRecord) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    memcpy(newRecord->id, id, sizeof(uuid_t));
    newRecord->type = type;
    newRecord->data = *(union {int intValue; char* stringValue; void* customValue;}*)value;
    newRecord->next = *head;
    *head = newRecord;
}

void updateRecord(Record** head, uuid_t id, char type, void* newValue) {
    Record* current = *head;
    while (current != NULL) {
        if (memcmp(current->id, id, sizeof(uuid_t)) == 0) {
            current->type = type;
            current->data = *(union {int intValue; char* stringValue; void* customValue;}*)newValue;
            return;
        }
        current = current->next;
    }
}

void deleteRecord(Record** head, uuid_t id) {
    Record* current = *head;
    Record* prev = NULL;

    while (current != NULL) {
        if (memcmp(current->id, id, sizeof(uuid_t)) == 0) {
            if (prev == NULL) {
                *head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            return;
        }
        prev = current;
        current = current->next;
    }
}

Record* queryRecord(Record* head, uuid_t id) {
    Record* current = head;
    while (current != NULL) {
        if (memcmp(current->id, id, sizeof(uuid_t)) == 0) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}
