from splunklib.client import connect as splunk_connect
import aiohttp

class ModularLogger:
    def __init__(self):
        self.loggers = {
            'elk': ELKLogger(),
            'splunk': SplunkLogger(),
            'custom_api': CustomAPILogger()
        }

    async def log(self, level, message, service='elk'):
        logger.info(f"Logging to {service} with level {level}: {message}")
        await self.loggers[service].log(level, message)

class ELKLogger:
    def __init__(self):
        self.es = AsyncElasticsearch()

    async def log(self, level, message):
        body = {
            'level': level,
            'message': message
        }
        try:
            await self.es.index(index='logs', document=body)
        except Exception as e:
            logger.error(f"Failed to log to ELK: {e}")

class SplunkLogger:
    def __init__(self):
        self.service = splunk_connect(host='localhost', port=8089, username='user', password='pass')

    async def log(self, level, message):
        body = f'level={level} message={message}'
        try:
            service.indexes['logs'].submit(body)
        except Exception as e:
            logger.error(f"Failed to log to Splunk: {e}")

class CustomAPILogger:
    def __init__(self):
        self.session = aiohttp.ClientSession()

    async def log(self, level, message):
        url = 'https://api.example.com/log'
        data = {
            'level': level,
            'message': message
        }
        try:
            await self.session.post(url, json=data)
        except Exception as e:
            logger.error(f"Failed to log to custom API: {e}")

# Usage
async def main():
    logger = ModularLogger()
    await logger.log('info', 'This is an info message')
    await logger.log('error', 'This is an error message')

asyncio.run(main())
