using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;

public class NotificationManager
{
    private readonly Dictionary<string, INotificationChannel> _channels = new Dictionary<string, INotificationChannel>();
    private readonly HttpClient _httpClient;
    private readonly ISubscriptionService _subscriptionService;

    public NotificationManager(HttpClient httpClient, ISubscriptionService subscriptionService)
    {
        _httpClient = httpClient;
        _subscriptionService = subscriptionService;
    }

    public void AddChannel(string name, INotificationChannel channel)
    {
        if (_channels.ContainsKey(name))
        {
            throw new ArgumentException("Channel already exists.");
        }
        _channels[name] = channel;
    }

    public async Task SendNotificationAsync(string channelName, string message, List<string> recipients)
    {
        if (!_channels.ContainsKey(channelName))
        {
            throw new ArgumentException("Channel not found.");
        }

        var channel = _channels[channelName];
        var subscriptionPreferences = await _subscriptionService.GetSubscriptionPreferencesAsync(recipients);

        foreach (var recipient in recipients.Where(subscriptionPreferences.Contains))
        {
            try
            {
                await RetryWithExponentialBackoff(() => channel.SendAsync(message, recipient));
            }
            catch (Exception ex)
            {
                LogError(ex);
            }
        }
    }

    private async Task RetryWithExponentialBackoff(Func<Task> action, int maxRetries = 5, TimeSpan initialDelay = default)
    {
        var delay = initialDelay;
        for (int i = 0; i < maxRetries; i++)
        {
            try
            {
                await action();
                return;
            }
            catch (Exception)
            {
                if (i == maxRetries - 1) throw;
                await Task.Delay(delay);
                delay *= 2;
            }
        }
    }

    private void LogError(Exception ex)
    {
        // Implement logging logic here
        Console.Error.WriteLine($"Error: {ex.Message}");
    }
}

public interface INotificationChannel
{
    Task SendAsync(string message, string recipient);
}

public class EmailChannel : INotificationChannel
{
    public async Task SendAsync(string message, string recipient)
    {
        // Implement email sending logic here
        Console.WriteLine($"Sending email to {recipient}: {message}");
    }
}

// Additional channels like SMSChannel and PushNotificationChannel would be implemented similarly

public interface ISubscriptionService
{
    Task<HashSet<string>> GetSubscriptionPreferencesAsync(List<string> recipients);
}

// Implementation of ISubscriptionService that interacts with an external configuration service
