bool validate_oauth2_token(const char *token_json) {
    json_object *parsed_json;
    json_object *access_token_obj, *expires_in_obj, *token_type_obj, *refresh_token_obj = NULL;
    const char *access_token, *token_type;
    int expires_in;

    parsed_json = json_tokener_parse(token_json);
    if (!parsed_json) {
        return false;
    }

    // Check for required fields
    if (!json_object_object_get_ex(parsed_json, "access_token", &access_token_obj)) {
        json_object_put(parsed_json);
        return false;
    }
    if (!json_object_object_get_ex(parsed_json, "expires_in", &expires_in_obj)) {
        json_object_put(parsed_json);
        return false;
    }
    if (!json_object_object_get_ex(parsed_json, "token_type", &token_type_obj)) {
        json_object_put(parsed_json);
        return false;
    }

    // Validate field types and values
    access_token = json_object_get_string(access_token_obj);
    token_type = json_object_get_string(token_type_obj);

    if (strcmp(token_type, "Bearer") != 0) {
        json_object_put(parsed_json);
        return false;
    }

    if (!json_object_is_type(expires_in_obj, json_type_int)) {
        json_object_put(parsed_json);
        return false;
    }
    expires_in = json_object_get_int(expires_in_obj);
    if (expires_in <= 0) {
        json_object_put(parsed_json);
        return false;
    }

    // Check for optional refresh_token field
    if (json_object_object_get_ex(parsed_json, "refresh_token", &refresh_token_obj)) {
        const char *refresh_token = json_object_get_string(refresh_token_obj);
        // Additional validation for refresh_token can be added here
    }

    json_object_put(parsed_json);
    return true;
}

int main() {
    const char *token_json = "{\"access_token\":\"abc123\",\"expires_in\":3600,\"token_type\":\"Bearer\",\"refresh_token\":\"def456\"}";

    if (validate_oauth2_token(token_json)) {
        printf("Token is valid.\n");
    } else {
        printf("Token is invalid.\n");
    }

    return 0;
}
