        std::unique_lock<std::mutex> lock(mutex);
        cv.wait(lock, [this] { return availableRequests > 0; });
        availableRequests--;
        return std::make_shared<HTTP_REQUEST_PDU_T>();
    }

    void release(std::shared_ptr<HTTP_REQUEST_PDU_T>) {
        std::unique_lock<std::mutex> lock(mutex);
        if (availableRequests < maxRequests) {
            availableRequests++;
            cv.notify_one();
        }
    }

private:
    size_t maxRequests;
    std::atomic<size_t> availableRequests;
    std::mutex mutex;
    std::condition_variable cv;
};

// Thread pool for handling HTTP requests
class HTTPRequestHandler {
public:
    HTTPRequestHandler(size_t numThreads) : pool(100000), shutdown(false) {
        for (size_t i = 0; i < numThreads; ++i) {
            workers.emplace_back([this] {
                while (true) {
                    auto request = pool.get();
                    if (!request) break;
                    handleRequest(request);
                }
            });
        }
    }

    ~HTTPRequestHandler() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            shutdown = true;
        }
        cv.notify_all();
        for (auto& worker : workers) {
            worker.join();
        }
    }

    void submit(std::shared_ptr<HTTP_REQUEST_PDU_T> request) {
        pool.release(request);
    }

private:
    void handleRequest(const std::shared_ptr<HTTP_REQUEST_PDU_T>& request) {
        // Handle the HTTP request
    }

    HTTPRequestPool pool;
    bool shutdown;
    std::vector<std::thread> workers;
    std::mutex mutex;
    std::condition_variable cv;
};
