public class SecureFileUploader
{
    private readonly HttpClient _httpClient;
    private readonly string _authToken;
    private readonly string _storageServiceUrl;
    private readonly Dictionary<string, byte[]> _fileCache;

    public SecureFileUploader(string storageServiceUrl, string authToken)
    {
        _storageServiceUrl = storageServiceUrl;
        _authToken = authToken;
        _httpClient = new HttpClient
        {
            MaxResponseContentBufferSize = 1024 * 1024 // 1 MB
        };
        _fileCache = new Dictionary<string, byte[]>();
    }

    public async Task UploadFileAsync(string filePath)
    {
        var fileBytes = await GetFileBytesAsync(filePath);
        var uploadUrl = await GetUploadUrlAsync();

        var content = new ByteArrayContent(fileBytes);
        content.Headers.ContentType = MediaTypeHeaderValue.Parse("application/octet-stream");

        using (var response = await _httpClient.PutAsync(uploadUrl, content))
        {
            if (!response.IsSuccessStatusCode)
                throw new Exception($"Failed to upload file: {response.ReasonPhrase}");
        }
    }

    private async Task<byte[]> GetFileBytesAsync(string filePath)
    {
        if (_fileCache.ContainsKey(filePath))
            return _fileCache[filePath];

        using (var stream = File.OpenRead(filePath))
        using (var memoryStream = new MemoryStream())
        {
            await stream.CopyToAsync(memoryStream);
            var fileBytes = memoryStream.ToArray();
            _fileCache[filePath] = fileBytes;
            return fileBytes;
        }
    }

    private async Task<string> GetUploadUrlAsync()
    {
        // Simulate getting upload URL from external API
        return "https://storage.example.com/upload";
    }
}
