// Include necessary headers
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <atomic>
#include <memory>
#include <functional>
#include <stdexcept>

// Define CUSTOM_EVENT_T structure
struct CUSTOM_EVENT_T {
    // Event data members
};

// Forward declare the EventManager class
class EventManager;

// EventQueue class for managing events
class EventQueue {
public:
    EventQueue(size_t capacity) : capacity_(capacity), buffer_(capacity), head_(0), tail_(0), count_(0) {}

    void enqueue(const CUSTOM_EVENT_T& event);
    bool dequeue(CUSTOM_EVENT_T& event);

private:
    size_t capacity_;
    std::vector<CUSTOM_EVENT_T> buffer_;
    size_t head_;
    size_t tail_;
    size_t count_;
    mutable std::mutex mutex_;
    std::condition_variable not_full_;
    std::condition_variable not_empty_;
};

// EventManager class managing the dynamic pool of CUSTOM_EVENT_T structures
class EventManager {
public:
    EventManager(size_t maxEvents, size_t numEnvironments)
        : maxEvents_(maxEvents), numEnvironments_(numEnvironments),
          eventQueues_(numEnvironments_),
          workerThreads_(numEnvironments_) {
        for (size_t i = 0; i < numEnvironments_; ++i) {
            eventQueues_[i] = std::make_unique<EventQueue>(maxEvents / numEnvironments_);
            startWorker(i);
        }
    }

    ~EventManager() {
        stopWorkers();
    }

    void enqueueEvent(size_t environment, const CUSTOM_EVENT_T& event) {
        if (environment >= numEnvironments_) {
            throw std::invalid_argument("Invalid environment index");
        }
        eventQueues_[environment]->enqueue(event);
    }

private:
    size_t maxEvents_;
    size_t numEnvironments_;
    std::vector<std::unique_ptr<EventQueue>> eventQueues_;
    std::vector<std::thread> workerThreads_;

    void startWorker(size_t environment) {
        workerThreads_[environment] = std::thread([this, environment]() {
            while (true) {
                CUSTOM_EVENT_T event;
                if (eventQueues_[environment]->dequeue(event)) {
                    // Process the event
                    processEvent(event);
                } else {
                    break; // Exit thread when no more events are available
                }
            }
        });
    }

    void stopWorkers() {
        for (auto& queue : eventQueues_) {
            while (!queue->dequeue(CUSTOM_EVENT_T())) {}
        }
        for (auto& thread : workerThreads_) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    void processEvent(const CUSTOM_EVENT_T& event) {
        // Process the event logic here
    }
};

// Example usage
int main() {
    EventManager manager(500000, 3);
    for (size_t i = 0; i < 150000; ++i) {
        CUSTOM_EVENT_T event;
        manager.enqueueEvent(i % 3, event);
    }
    return 0;
}
```

This code provides a basic structure for an `EventManager` class that manages multiple environments and uses an `EventQueue` to handle events. The `EventQueue` is designed with thread-safe operations using mutexes and condition variables. Worker threads are created to process events asynchronously.

Note: This is a simplified version of the framework and does not include all the advanced features such as adaptive event handling, data consistency, security, or extensive testing.']

