        var result = await _userManager.CreateAsync(user, model.Password);
        if (result.Succeeded)
        {
            // Validate user accounts from multiple providers
            foreach (var provider in _providers.Values.SelectMany(p => p))
            {
                if (!await ValidateUserAsync(provider.Name, provider.UserId))
