const fs = require('fs');
const path = require('path');
const { Worker, isMainThread, parentPort } = require('worker_threads');
const axios = require('axios');
const { Queue } = require('bull');
const { promisify } = require('util');

// Initialize the file watching queue
const watchQueue = new Queue('file_watch', 'redis://localhost:6379');

// Function to start watching directories
function startWatchingDirectories(directories) {
  directories.forEach(dir => {
    fs.watch(dir, { recursive: true }, (eventType, filename) => {
      const fullPath = path.join(dir, filename);
      watchQueue.add({ eventType, filePath: fullPath });
    });
  });
}

// Worker thread function to process file events
function workerThread() {
  if (isMainThread) {
    throw new Error('This is a worker script');
  }

  parentPort.on('message', async ({ eventType, filePath }) => {
    try {
      const eventDetails = await getFileEventDetails(eventType, filePath);
      await logEventToExternalService(eventDetails);
    } catch (error) {
      console.error(`Error processing file event: ${error.message}`);
    }
  });
}

// Function to get details of a file event
async function getFileEventDetails(eventType, filePath) {
  const stats = await promisify(fs.stat)(filePath);
  let fileSize = stats.size;
  if (eventType === 'rename' && !stats.isFile()) {
    fileSize = 0; // Treat directories as having no size for simplicity
  }

  return {
    eventType,
    filePath,
    fileSize,
    fileType: path.extname(filePath).toLowerCase()
  };
}

// Function to log event details to an external service
async function logEventToExternalService(eventDetails) {
  try {
    const response = await axios.post('https://external-logging-service.com/log', eventDetails);
    if (response.status !== 200) {
      throw new Error(`Failed to log event: ${response.statusText}`);
    }
  } catch (error) {
    console.error(`Error logging event: ${error.message}`);
    // Implement retry logic with exponential backoff
  }
}

// Start watching directories
startWatchingDirectories(['/path/to/watch1', '/path/to/watch2']);

// Spawn worker threads to process file events in parallel
if (!isMainThread) {
  workerThread();
}
```

