using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Reflection;
using System.Threading.Tasks;

public class DynamicTestRunner
{
    public async Task RunDynamicTestSuiteAsync(string modulePath, string logServiceUrl)
    {
        try
        {
            var assembly = await LoadModuleAsync(modulePath);
            var testCases = GetTestCases(assembly);

            using (var logClient = new HttpClient())
            {
                foreach (var testCase in testCases)
                {
                    var result = await ExecuteTestCaseAsync(testCase);
                    await LogTestResultAsync(logClient, logServiceUrl, testCase.Name, result);
                }
            }
        }
        catch (Exception ex)
        {
            // Handle global exceptions
            Console.Error.WriteLine($"An error occurred: {ex.Message}");
        }
    }

    private async Task<Assembly> LoadModuleAsync(string modulePath)
    {
        var assembly = null;
        while (assembly == null)
        {
            try
            {
                assembly = Assembly.LoadFrom(modulePath);
            }
            catch (Exception ex)
            {
                // Handle network instability or transient failures
                Console.WriteLine($"Failed to load module. Retrying...");
                await Task.Delay(500); // Wait before retrying
            }
        }
        return assembly;
    }

    private IEnumerable<MethodInfo> GetTestCases(Assembly assembly)
    {
        var testTypes = assembly.GetTypes().Where(t => t.GetCustomAttributes(typeof(DynamicTestAttribute), false).Any());
        var testMethods = testTypes.SelectMany(t => t.GetMethods(BindingFlags.Public | BindingFlags.Instance))
                                   .Where(m => m.GetCustomAttributes(typeof(TestMethodAttribute), false).Any());
        return testMethods;
    }

    private async Task<TestCaseResult> ExecuteTestCaseAsync(MethodInfo testCase)
    {
        try
        {
            using (var instance = Activator.CreateInstance(testCase.DeclaringType))
            {
                var result = await (Task<bool>)testCase.Invoke(instance, null);
                return new TestCaseResult { Name = testCase.Name, Success = result };
            }
        }
        catch (Exception ex)
        {
            // Handle exceptions during test execution
            Console.WriteLine($"Test failed: {ex.Message}");
            return new TestCaseResult { Name = testCase.Name, Success = false };
        }
    }

    private async Task LogTestResultAsync(HttpClient logClient, string logServiceUrl, string testName, TestCaseResult result)
    {
        var logMessage = new { TestName = testName, Result = result.Success ? "Pass" : "Fail" };
        var logContent = Newtonsoft.Json.JsonConvert.SerializeObject(logMessage);
        var content = new StringContent(logContent, System.Text.Encoding.UTF8, "application/json");

        try
        {
            await logClient.PostAsync(logServiceUrl, content);
        }
        catch (Exception ex)
        {
            // Handle logging errors
            Console.WriteLine($"Failed to log test result. Error: {ex.Message}");
        }
    }

    public class TestCaseResult
    {
        public string Name { get; set; }
        public bool Success { get; set; }
    }

    [AttributeUsage(AttributeTargets.Class)]
    public class DynamicTestAttribute : Attribute { }

    [AttributeUsage(AttributeTargets.Method)]
    public class TestMethodAttribute : Attribute { }
}
