import express from 'express';
import axios from 'axios';
import { CircuitBreaker } from 'opossum';
import * as Redis from 'ioredis';
import { loadSync } from '@esbuild/esbuild';
import * as Koa from 'koa';

const app = express();
const redis = new Redis();

// Load HTML content using esbuild
const build = loadSync({
  entryPoints: ['index.html'],
  outfile: 'dist/index.js',
});

// Define a CircuitBreaker for external API calls
const circuitBreaker = new CircuitBreaker(axios, {
  timeout: 5000,
  errorThresholdPercentage: 50,
  resetTimeout: 60000,
  onOpen() {
    console.log('Circuit breaker opened');
  },
  onClose() {
    console.log('Circuit breaker closed');
  },
});

// Define a Redis key for caching HTML content
const htmlCacheKey = 'html_content';

// Middleware to fetch and cache HTML content
app.use(async (req, res, next) => {
  try {
    let htmlContent = await redis.get(htmlCacheKey);
    if (!htmlContent) {
      const response = await axios.get('http://example.com/html');
      htmlContent = response.data;
      await redis.set(htmlCacheKey, htmlContent, 'EX', 3600); // Cache for 1 hour
    }
    req.htmlContent = htmlContent;
    next();
  } catch (error) {
    res.status(500).send('Failed to fetch HTML content');
  }
});

// Endpoint to process HTML content and identify elements matching a given CSS selector
app.get('/process', async (req, res) => {
  const { selector } = req.query;
  if (!selector) return res.status(400).send('Missing CSS selector');

  try {
    // Use esbuild to parse HTML content into DOM
    const result = build({ stdin: { contents: req.htmlContent } });
    const dom = await result.outputFiles[0].text;

    // Use querySelectorAll to identify elements matching the given CSS selector
    const elements = Array.from(dom.querySelectorAll(selector));

    // Fetch metadata for each identified element using the CircuitBreaker
    const promises = elements.map(async (element) => {
      const id = element.getAttribute('id');
      if (!id) return null;
      try {
        const response = await circuitBreaker.fetch(`http://api.example.com/metadata/${id}`);
        return { id, metadata: response.data };
      } catch (error) {
        console.error(`Failed to fetch metadata for element with id ${id}:`, error);
        return null;
      }
    });

    // Wait for all metadata fetches to complete and filter out null values
    const metadata = (await Promise.all(promises)).filter((metadata) => metadata !== null);

    res.json(metadata);
  } catch (error) {
    console.error('Failed to process HTML content:', error);
    res.status(500).send('Failed to process HTML content');
  }
});

// Start the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
