            .failureRateThreshold(50)
            .waitDurationInOpenState(Duration.ofMillis(1000))
            .build();
    }

    @Bean
    public CircuitBreakerRegistry circuitBreakerRegistry(CircuitBreakerConfig config) {
        return CircuitBreakerRegistry.of(config);
    }

    @Bean
    public StreamProcessor streamProcessor(CircuitBreakerRegistry registry) {
        return new StreamProcessor(registry);
    }

    @Bean
    public ApiClientFactory apiClientFactory(CircuitBreakerRegistry registry) {
        return new ApiClientFactory(registry, new JacksonEncoder(), new JacksonDecoder());
    }
}
