package com.streamingdata.service;

import io.github.resilience4j.circuitbreaker.CircuitBreaker;
import feign.Feign;
import feign.jackson.JacksonDecoder;
import feign.jackson.JacksonEncoder;

public class ApiClientFactory {

    private final CircuitBreakerRegistry registry;
    private final JacksonEncoder encoder;
    private final JacksonDecoder decoder;

    public ApiClientFactory(CircuitBreakerRegistry registry, JacksonEncoder encoder, JacksonDecoder decoder) {
        this.registry = registry;
        this.encoder = encoder;
        this.decoder = decoder;
    }

    public <T> T createClient(Class<T> type, String url, String apiName) {
        CircuitBreaker circuitBreaker = registry.circuitBreaker(apiName);
        return Feign.builder()
            .encoder(encoder)
            .decoder(decoder)
            .options(new Retryer.Default())
            .target(CircuitBreakerOperator.decorateSupplier(circuitBreaker, () -> 
                Feign.builder()
                    .encoder(encoder)
                    .decoder(decoder)
                    .requestInterceptor(requestTemplate -> requestTemplate.target(url))
                    .build()
                    .target(type, url)
            ));
    }
}
