package com.streamingdata.service;

import io.github.resilience4j.circuitbreaker.CircuitBreakerRegistry;
import reactor.core.publisher.Flux;

public class StreamProcessor {

    private final CircuitBreakerRegistry registry;

    public StreamProcessor(CircuitBreakerRegistry registry) {
        this.registry = registry;
    }

    public Flux<Integer> processStream(Flux<Integer> inputStream, String[] apiEndpoints) {
        return inputStream.flatMapMany(integer -> {
            for (String endpoint : apiEndpoints) {
                ApiClientFactory factory = new ApiClientFactory(registry, new JacksonEncoder(), new JacksonDecoder());
                ApiService client = factory.createClient(ApiService.class, endpoint, "api-service");
                if (client.isValidInteger(integer)) {
                    return Flux.just(integer);
                }
            }
            return Flux.empty();
        });
    }

    public static interface ApiService {
        @RequestLine("GET /validate/{integer}")
        boolean isValidInteger(@Param("integer") Integer integer);
    }
}
