        this.processor = processor;
    }

    @GetMapping("/process")
    public Mono<Integer> process(@RequestParam("input") String input) {
        Flux<Integer> inputStream = Flux.fromStream(Arrays.stream(input.split(",")))
            .map(Integer::parseInt);
        return processor.processStream(inputStream, new String[]{"http://api1.com", "http://api2.com"})
            .reduce(Integer::max)
            .switchIfEmpty(Mono.just(0));
    }
