import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.SocketChannel;
import java.util.HashMap;
import java.util.Map;

public class ChannelConnectionManager {
    private final Map<String, ConnectionFactory> factoryRegistry = new HashMap<>();
    private int maxConnections;
    private boolean isRunning;

    public void registerConnectionFactory(String id, ConnectionFactory factory) {
        factoryRegistry.put(id, factory);
    }

    public SocketChannel getConnection(String connectionId) throws IOException {
        if (!isRunning) {
            throw new IllegalStateException("ConnectionManager not running");
        }
        // Logic to check if the connection pool is full
        if (factoryRegistry.size() >= maxConnections) {
            throw new IOException("Maximum connections reached");
        }

        ConnectionFactory factory = factoryRegistry.get(connectionId);
        if (factory == null) {
            throw new IllegalArgumentException("Invalid connection ID: " + connectionId);
        }
        return factory.createChannel();
    }

    public void start(int maxConnections, ExternalConfigService configService) throws IOException {
        this.maxConnections = maxConnections;
        isRunning = true;
        // Logic to listen for configuration updates
        configService.addListener(this::onConfigUpdate);
    }

    private void onConfigUpdate(Map<String, Object> newConfig) {
        // Handle configuration update logic here
    }

    public void stop() {
        isRunning = false;
        // Logic to close all active connections
    }

    @FunctionalInterface
    public interface ConnectionFactory {
        SocketChannel createChannel() throws IOException;
    }
}

interface ExternalConfigService {
    void addListener(ConfigChangeListener listener);
}

interface ConfigChangeListener {
    void onChange(Map<String, Object> newConfig);
}
