use reqwest::{Client, Error, Response};
use std::time::Duration;
use log::{info, error};

// Define a struct for the HTTP client configuration
struct HttpClientConfig {
    base_url: String,
    timeout: Duration,
    rate_limit: Option<u32>,
}

// Implement methods for the HTTP client
impl HttpClientConfig {
    // Create a new instance of HttpClientConfig
    fn new(base_url: &str, timeout: u64, rate_limit: Option<u32>) -> Self {
        HttpClientConfig {
            base_url: base_url.to_string(),
            timeout: Duration::from_secs(timeout),
            rate_limit,
        }
    }

    // Send a GET request to the specified endpoint
    async fn get(&self, endpoint: &str) -> Result<Response, Error> {
        let client = Client::builder()
            .timeout(self.timeout)
            .build()?;

        client.get(format!("{}{}", self.base_url, endpoint))
            .send()
            .await
    }

    // Send a POST request to the specified endpoint with JSON data
    async fn post_json(&self, endpoint: &str, json_data: serde_json::Value) -> Result<Response, Error> {
        let client = Client::builder()
            .timeout(self.timeout)
            .build()?;

        client.post(format!("{}{}", self.base_url, endpoint))
            .json(&json_data)
            .send()
            .await
    }

    // Send a PUT request to the specified endpoint with JSON data
    async fn put_json(&self, endpoint: &str, json_data: serde_json::Value) -> Result<Response, Error> {
        let client = Client::builder()
            .timeout(self.timeout)
            .build()?;

        client.put(format!("{}{}", self.base_url, endpoint))
            .json(&json_data)
            .send()
            .await
    }

    // Send a DELETE request to the specified endpoint
    async fn delete(&self, endpoint: &str) -> Result<Response, Error> {
        let client = Client::builder()
            .timeout(self.timeout)
            .build()?;

        client.delete(format!("{}{}", self.base_url, endpoint))
            .send()
            .await
    }
}

// Main function to demonstrate the usage of HttpClientConfig
#[tokio::main]
async fn main() {
    let config = HttpClientConfig::new("https://api.example.com", 10, Some(100));

    match config.get("/data").await {
        Ok(response) => info!("Response status: {}", response.status()),
        Err(e) => error!("Error sending GET request: {}", e),
    }

    let json_data = serde_json::json!({
        "key": "value"
    });

    match config.post_json("/submit", json_data).await {
        Ok(response) => info!("Response status: {}", response.status()),
        Err(e) => error!("Error sending POST request: {}", e),
    }
}
