#define MAX_USERS 100

typedef struct {
    int user_id;
    char access_token[256];
    char refresh_token[256];
    sem_t semaphore;
} UserSession;

UserSession sessions[MAX_USERS];

void init_user_session(int user_id) {
    snprintf(sessions[user_id].access_token, 256, "token_%d", user_id);
    snprintf(sessions[user_id].refresh_token, 256, "refresh_token_%d", user_id);
    sem_init(&sessions[user_id].semaphore, 0, 1);
}

void* handle_user_request(void* arg) {
    int user_id = *(int*)arg;
    sem_wait(&sessions[user_id].semaphore);

    // Handle user request
    printf("User %d handling request\n", user_id);

    sem_post(&sessions[user_id].semaphore);
    return NULL;
}

int main() {
    pthread_t threads[MAX_USERS];
    int user_ids[MAX_USERS];

    for (int i = 0; i < MAX_USERS; i++) {
        init_user_session(i);
        user_ids[i] = i;
        pthread_create(&threads[i], NULL, handle_user_request, &user_ids[i]);
    }

    for (int i = 0; i < MAX_USERS; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
