# Import necessary libraries
from flask import Flask, request, jsonify
import requests
from sqlalchemy import create_engine, Table, MetaData, select, func
from redis import Redis
from functools import wraps
import time

app = Flask(__name__)

# Load environment variables for secure configurations
SUPERVISOR_ID = 'your_supervisor_id'
DATABASE_URL = 'your_database_url'
HR_API_KEY = 'your_hr_api_key'
REDIS_HOST = 'your_redis_host'

# Initialize database connection and Redis cache
engine = create_engine(DATABASE_URL)
redis_cache = Redis(host=REDIS_HOST)

# Define the Employees and Addresses tables
metadata = MetaData()
employees = Table('Employees', metadata, autoload_with=engine)
addresses = Table('Addresses', metadata, autoload_with=engine)

# Function to handle rate limiting for HR API
def ratelimit(limit, period):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            key = f"rate_limit_{request.remote_addr}"
            current_time = time.time()
            timestamps = redis_cache.lrange(key, 0, -1)
            timestamps = [float(ts.decode('utf-8')) for ts in timestamps if isinstance(ts, bytes)]
            timestamps.append(current_time)
            timestamps.sort()

            while len(timestamps) > limit:
                del timestamps[0]

            # Remove old timestamps
            redis_cache.ltrim(key, 0, limit - 1)

            if len(timestamps) >= limit and (current_time - timestamps[-1]) < period:
                return jsonify({'error': 'Rate limit exceeded'}), 429

            timestamp = str(current_time)
            redis_cache.rpush(key, timestamp)
            return func(*args, **kwargs)
        return wrapper
    return decorator

# HR API client with rate limiting and caching
@ratelimit(10, 60)  # Allow 10 requests per minute
def get_employee_data(employee_id):
    cache_key = f"employee_{employee_id}"
    if redis_cache.exists(cache_key):
        return jsonify(redis_cache.hgetall(cache_key))

    url = 'https://api.hr.com/employees'
    headers = {'Authorization': f'Bearer {HR_API_KEY}'}
    params = {'id': employee_id}

    response = requests.get(url, headers=headers, params=params)
    if response.status_code == 200:
        data = response.json()
        redis_cache.hset(cache_key, mapping=data)
        return jsonify(data)
    else:
        return jsonify({'error': 'Failed to fetch employee data'}), response.status_code

# API endpoint to retrieve employee information
@app.route('/employees/<int:employee_id>', methods=['GET'])
def get_employee(employee_id):
    supervisor_id = request.args.get('supervisor_id', SUPERVISOR_ID)
    department = request.args.get('department')

    # Fetch employee data from HR API
    employee_data = get_employee_data(employee_id)
    if employee_data.status_code != 200:
        return employee_data

    # Query local database for additional details
    connection = engine.connect()
    stmt = select(employees, addresses).where(employees.c.employee_id == employee_id)
    result = connection.execute(stmt).fetchone()

    if result:
        employee_info = {
            **employee_data.json(),
            **{
                'department': result['department'],
                'address': result['address']
            }
        }
        return jsonify(employee_info)
    else:
        return jsonify({'error': 'Employee not found'}), 404

if __name__ == '__main__':
    app.run(debug=True, host='0.0.0.0')
```

