impl RealtimeDataProcessor {
    pub fn new(config: HashMap<String, String>) -> Self {
        let client = Client::new();
        let state_machine = Arc::new(RwLock::new(state_machine::StateMachine::new()));

        RealtimeDataProcessor {
            config,
            client,
            state_machine,
        }
    }

