    std::condition_variable cv_;

    void insertRecursive(Node* node, const GeospatialData& data, int currentLevel);
    bool queryRangeRecursive(const Node* node, double minLat, double maxLat, double minLon, double maxLon, std::vector<GeospatialData>& results) const;
};

// Implementations of member functions
void DistributedOctree::initialize(int maxLevel, int branchingFactor) {
    root = new Node();
    this->maxLevel = maxLevel;
    this->branchingFactor = branchingFactor;
}

void DistributedOctree::insert(const GeospatialData& data) {
    std::lock_guard<std::mutex> lock(mutex_);
    insertRecursive(root, data, 0);
}

std::vector<GeospatialData> DistributedOctree::queryRange(double minLat, double maxLat, double minLon, double maxLon) {
    std::unique_lock<std::mutex> lock(mutex_);
    cv_.wait(lock, [this] { return !root->children.empty(); }); // Ensure the root has children
    std::vector<GeospatialData> results;
    queryRangeRecursive(root, minLat, maxLat, minLon, maxLon, results);
    return results;
}

