    }

    void addCustomProtocol() {
        // Add custom protocol source
    }

private:
    std::atomic<bool> running;
    int numThreads;
    std::vector<std::thread> threadPool;
    std::queue<LogEntry> queue;
    std::mutex mutex;
    std::condition_variable condition;
};

