#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_THREADS 100

typedef struct {
    int id;
    void (*task)(void*);
    void* arg;
} Task;

Task task_queue[MAX_THREADS];
int front = -1, rear = -1;
sem_t queue_mutex;
sem_t queue_not_empty;
sem_t queue_not_full;

void enqueue(Task task) {
    sem_wait(&queue_not_full);
    sem_wait(&queue_mutex);
    if (front == -1)
        front = 0;
    rear = (rear + 1) % MAX_THREADS;
    task_queue[rear] = task;
    sem_post(&queue_mutex);
    sem_post(&queue_not_empty);
}

Task dequeue() {
    Task task;
    sem_wait(&queue_not_empty);
    sem_wait(&queue_mutex);
    task = task_queue[front];
    if (front == rear) {
        front = -1;
        rear = -1;
    } else
        front = (front + 1) % MAX_THREADS;
    sem_post(&queue_mutex);
    sem_post(&queue_not_full);
    return task;
}

void* worker(void* arg) {
    int id = *(int*)arg;
    while (1) {
        Task task = dequeue();
        if (task.task != NULL)
            task.task(task.arg);
        else
            break;
    }
    free(arg);
    pthread_exit(NULL);
}

void init_thread_pool() {
    sem_init(&queue_mutex, 0, 1);
    sem_init(&queue_not_empty, 0, 0);
    sem_init(&queue_not_full, 0, MAX_THREADS);

    for (int i = 0; i < MAX_THREADS; i++) {
        int* id = malloc(sizeof(int));
        *id = i;
        pthread_t thread;
        pthread_create(&thread, NULL, worker, id);
    }
}

void destroy_thread_pool() {
    for (int i = 0; i < MAX_THREADS; i++) {
        Task task = {i, NULL, NULL};
        enqueue(task);
    }

    sem_destroy(&queue_mutex);
    sem_destroy(&queue_not_empty);
    sem_destroy(&queue_not_full);
}

void* process_image(void* arg) {
    // Image processing logic here
    return NULL;
}

int main() {
    init_thread_pool();

    Task task1 = {0, process_image, NULL};
    enqueue(task1);

    destroy_thread_pool();
    return 0;
}
