using System;
using System.IO;
using System.Threading.Tasks;

class WebsiteManager {
    static async Task Main(string[] args) {
        string action = "";
        string path = "";
        bool checkSyntax = false;
        string logFile = "";

        for (int i = 0; i < args.Length; i++) {
            switch (args[i]) {
                case "--manpage":
                    DisplayManPage();
                    return;
                case "-cs":
                    checkSyntax = true;
                    break;
                case "-o":
                    if (i + 1 < args.Length) {
                        logFile = args[++i];
                    }
                    break;
                default:
                    action = args[i];
                    path = args[++i];
                    break;
            }
        }

        switch (action.ToLower()) {
            case "add":
                await AddWebsite(path, logFile);
                break;
            case "update":
                await UpdateWebsite(path, logFile);
                break;
            default:
                DisplayUsage();
                return;
        }

        if (checkSyntax) {
            await CheckConfigurationSyntax(path, logFile);
        }
    }

    static void DisplayManPage() {
        Console.WriteLine("WebManager: A tool to manage and deploy websites.");
        Console.WriteLine("Usage:");
        Console.WriteLine("  WebManager add <path> -o <log_file>");
        Console.WriteLine("  WebManager update <path> -o <log_file>");
        Console.WriteLine("Options:");
        Console.WriteLine("  --manpage       Display this message.");
        Console.WriteLine("  -cs              Check the syntax of the configuration file.");
        Console.WriteLine("  -o               Output log to specified file.");
    }

    static void DisplayUsage() {
        Console.WriteLine("Invalid usage. Please use --manpage for help.");
    }

    static async Task AddWebsite(string path, string logFile) {
        // Logic to add website
        await LogAsync($"Adding website at {path}", logFile);
    }

    static async Task UpdateWebsite(string path, string logFile) {
        // Logic to update website
        await LogAsync($"Updating website at {path}", logFile);
    }

    static async Task CheckConfigurationSyntax(string path, string logFile) {
        if (File.Exists(Path.Combine(path, "web.config"))) {
            // Logic to check configuration syntax
            await LogAsync("Checking configuration syntax", logFile);
        } else {
            Console.WriteLine("No web.config file found.");
        }
    }

    static async Task LogAsync(string message, string logFile) {
        if (!string.IsNullOrEmpty(logFile)) {
            using (StreamWriter writer = new StreamWriter(logFile, true)) {
                await writer.WriteLineAsync($"{DateTime.Now}: {message}");
            }
        } else {
            Console.WriteLine(message);
        }
    }
}
