public class FileCommandManager {

    private final String directoryPath;
    private final long fileAgeThreshold; // in milliseconds
    private final int maxConcurrentCommands;
    private final long commandTimeout;
    private final double diskSpaceThreshold;

    private ExecutorService executorService;

    public FileCommandManager(String configFilePath) throws IOException {
        Properties properties = loadProperties(configFilePath);
        directoryPath = properties.getProperty("directory.path");
        fileAgeThreshold = Long.parseLong(properties.getProperty("file.age.threshold")) * 24 * 60 * 60 * 1000;
        maxConcurrentCommands = Integer.parseInt(properties.getProperty("max.concurrent.commands"));
        commandTimeout = Long.parseLong(properties.getProperty("command.timeout")) * 1000;
        diskSpaceThreshold = Double.parseDouble(properties.getProperty("disk.space.threshold"));

        executorService = Executors.newFixedThreadPool(maxConcurrentCommands);
    }

    private Properties loadProperties(String configFilePath) throws IOException {
        Properties properties = new Properties();
        try (FileInputStream fis = new FileInputStream(configFilePath)) {
            properties.load(fis);
        }
        return properties;
    }

    public void monitorDirectory() {
        ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
        scheduler.scheduleAtFixedRate(this::processFiles, 0, 60, TimeUnit.SECONDS);
    }

    private void processFiles() {
        try (Stream<Path> walk = Files.walk(Paths.get(directoryPath))) {
            walk.filter(Files::isRegularFile)
                 .filter(path -> System.currentTimeMillis() - Files.getLastModifiedTime(path).toMillis() > fileAgeThreshold)
                 .forEach(this::processFile);
        } catch (IOException e) {
            logError("Failed to process files", e);
        }
    }

    private void processFile(Path filePath) {
        if (!checkDiskSpace()) {
            logWarning("Insufficient disk space, skipping file processing");
            return;
        }

        try {
            String command = getCommandForFile(filePath);
            if (command != null) {
                Future<?> future = executorService.submit(() -> executeCommand(command));
                future.get(commandTimeout, TimeUnit.MILLISECONDS);
            }
        } catch (Exception e) {
            logError("Failed to process file " + filePath, e);
        }
    }

    private String getCommandForFile(Path filePath) {
        // Implement logic to determine the command based on file metadata or tags
        return null;
    }

    private void executeCommand(String command) {
        try {
            ProcessBuilder pb = new ProcessBuilder(command.split(" "));
            Process process = pb.start();
            int exitCode = process.waitFor();
            if (exitCode != 0) {
                logError("Command execution failed with exit code " + exitCode);
            }
        } catch (IOException | InterruptedException e) {
            logError("Failed to execute command", e);
        }
    }

    private boolean checkDiskSpace() {
        try {
            File file = new File(directoryPath);
            long totalSpace = file.getTotalSpace();
            long freeSpace = file.getFreeSpace();
            return (double) freeSpace / totalSpace >= diskSpaceThreshold;
        } catch (Exception e) {
            logError("Failed to check disk space", e);
            return false;
        }
    }

    private void logError(String message, Exception e) {
        // Implement error logging
    }

    private void logWarning(String message) {
        // Implement warning logging
    }

    public void shutdown() {
        executorService.shutdown();
    }
}
