#define MAX_RNTI 16384

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode *next;
};

typedef struct ListNode ListNode;

ListNode* createNode(const NFAPI_CRC_INDICATION_PDU_T* data) {
    ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
    if (newNode != NULL) {
        newNode->data = *data;
        newNode->next = NULL;
    }
    return newNode;
}

void appendNode(ListNode** head, const NFAPI_CRC_INDICATION_PDU_T* data) {
    ListNode* newNode = createNode(data);
    if (*head == NULL) {
        *head = newNode;
    } else {
        ListNode* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
}

void freeList(ListNode** head) {
    ListNode* current = *head;
    while (current != NULL) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int storeInDatabase(ListNode* head, const char* dbName) {
    // Simulated database storage
    printf("Storing in database: %s\n", dbName);
    while (head != NULL) {
        printf("Stored: RX_UE_INFORMATION_TAG=%u, RNTI=%hu, CRC_INDICATION_REL8_TAG=%hhu\n",
               head->data.RX_UE_INFORMATION_TAG, head->data.RNTI, head->data.CRC_INDICATION_REL8_TAG);
        head = head->next;
    }
    return 0; // Success
}

void processBatch(ListNode** head, const char* dbName) {
    ListNode* tempHead = NULL;
    while (*head != NULL) {
        appendNode(&tempHead, &(*head)->data);
        ListNode* next = (*head)->next;
        free(*head);
        *head = next;
    }
    storeInDatabase(tempHead, dbName);
    freeList(&tempHead);
}

void* manageLinkedList(void* arg) {
    ListNode* head = (ListNode*)malloc(sizeof(ListNode));
    if (head == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Populate the linked list with random data
    srand(time(NULL));
    for (int i = 0; i < MAX_RNTI; i++) {
        NFAPI_CRC_INDICATION_PDU_T data;
        data.RX_UE_INFORMATION_TAG = i + 1;
        data.RNTI = rand() % MAX_RNTI;
        data.CRC_INDICATION_REL8_TAG = (rand() % 2) ? 'Y' : 'N';
        appendNode(&head, &data);
    }

    // Process the linked list in batches
    processBatch(&head, "nfapi_database.db");

    freeList(&head);
    return NULL;
}

int main() {
    pthread_t thread;
    if (pthread_create(&thread, NULL, manageLinkedList, NULL) != 0) {
        printf("Thread creation failed\n");
        return 1;
    }

    pthread_join(thread, NULL);

    return 0;
}
