#include <iostream>
#include <string>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <thread>

// Define a simple file system node structure
struct FileSystemNode {
    std::string name;
    std::vector<FileSystemNode> children;

    FileSystemNode(const std::string& n) : name(n) {}
};

// Class to manage the hierarchical file system
class FileSystemManager {
public:
    void addFile(const std::string& parent, const std::string& child) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = findNode(root_, parent);
        if (it != root_.children.end()) {
            it->children.emplace_back(child);
        } else {
            throw std::runtime_error("Parent node not found");
        }
    }

    void removeFile(const std::string& path) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto parentPath = getParentPath(path);
        auto childName = getChildName(path);

        if (parentPath.empty()) {
            root_.children.erase(std::remove_if(root_.children.begin(), root_.children.end(),
                                                [childName](const FileSystemNode& node) { return node.name == childName; }),
                                 root_.children.end());
        } else {
            auto parentIt = findNode(root_, parentPath);
            if (parentIt != root_.children.end()) {
                parentIt->children.erase(std::remove_if(parentIt->children.begin(), parentIt->children.end(),
                                                        [childName](const FileSystemNode& node) { return node.name == childName; }),
                                         parentIt->children.end());
            } else {
                throw std::runtime_error("Parent node not found");
            }
        }
    }

private:
    FileSystemNode root_;
    std::mutex mutex_;

    auto findNode(FileSystemNode& node, const std::string& path) -> decltype(node.children.begin()) {
        if (path.empty()) return node.children.end();
        for (auto& child : node.children) {
            if (child.name == path.substr(0, path.find('/'))) {
                if (path.find('/') != std::string::npos) {
                    return findNode(child, path.substr(path.find('/') + 1));
                } else {
                    return node.children.begin() + std::distance(node.children.begin(), &node.children[std::distance(node.children.begin(), &child)]);
                }
            }
        }
        return node.children.end();
    }

    std::string getParentPath(const std::string& path) {
        size_t pos = path.find_last_of('/');
        if (pos != std::string::npos && pos > 0) {
            return path.substr(0, pos);
        }
        return "";
    }

    std::string getChildName(const std::string& path) {
        size_t pos = path.find_last_of('/');
        if (pos != std::string::npos && pos < path.size() - 1) {
            return path.substr(pos + 1);
        }
        return path;
    }
};

int main() {
    FileSystemManager fsManager;
    fsManager.addFile("/", "folder1");
    fsManager.addFile("/folder1", "file1.txt");
    fsManager.removeFile("/folder1/file1.txt");

    return 0;
}
```

