using System;
using System.Collections.Concurrent;
using System.Data.SqlClient;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;
using Azure.Storage.Blobs;
using Microsoft.Extensions.Configuration;

public class SensorDataPipeline
{
    private readonly IConfiguration _configuration;
    private readonly SqlConnection _connection;
    private readonly HttpClient _httpClient;
    private readonly BlobContainerClient _blobContainerClient;
    private readonly ConcurrentDictionary<string, ISensor> _sensorPlugins;

    public SensorDataPipeline(IConfiguration configuration)
    {
        _configuration = configuration;
        _connection = new SqlConnection(configuration.GetConnectionString("Database"));
        _httpClient = new HttpClient();
        _blobContainerClient = new BlobContainerClient(configuration.GetValue<string>("BlobStorage"), configuration.GetValue<string>("ContainerName"));
        _sensorPlugins = new ConcurrentDictionary<string, ISensor>();

        // Load sensor plugins
        var pluginPaths = Directory.GetFiles(_configuration.GetValue<string>("SensorPluginPath"), "*.dll");
        foreach (var path in pluginPaths)
        {
            var assembly = System.Reflection.Assembly.LoadFrom(path);
            var types = assembly.GetTypes().Where(t => t.GetInterfaces().Contains(typeof(ISensor)));
            foreach (var type in types)
            {
                _sensorPlugins[type.Name] = (ISensor)Activator.CreateInstance(type);
            }
        }
    }

    public async Task ProcessSensorDataAsync(Stream binaryDataStream)
    {
        using (var reader = new BinaryReader(binaryDataStream))
        {
            var sensorType = reader.ReadString();
            if (_sensorPlugins.TryGetValue(sensorType, out ISensor sensorPlugin))
            {
                var data = await sensorPlugin.DecodeAsync(reader);
                await _connection.OpenAsync();
                using (var command = _connection.CreateCommand())
                {
                    command.CommandText = "INSERT INTO SensorData (SensorType, Metrics) VALUES (@SensorType, @Metrics)";
                    command.Parameters.AddWithValue("@SensorType", sensorType);
                    command.Parameters.AddWithValue("@Metrics", data.Metrics);
                    await command.ExecuteNonQueryAsync();
                }
            }
        }
    }

    public async Task ArchiveDataAsync(string blobName)
    {
        var blobClient = _blobContainerClient.GetBlobClient(blobName);
        await blobClient.UploadAsync(await _httpClient.GetStreamAsync(_configuration.GetValue<string>("ExternalServiceUrl") + "/" + blobName));
    }
}

public interface ISensor
{
    Task<SensorData> DecodeAsync(BinaryReader reader);
}

public class SensorData
{
    public string Metrics { get; set; }
}
