// C# Component for Triple DES Decryption and Parallel Processing

using System;
using System.Collections.Generic;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class SecureCommunicator
{
    private readonly byte[] _key;
    private readonly byte[] _iv;

    public SecureCommunicator(byte[] key, byte[] iv)
    {
        _key = key;
        _iv = iv;
    }

    public async Task<List<int>> ProcessDecryptedMessages(List<string> base64Messages)
    {
        var tasks = new List<Task<List<int>>>();

        foreach (var message in base64Messages)
        {
            tasks.Add(DecryptAndProcessMessageAsync(message));
        }

        await Task.WhenAll(tasks);

        return tasks.SelectMany(t => t.Result).ToList();
    }

    private async Task<List<int>> DecryptAndProcessMessageAsync(string base64Message)
    {
        try
        {
            byte[] decryptedBytes = DecryptMessage(Encoding.UTF8.GetBytes(base64Message));
            List<int> integers = ConvertStringToIntegers(Encoding.UTF8.GetString(decryptedBytes));

            return new List<int> { FindLargestInteger(integers) };
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Decryption or processing error: {ex.Message}");
            return new List<int>();
        }
    }

    private byte[] DecryptMessage(byte[] encryptedBytes)
    {
        using (TripleDES tdes = TripleDES.Create())
        {
            tdes.Key = _key;
            tdes.IV = _iv;
            tdes.Mode = CipherMode.CBC;
            tdes.Padding = PaddingMode.PKCS7;

            using (MemoryStream msDecrypt = new MemoryStream(encryptedBytes))
            using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, tdes.CreateDecryptor(), CryptoStreamMode.Read))
            {
                byte[] decryptedBytes = new byte[encryptedBytes.Length];
                int bytesRead = csDecrypt.Read(decryptedBytes, 0, decryptedBytes.Length);
                return decryptedBytes.Take(bytesRead).ToArray();
            }
        }
    }

    private List<int> ConvertStringToIntegers(string message)
    {
        try
        {
            string[] parts = message.Split(',');
            return parts.Select(int.Parse).ToList();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Invalid data format: {ex.Message}");
            return new List<int>();
        }
    }

    private int FindLargestInteger(List<int> integers)
    {
        if (!integers.Any())
        {
            throw new InvalidOperationException("Empty message batch");
        }
        return integers.Max();
    }
}
