// C Function for Path Resolution with Backpressure

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

typedef void (*PathResolutionCallback)(const char* resolvedPath, void* userData);

void constructPath(const char* originalPath, size_t maxBufferSize, int trailingSlash, PathResolutionCallback callback, void* userData)
{
    if (originalPath == NULL || callback == NULL) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    char resolvedPath[maxBufferSize];
    snprintf(resolvedPath, maxBufferSize, "%s", originalPath);

    // Simulate path resolution logic
    for (size_t i = 0; i < strlen(resolvedPath); ++i) {
        if (resolvedPath[i] == '~') {
            strncat(resolvedPath + i, "/home/user", maxBufferSize - i);
            i += 12;
        } else if (strncmp(resolvedPath + i, "./", 2) == 0) {
            memmove(resolvedPath + i, resolvedPath + i + 2, strlen(resolvedPath + i + 2) + 1);
            --i;
        }
    }

    // Add trailing slash if requested
    if (trailingSlash && resolvedPath[strlen(resolvedPath) - 1] != '/') {
        strncat(resolvedPath, "/", maxBufferSize - strlen(resolvedPath));
    }

    callback(resolvedPath, userData);
}

// Example usage
void exampleCallback(const char* resolvedPath, void* userData)
{
    printf("Resolved Path: %s\n", resolvedPath);
}

int main() {
    const char* originalPath = "~/projects/myproject/./src/main.c";
    size_t maxBufferSize = 1024;
    int trailingSlash = 1;

    constructPath(originalPath, maxBufferSize, trailingSlash, exampleCallback, NULL);

    return 0;
}
