#include <forward_list>
#include <string>
#include <vector>
#include <functional>

void insertOrAppend(std::forward_list<std::string>& list, const std::string& target, const std::string& toInsert, external_data_source dataSource) {
    auto it = list.before_begin();
    while (it != list.end()) {
        if (*it == target) {
            it = list.insert_after(it, toInsert);
            if (!dataSource().empty()) {
                for (const auto& item : dataSource()) {
                    it = list.insert_after(it, item);
                }
                ++it; // Skip over the last inserted element
            }
            return;
        }
        ++it;
    }
    list.push_back(toInsert);
}
