    }

    // Save file to storage
    const filePath = path.join(__dirname, 'uploads', file.originalname);
    fs.writeFileSync(filePath, file.buffer);

    // Extract metadata using external API
    const metadataResponse = await axios.get('https://metadata-extraction-api.com/extract', { params: { url: filePath } });
    const metadata = metadataResponse.data;

    // Save file and metadata to database
    await client.connect();
    const db = client.db('document-management');
    const filesCollection = db.collection('files');
    const result = await filesCollection.insertOne({
      user,
      originalname: file.originalname,
      size: file.size,
      type: file.mimetype,
      metadata,
      path: filePath
    });

    done(null, { _id: result.insertedId });
  } catch (error) {
    done(error);
  }
});

app.post('/uploads', async (req, res) => {
  if (!req.user || !req.user.id) return res.status(401).send('Unauthorized');

  const job = await queue.add({ file: req.file, user: req.user.id });
  res.json({ jobId: job.id });
});

app.listen(3000, () => console.log('Server is running on port 3000'));
```

