// Import necessary libraries
const express = require('express');
const axios = require('axios');
const CircuitBreaker = require('opossum');
const { Pool } = require('pg');
const Redis = require('ioredis');

// Initialize Express app
const app = express();
app.use(express.json());

// Database connection pool
const dbPool = new Pool({
  connectionString: 'your_database_connection_string',
});

// Redis client for caching and configuration store
const redisClient = new Redis();

// Circuit breaker setup
const apiCircuitBreaker = new CircuitBreaker(axios.get, {
  timeout: 3000,
  errorThresholdPercentage: 50,
  resetTimeout: 60000,
});

apiCircuitBreaker.on('success', () => {
  console.log('API call succeeded');
});

apiCircuitBreaker.on('failure', () => {
  console.error('API call failed, falling back to cache');
});

// Function to fetch data from external API with circuit breaker
async function fetchDataFromApi(apiUrl) {
  try {
    const response = await apiCircuitBreaker.fire(apiUrl);
    return response.data;
  } catch (error) {
    // Fallback to Redis cache if API fails
    console.error('API call failed, using fallback from cache');
    return redisClient.get(apiUrl);
  }
}

// Route to update configuration in the central store
app.post('/update-config', async (req, res) => {
  const { key, value } = req.body;

  try {
    // Update configuration in Redis
    await redisClient.set(key, value);

    // Optionally update database for persistent storage
    await dbPool.query('UPDATE config SET value=$1 WHERE key=$2', [value, key]);

    res.status(200).json({ message: 'Configuration updated successfully' });
  } catch (error) {
    res.status(500).json({ error: 'Failed to update configuration' });
  }
});

// Route to get configuration from the central store
app.get('/get-config/:key', async (req, res) => {
  const { key } = req.params;

  try {
    // Try to fetch from Redis cache first
    let value = await redisClient.get(key);

    if (!value) {
      // If not found in cache, fetch from API and update cache
      value = await fetchDataFromApi(`https://api.example.com/config/${key}`);
      await redisClient.set(key, value);
    }

    res.json({ key, value });
  } catch (error) {
    res.status(500).json({ error: 'Failed to fetch configuration' });
  }
});

// Start the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
```

