#define HMAC_KEY_LENGTH 32

typedef struct {
    unsigned char aes_key[AES_KEY_LENGTH];
    unsigned char hmac_key[HMAC_KEY_LENGTH];
} EncryptionKeys;

EncryptionKeys generate_encryption_keys() {
    EncryptionKeys keys;
    if (!RAND_bytes(keys.aes_key, AES_KEY_LENGTH) || !RAND_bytes(keys.hmac_key, HMAC_KEY_LENGTH)) {
        fprintf(stderr, "Failed to generate random encryption keys\n");
        exit(EXIT_FAILURE);
    }
    return keys;
}

// Function to decrypt JSON payload using AES-GCM
int decrypt_json_payload(unsigned char *ciphertext, size_t ciphertext_len, unsigned char *aad, size_t aad_len, const EncryptionKeys *keys, unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, keys->aes_key, NULL)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    if (aad_len > 0 && 1 != EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_ADDITIONAL_AUTHENTICATED_DATA, aad_len, aad)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    int len;
    if (1 != EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    ciphertext_len = len;

    unsigned char tag[AES_BLOCK_SIZE];
    if (1 != EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, sizeof(tag), tag)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    if (1 != EVP_DecryptFinal_ex(ctx, plaintext + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);

    // Verify tag
    return 0;
}

