// C++ Library Code
#include <iostream>
#include <fstream>
#include <string>
#include <stdexcept>

class State {
public:
    virtual ~State() {}
};

template <typename T>
T load_state(const std::string& filename) {
    if (filename.empty()) {
        throw std::invalid_argument("Filename cannot be empty");
    }

    std::ifstream file(filename, std::ios::binary);
    if (!file.is_open()) {
        throw std::runtime_error("Failed to open file for reading");
    }

    T* state;
    try {
        state = new T();
        file.read(reinterpret_cast<char*>(state), sizeof(T));
    } catch (...) {
        delete state;
        throw;
    }

    return *state;
}
