void compute_hashes(OAuth2Token *token, char *md5_hash, char *sha256_hash) {
    MD5_CTX md5_ctx;
    SHA256_CTX sha256_ctx;

    // Compute MD5 hash
    MD5_Init(&md5_ctx);
    MD5_Update(&md5_ctx, token->access_token, strlen(token->access_token));
    MD5_Final((unsigned char *)md5_hash, &md5_ctx);

    // Compute SHA-256 hash
    SHA256_Init(&sha256_ctx);
    SHA256_Update(&sha256_ctx, token->access_token, strlen(token->access_token));
    SHA256_Final((unsigned char *)sha256_hash, &sha256_ctx);

    // Convert binary hash to hex string
