        sprintf(&md5_hash[i*2], "%02x", md5_hash[i]);
    }
    md5_hash[MD5_DIGEST_LENGTH*2] = '\0';

    for (int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
        sprintf(&sha256_hash[i*2], "%02x", sha256_hash[i]);
    }
    sha256_hash[SHA256_DIGEST_LENGTH*2] = '\0';
}

