        return "mocked_key";
    }
};

// Cryptographic library class
class CryptoLibrary {
private:
    KeyManagementServiceClient kms_client;
    std::unordered_map<std::string, std::pair<std::string, std::chrono::time_point<std::chrono::system_clock>>> key_cache;
    std::mutex cache_mutex;

public:
    // Encrypt data using DES ECB mode
    void encrypt_des_ecb(const std::string& key_id, const std::string& plaintext) {
        std::lock_guard<std::mutex> lock(cache_mutex);
        auto it = key_cache.find(key_id);
        if (it == key_cache.end() || std::chrono::system_clock::now() > it->second.second) {
            // Fetch key from KMS
            std::string key = kms_client.get_key(key_id);
            key_cache[key_id] = {key, std::chrono::system_clock::now() + std::chrono::minutes(5)};
        }
        des_ecb_encrypt(it->second.first, plaintext);
    }

    // Encrypt data using AES CBC mode
    void encrypt_aes_cbc(const std::string& key_id, const std::string& iv, const std::string& plaintext) {
        std::lock_guard<std::mutex> lock(cache_mutex);
        auto it = key_cache.find(key_id);
        if (it == key_cache.end() || std::chrono::system_clock::now() > it->second.second) {
            // Fetch key from KMS
            std::string key = kms_client.get_key(key_id);
            key_cache[key_id] = {key, std::chrono::system_clock::now() + std::chrono::minutes(5)};
        }
        aes_cbc_encrypt(it->second.first, iv, plaintext);
    }

    // Retry logic with exponential backoff
    template <typename Func>
    void retry(Func&& func) {
        for (int i = 0; i < 5; ++i) {
            try {
                func();
                return;
            } catch (const std::exception& e) {
                if (i == 4) throw;
                std::this_thread::sleep_for(std::chrono::milliseconds(static_cast<int>(std::pow(2, i))));
            }
        }
    }

    // Cache management with eviction policy
    void evict_old_keys() {
        auto now = std::chrono::system_clock::now();
        for (auto it = key_cache.begin(); it != key_cache.end();) {
            if (it->second.second < now) {
                it = key_cache.erase(it);
            } else {
                ++it;
            }
        }
    }
};

int main() {
    CryptoLibrary crypto_lib;
    crypto_lib.retry([&crypto_lib]() {
        crypto_lib.encrypt_des_ecb("key1", "plaintext");
    });
    crypto_lib.evict_old_keys();
    return 0;
}
