typedef struct {
    // Define NFAPI_CRC_INDICATION_PDU_T structure here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T events[MAX_EVENTS_PER_RAN];
    int count;
} EventPool;

EventPool eventPools[5]; // Assuming up to 5 RANs

pthread_mutex_t poolMutexes[5];

void init_event_pool(int ranId) {
    pthread_mutex_init(&poolMutexes[ranId], NULL);
}

int add_event_to_pool(int ranId, NFAPI_CRC_INDICATION_PDU_T event) {
    pthread_mutex_lock(&poolMutexes[ranId]);
    if (eventPools[ranId].count < MAX_EVENTS_PER_RAN) {
        eventPools[ranId].events[eventPools[ranId].count++] = event;
        pthread_mutex_unlock(&poolMutexes[ranId]);
        return 1; // Success
    }
    pthread_mutex_unlock(&poolMutexes[ranId]);
    return 0; // Failure, pool is full
}

NFAPI_CRC_INDICATION_PDU_T* get_event_from_pool(int ranId) {
    pthread_mutex_lock(&poolMutexes[ranId]);
    if (eventPools[ranId].count > 0) {
        NFAPI_CRC_INDICATION_PDU_T event = eventPools[ranId].events[--eventPools[ranId].count];
        pthread_mutex_unlock(&poolMutexes[ranId]);
        return &event;
    }
    pthread_mutex_unlock(&poolMutexes[ranId]);
    return NULL; // No events available
}

int main() {
    for (int i = 0; i < 5; i++) {
        init_event_pool(i);
    }

    NFAPI_CRC_INDICATION_PDU_T newEvent;
