#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>

class Task {
public:
    virtual void execute() = 0;
};

class BatchProcessingFramework {
private:
    std::vector<std::thread> workers;
    std::queue<Task*> taskQueue;
    std::mutex queueMutex;
    std::condition_variable taskCondition;
    bool stop;

public:
    BatchProcessingFramework(size_t numWorkers) : stop(false) {
        for (size_t i = 0; i < numWorkers; ++i) {
            workers.emplace_back(&BatchProcessingFramework::workerThread, this);
        }
    }

    ~BatchProcessingFramework() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            stop = true;
        }
        taskCondition.notify_all();
        for (auto& worker : workers) {
            worker.join();
        }
    }

    void submitTask(Task* task) {
        std::unique_lock<std::mutex> lock(queueMutex);
        taskQueue.push(task);
        taskCondition.notify_one();
    }

private:
    void workerThread() {
        while (true) {
            Task* task;
            {
                std::unique_lock<std::mutex> lock(queueMutex);
                taskCondition.wait(lock, [this] { return !taskQueue.empty() || stop; });
                if (stop && taskQueue.empty()) {
                    return;
                }
                task = taskQueue.front();
                taskQueue.pop();
            }
            task->execute();
        }
    }
};

// Example Task implementation
class ETLTask : public Task {
public:
    void execute() override {
        // Perform ETL operations here
        std::cout << "ETL Task Executed" << std::endl;
    }
};

int main() {
    BatchProcessingFramework framework(4);
    framework.submitTask(new ETLTask());
    return 0;
}
```

