#include <future>
#include <optional>

class ConfigManager {
public:
    void updateConfig(const std::string& configType, const std::string& newConfig) {
        std::lock_guard<std::mutex> lock(mutex_);
        pendingUpdates_[configType] = newConfig;
        cv_.notify_one();
    }

    std::optional<std::string> getConfig(const std::string& configType) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = cache_.find(configType);
        if (it != cache_.end() && !it->second.expired()) {
            return it->second.config;
        }
        return {};
    }

private:
    struct ConfigEntry {
        std::string config;
        std::chrono::steady_clock::time_point expiryTime;
    };

    void workerThread() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            cv_.wait(lock, [this] { return !pendingUpdates_.empty(); });
            auto [configType, newConfig] = pendingUpdates_.front();
            pendingUpdates_.pop();

            // Simulate asynchronous API call with retries and fallback
            if (auto config = fetchConfigFromAPI(configType)) {
                lock.unlock();
                updateCache(configType, *config);
            } else {
                lock.unlock();
                handleFallback(configType);
            }
        }
    }

    std::optional<std::string> fetchConfigFromAPI(const std::string& configType) {
        // Simulate API call with retries
        for (int i = 0; i < maxRetries_; ++i) {
            try {
                auto response = externalAPIClient_.get(configType);
                if (response.ok()) {
                    return response.config;
                }
            } catch (...) {
                std::this_thread::sleep_for(std::chrono::milliseconds(100));
            }
        }
        return {};
    }

    void updateCache(const std::string& configType, const std::string& newConfig) {
        cache_[configType] = {newConfig, getExpiryTime(configType)};
    }

    void handleFallback(const std::string& configType) {
        // Simulate local fallback mechanism
        if (auto staleConfig = staleCache_.find(configType)) {
            updateCache(configType, staleConfig->second);
        } else {
            updateCache(configType, defaultConfig_);
        }
    }

    std::chrono::steady_clock::time_point getExpiryTime(const std::string& configType) {
        // Implement cache expiration policy based on config type
        return std::chrono::steady_clock::now() + std::chrono::seconds(60);
    }

    ExternalAPIClient externalAPIClient_;
    std::unordered_map<std::string, ConfigEntry> cache_;
    std::unordered_map<std::string, std::string> staleCache_;
    std::queue<std::pair<std::string, std::string>> pendingUpdates_;
    std::mutex mutex_;
    std::condition_variable cv_;
    int maxRetries_ = 3;
    std::string defaultConfig_ = "default_config";
};
