        if (policyEngine.evaluatePolicy(telemetry)) {
            // Trigger appropriate actions based on policy evaluation
        }
    } else {
        std::cerr << "Invalid message: " << message << std::endl;
    }
}

void IoTTelemetryProcessor::start() {
    running = true;
    while (running) {
        // Process incoming telemetry messages from multiple sources
        processMessage("Sample message");
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
    }
}

void IoTTelemetryProcessor::stop() {
    running = false;
    cv.notify_all();
}
