#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/sha.h>
#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>

// Function to encrypt data using AES-256-CBC
std::vector<unsigned char> encryptAES(const std::vector<unsigned char>& plaintext, const unsigned char* key, const unsigned char* iv) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    int len;
    std::vector<unsigned char> ciphertext(plaintext.size() + AES_BLOCK_SIZE);
    EVP_EncryptUpdate(ctx, &ciphertext[0], &len, plaintext.data(), plaintext.size());
    ciphertext.resize(len);
    EVP_EncryptFinal_ex(ctx, &ciphertext[len], &len);
    EVP_CIPHER_CTX_free(ctx);
    return ciphertext;
}

// Function to decrypt data using AES-256-CBC
std::vector<unsigned char> decryptAES(const std::vector<unsigned char>& ciphertext, const unsigned char* key, const unsigned char* iv) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    int len;
    std::vector<unsigned char> plaintext(ciphertext.size());
    EVP_DecryptUpdate(ctx, &plaintext[0], &len, ciphertext.data(), ciphertext.size());
    plaintext.resize(len);
    EVP_DecryptFinal_ex(ctx, &plaintext[len], &len);
    EVP_CIPHER_CTX_free(ctx);
    return plaintext;
}

// Function to generate MD5 hash
std::vector<unsigned char> md5(const std::string& input) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)input.c_str(), input.size(), (unsigned char*)&digest);
    return std::vector<unsigned char>(digest, digest + MD5_DIGEST_LENGTH);
}

// Function to generate SHA-256 hash
std::vector<unsigned char> sha256(const std::string& input) {
    unsigned char digest[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char*)input.c_str(), input.size(), (unsigned char*)&digest);
    return std::vector<unsigned char>(digest, digest + SHA256_DIGEST_LENGTH);
}

// Function to perform RSA encryption using SHA-256
std::vector<unsigned char> rsaEncrypt(const unsigned char* data, size_t length, const RSA* key) {
    int len = RSA_size(key);
    std::vector<unsigned char> encrypted(len);
    RSA_public_encrypt(length, data, &encrypted[0], key, RSA_PKCS1_PADDING);
    return encrypted;
}

// Function to perform RSA decryption using SHA-256
std::vector<unsigned char> rsaDecrypt(const unsigned char* data, size_t length, const RSA* key) {
    int len = RSA_size(key);
    std::vector<unsigned char> decrypted(len);
    RSA_private_decrypt(length, data, &decrypted[0], key, RSA_PKCS1_PADDING);
    return decrypted;
}

// Thread pool implementation
class ThreadPool {
public:
    ThreadPool(size_t threads) : stop(false) {
        for (size_t i = 0; i < threads; ++i)
            workers.emplace_back([this] {
                while (true) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(this->queue_mutex);
                        this->condition.wait(lock, [this] { return this->stop || !this->tasks.empty(); });
                        if (this->stop && this->tasks.empty())
                            return;
                        task = std::move(this->tasks.front());
                        this->tasks.pop();
                    }
                    task();
                }
            });
    }

    template<class F, class... Args>
    auto enqueue(F&& f, Args&&... args) -> std::future<typename std::result_of<F(Args...)>::type> {
        using return_type = typename std::result_of<F(Args...)>::type;

        auto task = std::make_shared<std::packaged_task<return_type()>>(
            std::bind(std::forward<F>(f), std::forward<Args>(args)...)
        );

        std::future<return_type> res = task->get_future();
        {
            std::unique_lock<std::mutex> lock(queue_mutex);

            // don't allow enqueueing after stopping the pool
            if (stop)
                throw std::runtime_error("enqueue on stopped ThreadPool");

            tasks.emplace([task]() { (*task)(); });
        }
        condition.notify_one();
        return res;
    }

    ~ThreadPool() {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread& worker : workers)
            worker.join();
    }

private:
    std::vector<std::thread> workers;
    std::queue<std::function<void()>> tasks;
    std::mutex queue_mutex;
    std::condition_variable condition;
    bool stop;
};

// Example usage
int main() {
    ThreadPool pool(4);

    auto result = pool.enqueue([](const std::string& data) {
        return encryptAES(data.begin(), data.end(), "0123456789abcdef", "0123456789abcdef");
    }, "Hello, World!");

    std::vector<unsigned char> encrypted = result.get();
    std::cout << "Encrypted: ";
    for (auto& b : encrypted)
        std::cout << std::hex << std::setw(2) << std::setfill('0') << static_cast<int>(b);
    std::cout << std::endl;

    return 0;
}
