#include <unordered_map>
#include <cstring>

// Packet structure definition
struct PacketHandler {
    uint8_t protocolVersion;
    std::string srcIP;
    std::string dstIP;
    uint16_t srcPort;
    uint16_t dstPort;
    size_t payloadSize;
    std::chrono::steady_clock::time_point timestamp;
};

// In-memory data store
class MemoryStore {
public:
    void insert(const PacketHandler& packet) {
        std::lock_guard<std::mutex> lock(mutex);
        data[packet.timestamp] = packet;
    }

    bool removeInactiveEntries() {
        auto now = std::chrono::steady_clock::now();
        auto it = data.begin();
        while (it != data.end()) {
            if (now - it->second.timestamp > maxIdleTime) {
                it = data.erase(it);
            } else {
                ++it;
            }
        }
        return !data.empty();
    }

private:
    std::unordered_map<std::chrono::steady_clock::time_point, PacketHandler> data;
    std::mutex mutex;
    std::chrono::seconds maxIdleTime = std::chrono::seconds(60);
};

// Packet handler function
void packetHandler(const PacketHandler& packet) {
    // Process the packet (e.g., logging)
    std::cout << "Processing packet at " << packet.timestamp << std::endl;
}

// Asynchronous processing thread
void asyncProcessor(MemoryStore& store, std::queue<PacketHandler>& queue) {
    while (true) {
        std::unique_lock<std::mutex> lock(queueMutex);
        queue.wait(lock, []{ return !packetQueue.empty() || stopProcessing; });
        if (stopProcessing && packetQueue.empty()) break;
        PacketHandler packet = packetQueue.front();
        packetQueue.pop();
        lock.unlock();

        // Process the packet asynchronously
        std::thread([=](){ packetHandler(packet); }).detach();
    }
}

// Main function to simulate UDP packet handling
int main() {
    MemoryStore store;
    std::queue<PacketHandler> packetQueue;
    std::mutex queueMutex;
    bool stopProcessing = false;

    // Start async processing thread
    std::thread processorThread(asyncProcessor, std::ref(store), std::ref(packetQueue));

    // Simulate receiving packets
    for (int i = 0; i < 1000; ++i) {
        PacketHandler packet = { /* initialize fields */ };
        store.insert(packet);
        std::lock_guard<std::mutex> lock(queueMutex);
        packetQueue.push(packet);
    }

    // Stop processing and wait for thread to finish
    stopProcessing = true;
    queue.notify_all();
    processorThread.join();

    return 0;
}
