# Function to read data from various sources
def read_data(source):
    if source == 'AWS S3':
        return spark.read.format('parquet').load('s3a://your-bucket/data')
    elif source == 'Google BigQuery':
        return spark.read.format('bigquery').option('table', 'project.dataset.table').load()
    elif source == 'Azure Blob Storage':
        return spark.read.format('avro').load('wasbs://container@account.blob.core.windows.net/data')

# Function to process data
def process_data(df):
    # Example transformation: filter and select specific columns
    return df.filter(col("age") > 18).select("id", "name", "email")

# Function to write data back to storage
def write_data(df, target):
    if target == 'AWS S3':
        df.write.format('parquet').mode('append').save('s3a://your-bucket/output')
    elif target == 'Google BigQuery':
        df.write.format('bigquery').option('table', 'project.dataset.table').mode('append').save()
    elif target == 'Azure Blob Storage':
        df.write.format('avro').mode('append').save('wasbs://container@account.blob.core.windows.net/output')

# Main function to orchestrate the pipeline
def main():
    sources = ['AWS S3', 'Google BigQuery', 'Azure Blob Storage']
    for source in sources:
        data = read_data(source)
        processed_data = process_data(data)
        write_data(processed_data, source)

if __name__ == "__main__":
    main()
