#include <iostream>
#include <string>
#include <openssl/des.h>
#include <openssl/aes.h>
#include <openssl/rand.h>

class CryptoLibrary {
public:
    CryptoLibrary() {
        OpenSSL_add_all_algorithms();
        ERR_load_crypto_strings();
    }

    ~CryptoLibrary() {
        EVP_cleanup();
        ERR_free_strings();
    }

    std::string des_encrypt(const std::string& data, const std::string& key, DES_EDE3_CBC_MODE mode = DES_EDE3_CBC) {
        if (data.empty() || key.length() != 24) return "";

        unsigned char iv[DES_BLOCK_SIZE];
        RAND_bytes(iv, sizeof(iv));

        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        if (!ctx) return "";

        if (mode == DES_EDE3_CBC) {
            if (!EVP_EncryptInit_ex(ctx, EVP_des_ede3_cbc(), NULL, reinterpret_cast<const unsigned char*>(key.c_str()), iv)) {
                EVP_CIPHER_CTX_free(ctx);
                return "";
            }
        } else if (mode == DES_EDE_CBC) {
            if (!EVP_EncryptInit_ex(ctx, EVP_des_ede_cbc(), NULL, reinterpret_cast<const unsigned char*>(key.c_str()), iv)) {
                EVP_CIPHER_CTX_free(ctx);
                return "";
            }
        } else {
            EVP_CIPHER_CTX_free(ctx);
            return "";
        }

        int len;
        if (!EVP_EncryptUpdate(ctx, NULL, &len, NULL, 0) || !EVP_EncryptFinal_ex(ctx, NULL, &len)) {
            EVP_CIPHER_CTX_free(ctx);
            return "";
        }

        unsigned char* ciphertext = new unsigned char[data.size() + DES_BLOCK_SIZE];
        if (!EVP_EncryptUpdate(ctx, ciphertext, &len, reinterpret_cast<const unsigned char*>(data.c_str()), data.size()) || !EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) {
            delete[] ciphertext;
            EVP_CIPHER_CTX_free(ctx);
            return "";
        }

        std::string result(reinterpret_cast<char*>(ciphertext), len);
        delete[] ciphertext;
        EVP_CIPHER_CTX_free(ctx);

        // Append IV to the result
        result.append(reinterpret_cast<char*>(iv), DES_BLOCK_SIZE);

        return result;
    }

    std::string des_decrypt(const std::string& data, const std::string& key, DES_EDE3_CBC_MODE mode = DES_EDE3_CBC) {
        if (data.size() < DES_BLOCK_SIZE || key.length() != 24) return "";

        unsigned char iv[DES_BLOCK_SIZE];
        memcpy(iv, data.data() + data.size() - DES_BLOCK_SIZE, DES_BLOCK_SIZE);

        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        if (!ctx) return "";

        if (mode == DES_EDE3_CBC) {
            if (!EVP_DecryptInit_ex(ctx, EVP_des_ede3_cbc(), NULL, reinterpret_cast<const unsigned char*>(key.c_str()), iv)) {
                EVP_CIPHER_CTX_free(ctx);
                return "";
            }
        } else if (mode == DES_EDE_CBC) {
            if (!EVP_DecryptInit_ex(ctx, EVP_des_ede_cbc(), NULL, reinterpret_cast<const unsigned char*>(key.c_str()), iv)) {
                EVP_CIPHER_CTX_free(ctx);
                return "";
            }
        } else {
            EVP_CIPHER_CTX_free(ctx);
            return "";
        }

        int len;
        if (!EVP_DecryptUpdate(ctx, NULL, &len, NULL, 0) || !EVP_DecryptFinal_ex(ctx, NULL, &len)) {
            EVP_CIPHER_CTX_free(ctx);
            return "";
        }

        unsigned char* plaintext = new unsigned char[data.size() - DES_BLOCK_SIZE];
        if (!EVP_DecryptUpdate(ctx, plaintext, &len, reinterpret_cast<const unsigned char*>(data.data()), data.size() - DES_BLOCK_SIZE) || !EVP_DecryptFinal_ex(ctx, plaintext + len, &len)) {
            delete[] plaintext;
            EVP_CIPHER_CTX_free(ctx);
            return "";
        }

        std::string result(reinterpret_cast<char*>(plaintext), len);
        delete[] plaintext;
        EVP_CIPHER_CTX_free(ctx);

        return result;
    }

    // Similar methods for AES encryption/decryption with CBC, GCM, and CTR modes

private:
    // Helper methods for key management, caching, error handling, etc.
};

int main() {
    CryptoLibrary cryptoLib;
    std::string key = "0123456789abcdef0123456789abcdef"; // 24 bytes for DES-EDE3
    std::string data = "Hello, World!";

    std::string encrypted = cryptoLib.des_encrypt(data, key, DES_EDE3_CBC);
    std::cout << "Encrypted: " << encrypted << std::endl;

    std::string decrypted = cryptoLib.des_decrypt(encrypted, key, DES_EDE3_CBC);
    std::cout << "Decrypted: " << decrypted << std::endl;

    return 0;
}
```

