#include <time.h>
#include <unistd.h>

#define MAX_UE 1000

typedef struct {
    uint64_t rnti;
    uint8_t crc_flag;
} NAS_PDU;

NAS_PDU nas_pdu[MAX_UE];
pthread_mutex_t nas_mutex = PTHREAD_MUTEX_INITIALIZER;

void log_action(const char *action) {
    char timestamp[20];
    struct timeval tv;
    gettimeofday(&tv, NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));

    FILE *log_file = fopen("nas_library.log", "a");
    if (log_file) {
        fprintf(log_file, "[%s] %s\n", timestamp, action);
        fclose(log_file);
    } else {
        fprintf(stderr, "Failed to open log file for logging action: %s\n", action);
    }
}

void *process_nas_pdu(void *arg) {
    int ue_id = *(int *)arg;
    pthread_mutex_lock(&nas_mutex);

    // Simulate processing NAS PDU
    nas_pdu[ue_id].rnti = rand();
    nas_pdu[ue_id].crc_flag = (rand() % 2 == 0) ? 1 : 0;

    log_action("Processed NAS PDU");

    pthread_mutex_unlock(&nas_mutex);
    return NULL;
}

int main() {
    int num_threads = 5;
    pthread_t threads[num_threads];
    int ue_ids[num_threads];

    for (int i = 0; i < num_threads; i++) {
        ue_ids[i] = i;
        if (pthread_create(&threads[i], NULL, process_nas_pdu, &ue_ids[i]) != 0) {
            fprintf(stderr, "Failed to create thread %d\n", i);
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < num_threads; i++) {
        if (pthread_join(threads[i], NULL) != 0) {
            fprintf(stderr, "Failed to join thread %d\n", i);
            return EXIT_FAILURE;
        }
    }

    // Output processed NAS PDUs
    for (int i = 0; i < num_threads; i++) {
        printf("UE ID: %d, RNTI: %llu, CRC Flag: %u\n", i, nas_pdu[i].rnti, nas_pdu[i].crc_flag);
    }

    return EXIT_SUCCESS;
}
```

