# Import necessary libraries
import hashlib
import asyncio
from aiofiles import open as async_open

class StreamingMD5Hasher:
    def __init__(self):
        self.hash = hashlib.md5()

    async def update(self, data: bytes):
        self.hash.update(data)

    async def finalize(self) -> str:
        return self.hash.hexdigest()

async def hash_stream(file_path: str) -> str:
    hasher = StreamingMD5Hasher()
    async with async_open(file_path, mode='rb') as file:
        while True:
            chunk = await file.read(8192)
            if not chunk:
                break
            await hasher.update(chunk)
    return await hasher.finalize()

async def main():
    file_path = 'example.txt'
    md5_hash = await hash_stream(file_path)
    print(f"MD5 Hash: {md5_hash}")

# Run the main function
if __name__ == "__main__":
    asyncio.run(main())
