#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_POOL_SIZE 1024

typedef struct {
    // Define the structure fields for NFAPI_CRC_INDICATION_PDU_T
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    int size;
    int head;
    int tail;
    sem_t empty;
    sem_t full;
    pthread_mutex_t mutex;
} PDU_POOL;

PDU_POOL *create_pdu_pool(int initial_size) {
    PDU_POOL *pool = (PDU_POOL *)malloc(sizeof(PDU_POOL));
    pool->pool = (NFAPI_CRC_INDICATION_PDU_T *)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pool->size = initial_size;
    pool->head = 0;
    pool->tail = 0;
    sem_init(&pool->empty, 0, initial_size);
    sem_init(&pool->full, 0, 0);
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

void destroy_pdu_pool(PDU_POOL *pool) {
    free(pool->pool);
    sem_destroy(&pool->empty);
    sem_destroy(&pool->full);
    pthread_mutex_destroy(&pool->mutex);
    free(pool);
}

int enqueue_pdu(PDU_POOL *pool, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    sem_wait(&pool->empty);
    pthread_mutex_lock(&pool->mutex);

    pool->pool[pool->tail] = *pdu;
    pool->tail = (pool->tail + 1) % pool->size;

    pthread_mutex_unlock(&pool->mutex);
    sem_post(&pool->full);

    return 0;
}

int dequeue_pdu(PDU_POOL *pool, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    sem_wait(&pool->full);
    pthread_mutex_lock(&pool->mutex);

    *pdu = pool->pool[pool->head];
    pool->head = (pool->head + 1) % pool->size;

    pthread_mutex_unlock(&pool->mutex);
    sem_post(&pool->empty);

    return 0;
}

// Additional functions for managing dynamic scaling, error handling, logging, and concurrency control
