class NFAPI_Crc_Indication_Pdu_Manager {
public:
    using PoolType = std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>;

    NFAPI_Crc_Indication_Pdu_Manager(size_t poolSize) : poolSize(poolSize), memoryPool(poolSize) {
        for (size_t i = 0; i < poolSize; ++i) {
            memoryPool[i] = std::make_unique<NFAPI_CRC_INDICATION_PDU_T>();
        }
    }

    PoolType getFromPool() {
        std::lock_guard<std::mutex> lock(mutex);
        if (!freeList.empty()) {
            PoolType item = freeList.front();
            freeList.pop();
            return item;
        } else {
            // Handle pool exhaustion
            throw std::runtime_error("Memory pool exhausted");
        }
    }

    void returnToPool(PoolType item) {
        std::lock_guard<std::mutex> lock(mutex);
        if (freeList.size() < poolSize) {
            freeList.push(item);
        } else {
            // Handle pool overflow
            throw std::runtime_error("Memory pool overflow");
        }
    }

private:
    size_t poolSize;
    std::vector<PoolType> memoryPool;
    std::queue<PoolType> freeList;
    std::mutex mutex;
};

