public class MessageQueue {
    private BlockingQueue<PacketHandler> queue = new LinkedBlockingQueue<>();

    public void send(PacketHandler packet) {
        try {
            // Add packet to the queue asynchronously
            executorService.submit(() -> queue.put(packet));
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public PacketHandler receive() {
        try {
            return queue.take();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return null;
        }
    }
}

