import java.io.*;

public class CommandExecutor {

    public static void executeCommand(String[] command, String[] env, File workingDir) {
        try {
            Process process = Runtime.getRuntime().exec(command, env, workingDir);

            // Read output stream
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }

            // Read error stream
            BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            String errorLine;
            while ((errorLine = errorReader.readLine()) != null) {
                System.err.println(errorLine);
            }

            int exitCode = process.waitFor();
            System.out.println("Command exited with code: " + exitCode);

        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        String[] command = {"ls", "-la"};
        String[] env = null;
        File workingDir = new File("/home/user");

        executeCommand(command, env, workingDir);
    }
}
