#define MAX_STRUCTS 100000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_tag;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_flag;
} NFAPI_CRC_INDICATION_PDU;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    size_t size;
    pthread_mutex_t lock;
} LinkedList;

void initLinkedList(LinkedList* list) {
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void append(LinkedList* list, NFAPI_CRC_INDICATION_PDU data) {
    pthread_mutex_lock(&list->lock);
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = NULL;

    if (list->head == NULL) {
        list->head = newNode;
    } else {
        Node* temp = list->head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

void freeLinkedList(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->size = 0;
    pthread_mutex_unlock(&list->lock);
}

