public class DistributedFileSyncService {
    private Map<String, File> fileMap = new ConcurrentHashMap<>();
    private ExecutorService executorService = Executors.newFixedThreadPool(10);
    private AmazonS3 s3Client;
    private Storage googleStorageClient;

    public DistributedFileSyncService(String awsAccessKey, String awsSecretKey, String googleProjectId) {
        this.s3Client = AmazonS3ClientBuilder.standard()
                .withCredentials(new AWSStaticCredentialsProvider(new BasicAWSCredentials(awsAccessKey, awsSecretKey)))
                .build();
        this.googleStorageClient = StorageOptions.newBuilder().setProjectId(googleProjectId).build().getService();
    }

    public void uploadFile(String filePath) {
        File file = new File(filePath);
        if (fileMap.putIfAbsent(file.getName(), file) == null) {
            executorService.submit(() -> syncFileToCloud(file));
        }
    }

    private void syncFileToCloud(File file) {
        try {
            s3Client.putObject("my-bucket", file.getName(), new FileInputStream(file));
            googleStorageClient.create("my-project/my-bucket", file.getName(), Files.readAllBytes(Paths.get(file.getPath())));
        } catch (IOException e) {
            handleException(e);
        }
    }

    public void downloadFile(String fileName) {
        executorService.submit(() -> {
            try {
                File file = new File(fileName);
                s3Client.getObject("my-bucket", fileName, file);
                googleStorageClient.download("my-project/my-bucket/" + fileName, file);
                fileMap.putIfAbsent(file.getName(), file);
            } catch (IOException e) {
                handleException(e);
            }
        });
    }

    private void handleException(Exception e) {
        // Log the error and retry logic
        System.err.println("Error during file sync: " + e.getMessage());
        executorService.submit(() -> handleException(e));
    }

    public void startDeduplication() {
        executorService.submit(this::deduplicateFiles);
    }

    private void deduplicateFiles() {
        try (BufferedReader reader = new BufferedReader(new FileReader("file_hashes.txt"))) {
            Set<String> uniqueHashes = new HashSet<>();
            for (String line : reader.lines().collect(Collectors.toList())) {
                if (!uniqueHashes.contains(line)) {
                    uniqueHashes.add(line);
                } else {
                    // Remove redundant file
                    executorService.submit(() -> removeRedundantFile(line));
                }
            }
        } catch (IOException e) {
            handleException(e);
        }
    }

    private void removeRedundantFile(String hash) {
        try {
            List<String> filesToRemove = findFilesByHash(hash);
            for (String file : filesToRemove) {
                s3Client.deleteObject("my-bucket", file);
                googleStorageClient.delete("my-project/my-bucket/" + file);
                fileMap.remove(file);
            }
        } catch (IOException e) {
            handleException(e);
        }
    }

    private List<String> findFilesByHash(String hash) throws IOException {
