class RetryManager {
private:
    using BackoffStrategy = std::function<int(int)>;

public:
    RetryManager(BackoffStrategy backoff, int maxAttempts)
        : backoff_(backoff), maxAttempts_(maxAttempts) {}

    template <typename Func>
    auto retry(Func&& func, int attempts = 0) const {
        while (attempts++ < maxAttempts_) {
            try {
                return std::invoke(std::forward<Func>(func));
            } catch (...) {
                std::this_thread::sleep_for(std::chrono::milliseconds(backoff_(attempts)));
            }
        }
        throw std::runtime_error("Max retry attempts exceeded");
    }

private:
    BackoffStrategy backoff_;
    int maxAttempts_;
};

class CircuitBreaker {
public:
    void execute(const std::function<void()>& func) {
        if (isOpen_) {
            throw std::runtime_error("Circuit breaker is open");
        }
        try {
            func();
        } catch (...) {
            setOpenState();
            throw;
        }
    }

private:
