#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int packet_id;
    time_t timestamp;
    size_t data_size;
    unsigned char *data;
} DataPacket;

typedef struct {
    EVP_CIPHER *cipher;
    unsigned char *key;
    unsigned char *iv;
} CipherContext;

CipherContext* create_cipher_context(const char *algorithm, const unsigned char *key, const unsigned char *iv) {
    CipherContext *ctx = (CipherContext*)malloc(sizeof(CipherContext));
    ctx->cipher = EVP_CIPHER_fetch(NULL, algorithm, NULL);
    if (!ctx->cipher) {
        free(ctx);
        return NULL;
    }
    ctx->key = (unsigned char*)malloc(EVP_CIPHER_key_length(ctx->cipher));
    memcpy(ctx->key, key, EVP_CIPHER_key_length(ctx->cipher));
    ctx->iv = (unsigned char*)malloc(EVP_CIPHER_iv_length(ctx->cipher));
    memcpy(ctx->iv, iv, EVP_CIPHER_iv_length(ctx->cipher));
    return ctx;
}

void free_cipher_context(CipherContext *ctx) {
    if (ctx) {
        EVP_CIPHER_free(ctx->cipher);
        free(ctx->key);
        free(ctx->iv);
        free(ctx);
    }
}

int encrypt_data(const CipherContext *ctx, DataPacket *packet, unsigned char **encrypted_data, size_t *encrypted_size) {
    *encrypted_size = packet->data_size + EVP_CIPHER_block_size(ctx->cipher);
    *encrypted_data = (unsigned char*)malloc(*encrypted_size);
    if (!*encrypted_data) return 1;
    int len;
    EVP_EncryptInit_ex(NULL, ctx->cipher, NULL, ctx->key, ctx->iv);
    EVP_EncryptUpdate(NULL, *encrypted_data, &len, packet->data, packet->data_size);
    int final_len;
    EVP_EncryptFinal_ex(NULL, (*encrypted_data) + len, &final_len);
    *encrypted_size = len + final_len;
    return 0;
}

int decrypt_data(const CipherContext *ctx, unsigned char *encrypted_data, size_t encrypted_size, DataPacket *packet) {
    packet->data = (unsigned char*)malloc(encrypted_size - EVP_CIPHER_block_size(ctx->cipher));
    if (!packet->data) return 1;
    int len;
    EVP_DecryptInit_ex(NULL, ctx->cipher, NULL, ctx->key, ctx->iv);
    EVP_DecryptUpdate(NULL, packet->data, &len, encrypted_data, encrypted_size - EVP_CIPHER_block_size(ctx->cipher));
    int final_len;
    EVP_DecryptFinal_ex(NULL, packet->data + len, &final_len);
    packet->data_size = len + final_len;
    return 0;
}

int main() {
    unsigned char key[32];
    unsigned char iv[EVP_CIPHER_iv_length(EVP_aes_256_cbc())];
    RAND_bytes(key, sizeof(key));
    RAND_bytes(iv, sizeof(iv));

    CipherContext *ctx = create_cipher_context("aes-256-cbc", key, iv);
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        return 1;
    }

    DataPacket packet = { .packet_id = 1, .timestamp = time(NULL), .data_size = 1024, .data = (unsigned char*)malloc(1024) };
    if (!packet.data) {
        fprintf(stderr, "Failed to allocate memory for data\n");
        free_cipher_context(ctx);
        return 1;
    }

    unsigned char *encrypted_data;
    size_t encrypted_size;
    if (encrypt_data(ctx, &packet, &encrypted_data, &encrypted_size)) {
        fprintf(stderr, "Failed to encrypt data\n");
        free(packet.data);
        free_cipher_context(ctx);
        return 1;
    }

    DataPacket decrypted_packet = { .data = NULL };
    if (decrypt_data(ctx, encrypted_data, encrypted_size, &decrypted_packet)) {
        fprintf(stderr, "Failed to decrypt data\n");
        free(encrypted_data);
        free(decrypted_packet.data);
        free_cipher_context(ctx);
        return 1;
    }

    printf("Decrypted packet size: %zu\n", decrypted_packet.data_size);

    free(encrypted_data);
    free(decrypted_packet.data);
    free(packet.data);
    free_cipher_context(ctx);
    return 0;
}
