    private static final int AES_KEY_SIZE = 256;
    private static final String HASH_ALGORITHM = "SHA-256";

    private ConcurrentHashMap<String, File> cache = new ConcurrentHashMap<>();
    private AtomicInteger cacheSize = new AtomicInteger(0);
    private KeyGenerator keyGenerator;

    public DynamicSecureFileDownloader() throws NoSuchAlgorithmException {
        keyGenerator = KeyGenerator.getInstance(CRYPTO_ALGORITHM);
        keyGenerator.init(AES_KEY_SIZE);
    }

    public byte[] downloadAndDecrypt(String url, String identifier) throws IOException, NoSuchAlgorithmException {
        File cachedFile = cache.get(identifier);
        if (cachedFile == null) {
            byte[] fileData = downloadFile(url);
            SecretKey key = generateAESKey();
            byte[] encryptedData = encrypt(fileData, key);
            byte[] hash = calculateMD5(encryptedData);

            cachedFile = new File(identifier + ".data");
            try (OutputStream fos = new FileOutputStream(cachedFile)) {
                fos.write(encryptedData);
                fos.write(hash);
            }
            cache.put(identifier, cachedFile);
        }

        byte[] encryptedData = readEncryptedDataFromCache(cachedFile);
        SecretKey key = generateAESKey();
        return decrypt(encryptedData, key);
    }

    private byte[] downloadFile(String url) throws IOException {
        URL fileURL = new URL(url);
        try (InputStream in = fileURL.openStream()) {
            ByteArrayOutputStream out = new ByteArrayOutputStream();
            byte[] buffer = new byte[1024];
            int bytesRead;
            while ((bytesRead = in.read(buffer)) != -1) {
                out.write(buffer, 0, bytesRead);
            }
            return out.toByteArray();
        }
    }

    private SecretKey generateAESKey() throws NoSuchAlgorithmException {
        return keyGenerator.generateKey();
    }

    private byte[] encrypt(byte[] data, SecretKey key) throws Exception {
        Cipher cipher = Cipher.getInstance(CRYPTO_ALGORITHM);
        cipher.init(Cipher.ENCRYPT_MODE, key);
        return cipher.doFinal(data);
    }

    private byte[] decrypt(byte[] encryptedData, SecretKey key) throws Exception {
        Cipher cipher = Cipher.getInstance(CRYPTO_ALGORITHM);
        cipher.init(Cipher.DECRYPT_MODE, key);
        return cipher.doFinal(encryptedData);
    }

    private byte[] calculateMD5(byte[] data) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance(HASH_ALGORITHM);
        return digest.digest(data);
    }

    private byte[] readEncryptedDataFromCache(File cachedFile) throws IOException {
        try (RandomAccessFile file = new RandomAccessFile(cachedFile, "r")) {
            int encryptedDataLength = (int) file.length() - 32; // Assuming MD5 hash is 32 bytes
            byte[] encryptedData = new byte[encryptedDataLength];
            file.readFully(encryptedData);
            return encryptedData;
        }
    }

    public void updateCacheSize(int newSize) {
        cacheSize.set(newSize);
    }

    public int getCacheSize() {
        return cacheSize.get();
    }
}
