public class LoggingFramework {
    private static final BlockingQueue<LogEntry> queue = new LinkedBlockingQueue<>();
    private static volatile boolean running = true;

    public static void init() {
        Thread loggingThread = new Thread(LoggingFramework::processLogs);
        loggingThread.setDaemon(true);
        loggingThread.start();
    }

    public static void log(String message, LogLevel level) {
        if (shouldLog(level)) {
            queue.add(new LogEntry(message, level));
        }
    }

    private static boolean shouldLog(LogLevel level) {
        // Implement logic to determine if a log at the given level should be recorded
        return true;
    }

    private static void processLogs() {
        while (running) {
            try {
                LogEntry entry = queue.take();
                // Implement logic to handle each log entry, including external service integration
                System.out.println("Logging: " + entry);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    public static void stop() {
        running = false;
    }

    enum LogLevel {
        DEBUG,
        INFO,
        WARN,
        ERROR,
        FATAL
    }

    static class LogEntry {
        private final String message;
        private final LogLevel level;

        public LogEntry(String message, LogLevel level) {
            this.message = message;
            this.level = level;
        }

        @Override
        public String toString() {
            return "LogEntry{" +
                    "message='" + message + '\'' +
                    ", level=" + level +
                    '}';
        }
    }
