import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import javax.ws.rs.*;
import javax.ws.rs.core.MediaType;

@Path("/broker")
public class MessageBroker {

    private final ConcurrentHashMap<String, Topic> topics = new ConcurrentHashMap<>();
    private final AtomicInteger messageIdGenerator = new AtomicInteger(0);

    @POST
    @Path("/publish/{topic}")
    @Consumes(MediaType.APPLICATION_JSON)
    public void publish(@PathParam("topic") String topic, String message) {
        Topic t = topics.computeIfAbsent(topic, k -> new Topic());
        t.addMessage(message);
        t.processMessages();
    }

    @GET
    @Path("/subscribe/{topic}")
    @Produces(MediaType.APPLICATION_JSON)
    public Response subscribe(@PathParam("topic") String topic) {
        Topic t = topics.computeIfAbsent(topic, k -> new Topic());
        return Response.ok(t.getSubscription()).build();
    }

    private static class Topic {
        private final ConcurrentHashMap<Integer, Message> messages = new ConcurrentHashMap<>();
        private final AtomicInteger subscriptionIdGenerator = new AtomicInteger(0);

        public void addMessage(String message) {
            int id = messageIdGenerator.incrementAndGet();
            messages.put(id, new Message(message));
        }

        public Subscription getSubscription() {
            int id = subscriptionIdGenerator.incrementAndGet();
            return new Subscription(id, messages.values());
        }

        public void processMessages() {
            for (Message m : messages.values()) {
                if (!m.isProcessed()) {
                    // Process message logic here
                    m.setProcessed(true);
                }
            }
        }
    }

    private static class Message {
        private final String content;
        private volatile boolean processed;

        public Message(String content) {
            this.content = content;
            this.processed = false;
        }

        public String getContent() {
            return content;
        }

        public boolean isProcessed() {
            return processed;
        }

        public void setProcessed(boolean processed) {
            this.processed = processed;
        }
    }

    private static class Subscription {
        private final int id;
        private final Iterable<Message> messages;

        public Subscription(int id, Iterable<Message> messages) {
            this.id = id;
            this.messages = messages;
        }

        public int getId() {
            return id;
        }

        public Iterable<Message> getMessages() {
            return messages;
        }
    }
}
