    AES, Camellia, RSA, DES_ECB, DES_EDE, DES_EDE3, DES_CFB
};

enum class Mode {
    ECB, EDE, EDE3, CFB
};

class CryptographicLibrary {
public:
    CryptographicLibrary() {
        EVP_add_cipher(EVP_aes_256_cbc());
        EVP_add_cipher(EVP_camellia_256_cbc());
        // Initialize other ciphers and modes...
    }

    ~CryptographicLibrary() {
        EVP_cleanup();
    }

    void encrypt(const std::string& key, const std::string& iv, Algorithm algo, Mode mode, const std::string& plaintext, std::string& ciphertext) {
        EVP_CIPHER* cipher = nullptr;
        switch (algo) {
            case Algorithm::AES: cipher = EVP_aes_256_cbc(); break;
            case Algorithm::Camellia: cipher = EVP_camellia_256_cbc(); break;
            // Add other ciphers...
            default: throw std::runtime_error("Unsupported algorithm");
        }

        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(ctx, cipher, nullptr, reinterpret_cast<const unsigned char*>(key.c_str()), reinterpret_cast<const unsigned char*>(iv.c_str()));
        int len;
        EVP_EncryptUpdate(ctx, nullptr, &len, nullptr, 0);
        ciphertext.resize(len + plaintext.size());
        EVP_EncryptUpdate(ctx, reinterpret_cast<unsigned char*>(&ciphertext[0]), &len, reinterpret_cast<const unsigned char*>(plaintext.c_str()), plaintext.size());
        ciphertext.resize(len);
        EVP_EncryptFinal_ex(ctx, reinterpret_cast<unsigned char*>(&ciphertext[0]) + len, &len);
        ciphertext.resize(len);

        EVP_CIPHER_CTX_free(ctx);
    }

    void decrypt(const std::string& key, const std::string& iv, Algorithm algo, Mode mode, const std::string& ciphertext, std::string& plaintext) {
        EVP_CIPHER* cipher = nullptr;
        switch (algo) {
            case Algorithm::AES: cipher = EVP_aes_256_cbc(); break;
            case Algorithm::Camellia: cipher = EVP_camellia_256_cbc(); break;
            // Add other ciphers...
            default: throw std::runtime_error("Unsupported algorithm");
        }

        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        EVP_DecryptInit_ex(ctx, cipher, nullptr, reinterpret_cast<const unsigned char*>(key.c_str()), reinterpret_cast<const unsigned char*>(iv.c_str()));
        int len;
        EVP_DecryptUpdate(ctx, nullptr, &len, nullptr, 0);
        plaintext.resize(len + ciphertext.size());
        EVP_DecryptUpdate(ctx, reinterpret_cast<unsigned char*>(&plaintext[0]), &len, reinterpret_cast<const unsigned char*>(ciphertext.c_str()), ciphertext.size());
        plaintext.resize(len);
        EVP_DecryptFinal_ex(ctx, reinterpret_cast<unsigned char*>(&plaintext[0]) + len, &len);
        plaintext.resize(len);

        EVP_CIPHER_CTX_free(ctx);
    }

    void hash(const std::string& data, const EVP_MD* md, std::string& hash) {
        unsigned char buffer[EVP_MAX_MD_SIZE];
        int length;
        EVP_Digest(data.c_str(), data.size(), buffer, &length, md, nullptr);
        hash.resize(length);
        memcpy(&hash[0], buffer, length);
    }

    void hmac(const std::string& key, const std::string& data, const EVP_MD* md, std::string& hmac) {
        unsigned char buffer[EVP_MAX_MD_SIZE];
        int length;
        HMAC(md, key.c_str(), key.size(), reinterpret_cast<const unsigned char*>(data.c_str()), data.size(), buffer, &length);
        hmac.resize(length);
        memcpy(&hmac[0], buffer, length);
    }

    // Add other cryptographic functions...
};

