#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>

#define MAX_LOG_SIZE 1024
#define MAX_THREADS 10

typedef struct {
    char log[MAX_LOG_SIZE];
    int level;
} LogEntry;

typedef struct {
    pthread_t thread_id;
    int id;
    int client_socket;
    LogEntry *logs;
    int logs_size;
    int logs_count;
    int buffer_size;
} WorkerThread;

void* worker_thread_func(void *arg) {
    WorkerThread *wt = (WorkerThread*)arg;
    while (1) {
        if (wt->logs_count > 0) {
            for (int i = 0; i < wt->logs_count; i++) {
                printf("Processing log entry from client %d: %s\n", wt->id, wt->logs[i].log);
                // Add code to handle log processing
            }
            wt->logs_count = 0;
        }
    }
}

int main() {
    int server_socket, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);

    if ((server_socket = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(8080);

    if (bind(server_socket, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }

    if (listen(server_socket, 3) < 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    WorkerThread workers[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_create(&workers[i].thread_id, NULL, worker_thread_func, &workers[i]);
        workers[i].id = i;
        workers[i].logs = malloc(MAX_LOG_SIZE * sizeof(LogEntry));
        workers[i].logs_size = MAX_LOG_SIZE;
        workers[i].logs_count = 0;
        workers[i].buffer_size = 1024 * 1024;
    }

    while (1) {
        if ((new_socket = accept(server_socket, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            continue;
        }

        for (int i = 0; i < MAX_THREADS; i++) {
            if (workers[i].logs_count < workers[i].logs_size) {
                LogEntry log_entry;
                recv(new_socket, &log_entry, sizeof(LogEntry), 0);
                workers[i].logs[workers[i].logs_count] = log_entry;
                workers[i].logs_count++;
                break;
            }
        }
    }

    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(workers[i].thread_id, NULL);
    }

    close(server_socket);
    return 0;
}
