using System;
using System.Collections.Concurrent;
using System.Data;
using System.Net;
using System.Threading.Tasks;

public class PacketHandler
{
    public int ProtocolVersion { get; set; }
    public int SensorID { get; set; }
    public IPAddress SourceIP { get; set; }
    public IPAddress DestinationIP { get; set; }
    public int SourcePort { get; set; }
    public int DestinationPort { get; set; }
    public int PayloadSize { get; set; }
    public DateTime Timestamp { get; set; }
}

public class DataStore
{
    private readonly ConcurrentDictionary<string, PacketHandler> _store = new ConcurrentDictionary<string, PacketHandler>();

    public void Add(PacketHandler packet)
    {
        _store.TryAdd(packet.Timestamp.ToString(), packet);
    }

    public IEnumerable<PacketHandler> GetAll()
    {
        return _store.Values;
    }
}

public class AsyncProcessor
{
    private readonly DataStore _dataStore;

    public AsyncProcessor(DataStore dataStore)
    {
