// Base class for encryption
class Encryption {
public:
    virtual ~Encryption() {}
    virtual std::string encrypt(const std::string& data) = 0;
    virtual std::string decrypt(const std::string& encryptedData) = 0;
};

// AES encryption class
class AES : public Encryption {
public:
    AES(Algorithm algo, Mode mode, int keySize) {
        // Initialize AES context and set parameters
    }
    ~AES() override {}
    std::string encrypt(const std::string& data) override {
        // Encrypt data using AES algorithm
    }
    std::string decrypt(const std::string& encryptedData) override {
        // Decrypt data using AES algorithm
    }
};

// ChaCha20 encryption class
class ChaCha20 : public Encryption {
public:
    ChaCha20() {}
    ~ChaCha20() override {}
    std::string encrypt(const std::string& data) override {
        // Encrypt data using ChaCha20 algorithm
    }
    std::string decrypt(const std::string& encryptedData) override {
        // Decrypt data using ChaCha20 algorithm
    }
};

// Encryption service class
class EncryptionService {
private:
    std::vector<std::unique_ptr<Encryption>> encryptionModules;

public:
    void addModule(std::unique_ptr<Encryption> module) {
        encryptionModules.push_back(std::move(module));
    }

    std::string process(const std::string& data, Algorithm algo, Mode mode, int keySize) {
        for (auto& module : encryptionModules) {
            if (module->encrypt(data).empty()) {
                return module->decrypt(data);
            }
        }
        // Handle no available modules
        return "";
    }
};

// Example usage
int main() {
    EncryptionService service;
    auto aesModule = std::make_unique<AES>(Algorithm::AES, Mode::CBC, 256);
    auto chacha20Module = std::make_unique<ChaCha20>();

    service.addModule(std::move(aesModule));
    service.addModule(std::move(chacha20Module));

    std::string data = "Hello, World!";
    std::string encryptedData = service.process(data, Algorithm::AES, Mode::CBC, 256);
    std::string decryptedData = service.process(encryptedData, Algorithm::AES, Mode::CBC, 256);

    std::cout << "Original: " << data << "\nEncrypted: " << encryptedData << "\nDecrypted: " << decryptedData << std::endl;

    return 0;
}
