#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <uuid/uuid.h>

// Define record structure with variable-sized data and UUID
typedef struct Record {
    uuid_t uuid;
    char *data;
    size_t size;
} Record;

// Function to create a new record
Record* create_record(size_t initial_size) {
    Record *record = (Record *)malloc(sizeof(Record));
    if (!record) return NULL;

    uuid_generate(record->uuid);

    record->data = (char *)malloc(initial_size);
    if (!record->data) {
        free(record);
        return NULL;
    }

    record->size = initial_size;

    return record;
}

// Function to resize a record
int resize_record(Record *record, size_t new_size) {
    char *new_data = (char *)realloc(record->data, new_size);
    if (!new_data) return -1;

    record->data = new_data;
    record->size = new_size;
    return 0;
}

// Function to free a record
void free_record(Record *record) {
    if (record->data) free(record->data);
    free(record);
}

// Function to set data in a record
int set_record_data(Record *record, const char *new_data, size_t new_size) {
    if (resize_record(record, new_size) != 0) return -1;
    strcpy(record->data, new_data);
    return 0;
}

// Function to get data from a record
const char* get_record_data(Record *record) {
    return record->data;
}
```

