import threading
import time
import random

class DEVICE_CONNECTION_RECORD:
    def __init__(self, last_heartbeat_timestamp, connection_id, current_data_rate, last_error_code):
        self.last_heartbeat_timestamp = last_heartbeat_timestamp
        self.connection_id = connection_id
        self.current_data_rate = current_data_rate
        self.last_error_code = last_error_code

class BinaryHeap:
    def __init__(self):
        self.heap = []
        self.lock = threading.Lock()

    def _parent(self, i):
        return (i - 1) // 2

    def _left_child(self, i):
        return 2 * i + 1

    def _right_child(self, i):
        return 2 * i + 2

    def _swap(self, i, j):
        self.heap[i], self.heap[j] = self.heap[j], self.heap[i]

    def _bubble_up(self, i):
        while i > 0 and self.heap[self._parent(i)].last_heartbeat_timestamp < self.heap[i].last_heartbeat_timestamp:
            self._swap(i, self._parent(i))
            i = self._parent(i)

    def _bubble_down(self, i):
        while (self._left_child(i) < len(self.heap) or self._right_child(i) < len(self.heap)) and \
              (self.heap[self._left_child(i)].last_heartbeat_timestamp > self.heap[i].last_heartbeat_timestamp or
               self.heap[self._right_child(i)].last_heartbeat_timestamp > self.heap[i].last_heartbeat_timestamp):
            if self._right_child(i) >= len(self.heap) or \
               self.heap[self._left_child(i)].last_heartbeat_timestamp <= self.heap[self._right_child(i)].last_heartbeat_timestamp:
                child = self._left_child(i)
            else:
                child = self._right_child(i)
            self._swap(i, child)
            i = child

    def insert(self, record):
        with self.lock:
            self.heap.append(record)
            self._bubble_up(len(self.heap) - 1)

    def extract_max(self):
        with self.lock:
            if len(self.heap) == 0:
                return None
            max_record = self.heap[0]
            self.heap[0] = self.heap[-1]
            del self.heap[-1]
            self._bubble_down(0)
            return max_record

    def update_data_rate(self, connection_id, new_rate):
        with self.lock:
            for i, record in enumerate(self.heap):
                if record.connection_id == connection_id:
                    self.heap[i].current_data_rate = new_rate
                    self._bubble_up(i)
                    break

class ExternalService:
    def __init__(self, name, service_url, fallback_service=None, cache_eviction_policy=None):
        self.name = name
        self.service_url = service_url
        self.fallback_service = fallback_service
        self.cache_eviction_policy = cache_eviction_policy
        self.cache = {}

    def call(self, request):
        try:
            # Simulate external service call with random delay and failure rate
            time.sleep(random.uniform(0.1, 2))
            if random.random() < 0.1:
                raise Exception("Service timeout or connection issue")
            return "Success"
        except Exception as e:
            if self.fallback_service:
                return self.fallback_service.call(request)
            else:
                raise e

class LoggingSystem:
    def __init__(self, level="INFO"):
        self.level = level
        self.logs = []

    def log(self, message, level):
        if level >= self.level:
            self.logs.append((time.time(), level, message))
            print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} [{level}] {message}")

class Module:
    def __init__(self, heap_size=10_000_000):
        self.heap = BinaryHeap()
        self.external_services = {
            "billing": ExternalService("Billing", "http://billing.example.com"),
            "status_monitoring": ExternalService("Status Monitoring", "http://monitoring.example.com"),
            "logging": LoggingSystem(level="DEBUG")
        }

    def add_device(self, record):
        self.heap.insert(record)

    def update_rate(self, connection_id, new_rate):
        self.heap.update_data_rate(connection_id, new_rate)

    def process_records(self):
        while True:
            max_record = self.heap.extract_max()
            if not max_record:
                break
            try:
                # Simulate processing with external services
                billing_result = self.external_services["billing"].call(max_record)
                status_result = self.external_services["status_monitoring"].call(max_record)
                log_message = f"Processed device {max_record.connection_id}, Billing: {billing_result}, Status: {status_result}"
                self.external_services["logging"].log(log_message, "INFO")
            except Exception as e:
                log_message = f"Error processing device {max_record.connection_id}: {e}"
                self.external_services["logging"].log(log_message, "ERROR")

if __name__ == "__main__":
    module = Module()
    for _ in range(100_000):
        record = DEVICE_CONNECTION_RECORD(time.time(), str(_), random.randint(100, 1000), random.choice(["None", "Error1", "Error2"]))
        module.add_device(record)

    process_thread = threading.Thread(target=module.process_records)
    process_thread.start()
```

