// ClinicStatusUpdater.java

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.cache.CacheManager;
import org.springframework.http.ResponseEntity;
import org.springframework.retry.backoff.ExponentialBackOffPolicy;
import org.springframework.retry.support.RetryTemplate;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestTemplate;

@Service
public class ClinicStatusUpdater {

    @Autowired
    private RestTemplate restTemplate;

    @Autowired
    private CacheManager cacheManager;

    private RetryTemplate retryTemplate;

    public ClinicStatusUpdater() {
        retryTemplate = new RetryTemplate();
        ExponentialBackOffPolicy backOffPolicy = new ExponentialBackOffPolicy();
        backOffPolicy.setInitialInterval(1000L);
        backOffPolicy.setMaxInterval(30000L);
        backOffPolicy.setMultiplier(2.0);
        retryTemplate.setBackOffPolicy(backOffPolicy);
    }

    public ResponseEntity<String> getClinicStatus(String clinicId) {
        String cacheKey = "clinicStatus:" + clinicId;
        Object cachedValue = cacheManager.getCache("clinics").get(cacheKey).get();

        if (cachedValue != null) {
            return new ResponseEntity<>(cachedValue.toString(), HttpStatus.OK);
        } else {
            return retryTemplate.execute(context -> {
                String statusFromApi = restTemplate.getForObject("https://api.clinic.com/status/" + clinicId, String.class);
                cacheManager.getCache("clinics").put(cacheKey, statusFromApi);
                return new ResponseEntity<>(statusFromApi, HttpStatus.OK);
            });
        }
    }

    // Additional methods for handling retries, fallbacks, and caching as described
}
