# Import necessary libraries
from flask import Flask, request, jsonify
from flask_cors import CORS
from flask_httpauth import HTTPBasicAuth
from ratelimiter import RateLimiter
import redis
import requests

# Initialize Flask app
app = Flask(__name__)
CORS(app)
auth = HTTPBasicAuth()

# Setup rate limiting
rate_limiter = RateLimiter(max_calls=100, period=60)

# Setup Redis for caching
redis_client = redis.StrictRedis(host='localhost', port=6379, db=0)

# Dummy user database for authentication
users = {
    "admin": "secret",
}

@auth.verify_password
def verify_password(username, password):
    if username in users and users[username] == password:
        return username

@app.route('/api/external', methods=['GET'])
@auth.login_required
@rate_limiter.limit("100/day;20/hour")
def external_api():
    cache_key = request.url
    result = redis_client.get(cache_key)

    if result is None:
        try:
            response = requests.get('https://api.example.com/data')
            response.raise_for_status()
            result = response.json()
            redis_client.setex(cache_key, 3600, result)  # Cache for 1 hour
        except requests.RequestException as e:
            return jsonify({"error": str(e)}), 502
    else:
        result = json.loads(result)

    return jsonify(result)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
