DATABASE_URL = "sqlite:///banking.db"
engine = create_engine(DATABASE_URL)
SessionLocal = sessionmaker(autocommit=False, autoflush=False, bind=engine)
Base = declarative_base()

# Models
class Customer(Base):
    __tablename__ = "customers"

    id = Column(Integer, primary_key=True, index=True)
    name = Column(String, index=True)
    email = Column(String, unique=True, index=True)
    balance = Column(Float, default=0.0)
    is_active = Column(Boolean, default=True)
    last_updated = Column(DateTime, default=datetime.utcnow)

Base.metadata.create_all(bind=engine)

# Dependency
def get_db():
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()

# Schemas
class CustomerCreate(BaseModel):
    name: str
    email: str

class CustomerUpdate(BaseModel):
    name: Optional[str]
    email: Optional[str]
    balance: Optional[float]

# Services
def create_customer(db: Session, customer_create: CustomerCreate):
    db_customer = Customer(name=customer_create.name, email=customer_create.email)
    try:
        db.add(db_customer)
        db.commit()
        db.refresh(db_customer)
        return db_customer
    except ValidationError as e:
        raise HTTPException(status_code=400, detail=str(e))

def update_customer(db: Session, customer_id: int, customer_update: CustomerUpdate):
    db_customer = db.query(Customer).filter(Customer.id == customer_id).first()
    if not db_customer:
        raise HTTPException(status_code=404, detail="Customer not found")
    try:
        for field in customer_update.dict(exclude_unset=True):
            setattr(db_customer, field, customer_update.dict()[field])
        db.add(db_customer)
        db.commit()
        db.refresh(db_customer)
        return db_customer
    except ValidationError as e:
        raise HTTPException(status_code=400, detail=str(e))

def delete_customer(db: Session, customer_id: int):
    db_customer = db.query(Customer).filter(Customer.id == customer_id).first()
    if not db_customer:
        raise HTTPException(status_code=404, detail="Customer not found")
    try:
        if db_customer.is_active:
            return {"error": "Cannot delete active customer"}
        db.delete(db_customer)
        db.commit()
        return {"message": "Customer deleted successfully"}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

# Endpoints
@app.post("/customers/", response_model=Customer)
def create_customer_endpoint(customer_create: CustomerCreate, db: Session = Depends(get_db)):
    return create_customer(db=db, customer_create=customer_create)

@app.put("/customers/{customer_id}", response_model=Customer)
def update_customer_endpoint(customer_id: int, customer_update: CustomerUpdate, db: Session = Depends(get_db)):
    return update_customer(db=db, customer_id=customer_id, customer_update=customer_update)

@app.delete("/customers/{customer_id}")
def delete_customer_endpoint(customer_id: int, db: Session = Depends(get_db)):
    return delete_customer(db=db, customer_id=customer_id)
```

