<?php
function manageUserAccount($_REQUEST) {
    $id = isset($_REQUEST['id']) ? intval($_REQUEST['id']) : null;
    $name = isset($_REQUEST['name']) ? mysqli_real_escape_string($conn, $_REQUEST['name']) : '';
    $email = isset($_REQUEST['email']) ? mysqli_real_escape_string($conn, $_REQUEST['email']) : '';
    $password = isset($_REQUEST['password']) ? mysqli_real_escape_string($conn, $_REQUEST['password']) : '';
    $sub_action = isset($_REQUEST['sub_action']) ? $_REQUEST['sub_action'] : '';

    // Validate and sanitize input
    if (empty($name) || empty($email) || empty($sub_action)) {
        http_response_code(400);
        echo json_encode(array('error' => 'Invalid input'));
        return;
    }

    if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
        http_response_code(400);
        echo json_encode(array('error' => 'Invalid email format'));
        return;
    }

    // Connect to the database
    $conn = mysqli_connect("localhost", "username", "password", "database");
    if (!$conn) {
        die(json_encode(array('error' => 'Database connection failed')));
    }

    // Start a transaction
    mysqli_begin_transaction($conn);

    try {
        switch ($sub_action) {
            case 'create':
                $sql = "INSERT INTO users (name, email, password) VALUES (?, ?, ?)";
                break;
            case 'update':
                $sql = "UPDATE users SET name=?, email=?, password=? WHERE id=?";
                break;
            case 'delete':
                $sql = "DELETE FROM users WHERE id=?";
                break;
            default:
                http_response_code(400);
                echo json_encode(array('error' => 'Invalid sub_action'));
                return;
        }

        $stmt = mysqli_prepare($conn, $sql);
        if (!$stmt) {
            throw new Exception("Prepare failed: " . mysqli_error($conn));
        }

        switch ($sub_action) {
            case 'create':
                mysqli_stmt_bind_param($stmt, "sssi", $name, $email, $password, $id);
                break;
            case 'update':
                mysqli_stmt_bind_param($stmt, "sssis", $name, $email, $password, $id, $id);
                break;
            case 'delete':
                mysqli_stmt_bind_param($stmt, "i", $id);
                break;
        }

        if (!mysqli_stmt_execute($stmt)) {
            throw new Exception("Execute failed: " . mysqli_error($conn));
        }

        // Commit the transaction
        mysqli_commit($conn);

        echo json_encode(array('success' => true));
    } catch (Exception $e) {
        // Rollback the transaction on error
        mysqli_rollback($conn);
        http_response_code(500);
        echo json_encode(array('error' => $e->getMessage()));
    }

    // Close the database connection
    mysqli_close($conn);
}
?>
