const fs = require('fs').promises;
const path = require('path');
const axios = require('axios');

class AsyncFileProcessor {
  constructor(apiUrl, maxConcurrentDownloads = 10, logger = console) {
    this.apiUrl = apiUrl;
    this.maxConcurrentDownloads = maxConcurrentDownloads;
    this.logger = logger;
    this.pendingDownloads = 0;
    this.queue = [];
  }

  async fetchMetadata(filePath) {
    try {
      const response = await axios.get(`${this.apiUrl}/metadata`, { params: { filePath } });
      return response.data;
    } catch (error) {
      this.logger.error(`Error fetching metadata for ${filePath}:`, error);
      throw error;
    }
  }

  async processFile(filePath, transformFunction) {
    try {
      const metadata = await this.fetchMetadata(filePath);
      const content = await fs.readFile(filePath, 'utf8');
      return transformFunction(content, metadata);
    } catch (error) {
      this.logger.error(`Error processing file ${filePath}:`, error);
      throw error;
    }
  }

  async downloadFile(filePath, transformFunction) {
    if (this.pendingDownloads >= this.maxConcurrentDownloads) {
      await new Promise(resolve => setTimeout(resolve, 100));
      return this.downloadFile(filePath, transformFunction);
    }

    try {
      this.pendingDownloads++;
      const result = await this.processFile(filePath, transformFunction);
      this.logger.info(`Processed file ${filePath}`);
      return result;
    } finally {
      this.pendingDownloads--;
    }
  }

  async startProcessing(files, transformFunction) {
    files.forEach(filePath => {
      if (!this.queue.includes(filePath)) {
        this.queue.push(filePath);
        this.downloadFile(filePath, transformFunction).catch(console.error);
      }
    });
  }

  static createLogger() {
    return require('winston').createLogger({
      level: 'info',
      format: winston.format.json(),
      transports: [
        new winston.transports.File({ filename: 'app.log' }),
        new winston.transports.Console()
      ]
    });
  }
}

// Usage example
const apiURL = 'https://api.example.com';
const logger = AsyncFileProcessor.createLogger();
const processor = new AsyncFileProcessor(apiURL, 10, logger);

fs.readdir('/path/to/directory')
  .then(files => files.map(file => path.join('/path/to/directory', file)))
  .then(processor.startProcessing.bind(processor, (_, content) => {
    // Example transformation function
    return content.toUpperCase();
  }))
  .catch(console.error);
```

This code provides a basic structure for an asynchronous file processing system in JavaScript. It uses Promises and the `axios` library to fetch metadata from an external API and handle file reading. The `AsyncFileProcessor` class manages concurrency, error handling, and logging.

To use this code, you need to replace `'https://api.example.com'` with the actual URL of your external API. You can also customize the transformation function as needed for different processing requirements."]

