const express = require('express');
const fs = require('fs');
const path = require('path');
const axios = require('axios');
const { promisify } = require('util');

const app = express();
app.use(express.json());

// Load modules dynamically from a directory
async function loadModulesFromDirectory(directory) {
    const files = await promisify(fs.readdir)(directory);
    return Promise.all(files.filter(file => file.endsWith('.js')).map(async file => {
        try {
            const modulePath = path.join(directory, file);
            const module = require(modulePath);
            if (module.dependencies && Array.isArray(module.dependencies)) {
                module.dependencies = await loadModulesFromDirectory(path.join(__dirname, module.dependencies));
            }
            return module;
        } catch (error) {
            console.error(`Failed to load module ${file}:`, error);
            return null;
        }
    }));
}

// Execute modules in the correct dependency order
async function executeModule(module, args = {}) {
    if (!module || !module.execute) return;

    const dependenciesPromise = Promise.all(module.dependencies.map(dep => executeModule(dep, args)));
    const [dependenciesResult] = await Promise.race([
        dependenciesPromise,
        promisify(setTimeout)(10000).then(() => { throw new Error('Execution timed out'); })
    ]);

    try {
        return await module.execute(args, dependenciesResult);
    } catch (error) {
        console.error(`Error executing module ${module.name}:`, error);
        throw error;
    }
}

// Route to process user data
app.post('/process', async (req, res) => {
    const userData = req.body;

    try {
        // Load modules dynamically from a specified directory
        const modules = await loadModulesFromDirectory(path.join(__dirname, 'modules'));

        // Execute modules in the correct dependency order
        for (const module of modules) {
            if (module && typeof module.name === 'string' && module.execute) {
                console.log(`Executing module: ${module.name}`);
                await executeModule(module, { userData });
            }
        }

        res.status(200).json({ message: 'User data processed successfully' });
    } catch (error) {
        console.error('Error processing user data:', error);
        res.status(500).json({ error: 'Internal Server Error' });
    }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
    console.log(`Server is running on port ${PORT}`);
});
