# Define the main pipeline class
class LogIngestionPipeline:
    def __init__(self):
        self.log_parsers = {}
        self.transformation_tools = {}
        self.storage_backends = {}
        self.alerting_systems = {}

    def add_log_parser(self, name, parser_function):
        self.log_parsers[name] = parser_function

    def add_transformation_tool(self, name, transformation_function):
        self.transformation_tools[name] = transformation_function

    def add_storage_backend(self, name, storage_connection):
        self.storage_backends[name] = storage_connection

    def add_alerting_system(self, name, alerting_function):
        self.alerting_systems[name] = alerting_function

    def route_logs(self, logs, target):
        for log in logs:
            parsed_log = self.parse_log(log)
            transformed_log = self.transform_log(parsed_log)
            self.store_log(transformed_log, target)

    def parse_log(self, log):
        parser_name = "default"  # Default to a default parser if none specified
        return self.log_parsers.get(parser_name)(log)

    def transform_log(self, log):
        transformation_name = "default"  # Default to a default transformation if none specified
        return self.transformation_tools.get(transformation_name)(log)

    def store_log(self, log, target):
        storage_name = "default"  # Default to a default storage backend if none specified
        return self.storage_backends.get(storage_name).store(log, target)

# Example usage of the LogIngestionPipeline class
