#include <stdlib.h>
#include <stdio.h>

// Define a simple structure for a Finite State Automaton (FSA)
typedef struct {
    int** transitionTable;
    int numStates;
    int* initialState;
} FSA;

// Function to create a new state list from an FSA
int* createStateList(int* states, int numStates, FSA* fsa, int lastState) {
    if (numStates <= 0 || lastState >= fsa->numStates) {
        return NULL; // Invalid input or FSA configuration
    }

    // Allocate memory for the new state list
    int* newStateList = (int*)malloc((numStates + 1) * sizeof(int));
    if (newStateList == NULL) {
        return NULL; // Insufficient memory
    }

    // Copy states from input to new list, including the last state
    for (int i = 0; i < numStates; i++) {
        newStateList[i] = states[i];
    }
    newStateList[numStates] = lastState;

    return newStateList;
}

// Example usage
int main() {
    // Create an FSA with 4 states and a simple transition table
    int initialState[] = {0};
    int** transitionTable = (int**)malloc(4 * sizeof(int*));
    for (int i = 0; i < 4; i++) {
        transitionTable[i] = (int*)malloc(4 * sizeof(int));
        for (int j = 0; j < 4; j++) {
            transitionTable[i][j] = (i + j) % 4;
        }
    }

    FSA fsa = {transitionTable, 4, initialState};

    // Define states and last state
    int states[] = {0, 1};
    int numStates = 2;
    int lastState = 3;

    // Create a new state list
    int* newStateList = createStateList(states, numStates, &fsa, lastState);
    if (newStateList != NULL) {
        printf("New State List: ");
        for (int i = 0; i <= numStates; i++) {
            printf("%d ", newStateList[i]);
        }
        printf("\n");

        // Free allocated memory
        free(newStateList);
    } else {
        printf("Failed to create state list.\n");
    }

    return 0;
}
