```c
#include <semaphore.h>
#include <stdio.h>

#define MAX_TOKEN_RECORDS 100

typedef struct {
    char access_token[256];
    int expires_in;
    char token_type[32];
    char refresh_token[256];
} TokenRecord;

TokenRecord token_records[MAX_TOKEN_RECORDS];
sem_t semaphore;

void initialize_semaphore() {
    sem_init(&semaphore, 0, MAX_TOKEN_RECORDS);
}

int update_token_record(int index, const TokenRecord *new_record) {
    if (sem_wait(&semaphore) == -1) {
        perror("Failed to acquire semaphore");
        return -1;
    }

    token_records[index] = *new_record;

    if (sem_post(&semaphore) == -1) {
        perror("Failed to release semaphore");
        return -1;
    }

    return 0;
}

int main() {
    initialize_semaphore();

    TokenRecord new_record = {"token", 3600, "Bearer", "refresh_token"};
    update_token_record(0, &new_record);

    return 0;
}
```

This code initializes a semaphore with an initial value equal to the maximum number of token records. It then acquires the semaphore before updating a token record and releases it afterward to ensure atomic updates.

Please note that this is a basic implementation for educational purposes. In a real-world scenario, you would need to consider additional factors such as error handling, security measures, and performance optimizations.']

