#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_STRUCTURES 1024

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_FLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct LinkedListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct LinkedListNode* next;
} LinkedListNode;

LinkedListNode* head = NULL;
pthread_mutex_t listMutex;

void initializeCRCIndicationPDU(NFAPI_CRC_INDICATION_PDU_T* pdu, uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
    pdu->CRC_FLAG = rand() % 2; // Simplified for example
}

LinkedListNode* createNewNode(uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    LinkedListNode* newNode = (LinkedListNode*)malloc(sizeof(LinkedListNode));
    if (newNode == NULL) {
        // Handle memory allocation failure, e.g., retry or fallback
        return NULL;
    }
    initializeCRCIndicationPDU(&newNode->data, RX_UE_INFORMATION_TAG, RNTI);
    newNode->next = NULL;
    return newNode;
}

void insertNode(uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    pthread_mutex_lock(&listMutex);
    LinkedListNode* newNode = createNewNode(RX_UE_INFORMATION_TAG, RNTI);
    if (newNode != NULL) {
        if (head == NULL) {
            head = newNode;
        } else {
            LinkedListNode* temp = head;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = newNode;
        }
    }
    pthread_mutex_unlock(&listMutex);
}

void freeList() {
    pthread_mutex_lock(&listMutex);
    LinkedListNode* current = head;
    while (current != NULL) {
        LinkedListNode* next = current->next;
        free(current);
        current = next;
    }
    head = NULL;
    pthread_mutex_unlock(&listMutex);
}

int main() {
    srand(time(NULL));
    pthread_mutex_init(&listMutex, NULL);

    // Example usage
    insertNode(12345, 67890);
    insertNode(54321, 09876);

    freeList();
    pthread_mutex_destroy(&listMutex);

    return 0;
}
```

