// Import necessary libraries
const express = require('express');
const bodyParser = require('body-parser');
const http = require('http');
const WebSocket = require('ws');

// Initialize Express application
const app = express();
app.use(bodyParser.json());

// Create HTTP server and WebSocket server
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

// Define data source connectors
const iotConnector = require('./connectors/iot');
const socialMediaConnector = require('./connectors/socialMedia');
const legacyDBConnector = require('./connectors/legacyDB');

// Define data processors
const iotProcessor = require('./processors/iot');
const socialMediaProcessor = require('./processors/socialMedia');
const legacyDBProcessor = require('./processors/legacyDB');

// Connect to data sources
iotConnector.connect();
socialMediaConnector.connect();
legacyDBConnector.connect();

// Handle WebSocket connections
wss.on('connection', (ws) => {
  ws.on('message', (message) => {
    const data = JSON.parse(message);
    processMessage(data, ws);
  });
});

// Process incoming messages
async function processMessage(data, ws) {
  try {
    let processedData;
    if (data.source === 'iot') {
      processedData = await iotProcessor.process(data);
    } else if (data.source === 'socialMedia') {
      processedData = await socialMediaProcessor.process(data);
    } else if (data.source === 'legacyDB') {
      processedData = await legacyDBProcessor.process(data);
    }

    ws.send(JSON.stringify(processedData));
  } catch (error) {
    console.error('Error processing message:', error);
    ws.send(JSON.stringify({ error: 'Internal Server Error' }));
  }
}

// Start the server
const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
```

