class PeriodicPruner {
private:
    Octree& octree_;
    SpatialDatabase& db_;
    std::thread thread_;
    std::condition_variable cv_;
    bool running_;

public:
    PeriodicPruner(Octree& octree, SpatialDatabase& db)
        : octree_(octree), db_(db), running_(true) {
        thread_ = std::thread(&PeriodicPruner::run, this);
    }

    ~PeriodicPruner() {
        {
            std::lock_guard<std::mutex> lock(cv_.mutex_);
            running_ = false;
        }
        cv_.notify_all();
        if (thread_.joinable()) {
            thread_.join();
        }
    }

private:
    void run() {
        while (true) {
            std::unique_lock<std::mutex> lock(cv_.mutex_);
            cv_.wait_for(lock, std::chrono::minutes(1), [this] { return !running_; });
            if (!running_) break;
            octree_.prune();
            db_.saveOctree(octree_, "octree.db");
        }
    }
};

int main() {
