// Define necessary headers and libraries
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>

// Function to initialize cryptographic context
EVP_CIPHER_CTX* init_crypto_context(const char *cipher_name, int encrypt) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;
    const EVP_CIPHER *cipher = EVP_get_cipherbyname(cipher_name);
    if (!cipher) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    if (encrypt)
        EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);
    else
        EVP_DecryptInit_ex(ctx, cipher, NULL, NULL, NULL);
    return ctx;
}

// Function to set cryptographic key and IV
int set_key_iv(EVP_CIPHER_CTX *ctx, const unsigned char *key, int key_len, const unsigned char *iv) {
    if (!EVP_CIPHER_CTX_set_key_length(ctx, key_len))
        return 0;
    if (!EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv)) // IV is only used for decryption
        return 0;
    return 1;
}

// Function to handle encryption/decryption of data
int crypto_transform(EVP_CIPHER_CTX *ctx, unsigned char *out, int *outl, const unsigned char *in, int inl) {
    if (!EVP_EncryptUpdate(ctx, out, outl, in, inl))
        return 0;
    if (!EVP_EncryptFinal_ex(ctx, out + *outl, outl))
        return 0;
    return 1;
}

// Function to cleanup cryptographic context
void cleanup_crypto_context(EVP_CIPHER_CTX *ctx) {
    EVP_CIPHER_CTX_free(ctx);
}

// Example usage of the cryptographic library
int main() {
    unsigned char key[32], iv[16];
    RAND_bytes(key, sizeof(key));
    RAND_bytes(iv, sizeof(iv));

    const char *cipher_name = "aes-256-cbc";
    EVP_CIPHER_CTX *ctx = init_crypto_context(cipher_name, 1);
    if (!ctx) {
        fprintf(stderr, "Failed to initialize cryptographic context\n");
        return 1;
    }

    unsigned char plaintext[] = "Hello, World!";
    int outlen, plaintext_len = sizeof(plaintext) - 1;
    unsigned char ciphertext[64];

    if (!set_key_iv(ctx, key, sizeof(key), iv)) {
        fprintf(stderr, "Failed to set key and IV\n");
        cleanup_crypto_context(ctx);
        return 1;
    }

    if (!crypto_transform(ctx, ciphertext, &outlen, plaintext, plaintext_len)) {
        fprintf(stderr, "Encryption failed\n");
        cleanup_crypto_context(ctx);
        return 1;
    }
    printf("Encrypted: %.*s\n", outlen, ciphertext);

    unsigned char decryptedtext[64];
    int decoutlen;

    if (!crypto_transform(ctx, decryptedtext, &decoutlen, ciphertext, outlen)) {
        fprintf(stderr, "Decryption failed\n");
        cleanup_crypto_context(ctx);
        return 1;
    }
    decryptedtext[decoutlen] = '\0';
    printf("Decrypted: %s\n", decryptedtext);

    cleanup_crypto_context(ctx);
    return 0;
}
