    private readonly ILogger<CertificateService> _logger;
    private readonly AsyncRetryPolicy _retryPolicy;

    public CertificateService(HttpClient httpClient, ILogger<CertificateService> logger)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _retryPolicy = Policy
            .Handle<HttpRequestException>()
            .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));
    }

    public async Task<string> GenerateCertificateFromOAuthRequestAsync(string accessToken, string directoryPath)
    {
        if (string.IsNullOrEmpty(accessToken))
            throw new ArgumentException("Access token is required", nameof(accessToken));
        if (!Directory.Exists(directoryPath) || !Path.IsPathFullyQualified(directoryPath))
            throw new ArgumentException("Invalid or non-existent directory path", nameof(directoryPath));

        _logger.LogInformation("Starting certificate generation process.");

        try
        {
            var config = await GetDynamicConfigurationAsync(accessToken);
            var privateKeyPath = Path.Combine(directoryPath, config.PrivateKeyFileName);
            var certificatePath = Path.Combine(directoryPath, config.CertificateFileName);

            // Perform file operations here

            return "Certificate generated successfully.";
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to generate certificate.");
            throw;
        }
    }

    private async Task<DynamicConfig> GetDynamicConfigurationAsync(string accessToken)
    {
        using var request = new HttpRequestMessage(HttpMethod.Get, "https://api.example.com/config");
        request.Headers.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", accessToken);

        var response = await _retryPolicy.ExecuteAsync(async () =>
            await _httpClient.SendAsync(request));

        if (!response.IsSuccessStatusCode)
            throw new HttpRequestException($"Failed to fetch configuration: {response.StatusCode}");

        return await response.Content.ReadAsAsync<DynamicConfig>();
    }
}

public class DynamicConfig
{
    public string PrivateKeyFileName { get; set; }
    public string CertificateFileName { get; set; }
}
