        if (transactions[i].age <= max_age && transactions[i].count <= max_count && transactions[i].weighted_sum > *out_max_weighted_sum) {
            *out_max_weighted_sum = transactions[i].weighted_sum;
            *out_transaction_id = i;
        }
    }

    return 0;
}
