import java.io.*;
import java.net.*;
import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import java.security.MessageDigest;

interface Deserializable {
    void deserialize(ObjectInputStream ois) throws IOException, ClassNotFoundException;
}

class DeserializationFramework {
    public static <T extends Deserializable> T loadFromByteArray(byte[] data, Class<T> cls) throws Exception {
        SecretKeySpec secretKey = generateSecretKey();
        Cipher cipher = Cipher.getInstance("AES");
        cipher.init(Cipher.DECRYPT_MODE, secretKey);
        byte[] decryptedData = cipher.doFinal(data);

        ByteArrayInputStream bais = new ByteArrayInputStream(decryptedData);
        ObjectInputStream ois = new ObjectInputStream(bais);
        T instance = cls.cast(ois.readObject());
        ois.close();

        return instance;
    }

    private static SecretKeySpec generateSecretKey() throws Exception {
        byte[] keyBytes = "MySecretKey123".getBytes();
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        keyBytes = md.digest(keyBytes);
        return new SecretKeySpec(keyBytes, "AES");
    }
}

class NetworkCommunicationLayer {
    public static void sendTCPMessage(String host, int port, byte[] data) throws IOException {
        Socket socket = new Socket(host, port);
        OutputStream os = socket.getOutputStream();
        os.write(data);
        os.flush();
        socket.close();
    }

    public static void sendUDPMessage(String host, int port, byte[] data) throws IOException {
        DatagramSocket socket = new DatagramSocket();
        InetAddress address = InetAddress.getByName(host);
        DatagramPacket packet = new DatagramPacket(data, data.length, address, port);
        socket.send(packet);
        socket.close();
    }
}

class EncryptionUtils {
    public static byte[] encrypt(byte[] data, SecretKeySpec secretKey) throws Exception {
        Cipher cipher = Cipher.getInstance("AES");
        cipher.init(Cipher.ENCRYPT_MODE, secretKey);
        return cipher.doFinal(data);
    }

    public static byte[] decrypt(byte[] encryptedData, SecretKeySpec secretKey) throws Exception {
        Cipher cipher = Cipher.getInstance("AES");
        cipher.init(Cipher.DECRYPT_MODE, secretKey);
        return cipher.doFinal(encryptedData);
    }
}

class SecureClassLoader extends ClassLoader {
    private String whitelist;

    public SecureClassLoader(String whitelist) {
        this.whitelist = whitelist;
    }

    @Override
    protected Class<?> loadClass(String name, boolean resolve) throws ClassNotFoundException {
        if (!whitelist.contains(name)) {
            throw new SecurityException("Class " + name + " is not in the whitelist.");
        }
        return super.loadClass(name, resolve);
    }
}

