const express = require('express');
const aws = require('aws-sdk');
const axios = require('axios');
const Redis = require('ioredis');

const app = express();
app.use(express.json());

// AWS S3 Configuration
const s3 = new aws.S3({
  accessKeyId: 'YOUR_ACCESS_KEY_ID',
  secretAccessKey: 'YOUR_SECRET_ACCESS_KEY'
});

// Database Configuration
const dbUrl = 'http://your-database-api.com/users';

// Redis Configuration
const redisClient = new Redis();

app.get('/files/:userId', async (req, res) => {
  const { userId } = req.params;
  const page = parseInt(req.query.page || 1);
  const limit = Math.min(parseInt(req.query.limit || 1000), 1000);

  try {
    // Check Redis cache
    let cachedFiles = await redisClient.get(`files:${userId}:${page}`);
    if (cachedFiles) {
      return res.json(JSON.parse(cachedFiles));
    }

    // Fetch user profile from database
    const response = await axios.get(`${dbUrl}/${userId}`);
    const user = response.data;

    // Fetch files from S3
    let params = {
      Bucket: 'your-s3-bucket-name',
      Prefix: `${user.id}/`,
      MaxKeys: limit,
      Marker: page > 1 ? req.query.marker : undefined
    };

    let data = [];
    do {
      const result = await s3.listObjectsV2(params).promise();
      data = data.concat(result.Contents);
      params.Marker = result.NextMarker;
    } while (data.length < limit && result.IsTruncated);

    // Process file metadata
    const files = data.map(file => ({
      fileName: file.Key.split('/').pop(),
      uploadTimestamp: file.LastModified,
      fileSize: file.Size
    }));

    // Cache the result
    await redisClient.set(`files:${userId}:${page}`, JSON.stringify(files));

    res.json({
      totalCount: data.length,
      files: files
    });
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

app.listen(3000, () => {
  console.log('Server is running on port 3000');
});
```

