from flask import Flask, request, jsonify
import json
from retrying import retry
from functools import wraps
from threading import Lock

app = Flask(__name__)
lock = Lock()

# Define a decorator for retries with exponential backoff
@retry(stop_max_attempt_number=3, wait_exponential_multiplier=1000)
def call_external_service(url):
    response = requests.get(url)
    if response.status_code != 200:
        raise Exception("External service error")
    return response.json()

# Define a decorator for idempotent operations
def idempotent(f):
    @wraps(f)
    def wrapper(*args, **kwargs):
        with lock:
            result = f(*args, **kwargs)
        return result
    return wrapper

# Define an asynchronous task handler
@app.route('/process_task', methods=['POST'])
def process_task():
    data = request.json
    # Asynchronously process the task
    import threading
    thread = threading.Thread(target=_process_task, args=(data,))
    thread.start()
    return jsonify({"message": "Task started"}), 202

def _process_task(data):
    # Task processing logic here
    pass

# Define a route to handle payment gateway operations
@app.route('/payment', methods=['POST'])
@idempotent
def process_payment():
    data = request.json
    payment_info = call_external_service(f"https://gateway.com/pay?data={json.dumps(data)}")
    return jsonify(payment_info), 200

# Define a route to handle inventory management
@app.route('/inventory', methods=['GET'])
@idempotent
def get_inventory():
    inventory_data = call_external_service("https://inventory.com/data")
    return jsonify(inventory_data), 200

# Define a route for user authentication
@app.route('/auth', methods=['POST'])
@idempotent
def authenticate_user():
    data = request.json
    auth_info = call_external_service(f"https://auth.com/login?data={json.dumps(data)}")
    return jsonify(auth_info), 200

# Main function to run the Flask app
if __name__ == '__main__':
