import hashlib
from concurrent.futures import ThreadPoolExecutor
import aiohttp
import asyncio
from cryptography.fernet import Fernet

class MD5Hasher:
    def __init__(self, key):
        self.key = Fernet(key)

    def hash_data(self, data):
        return hashlib.md5(data.encode()).hexdigest()

    async def hash_webhook_data(self, url):
        async with aiohttp.ClientSession() as session:
            async with session.get(url) as response:
                data = await response.read()
                return self.hash_data(data)

    def hash_file(self, file_path):
        with open(file_path, 'rb') as f:
            return hashlib.md5(f.read()).hexdigest()

class AsyncHasher(MD5Hasher):
    async def __aenter__(self):
        self.executor = ThreadPoolExecutor(max_workers=10)
        await asyncio.sleep(0.1)  # Simulate setup time
        return self

    async def __aexit__(self, exc_type, exc_value, traceback):
        self.executor.shutdown(wait=True)

async def process_request(request):
    hasher = MD5Hasher(key=Fernet.generate_key())
    if request['source'] == 'file':
        return await hasher.hash_file(request['path'])
    elif request['source'] == 'webhook':
        return await hasher.hash_webhook_data(request['url'])

async def main():
    requests = [
        {'source': 'file', 'path': 'example.txt'},
        {'source': 'webhook', 'url': 'http://example.com/data'}
    ]
    tasks = [process_request(req) for req in requests]
    results = await asyncio.gather(*tasks)
    print(results)

if __name__ == "__main__":
    asyncio.run(main())
