#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/sha.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef enum {
    CIPHER_DES_ECB,
    CIPHER_DES_EDE,
    CIPHER_DES_EDE3,
    CIPHER_AES_CBC,
    CIPHER_AES_GCM,
    CIPHER_CHACHA20,
    CIPHER_CUSTOM
} CipherType;

typedef struct {
    EVP_CIPHER* cipher;
    unsigned char key[32];
    unsigned char iv[16];
} CipherContext;

CipherContext* create_cipher_context(CipherType type) {
    CipherContext* context = (CipherContext*)malloc(sizeof(CipherContext));
    memset(context, 0, sizeof(CipherContext));

    switch (type) {
        case CIPHER_DES_ECB:
            context->cipher = EVP_des_ecb();
            break;
        case CIPHER_DES_EDE:
            context->cipher = EVP_des_ede();
            break;
        case CIPHER_DES_EDE3:
            context->cipher = EVP_des_ede3();
            break;
        case CIPHER_AES_CBC:
            context->cipher = EVP_aes_256_cbc();
            break;
        case CIPHER_AES_GCM:
            context->cipher = EVP_aes_256_gcm();
            break;
        case CIPHER_CHACHA20:
            context->cipher = EVP_chacha20_poly1305();
            break;
        default:
            free(context);
            return NULL;
    }

    if (!RAND_bytes(context->key, 32) || !RAND_bytes(context->iv, 16)) {
        free(context);
        return NULL;
    }

    return context;
}

void encrypt_data(CipherContext* context, unsigned char* data, size_t data_len, unsigned char** encrypted_data, size_t* encrypted_len) {
    EVP_CIPHER_CTX* cipher_ctx = EVP_CIPHER_CTX_new();
    if (!cipher_ctx) {
        free(context);
        return;
    }

    int len;
    int ciphertext_len = 0;

    if (EVP_EncryptInit_ex(cipher_ctx, context->cipher, NULL, context->key, context->iv) != 1 ||
        EVP_EncryptUpdate(cipher_ctx, *encrypted_data, &len, data, data_len) != 1) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        free(context);
        return;
    }

    ciphertext_len += len;

    if (EVP_EncryptFinal_ex(cipher_ctx, (*encrypted_data) + len, &len) != 1) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        free(context);
        return;
    }

    ciphertext_len += len;

    *encrypted_len = ciphertext_len;
    EVP_CIPHER_CTX_free(cipher_ctx);
}

void decrypt_data(CipherContext* context, unsigned char* encrypted_data, size_t encrypted_len, unsigned char** decrypted_data, size_t* decrypted_len) {
    EVP_CIPHER_CTX* cipher_ctx = EVP_CIPHER_CTX_new();
    if (!cipher_ctx) {
        free(context);
        return;
    }

    int len;
    int plaintext_len = 0;

    if (EVP_DecryptInit_ex(cipher_ctx, context->cipher, NULL, context->key, context->iv) != 1 ||
        EVP_DecryptUpdate(cipher_ctx, *decrypted_data, &len, encrypted_data, encrypted_len) != 1) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        free(context);
        return;
    }

    plaintext_len += len;

    if (EVP_DecryptFinal_ex(cipher_ctx, (*decrypted_data) + len, &len) != 1) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        free(context);
        return;
    }

    plaintext_len += len;

    *decrypted_len = plaintext_len;
    EVP_CIPHER_CTX_free(cipher_ctx);
}

void destroy_cipher_context(CipherContext* context) {
    if (context) {
        free(context);
    }
}
