class Command {
public:
    virtual void execute() = 0;
};

class UsageCommand : public Command {
public:
    void execute() override {
        std::cout << "Usage: tool [options] [input files...]" << std::endl;
    }
};

class ManPageCommand : public Command {
public:
    void execute() override {
        std::cout << "Man page content here..." << std::endl;
    }
};

class OutputDirCommand : public Command {
public:
    void execute() override {
        std::cout << "Output directory set..." << std::endl;
    }
};

int main(int argc, char* argv[]) {
    std::vector<Command*> commands;

    for (int i = 1; i < argc; ++i) {
        if (std::string(argv[i]) == "--usage") {
            commands.push_back(new UsageCommand());
        } else if (std::string(argv[i]) == "--man") {
            commands.push_back(new ManPageCommand());
        } else if (std::string(argv[i]).substr(0, 2) == "-o") {
            commands.push_back(new OutputDirCommand());
        }
    }

    for (auto command : commands) {
        command->execute();
    }

    // Cleanup
    for (auto command : commands) {
        delete command;
    }

    return 0;
}
