#include <iostream>
#include <thread>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <openssl/md5.h>

struct LOG_ENTRY_T {
    std::string message;
    // Other fields as needed
};

class LogEntryPool {
private:
    std::vector<LOG_ENTRY_T*> pool;
    std::mutex mutex;
    std::condition_variable not_full;

public:
    LogEntryPool(size_t size) : pool(size, nullptr) {}

    ~LogEntryPool() {
        for (auto& entry : pool) {
            delete entry;
        }
    }

    LOG_ENTRY_T* getEntry() {
        std::unique_lock<std::mutex> lock(mutex);
        not_full.wait(lock, [this] { return !pool.empty(); });
        auto entry = pool.back();
        pool.pop_back();
        return entry;
    }

    void releaseEntry(LOG_ENTRY_T* entry) {
        std::lock_guard<std::mutex> lock(mutex);
        pool.push_back(entry);
        not_full.notify_one();
    }
};

class MD5Hasher {
public:
    static std::string hash(const std::string& data) {
        unsigned char digest[MD5_DIGEST_LENGTH];
        MD5((unsigned char*)data.c_str(), data.size(), (unsigned char*)&digest);

        char mdString[33];
        for(int i = 0; i < 16; ++i)
            sprintf(&mdString[i*2], "%02x", (unsigned int)digest[i]);

        return std::string(mdString);
    }
};

class LogProcessor {
private:
    LogEntryPool pool;
    std::queue<LOG_ENTRY_T*> taskQueue;
    std::mutex queueMutex;
    std::condition_variable not_empty;
    bool running;

public:
    LogProcessor(size_t poolSize, size_t numThreads) : pool(poolSize), running(true) {
        for (size_t i = 0; i < numThreads; ++i) {
            threads.emplace_back([this] { worker(); });
        }
    }

    ~LogProcessor() {
        {
            std::lock_guard<std::mutex> lock(queueMutex);
            running = false;
        }
        not_empty.notify_all();
        for (auto& thread : threads) {
            thread.join();
        }
    }

    void addTask(LOG_ENTRY_T* entry) {
        std::unique_lock<std::mutex> lock(queueMutex);
        taskQueue.push(entry);
        not_empty.notify_one();
    }

private:
    std::vector<std::thread> threads;

    void worker() {
        while (true) {
            LOG_ENTRY_T* entry = nullptr;
            {
                std::unique_lock<std::mutex> lock(queueMutex);
                not_empty.wait(lock, [this] { return !taskQueue.empty() || !running; });
                if (!running && taskQueue.empty()) break;
                entry = taskQueue.front();
                taskQueue.pop();
            }
            std::string hash = MD5Hasher::hash(entry->message);
            // Process the hash as needed
            pool.releaseEntry(entry);
        }
    }
};

int main() {
    LogProcessor processor(1024, 16);

    for (size_t i = 0; i < 1000000; ++i) {
        LOG_ENTRY_T* entry = new LOG_ENTRY_T{ "Log message " + std::to_string(i) };
        processor.addTask(entry);
    }

    return 0;
}
