import threading
import queue
import hashlib

LOG_ENTRY_T = namedtuple('LOG_ENTRY_T', ['message'])

class LogEntryPool:
    def __init__(self, size):
        self.pool = [None] * size
        self.lock = threading.Lock()
        self.not_full = threading.Condition(self.lock)

    def get_entry(self):
        with self.lock:
            self.not_full.wait_for(lambda: any(entry is None for entry in self.pool))
            entry = next(entry for entry in self.pool if entry is not None)
            self.pool.remove(entry)
            return entry

    def release_entry(self, entry):
        with self.lock:
            self.pool.append(entry)
            self.not_full.notify()

class MD5Hasher:
    @staticmethod
    def hash(data):
        md5 = hashlib.md5()
        md5.update(data.encode())
        return md5.hexdigest()

class LogProcessor:
    def __init__(self, pool_size, num_threads):
        self.pool = LogEntryPool(pool_size)
        self.task_queue = queue.Queue()
        self.lock = threading.Lock()
        self.not_empty = threading.Condition(self.lock)
        self.running = True
        self.threads = [threading.Thread(target=self.worker) for _ in range(num_threads)]
        for thread in self.threads:
            thread.start()

    def add_task(self, entry):
        with self.lock:
            self.task_queue.put(entry)
            self.not_empty.notify()

    def worker(self):
        while True:
            with self.lock:
                self.not_empty.wait_for(lambda: not self.task_queue.empty() or not self.running)
                if not self.running and self.task_queue.empty():
                    break
                entry = self.task_queue.get()
            hash_value = MD5Hasher.hash(entry.message)
            # Process the hash as needed
            self.pool.release_entry(entry)

if __name__ == "__main__":
    processor = LogProcessor(pool_size=1024, num_threads=16)

    for i in range(1000000):
        entry = LOG_ENTRY_T(message=f"Log message {i}")
        processor.add_task(entry)
