# Python function to calculate MD5 hash of a file

import hashlib

def calculate_md5_file(path):
    hasher = hashlib.md5()
    with open(path, 'rb') as f:
        while chunk := f.read(4096):
            hasher.update(chunk)
    return hasher.hexdigest()
