#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <stdbool.h>

// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the linked list node structure
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Define the linked list structure
typedef struct LinkedList {
    Node* head;
    Node* tail;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} LinkedList;

// Function to create a new node
Node* create_node(const NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode != NULL) {
        newNode->data = *data;
        newNode->next = NULL;
    }
    return newNode;
}

// Function to initialize the linked list
void init_linked_list(LinkedList* list, size_t initial_capacity) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
}

// Function to insert a node at the end of the linked list
void insert_node(LinkedList* list, const NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&list->lock);
    Node* newNode = create_node(data);
    if (newNode != NULL) {
        if (list->head == NULL) {
            list->head = newNode;
            list->tail = newNode;
        } else {
            list->tail->next = newNode;
            list->tail = newNode;
        }
        list->count++;
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to delete a node from the linked list
void delete_node(LinkedList* list, const NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* previous = NULL;
    while (current != NULL) {
        if (current->data.RX_UE_INFORMATION_TAG == data->RX_UE_INFORMATION_TAG &&
            current->data.RNTI == data->RNTI) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            if (current->next == NULL) {
                list->tail = previous;
            }
            free(current);
            list->count--;
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to get the count of nodes in the linked list
size_t get_count(LinkedList* list) {
    return list->count;
}

// Function to free the memory allocated for the linked list
void free_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}
