// C++ portion of the library

#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <functional>
#include <openssl/md5.h>

#define LOG_ENTRY_T int // Simplified for example purposes

struct LogEntry {
    LOG_ENTRY_T data;
};

class LogPool {
private:
    std::vector<LogEntry> pool;
    size_t capacity;
    std::mutex mtx;
    std::condition_variable cv;
    bool closed;

public:
    LogPool(size_t cap) : capacity(cap), closed(false) {}

    void add(const LogEntry& entry) {
        std::unique_lock<std::mutex> lock(mtx);
        while (pool.size() >= capacity && !closed) {
            cv.wait(lock);
        }
        if (!closed) {
            pool.push_back(entry);
            cv.notify_one();
        }
    }

    void processEntries(const std::function<void(LogEntry&)>& processor) {
        std::unique_lock<std::mutex> lock(mtx);
        while (true) {
            if (pool.empty() && closed) break;
            if (!pool.empty()) {
                LogEntry entry = pool.front();
                pool.erase(pool.begin());
                lock.unlock();
                processor(entry);
                lock.lock();
            }
        }
    }

    void close() {
        std::unique_lock<std::mutex> lock(mtx);
        closed = true;
        cv.notify_all();
    }
};

void findAndPrintMax(const LogEntry* arr, size_t size) {
    if (size == 0) return;
    LOG_ENTRY_T max = arr[0];
    for (size_t i = 1; i < size; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    std::cout << "Largest integer: " << max << std::endl;
}

// Python portion of the library

import hashlib
import asyncio

LOG_ENTRY_T = int

class LogPool:
    def __init__(self, capacity):
        self.pool = []
        self.capacity = capacity
        self.lock = asyncio.Lock()
        self.condition = asyncio.Condition(self.lock)
        self.closed = False

    async def add(self, entry: LOG_ENTRY_T):
        async with self.condition:
            while len(self.pool) >= self.capacity and not self.closed:
                await self.condition.wait()
            if not self.closed:
                self.pool.append(entry)
                self.condition.notify_one()

    async def process_entries(self, processor):
        async with self.lock:
            while True:
                if not self.pool and self.closed: break
                if self.pool:
                    entry = self.pool.pop(0)
                    await asyncio.to_thread(processor, entry)

    async def close(self):
        async with self.condition:
            self.closed = True
            self.condition.notify_all()

def find_and_print_max(arr: list[LOG_ENTRY_T]) -> None:
    if not arr: return
    max_value = max(arr)
    print(f"Largest integer: {max_value}")

# Entry point for Python script to read from stdin and process log entries

import sys
import asyncio

async def main():
    log_pool = LogPool(10000)  # Example capacity
    processor_task = asyncio.create_task(log_pool.process_entries(find_and_print_max))

    try:
        async for line in sys.stdin:
            entry = int(line.strip())
            await log_pool.add(entry)
    except EOFError:
        pass

    await log_pool.close()
    processor_task.cancel()

asyncio.run(main())
