    std::mutex clientsMutex;
    std::vector<Attack> attacks;
};

// GameAttackManager.cpp
#include "GameAttackManager.h"

GameAttackManager::GameAttackManager(const std::vector<Attack>& attacks)
    : attacks(attacks) {
    for (int i = 0; i < attacks.size(); ++i) {
        attackAvailability[i] = {false, std::condition_variable()};
    }
}

GameAttackManager::~GameAttackManager() {}

void GameAttackManager::selectAttack(int clientID, std::function<void(const Attack&)> callback) {
    std::unique_lock<std::mutex> lock(clientsMutex);
    int availableAttackIndex;
    do {
        for (int i = 0; i < attacks.size(); ++i) {
            if (!attackAvailability[i].first.load()) {
                availableAttackIndex = i;
                attackAvailability[i].first.store(true);
                break;
            }
        }
        if (availableAttackIndex == -1) {
            clientsCond.wait(lock, [this] { return !clients.empty(); });
        } else {
            clients.push_back(clientID);
        }
    } while (clientID == -1);

    lock.unlock();

    // Simulate attack selection
    callback(attacks[availableAttackIndex]);

    lock.lock();
    attackAvailability[availableAttackIndex].first.store(false);
    clientsCond.notify_one();
}

