const express = require('express');
const axios = require('axios');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');

const app = express();
const port = 3000;

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
});

app.use(limiter);

// Middleware for JWT authentication
const authenticateJWT = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];
  if (token == null) return res.sendStatus(401);

  jwt.verify(token, 'secret_key', (err, user) => {
    if (err) return res.sendStatus(403);
    req.user = user;
    next();
  });
};

app.use(express.json());

// Example route for a backend service
app.post('/api/data', authenticateJWT, async (req, res) => {
  try {
    const response = await axios.post('https://backend-service.com/api/data', req.body, {
      headers: {
        'Authorization': `Bearer ${req.headers['authorization'].split(' ')[1]}`,
      },
    });
    res.status(response.status).send(response.data);
  } catch (error) {
    res.status(error.response ? error.response.status : 500).send(error.message);
  }
});

// Caching mechanism
const cache = {};

app.get('/api/cache/:key', (req, res) => {
  const { key } = req.params;
  if (cache[key]) {
    return res.send(cache[key]);
  }

  axios.get(`https://data-source.com/api/data/${key}`)
    .then(response => {
      cache[key] = response.data;
      res.send(cache[key]);
    })
    .catch(error => {
      res.status(500).send(error.message);
    });
});

// Fallback mechanism
const fallbackService = async (req, res) => {
  try {
    const response = await axios.get('https://fallback-service.com/api/data');
    res.status(response.status).send(response.data);
  } catch (error) {
    res.status(500).send(error.message);
  }
};

app.use('/api/data', fallbackService);

app.listen(port, () => {
  console.log(`API Gateway running at http://localhost:${port}`);
});
