    mutable std::mutex mutex_;

public:
    void add(const std::string& key, const ImageMetadata& metadata) override {
        std::lock_guard<std::mutex> lock(mutex_);
        cache_[key] = metadata;
        // Implement eviction policy here
    }

    ImageMetadata get(const std::string& key) const override {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = cache_.find(key);
        if (it != cache_.end()) {
            return it->second;
        }
        // Return default value or handle error
        return ImageMetadata{};
    }

    void remove(const std::string& key) override {
        std::lock_guard<std::mutex> lock(mutex_);
        cache_.erase(key);
    }
};

