    int id;
    int stop_flag;
    pthread_cond_t condition;
    pthread_mutex_t mutex;
    ThreadPoolTask current_task;
} ThreadPoolWorker;

// Function to initialize the thread pool
void initThreadPool(ThreadPoolWorker* workers, int num_threads) {
    // Initialize worker threads and their data structures
}

// Function to add a task to the thread pool
void addToThreadPool(ThreadPoolWorker* workers, int num_workers, ThreadPoolTask task) {
    // Lock the mutex and add the task to the queue or available workers
}

// Function to start a worker thread
void* workerThreadFunc(void* arg) {
    ThreadPoolWorker* worker = (ThreadPoolWorker*)arg;
    while (!worker->stop_flag) {
        pthread_mutex_lock(&worker->mutex);
        while (worker->current_task.task == NULL && !worker->stop_flag) {
            pthread_cond_wait(&worker->condition, &worker->mutex);
        }
        if (worker->current_task.task != NULL) {
            worker->current_task.task(worker->current_task.arg);
            memset(&worker->current_task, 0, sizeof(ThreadPoolTask));
        }
        pthread_mutex_unlock(&worker->mutex);
    }
    return NULL;
}

