// DynamicSecureFileDownloader.java
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class DynamicSecureFileDownloader {
    private ExecutorService executorService;
    private int cacheSize;

    public DynamicSecureFileDownloader(int maxThreads, int initialCacheSize) {
        this.executorService = Executors.newFixedThreadPool(maxThreads);
        this.cacheSize = initialCacheSize;
    }

    public void downloadFile(String fileUrl, String destinationPath) {
        executorService.submit(() -> {
            // Simulate downloading a file
            try {
                System.out.println("Downloading file from " + fileUrl);
                TimeUnit.SECONDS.sleep(2); // Simulate network delay
                System.out.println("File downloaded and saved to " + destinationPath);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                System.out.println("Download interrupted");
            }
        });
    }

    public void updateCacheSize(int newCacheSize) {
        this.cacheSize = newCacheSize;
        System.out.println("Cache size updated to " + cacheSize);
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }

    public static void main(String[] args) {
        DynamicSecureFileDownloader downloader = new DynamicSecureFileDownloader(5, 100);
        downloader.downloadFile("https://example.com/sensitivefile.txt", "/path/to/save/file");
        // Simulate cache size adjustment
        downloader.updateCacheSize(200);
        downloader.shutdown();
    }
}
```

