['```cpp
#include <iostream>
#include <thread>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <future>
#include <memory>

// Define a generic worker thread class
class Worker {
public:
    Worker(std::function<void()> task) : m_task(task), m_stop(false) {}

    void start() {
        m_thread = std::thread([this]() {
            while (!m_stop) {
                std::unique_lock<std::mutex> lock(m_queueMutex);
                m_condition.wait(lock, [this] { return !m_tasks.empty() || m_stop; });
                if (m_stop && m_tasks.empty()) {
                    break;
                }
                auto task = std::move(m_tasks.front());
                m_tasks.pop();
                lock.unlock();
                m_task();
            }
        });
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(m_queueMutex);
            m_stop = true;
        }
        m_condition.notify_all();
        if (m_thread.joinable()) {
            m_thread.join();
        }
    }

private:
    std::function<void()> m_task;
    std::thread m_thread;
    std::queue<std::function<void()>> m_tasks;
    std::mutex m_queueMutex;
    std::condition_variable m_condition;
    bool m_stop;
};

// Define a simple task processor class
class TaskProcessor {
public:
    void addTask(std::function<void()> task) {
        {
            std::unique_lock<std::mutex> lock(m_taskQueueMutex);
            m_tasks.push(task);
        }
        m_condition.notify_one();
    }

    void run(int numThreads) {
        for (int i = 0; i < numThreads; ++i) {
            m_workers.emplace_back([this]() { this->workerLoop(); });
        }
        for (auto& worker : m_workers) {
            worker.start();
        }
    }

    ~TaskProcessor() {
        for (auto& worker : m_workers) {
            worker.stop();
        }
    }

private:
    void workerLoop() {
        while (true) {
            std::function<void()> task;
            {
                std::unique_lock<std::mutex> lock(m_taskQueueMutex);
                if (m_stop && m_tasks.empty()) {
                    break;
                }
                m_condition.wait(lock, [this] { return !m_tasks.empty() || m_stop; });
                if (m_stop && m_tasks.empty()) {
                    break;
                }
                task = std::move(m_tasks.front());
                m_tasks.pop();
            }
            task();
        }
    }

private:
    std::vector<Worker> m_workers;
    std::queue<std::function<void()>> m_tasks;
    std::mutex m_taskQueueMutex;
    std::condition_variable m_condition;
    bool m_stop = false;
};

int main() {
    TaskProcessor processor;
    processor.run(4);

    for (int i = 0; i < 100; ++i) {
        processor.addTask([i]() {
            std::cout << "Processing task " << i << std::endl;
        });
    }

    return 0;
}
```

This code snippet demonstrates a simple implementation of a `TaskProcessor` class that uses multiple worker threads to process tasks concurrently. The `Worker` class encapsulates the functionality of a single worker thread, including starting and stopping the thread.

The `TaskProcessor` class manages a pool of workers and provides methods for adding tasks and running the processor with a specified number of threads. When a task is added, it is placed in a queue, and one of the worker threads picks up the next available task from the queue and executes it.

This example provides a basic structure for building a modular, scalable, and fault-tolerant C++ application that processes a continuous stream of data from multiple external APIs. It includes thread safety, efficient synchronization, and dynamic scaling capabilities through the use of worker threads.

