// Define the Gateway class as a central point for routing requests
public class Gateway {
    private Map<String, Service> serviceRegistry;
    private RateLimiter rateLimiter;
    private RequestShaper requestShaper;
    private AuthenticationManager authenticationManager;

    public Gateway() {
        this.serviceRegistry = new HashMap<>();
        this.rateLimiter = new RateLimiter();
        this.requestShaper = new RequestShaper();
        this.authenticationManager = new AuthenticationManager();
    }

    public Response routeRequest(Request request) {
        if (!rateLimiter.allow(request)) {
            return new ErrorResponse("Rate limit exceeded", 429);
        }

        request = requestShaper.shape(request);

        if (!authenticationManager.authenticate(request)) {
            return new ErrorResponse("Authentication failed", 401);
        }

        Service service = serviceRegistry.get(request.getTargetService());
        if (service == null) {
            return new ErrorResponse("Service not found", 404);
        }

        try {
            return service.handleRequest(request);
        } catch (Exception e) {
            return new ErrorResponse(e.getMessage(), 500);
        }
    }
}

