void manage_workers(int current_load, int cpu_availability, int memory_constraints) {
    int num_workers = 0;

    if (current_load < 50 && cpu_availability > 70 && memory_constraints > 30) {
        num_workers = 2;
    } else if (current_load >= 50 && current_load < 80 && cpu_availability > 40 && memory_constraints > 20) {
        num_workers = 1;
    } else {
        num_workers = 0;
