    for (int i = 0; i < num_workers; i++) {
        workers[i].id = i + 1;
        pthread_create(&workers[i].thread_id, NULL, worker_thread, &workers[i]);
    }

    // Wait for all worker threads to complete
    for (int i = 0; i < num_workers; i++) {
        pthread_join(workers[i].thread_id, NULL);
