typedef struct NFAPI_CRC_INDICATION_PDU {
    RX_UE_INFORMATION_TAG rx_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_flag;
    struct NFAPI_CRC_INDICATION_PDU* next;
    struct NFAPI_CRC_INDICATION_PDU* prev;
} NFAPI_CRC_INDICATION_PDU;

typedef struct DLL {
    NFAPI_CRC_INDICATION_PDU* head;
    NFAPI_CRC_INDICATION_PDU* tail;
    pthread_mutex_t mutex;
} DLL;

void dll_init(DLL* list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

void dll_insert(DLL* list, RX_UE_INFORMATION_TAG rx_tag, RNTI rnti, int snr, double noise_threshold, int* crc_flag) {
    NFAPI_CRC_INDICATION_PDU* new_node = (NFAPI_CRC_INDICATION_PDU*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
    if (new_node == NULL) {
        // Handle memory allocation failure
        return;
    }
    new_node->rx_tag = rx_tag;
    new_node->rnti = rnti;
    *crc_flag = (snr > noise_threshold) ? 1 : 0;

    pthread_mutex_lock(&list->mutex);
    if (list->head == NULL) {
        list->head = list->tail = new_node;
    } else {
        new_node->prev = list->tail;
        list->tail->next = new_node;
        list->tail = new_node;
    }
    pthread_mutex_unlock(&list->mutex);
}

void dll_remove(DLL* list, RX_UE_INFORMATION_TAG rx_tag) {
    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU* current = list->head;
    while (current != NULL) {
        if (current->rx_tag == rx_tag) {
            if (current->prev != NULL)
                current->prev->next = current->next;
            if (current->next != NULL)
                current->next->prev = current->prev;
            if (list->head == current)
                list->head = current->next;
            if (list->tail == current)
                list->tail = current->prev;
            free(current);
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

