// kv_store.h

#pragma once

#include <string>
#include <mutex>
#include <unordered_map>
#include <condition_variable>

template<typename T>
class KVStore {
public:
    using Key = std::string;
    using Value = T;

    void set(const Key& key, const Value& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        store_[key] = value;
        condition_.notify_one();
    }

    bool get(const Key& key, Value& value) {
        std::unique_lock<std::mutex> lock(mutex_);
        while (store_.find(key) == store_.end()) {
            if (!condition_.wait_for(lock, std::chrono::microseconds(100), [this, &key]() { return store_.find(key) != store_.end(); })) {
                return false; // Timeout or condition met
            }
        }
        value = store_[key];
        return true;
    }

    void remove(const Key& key) {
        std::lock_guard<std::mutex> lock(mutex_);
        store_.erase(key);
        condition_.notify_one();
    }

private:
    std::unordered_map<Key, Value> store_;
    mutable std::mutex mutex_;
    std::condition_variable condition_;
};
