```c
// fsa_library.c
#include "fsa_library.h"
#include <string.h>
#include <unistd.h>

FSA* fsa_init() {
    FSA *fsa = malloc(sizeof(FSA));
    if (fsa == NULL) {
        perror("Failed to allocate memory for FSA");
        exit(EXIT_FAILURE);
    }

    fsa->current_state = NULL;
    pthread_mutex_init(&fsa->mutex, NULL);
    fsa->log_file = fopen("fsa_log.txt", "w");
    if (fsa->log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    return fsa;
}

void fsa_free(FSA *fsa) {
    pthread_mutex_lock(&fsa->mutex);
    State *current = fsa->current_state;
    while (current != NULL) {
        State *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&fsa->mutex);

    pthread_mutex_destroy(&fsa->mutex);
    fclose(fsa->log_file);
    free(fsa);
}

void fsa_change_state(FSA *fsa, int new_state_id) {
    pthread_mutex_lock(&fsa->mutex);
    if (fsa->current_state == NULL) {
        fsa->current_state = malloc(sizeof(State));
        if (fsa->current_state == NULL) {
            perror("Failed to allocate memory for new state");
            exit(EXIT_FAILURE);
        }
        fsa->current_state->id = new_state_id;
        strcpy(fsa->current_state->name, "Initial State");
        fsa->current_state->next = NULL;
    } else {
        // Implement logic to transition between states
        // Example:
        // if (new_state_id == 1) {
        //     printf("Transitioning to State 1\n");
        // }
        // ...
    }
    pthread_mutex_unlock(&fsa->mutex);
}

void fsa_log_transition(FSA *fsa, int old_state_id, int new_state_id) {
    pthread_mutex_lock(&fsa->mutex);
    fprintf(fsa->log_file, "Transitioned from state %d to state %d\n", old_state_id, new_state_id);
    fflush(fsa->log_file);
    pthread_mutex_unlock(&fsa->mutex);
}

int fsa_get_current_state_id(FSA *fsa) {
    pthread_mutex_lock(&fsa->mutex);
    int current_state_id = (fsa->current_state != NULL) ? fsa->current_state->id : -1;
    pthread_mutex_unlock(&fsa->mutex);
    return current_state_id;
}
