// C Library for Finite State Automaton (FSA) State Management

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sqlite3.h>

typedef struct state {
    int id;
    char name[256];
    struct state *next;
} State;

State* create_state(int id, const char* name) {
    State* new_state = (State*)malloc(sizeof(State));
    if (!new_state) return NULL;
    new_state->id = id;
    strncpy(new_state->name, name, 256);
    new_state->next = NULL;
    return new_state;
}

void free_state(State* state) {
    while (state) {
        State* next = state->next;
        free(state);
        state = next;
    }
}

int save_state_to_db(State* state, sqlite3* db) {
    char sql[512];
    snprintf(sql, sizeof(sql), "INSERT INTO states (id, name) VALUES (%d, '%s')", state->id, state->name);
    sqlite3_stmt *stmt;
    int rc = sqlite3_prepare_v2(db, sql, -1, &stmt, 0);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "SQL error: %s\n", sqlite3_errmsg(db));
        return rc;
    }
    rc = sqlite3_step(stmt);
    sqlite3_finalize(stmt);
    return rc == SQLITE_DONE ? 0 : -1;
}

void* state_manager_thread(void* arg) {
    State* states = (State*)arg;
    sqlite3 *db;
    if (sqlite3_open("states.db", &db) != SQLITE_OK) {
        fprintf(stderr, "Cannot open database: %s\n", sqlite3_errmsg(db));
        return NULL;
    }
    while (1) {
        State* state = states;
        while (state) {
            save_state_to_db(state, db);
            state = state->next;
        }
        sleep(1); // Simulate periodic operation
    }
    sqlite3_close(db);
    return NULL;
}

int main() {
    State* head = create_state(1, "Initial");
    head->next = create_state(2, "State2");
    pthread_t tid;
    if (pthread_create(&tid, NULL, state_manager_thread, head) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return -1;
    }
    pthread_join(tid, NULL);
    free_state(head);
    return 0;
}
