import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class FSAStateManager {
    static {
        System.loadLibrary("fsa_manager"); // Load the C library
    }

    public native void saveState(int id, String name);

    private ExecutorService executorService = Executors.newFixedThreadPool(10);

    public void startService() {
        while (true) {
            try {
                executorService.submit(() -> {
                    int stateId = ThreadLocalRandom.current().nextInt(1, 100);
                    saveState(stateId, "Dynamic State");
                });
                TimeUnit.SECONDS.sleep(ThreadLocalRandom.current().nextInt(1, 5));
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }
    }

    public void stopService() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
        // Send message to messaging system
    }

    public static void main(String[] args) {
        FSAStateManager manager = new FSAStateManager();
        manager.startService();
        try {
            Thread.sleep(60000); // Run for 1 minute
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
        manager.stopService();
    }
}
