    public void processFeedback(FeedbackEvent event) {
        if (cache.getIfPresent(event.getId()) != null) {
            return; // Skip processing if already cached
        }
        cache.put(event.getId(), event);

        try {
            circuitBreaker.execute(() -> {
                externalApiClient.sendFeedbackToSystem(event);
                return null;
            });
        } catch (Exception e) {
            retryWithExponentialBackoff(5, 1000, () -> {
                externalApiClient.sendFeedbackToSystem(event);
                return null;
            });
        }

        feedbackQueue.put(event);
    }

    private void retryWithExponentialBackoff(int maxRetries, long initialDelay, Runnable task) {
        for (int attempt = 0; attempt < maxRetries; attempt++) {
            try {
                Thread.sleep(initialDelay * (1 << attempt));
                task.run();
                return;
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

