    std::condition_variable cv_;

public:
    TreeManager() : nodes(M) {}

    void expand() {
        std::unique_lock<std::mutex> lock(mutex_);
        if (nodes.size() < MAX_M) {
            size_t newSize = std::min(nodes.size() * 2, MAX_M);
            nodes.resize(newSize);
