    int worker_id = *(int*)arg;
    while (1) {
        // Simulate data processing
        printf("Worker %d: Processing data...\n", worker_id);
        sleep(1);
    }
    return NULL;
}

void start_workers() {
    for (int i = 0; i < NUM_WORKERS; ++i) {
        workers[i].id = i;
        pthread_create(&workers[i].thread_id, NULL, worker_thread, &workers[i].id);
    }
}

void stop_workers() {
    for (int i = 0; i < NUM_WORKERS; ++i) {
        pthread_join(workers[i].thread_id, NULL);
    }
}

int main() {
    start_workers();

    // Simulate system load and adjust workers dynamically
    sleep(10);

    stop_workers();
    return 0;
}
