using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;
using Polly;
using Polly.Retry;

public class RealtimeDataDrivenRandomValueGenerator
{
    private readonly HttpClient _httpClient;
    private readonly RetryPolicy _retryPolicy;
    private Dictionary<string, (float min, float max)> _ranges;
    private Random _random;

    public RealtimeDataDrivenRandomValueGenerator()
    {
        _httpClient = new HttpClient();
        _retryPolicy = Policy
            .Handle<HttpRequestException>()
            .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)))
            .WithCircuitBreakerAsync(
                onBreak: (ex, breakDuration) => Task.Delay(breakDuration),
                onReset: () => { /* Reset logic */ }
            );
        _ranges = new Dictionary<string, (float min, float max)>();
        _random = new Random();
    }

    public void AddRange(string sourceName, float min, float max)
    {
        _ranges[sourceName] = (min, max);
    }

    public float GenerateRandomFloat(string sourceName, bool includeMax = true)
    {
        if (!_ranges.ContainsKey(sourceName))
            throw new ArgumentException("Source not found", nameof(sourceName));

        var range = _ranges[sourceName];
        return _random.NextDouble() * (range.max - range.min) + range.min +
               (includeMax ? 0 : _random.NextDouble());
    }

    public int GenerateRandomInt(string sourceName, bool includeMax = true)
    {
        if (!_ranges.ContainsKey(sourceName))
            throw new ArgumentException("Source not found", nameof(sourceName));

        var range = _ranges[sourceName];
        return (int)_random.Next((int)(range.min * 100), (int)(range.max * 100) + (includeMax ? 1 : 0));
    }

    private async Task UpdateRangesAsync()
    {
        foreach (var source in _ranges.Keys)
        {
            try
            {
                var response = await _retryPolicy.ExecuteAsync(() => _httpClient.GetAsync($"https://api.example.com/range/{source}"));
                response.EnsureSuccessStatusCode();
                var data = await response.Content.ReadAsAsync<Dictionary<string, (float min, float max)>>();
                _ranges[source] = data[source];
            }
            catch
            {
                // Handle failure, possibly log or fallback to cached values
            }
        }
    }

    public void StartRangeUpdater()
    {
        Task.Run(async () =>
        {
            while (true)
            {
                await UpdateRangesAsync();
                await Task.Delay(TimeSpan.FromSeconds(60)); // Adjust update frequency as needed
            }
        });
    }
}
