        _cache = cache ?? throw new ArgumentNullException(nameof(cache));
    }

    public async Task<T> GetRandomValueAsync<T>(string tenantId, string generatorType)
    {
        var generatorKey = $"{tenantId}:{generatorType}";
        if (!_generators.TryGetValue(generatorKey, out var generator))
        {
            await LoadGeneratorAsync(tenantId, generatorType);
            _generators.TryAdd(generatorKey, generator);
        }

        return (T)await generator.GetRandomValueAsync(typeof(T));
    }

    private async Task LoadGeneratorAsync(string tenantId, string generatorType)
    {
        var config = await FetchTenantConfigAsync(tenantId);
        switch (generatorType.ToLower())
        {
            case "int":
                _generators.TryAdd($"{tenantId}:{generatorType}", new IntRandomValueGenerator(config.MinValue, config.MaxValue));
                break;
            case "double":
                _generators.TryAdd($"{tenantId}:{generatorType}", new DoubleRandomValueGenerator(config.MinValue, config.MaxValue));
                break;
            // Add more cases for other data types
            default:
                throw new ArgumentException("Invalid generator type");
        }
    }

    private async Task<TenantConfig> FetchTenantConfigAsync(string tenantId)
    {
        var cacheKey = $"config:{tenantId}";
        if (await _cache.GetStringAsync(cacheKey) is null)
        {
            using var response = await _httpClient.GetAsync($"https://api.example.com/config/{tenantId}");
            response.EnsureSuccessStatusCode();
            var config = await response.Content.ReadAsStringAsync();
            await _cache.SetStringAsync(cacheKey, config, new DistributedCacheEntryOptions { AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(5) });
            return JsonConvert.DeserializeObject<TenantConfig>(config);
        }

        var cachedConfig = await _cache.GetStringAsync(cacheKey);
        return JsonConvert.DeserializeObject<TenantConfig>(cachedConfig);
    }

    public void Dispose()
    {
        foreach (var generator in _generators.Values)
        {
            generator.Dispose();
        }
    }
}

public class TenantConfig
{
    public int MinValue { get; set; }
    public int MaxValue { get; set; }
    // Add more properties as needed for other data types
}

public interface IRandomValueGenerator : IDisposable
{
    Task<object> GetRandomValueAsync(Type valueType);
}

public class IntRandomValueGenerator : IRandomValueGenerator
{
    private readonly Random _random;

    public IntRandomValueGenerator(int minValue, int maxValue)
    {
        _random = new Random(minValue, maxValue);
    }

    public async Task<object> GetRandomValueAsync(Type valueType)
    {
        return _random.Next();
    }

    public void Dispose()
    {
        _random.Dispose();
    }
}

public class DoubleRandomValueGenerator : IRandomValueGenerator
{
    private readonly Random _random;

    public DoubleRandomValueGenerator(double minValue, double maxValue)
    {
        _random = new Random((int)(minValue * 1000), (int)(maxValue * 1000));
    }

    public async Task<object> GetRandomValueAsync(Type valueType)
    {
        return _random.NextDouble() * (double)(_random.Next(1, 2) == 1 ? 1 : -1);
    }

    public void Dispose()
    {
        _random.Dispose();
    }
}
