#include <iostream>
#include <mutex>
#include <condition_variable>
#include <unordered_map>
#include <vector>
#include <thread>
#include <atomic>
#include <chrono>

class Attack {
public:
    virtual ~Attack() = default;
    virtual void execute() const = 0;
};

class GameAttackManager {
private:
    std::unordered_map<int, Attack*> attackMap;
    std::mutex mapMutex;
    std::condition_variable cv;
    std::atomic<bool> running{true};
    int maxClients;

public:
    GameAttackManager(int maxClients) : maxClients(maxClients) {}

    ~GameAttackManager() {
        stop();
        for (auto& pair : attackMap) {
            delete pair.second;
        }
    }

    void addAttack(int id, Attack* attack) {
        std::lock_guard<std::mutex> lock(mapMutex);
        attackMap[id] = attack;
    }

    void removeAttack(int id) {
        std::lock_guard<std::mutex> lock(mapMutex);
        auto it = attackMap.find(id);
        if (it != attackMap.end()) {
            delete it->second;
            attackMap.erase(it);
        }
    }

    Attack* getAttack(int id) const {
        std::lock_guard<std::mutex> lock(mapMutex);
        auto it = attackMap.find(id);
        return (it != attackMap.end()) ? it->second : nullptr;
    }

    void start() {
        for (int i = 0; i < maxClients; ++i) {
            std::thread([this]() {
                while (running.load()) {
                    int id;
                    {
                        std::unique_lock<std::mutex> lock(mapMutex);
                        cv.wait(lock, [this] { return !attackMap.empty(); });
                        id = (*attackMap.begin()).first;
                        attackMap.erase(attackMap.begin());
                    }
                    Attack* attack = getAttack(id);
                    if (attack) {
                        attack->execute();
                    }
                }
            }).detach();
        }
    }

    void stop() {
        running.store(false);
        cv.notify_all();
    }
};

class SimpleAttack : public Attack {
public:
    void execute() const override {
        // Simulate an attack execution
        std::cout << "Executing simple attack" << std::endl;
    }
};

int main() {
    GameAttackManager manager(10000);
    manager.addAttack(1, new SimpleAttack());
    manager.start();

    // Simulate client selecting attacks
    for (int i = 0; i < 10000; ++i) {
        std::thread([&, i]() {
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
            int id = 1;
            manager.getAttack(id);
        }).detach();
    }

    manager.stop();
    return 0;
}
