# MemoryEfficientDataStore.py
from collections import OrderedDict
import threading
import time

class MemoryEfficientDataStore:
    def __init__(self, max_entries):
        self.data_store = OrderedDict()
        self.max_entries = max_entries
        self.lock = threading.Lock()

    def insert(self, key, value):
        with self.lock:
            if len(self.data_store) >= self.max_entries:
                self.data_store.popitem(last=False)
            self.data_store[key] = value

    def traverse(self):
        with self.lock:
            for entry in self.data_store.values():
                yield entry

    def remove_inactive_entries(self, timeout):
        current_time = time.time()
        with self.lock:
            for key, value in list(self.data_store.items()):
                if (current_time - value['timestamp']) > timeout:
                    del self.data_store[key]

