    def log(self, level, message):
        # Code to send logs to ELK Stack
        print(f"ELK - {level}: {message}")

class SplunkLogger(Logger):
    def log(self, level, message):
        # Code to send logs to Splunk
        print(f"Splunk - {level}: {message}")

class CloudWatchLogger(Logger):
    def log(self, level, message):
        # Code to send logs to CloudWatch
        print(f"CloudWatch - {level}: {message}")

class CustomLogger(Logger):
    def log(self, level, message):
        # Custom logging logic
        print(f"Custom - {level}: {message}")

class LoggingFramework:
    def __init__(self):
        self.loggers = []

    def add_logger(self, logger: Logger):
        self.loggers.append(logger)

    async def log_message(self, level, message):
        for logger in self.loggers:
            await logger.log(level, message)

# Configuration and usage
