if config_loggers['ELK']:
    framework.add_logger(ELKLogger())
if config_loggers['Splunk']:
    framework.add_logger(SplunkLogger())
if config_loggers['CloudWatch']:
    framework.add_logger(CloudWatchLogger())
if config_loggers['Custom']:
    framework.add_logger(CustomLogger())

# Asynchronous logging
