#include <iostream>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <vector>
#include <string>
#include <memory>

struct MESSAGE_T {
    std::string content;
    int priority;
};

class DistributedQueue {
public:
    void enqueue(const MESSAGE_T& msg) {
        std::unique_lock<std::mutex> lock(mutex_);
        queue_.push(msg);
        condition_.notify_one();
    }

    bool try_dequeue(MESSAGE_T& msg) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (queue_.empty()) return false;
        msg = queue_.front();
        queue_.pop();
        return true;
    }

private:
    std::queue<MESSAGE_T> queue_;
    mutable std::mutex mutex_;
    std::condition_variable condition_;
};

int main() {
    DistributedQueue dq;
    MESSAGE_T msg1{"Hello", 1};
    MESSAGE_T msg2{"World", 2};

    std::thread producer([&dq, &msg1, &msg2]() {
        dq.enqueue(msg1);
        std::this_thread::sleep_for(std::chrono::milliseconds(500));
        dq.enqueue(msg2);
    });

    MESSAGE_T received_msg;
    if (dq.try_dequeue(received_msg)) {
        std::cout << "Received: " << received_msg.content << " with priority " << received_msg.priority << std::endl;
    }

    producer.join();
    return 0;
}
