// AuthenticationController.java
@RestController
@RequestMapping("/auth")
public class AuthenticationController {

    @Autowired
    private AuthService authService;

    @PostMapping("/login")
    public ResponseEntity<String> login(@RequestBody LoginRequest request) {
        return ResponseEntity.ok(authService.authenticate(request));
    }

    @PostMapping("/mfa")
    public ResponseEntity<String> mfa(@RequestBody MFARequest request) {
        return ResponseEntity.ok(authService.authenticateWithMFA(request));
    }
}

// AuthService.java
@Service
public class AuthService {

    @Autowired
    private UserRepository userRepository;

    @Autowired
    private TokenStore tokenStore;

    public String authenticate(LoginRequest request) {
        User user = userRepository.findByUsername(request.getUsername());
        if (user != null && user.getPassword().equals(request.getPassword())) {
            return generateToken(user);
        }
        throw new AuthenticationException("Invalid username or password");
    }

    public String authenticateWithMFA(MFARequest request) {
        // Logic for MFA authentication
        return "MFA authenticated";
    }

    private String generateToken(User user) {
        Token token = new Token(user, Instant.now().plus(30, ChronoUnit.MINUTES));
        tokenStore.save(token);
        return token.getToken();
    }
}

// TokenStore.java
@Repository
public class TokenStore {

    @Autowired
    private RedisTemplate<String, String> redisTemplate;

    public void save(Token token) {
        redisTemplate.opsForValue().set(token.getToken(), token.getUser().getId());
    }

    public String getUserByToken(String token) {
        return redisTemplate.opsForValue().get(token);
    }
}

// Token.java
public class Token {

    private User user;
    private Instant expiration;

    public Token(User user, Instant expiration) {
        this.user = user;
        this.expiration = expiration;
    }

    // Getters and setters

    public String getToken() {
        return UUID.randomUUID().toString();
    }
}

// UserRepository.java
public interface UserRepository extends JpaRepository<User, String> {
    User findByUsername(String username);
}

// User.java
@Entity
public class User {

    @Id
    private String id;

    private String username;
    private String password;

    // Getters and setters

    public boolean isExpired() {
        return Instant.now().isAfter(expiration);
    }
}
