fetcher = ExternalAPIMetricFetcher(api_url_fetch)
store = MetricsStore()
aggregator = MetricsAggregator()
sender = ExternalAPIMetricSender(api_url_send)
monitor = MetricsMonitor(fetcher, store, aggregator, sender)
monitor.monitor()
