namespace RealTimeDataGenerator
{
    public class TenantConfigurations
    {
        public string RestApiUrl { get; set; }
        public int CacheTtlSeconds { get; set; }
    }

    public class RandomValueGeneratorFactory : IDisposable
    {
        private readonly ConcurrentDictionary<string, RandomValueGenerator> _generators = new();
        private readonly IDatabase _cache;
        private readonly HttpClient _httpClient;
        private Timer _refreshTimer;

        public RandomValueGeneratorFactory(string redisConnectionString)
        {
            var options = ConfigurationOptions.Parse(redisConnectionString);
            ConnectionMultiplexer redis = ConnectionMultiplexer.Connect(options);
            _cache = redis.GetDatabase();
            _httpClient = new HttpClient();

            // Initialize refresh timer
            _refreshTimer = new Timer(RefreshTenantConfigurations, null, TimeSpan.Zero, TimeSpan.FromMinutes(1));
        }

        public RandomValueGenerator GetGenerator(string tenantId)
        {
            if (!_generators.TryGetValue(tenantId, out var generator))
            {
                lock (_generators)
                {
                    if (!_generators.TryGetValue(tenantId, out generator))
                    {
                        generator = new RandomValueGenerator(tenantId, _cache, _httpClient);
                        _generators.TryAdd(tenantId, generator);
                    }
                }
            }
            return generator;
        }

        private async void RefreshTenantConfigurations(object state)
        {
            var tasks = _generators.Keys.Select(async tenantId =>
            {
                var config = await FetchTenantConfiguration(tenantId);
                if (config != null)
                {
                    // Update the generator with new configuration
                    if (_generators.TryGetValue(tenantId, out var generator))
                    {
                        generator.UpdateConfig(config);
                    }
                }
            });

            await Task.WhenAll(tasks);
        }

        private async Task<TenantConfigurations> FetchTenantConfiguration(string tenantId)
        {
            try
            {
                var response = await _httpClient.GetAsync($"https://api.example.com/config/{tenantId}");
                if (response.IsSuccessStatusCode)
                {
                    return await response.Content.ReadAsAsync<TenantConfigurations>();
                }
            }
            catch
            {
                // Handle exceptions and fallback logic here
            }

            return null;
        }

        public void Dispose()
        {
            _refreshTimer?.Change(Timeout.Infinite, 0);
            _httpClient.Dispose();
        }
    }

    public class RandomValueGenerator
    {
        private readonly string _tenantId;
        private readonly IDatabase _cache;
        private readonly HttpClient _httpClient;

        private TenantConfigurations _config;

        public RandomValueGenerator(string tenantId, IDatabase cache, HttpClient httpClient)
        {
            _tenantId = tenantId;
            _cache = cache;
            _httpClient = httpClient;

            // Initialize with default config
            _config = new TenantConfigurations { RestApiUrl = "https://api.example.com/data", CacheTtlSeconds = 3600 };
        }

        public void UpdateConfig(TenantConfigurations config)
        {
            _config = config;
        }

        public object GenerateRandomValue(Type dataType)
        {
            switch (dataType.Name)
            {
                case nameof(Int32):
                    return Random.Next(int.MinValue, int.MaxValue);
                case nameof(Double):
                    return Random.NextDouble();
                // Add more cases for other data types as needed
                default:
                    throw new ArgumentException("Unsupported data type");
            }
        }
    }
}
