// Forward declaration of external repository interfaces
class IAssetRepository {
public:
    virtual ~IAssetRepository() = default;
    virtual std::shared_ptr<void> FetchAsset(const std::string& assetId) = 0;
};

class LegacyAssetRepository : public IAssetRepository {
public:
    std::shared_ptr<void> FetchAsset(const std::string& assetId) override {
        // Implementation to fetch from legacy repository
        return nullptr;
    }
};

class ModernAssetRepository : public IAssetRepository {
public:
    std::shared_ptr<void> FetchAsset(const std::string& assetId) override {
        // Implementation to fetch from modern repository
        return nullptr;
    }
};

// AssetLoader class definition
class AssetLoader {
private:
    std::unordered_map<std::string, std::shared_ptr<void>> cache;
    std::unordered_map<std::string, std::unique_ptr<IAssetRepository>> repositories;
    std::mutex cacheMutex;
    std::condition_variable cv;

public:
    void RegisterRepository(const std::string& repoId, std::unique_ptr<IAssetRepository> repo) {
        repositories[repoId] = std::move(repo);
    }

    std::shared_ptr<void> LoadAsset(const std::string& assetId) {
        std::unique_lock<std::mutex> lock(cacheMutex);
        auto it = cache.find(assetId);
        if (it != cache.end()) {
            return it->second;
        }
        cv.notify_all();
        // Simulate network delay
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
        for (const auto& repo : repositories) {
            try {
                auto asset = repo.second->FetchAsset(assetId);
                if (asset) {
                    cache[assetId] = asset;
                    return asset;
                }
            } catch (...) {
                // Handle exceptions gracefully
            }
        }
        return nullptr; // Fallback policy
    }

    void StartLoaderThread() {
        std::thread([this]() {
            while (true) {
                cv.wait([] {});
                for (auto& [assetId, _] : cache) {
                    std::unique_lock<std::mutex> lock(cacheMutex);
                    if (!cache[assetId]) {
                        LoadAsset(assetId); // Retry loading
                    }
                }
            }
        }).detach();
    }
};

// Example usage
int main() {
    AssetLoader loader;
    loader.RegisterRepository("legacy", std::make_unique<LegacyAssetRepository>());
    loader.RegisterRepository("modern", std::make_unique<ModernAssetRepository>());
    loader.StartLoaderThread();

    // Simulate client requests
    for (int i = 0; i < 1000; ++i) {
        auto asset = loader.LoadAsset("asset" + std::to_string(i));
        if (asset) {
            // Process asset
        }
    }

    return 0;
}
```

