// Define the structure for an NFAPI_CRC_INDICATION_PDU_T
typedef struct NFapiCrcIndicationPdu {
    // Assume these are the required fields
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFapiCrcIndicationPdu;

// Define the structure for a node in the doubly-linked list
typedef struct Node {
    NFapiCrcIndicationPdu data;
    struct Node* prev;
    struct Node* next;
} Node;

// Define the structure for the doubly-linked list
typedef struct LinkedList {
    Node* head;
    Node* tail;
    pthread_mutex_t lock; // Mutex for thread safety
} LinkedList;

// Function to create a new node
Node* create_node(NFapiCrcIndicationPdu data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    new_node->prev = NULL;
    new_node->next = NULL;
    return new_node;
}

// Function to add a new node to the list
void add_node(LinkedList* list, NFapiCrcIndicationPdu data) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = create_node(data);
    if (list->head == NULL) {
        list->head = list->tail = new_node;
    } else {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to iterate over the list and process each node
void iterate_list(LinkedList* list, void (*process)(NFapiCrcIndicationPdu)) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        process(current->data);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to remove nodes based on specific criteria
void remove_node_by_rnti(LinkedList* list, int RNTI) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            if (current->prev != NULL) {
                current->prev->next = current->next;
            } else {
                list->head = current->next;
            }
            if (current->next != NULL) {
                current->next->prev = current->prev;
            } else {
                list->tail = current->prev;
            }
            free(current);
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to serialize the linked list to a file
void serialize_list(LinkedList* list, const char* filename) {
    pthread_mutex_lock(&list->lock);
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Failed to open file for writing");
        exit(EXIT_FAILURE);
    }
    Node* current = list->head;
    while (current != NULL) {
        fwrite(&current->data, sizeof(NFapiCrcIndicationPdu), 1, file);
        current = current->next;
    }
    fclose(file);
    pthread_mutex_unlock(&list->lock);
}

// Function to deserialize the linked list from a file
void deserialize_list(LinkedList* list, const char* filename) {
    pthread_mutex_lock(&list->lock);
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Failed to open file for reading");
        exit(EXIT_FAILURE);
    }
    NFapiCrcIndicationPdu data;
    while (fread(&data, sizeof(NFapiCrcIndicationPdu), 1, file)) {
        add_node(list, data);
    }
    fclose(file);
    pthread_mutex_unlock(&list->lock);
}

// Example usage of the module
void process_node(NFapiCrcIndicationPdu data) {
    // Implement the processing logic here
    printf("Processing node with RNTI: %d, CRCFLAG: %d\n", data.RNTI, data.CRCFLAG);
}

int main() {
    LinkedList list;
    pthread_mutex_init(&list.lock, NULL);

    // Add nodes to the list
    NFapiCrcIndicationPdu pdu1 = {1, 2001, 8, 1};
    NFapiCrcIndicationPdu pdu2 = {2, 2002, 9, 0};
    add_node(&list, pdu1);
    add_node(&list, pdu2);

    // Process each node
    iterate_list(&list, process_node);

    // Remove a node based on RNTI
    remove_node_by_rnti(&list, 2001);

    // Serialize the list to a file
    serialize_list(&list, "crc_indication_pdu.dat");

    // Deserialize the list from a file
    deserialize_list(&list, "crc_indication_pdu.dat");

    // Clean up resources
    pthread_mutex_destroy(&list.lock);
    return 0;
}
```

