import threading
from collections import deque
import time

class ConnectionState:
    def __init__(self, ip, port):
        self.ip = ip
        self.port = port
        self.last_active = time.time()
        self.status = "Active"

class CircularQueue:
    def __init__(self, capacity):
        self.queue = deque(maxlen=capacity)
        self.lock = threading.Lock()

    def enqueue(self, connection_state):
        with self.lock:
            self.queue.append(connection_state)

    def dequeue_inactive(self, timeout=60):
        with self.lock:
            for _ in range(len(self.queue)):
                if time.time() - self.queue[0].last_active > timeout:
                    return self.queue.popleft()
            return None

    def iterate_states(self):
        with self.lock:
            for state in self.queue:
                yield state

class NetworkManager:
    def __init__(self, queue_capacity, analytics_url):
        self.connection_queue = CircularQueue(queue_capacity)
        self.analytics_url = analytics_url
        self.analytics_lock = threading.Lock()

    def process_connection(self, ip, port):
        connection_state = ConnectionState(ip, port)
        self.connection_queue.enqueue(connection_state)

    def update_connection_status(self, ip, port, status):
        for state in self.connection_queue.iterate_states():
            if state.ip == ip and state.port == port:
                with self.analytics_lock:
                    state.status = status
                    # Simulate sending data to analytics platform
                    print(f"Updating {ip}:{port} status to {status}")
                    time.sleep(0.1)  # Simulate delay

    def analyze_connections(self):
        while True:
            inactive_connection = self.connection_queue.dequeue_inactive()
            if inactive_connection:
                with self.analytics_lock:
                    print(f"Dequeued inactive connection: {inactive_connection.ip}:{inactive_connection.port}")
                    # Simulate sending data to analytics platform
                    time.sleep(0.1)  # Simulate delay

# Example usage
if __name__ == "__main__":
    manager = NetworkManager(queue_capacity=100, analytics_url="http://example.com/analytics")

    # Simulate connection processing
    threading.Thread(target=manager.analyze_connections).start()
    for i in range(150):
        manager.process_connection(f"192.168.1.{i}", 8080)
        time.sleep(0.01)

    # Simulate updating connection status
    for _ in range(10):
        manager.update_connection_status("192.168.1.5", 8080, "Inactive")
        time.sleep(0.2)
