class WeatherForecastAggregator:
    def __init__(self, api_urls):
        self.api_urls = api_urls
        self.cache = {}

    @retry(stop=stop_after_attempt(10), wait=wait_exponential(multiplier=1, max=60) + wait_random(min=0, max=5))
    def get_weather_data(self, region, param):
        if region not in self.cache or self.is_cache_stale(region):
            response = requests.get(f"{self.api_urls[region]}/weather?param={param}")
            response.raise_for_status()
            weather_data = response.json()
            self.cache[region] = {param: weather_data}
            return weather_data
        else:
            return self.cache[region][param]

    def is_cache_stale(self, region):
        # Implement cache staleness logic
        pass

