package main

import (
    "encoding/json"
    "log"
)

type WeatherData struct {
    Temperature float64 `json:"temperature"`
    Humidity    int     `json:"humidity"`
    WindSpeed   float64 `json:"wind_speed"`
    PrecipProb  float64 `json:"precip_probability"`
}

func loadAndDeserializeJSON(jsonData []byte) (*WeatherData, error) {
    var weather WeatherData
    err := json.Unmarshal(jsonData, &weather)
    if err != nil {
        log.Fatalf("Error deserializing JSON: %v", err)
    }
    return &weather, nil
}

// usage
