// nodejs_update_db.js

const mysql = require('mysql');

async function updateDatabase(temperature, humidity, windSpeed, precipitationProbability, region) {
    const connection = mysql.createConnection({
        host: 'localhost',
        user: 'user',
        password: 'password',
        database: 'weather'
    });

    await new Promise((resolve, reject) => {
        connection.connect((err) => {
            if (err) return reject(err);
            resolve();
        });
    });

    const query = `
        INSERT INTO weather_data (region, temperature, humidity, wind_speed, precipitation_probability)
        VALUES (?, ?, ?, ?, ?)
        ON DUPLICATE KEY UPDATE
        temperature=VALUES(temperature),
        humidity=VALUES(humidity),
        wind_speed=VALUES(wind_speed),
        precipitation_probability=VALUES(precipitation_probability)
    `;

    await new Promise((resolve, reject) => {
        connection.query(query, [region, temperature, humidity, windSpeed, precipitationProbability], (err, results) => {
            if (err) return reject(err);
            resolve(results.affectedRows > 0 ? 'Success' : 'No change');
        });
    });

    await new Promise((resolve, reject) => {
        connection.end((err) => {
            if (err) return reject(err);
            resolve();
        });
    });
}

// usage
updateDatabase(20, 85, 15, 30, 'New York').then(console.log).catch(console.error);
