    virtual std::string decrypt(const std::string& data) = 0;
    virtual ~Cipher() {}
};

class DES : public Cipher {
public:
    std::string encrypt(const std::string& data) override {
        // DES encryption logic
        return "DES Encrypted Data";
    }

    std::string decrypt(const std::string& data) override {
        // DES decryption logic
        return "DES Decrypted Data";
    }
};

class AES : public Cipher {
public:
    std::string encrypt(const std::string& data) override {
        // AES encryption logic
        return "AES Encrypted Data";
    }

    std::string decrypt(const std::string& data) override {
        // AES decryption logic
        return "AES Decrypted Data";
    }
};

class CipherManager {
public:
    void addCipher(const std::string& name, std::unique_ptr<Cipher> cipher) {
        ciphers[name] = std::move(cipher);
    }

    std::string encrypt(const std::string& name, const std::string& data) {
        auto it = ciphers.find(name);
        if (it != ciphers.end()) {
            return it->second->encrypt(data);
        }
        throw std::runtime_error("Cipher not found");
    }

    std::string decrypt(const std::string& name, const std::string& data) {
        auto it = ciphers.find(name);
        if (it != ciphers.end()) {
            return it->second->decrypt(data);
        }
        throw std::runtime_error("Cipher not found");
    }

private:
    std::unordered_map<std::string, std::unique_ptr<Cipher>> ciphers;
};

int main() {
    CipherManager manager;
    manager.addCipher("DES", std::make_unique<DES>());
    manager.addCipher("AES", std::make_unique<AES>());

    try {
        std::cout << "Encrypted Data: " << manager.encrypt("DES", "Hello") << std::endl;
        std::cout << "Decrypted Data: " << manager.decrypt("AES", "World") << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
