using System.Threading.Tasks;

public class MultiTenantAuthenticationSystem
{
    private readonly Dictionary<string, List<Tenant>> _tenants = new Dictionary<string, List<Tenant>>();
    private readonly Dictionary<string, Func<string, bool, Task<bool>>> _identityProviders = new Dictionary<string, Func<string, bool, Task<bool>>>();

    public void AddIdentityProvider(string providerName, Func<string, bool, Task<bool>> validator)
    {
        _identityProviders[providerName] = validator;
    }

    public async Task<bool> ValidateUserAsync(Tenant tenant, string userId, string password)
    {
        if (string.IsNullOrEmpty(tenant) || !tenant.Any())
            return false;

        var identityProviderKey = tenant.Split('-').Last();
        if (!_identityProviders.ContainsKey(identityProviderKey))
            throw new Exception("Invalid identity provider");

        var validator = _identityProviders[identityProviderKey];
        return await validator(userId, password);
    }

    public void AddTenant(string tenantId, List<Tenant> users)
    {
        _tenants[tenantId] = users;
    }
}

public class Tenant
{
    public string UserId { get; set; }
    public string PasswordHash { get; set; }
}
