const express = require('express');
const axios = require('axios');
const retry = require('retry-promise');
const { promisify } = require('util');
const fs = require('fs').promises;
const Tracer = require('opentracing');

// Initialize Express app and OpenTracing tracer
const app = express();
const tracer = new Tracer({ /* configuration */ });

// Middleware to initialize spans for requests
app.use((req, res, next) => {
  const span = tracer.startSpan('request');
  req.span = span;
  next();
});

// Function to dynamically load modules with retry logic
async function loadModuleWithRetry(modulePath, maxRetries = 5) {
  const operation = retry.operation({ retries: maxRetries });
  return operation.attempt(async () => {
    const module = await import(modulePath);
    return module;
  });
}

// Function to execute tests with retry logic and exponential backoff
async function runTestWithRetry(testFunction, maxRetries = 5) {
  const operation = retry.operation({ retries: maxRetries });
  return operation.attempt(async () => {
    return await testFunction();
  });
}

// Endpoint to trigger test execution
app.post('/run-tests', async (req, res) => {
  const span = req.span;
  span.setTag('operation', 'runTests');

  try {
    // Load modules dynamically
    const module1 = await loadModuleWithRetry('./modules/module1.js');
    const module2 = await loadModuleWithRetry('./modules/module2.js');

    // Execute tests with retry logic
    const results = await Promise.all([
      runTestWithRetry(module1.test1, 3),
      runTestWithRetry(module2.test2, 4)
    ]);

    span.setTag('test_results', JSON.stringify(results));
    res.status(200).json({ message: 'Tests executed successfully', results });
  } catch (error) {
    span.setTag('error', error.message);
    res.status(500).json({ message: 'Error executing tests' });
  }
});

// C++ function to select attacks with cooldown
extern "C" {
  #include <atomic>
  #include <map>
  #include <string>

  std::mutex attackMutex;
  std::map<std::string, std::pair<int, std::chrono::system_clock::time_point>> attackCooldowns;

  std::string selectAttack(const std::string& character, int cooldown) {
    std::lock_guard<std::mutex> lock(attackMutex);
    auto now = std::chrono::system_clock::now();

    for (auto it = attackCooldowns.begin(); it != attackCooldowns.end();) {
      if (it->second.second <= now) {
        it = attackCooldowns.erase(it);
      } else {
        ++it;
      }
    }

    if (!attackCooldowns.empty()) {
      auto minCoolDownAttack = std::min_element(attackCooldowns.begin(), attackCooldowns.end(),
          [](const std::pair<std::string, std::pair<int, std::chrono::system_clock::time_point>>& a,
             const std::pair<std::string, std::pair<int, std::chrono::system_clock::time_point>>& b) {
            return a.second.second < b.second.second;
          });

      if (now >= minCoolDownAttack->second.second) {
        attackCooldowns.erase(minCoolDownAttack);
        int nextAvailableTime = static_cast<int>(std::chrono::duration_cast<std::chrono::seconds>(
            std::max(now, minCoolDownAttack->second.second) - now).count());
        return std::to_string(nextAvailableTime) + " seconds until available";
      }
    }

    auto currentTime = std::chrono::system_clock::now() + std::chrono::seconds(cooldown);
    attackCooldowns[character] = { cooldown, currentTime };
    return "Attack selected with " + std::to_string(cooldown) + " second cooldown";
  }
}

// Example usage of the C++ function in Node.js
app.post('/select-attack', async (req, res) => {
  const span = req.span;
  span.setTag('operation', 'selectAttack');

  try {
    const result = selectAttack(req.body.character, req.body.cooldown);
    span.log({ message: 'Attack selection result', result });
    res.status(200).json({ message: 'Attack selected', result });
  } catch (error) {
    span.setTag('error', error.message);
    res.status(500).json({ message: 'Error selecting attack' });
  }
});

app.listen(3000, () => {
  console.log('Server is running on port 3000');
});
