const express = require('express');
const bodyParser = require('body-parser');
const axios = require('axios');
const redis = require('redis');
const Bull = require('bull');

// Initialize Express app
const app = express();
app.use(bodyParser.json());

// Redis client for caching transaction metadata
const cacheClient = redis.createClient();

// Bull queue for buffering transaction requests
const paymentQueue = new Bull('paymentQueue', 'redis://localhost:6379');

// Circuit breaker pattern implementation
class CircuitBreaker {
  constructor() {
    this.state = 'CLOSED';
    this.failureCount = 0;
    this.successCount = 0;
    this.lastFailureTime = null;
    this.resetTimeout = 5000; // 5 seconds
  }

  async call(fn) {
    try {
      const result = await fn();
      this.state = 'CLOSED';
      return result;
    } catch (error) {
      this.failureCount++;
      this.lastFailureTime = new Date();
      if (this.state !== 'OPEN') {
        this.state = 'OPEN';
        setTimeout(() => {
          this.state = 'HALF-OPEN';
        }, this.resetTimeout);
      }
      throw error;
    }
  }

  async isClosed() {
    return this.state === 'CLOSED';
  }
}

const circuitBreaker = new CircuitBreaker();

// Payment gateway URLs
const paymentGateways = [
  'https://gateway1.example.com/pay',
  'https://gateway2.example.com/pay'
];

// Load balancer for routing transactions to gateways
function loadBalancer() {
  let index = Math.floor(Math.random() * paymentGateways.length);
  return paymentGateways[index];
}

// Middleware to handle transactions
app.post('/pay', async (req, res) => {
  const { amount, currency, cardNumber } = req.body;

  if (!circuitBreaker.isClosed()) {
    return res.status(503).send('Service is currently unavailable');
  }

  try {
    const gatewayUrl = loadBalancer();
    await circuitBreaker.call(async () => {
      const response = await axios.post(gatewayUrl, { amount, currency, cardNumber });
      paymentQueue.add({ transactionId: response.data.transactionId });
      return response;
    });

    res.status(200).send('Transaction processed successfully');
  } catch (error) {
    res.status(500).send('Failed to process transaction');
  }
});

// Worker for processing buffered transactions
paymentQueue.process(async (job, done) => {
  const { transactionId } = job.data;
  try {
    // Simulate transaction processing
    await new Promise(resolve => setTimeout(resolve, 100));
    console.log(`Processed transaction ${transactionId}`);
    done();
  } catch (error) {
    console.error(`Failed to process transaction ${transactionId}:`, error);
    done(error);
  }
});

// Cache middleware to store transaction metadata
app.use(async (req, res, next) => {
  const { transactionId } = req.body;
  if (transactionId) {
    try {
      const cachedData = await cacheClient.get(transactionId);
      if (cachedData) {
        req.transactionData = JSON.parse(cachedData);
      }
    } catch (error) {
      console.error('Failed to retrieve transaction data from cache:', error);
    }
  }
  next();
});

// Cache middleware to store response data
app.use(async (req, res, next) => {
  const { transactionId } = req.body;
  if (transactionId && !res.headersSent) {
    try {
      await cacheClient.set(transactionId, JSON.stringify(res.locals.data), 'EX', 3600);
    } catch (error) {
      console.error('Failed to store response data in cache:', error);
    }
  }
  next();
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).send('Something broke!');
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
