# Define the main components of the data ingestion pipeline

class LogIngestor:
    def __init__(self, parsers, transformer):
        self.parsers = parsers
        self.transformer = transformer

    def ingest_logs(self, logs):
        parsed_logs = self.parse_logs(logs)
        transformed_logs = self.transform_logs(parsed_logs)
        return transformed_logs

    def parse_logs(self, logs):
        return [parser.parse(log) for parser in self.parsers]

    def transform_logs(self, logs):
        return self.transformer.transform(logs)

