// main.rs

use reqwest::{Client, Error};
use std::time::Duration;
use tokio::sync::Mutex;
use oauth2::{AccessToken, BasicClient};

#[derive(Clone)]
struct APIClient {
    client: Client,
    access_token: Mutex<Option<AccessToken>>,
}

impl APIClient {
    fn new() -> Self {
        APIClient {
            client: Client::builder()
                .timeout(Duration::from_secs(10))
                .build()
                .unwrap(),
            access_token: Mutex::new(None),
        }
    }

    async fn refresh_access_token(&self, client_id: &str, client_secret: &str, token_url: &str) -> Result<(), Error> {
        let mut access_token = self.access_token.lock().await;
        if access_token.is_none() {
            *access_token = Some(BasicClient::new(client_id.to_string(), Some(client_secret.to_string()), token_url.parse().unwrap(), None)
                .exchange_client_credentials()
                .request_async(reqwest::Client::new())
                .await?);
        }
        Ok(())
    }

    async fn make_request(&self, url: &str) -> Result<String, Error> {
        self.refresh_access_token("your_client_id", "your_client_secret", "https://token.url").await?;
        let access_token = self.access_token.lock().await;
        let response = self.client
            .get(url)
            .bearer_auth(access_token.as_ref().unwrap().secret())
            .send()
            .await?
            .text()
            .await?;
        Ok(response)
    }
}

#[tokio::main]
async fn main() -> Result<(), Error> {
    let api_client = APIClient::new();
    let response = api_client.make_request("https://api.example.com/data").await?;
    println!("Response: {}", response);
    Ok(())
}
