# Import necessary libraries and modules
from flask import Flask, request, jsonify
from werkzeug.utils import secure_filename
import os
from cloudinary.uploader import upload
from cloudinary.api import delete_resources_by_tag
from cloudinary.exceptions import CloudinaryError

app = Flask(__name__)
app.config['UPLOAD_FOLDER'] = 'uploads/'
app.config['MAX_CONTENT_LENGTH'] = 16 * 1024 * 1024  # 16MB limit per file

# Initialize Cloudinary configurations (replace with your actual credentials)
cloudinary.config(
    cloud_name="your_cloud_name",
    api_key="your_api_key",
    api_secret="your_api_secret"
)

def allowed_file(filename):
    return '.' in filename and \
           filename.rsplit('.', 1)[1].lower() in {'png', 'jpg', 'jpeg', 'gif'}

@app.route('/upload', methods=['POST'])
def upload_file():
    if request.method == 'POST':
        # Check if the post request has the file part
        if 'file' not in request.files:
            return jsonify({"error": "No file part"}), 400
        file = request.files['file']
        # If the user does not select a file, the browser submits an empty file without a filename.
        if file.filename == '':
            return jsonify({"error": "No selected file"}), 400
        if file and allowed_file(file.filename):
            try:
                # Upload file to Cloudinary
                result = upload(file, folder="user_uploads")
                return jsonify(result), 201
            except CloudinaryError as e:
                return jsonify({"error": str(e)}), 500

@app.route('/delete/<public_id>', methods=['DELETE'])
def delete_file(public_id):
    try:
        # Delete file from Cloudinary
        result = delete_resources_by_tag(public_id)
        if result['deleted']:
            return jsonify({"message": "File deleted successfully"}), 200
        else:
            return jsonify({"error": "File not found or deletion failed"}), 404
    except Exception as e:
        return jsonify({"error": str(e)}), 500

if __name__ == '__main__':
    app.run(debug=True)
