class LogAggregator {
public:
    // Constructor
    LogAggregator(size_t numThreads = 4) : stop(false), threads(numThreads) {
        for (size_t i = 0; i < numThreads; ++i) {
            threads[i] = std::thread(&LogAggregator::worker, this);
        }
    }

    // Destructor
    ~LogAggregator() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stop = true;
        }
        condition.notify_all();
        for (auto& thread : threads) {
            thread.join();
        }
