    void addFileLog(const std::string& filename) {
        std::ifstream file(filename);
        if (!file.is_open()) {
            throw std::runtime_error("Cannot open file: " + filename);
        }
        std::string line;
        while (std::getline(file, line)) {
            logQueue.push({filename, line, std::chrono::system_clock::now()});
        }
    }

    // Function to add a log entry from a network stream
    void addNetworkLog(const std::string& data) {
        logQueue.push({"network", data, std::chrono::system_clock::now()});
    }

    // Function to add a custom protocol log entry
    void addCustomProtocolLog(const std::string& source, const std::string& data) {
        logQueue.push({source, data, std::chrono::system_clock::now()});
    }

private:
    std::queue<LogEntry> logQueue;
    std::vector<std::thread> threads;
    std::mutex mutex;
    std::condition_variable condition;
    bool stop;

    // Worker function to process log entries
    void worker() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            condition.wait(lock, [this]{ return !logQueue.empty() || stop; });
            if (stop && logQueue.empty()) {
                break;
            }
            LogEntry entry = logQueue.front();
            logQueue.pop();
            lock.unlock();

            // Process the log entry
            processLog(entry);
        }
    }

    // Function to process a single log entry
    void processLog(const LogEntry& entry) {
        // Placeholder for actual processing logic
        std::cout << "Processing log from " << entry.source << ": " << entry.message << std::endl;
    }
};

