```cpp
#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <random>
#include <chrono>
#include "nfaapi.h"

struct NFAPICRCIndication {
    RX_UE_INFORMATION_TAG rxUeInfoTag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcIndicationTag;
    uint8_t crcFlag;

    NFAPICRCIndication() : crcFlag(rand() % 2) {}
};

class NFAPIClient {
private:
    std::mutex mtx;
    std::condition_variable cv;
    std::queue<NFAPICRCIndication> requestQueue;
    bool stop;
    int maxRetries;
    std::chrono::milliseconds retryInterval;

public:
    NFAPIClient(int retries = 3, std::chrono::milliseconds interval = std::chrono::seconds(1))
        : stop(false), maxRetries(retries), retryInterval(interval) {}

    void start() {
        std::thread([this]() {
            while (true) {
                std::unique_lock<std::mutex> lock(mtx);
                cv.wait(lock, [this] { return !requestQueue.empty() || stop; });
                if (stop && requestQueue.empty()) break;
                NFAPICRCIndication request = requestQueue.front();
                requestQueue.pop();

                int retries = 0;
                while (retries < maxRetries) {
                    if (nfaapi_send_crc_indication(request)) {
                        std::cout << "CRC Indication sent successfully." << std::endl;
                        break;
                    }
                    ++retries;
                    std::this_thread::sleep_for(retryInterval);
                }

                if (retries == maxRetries) {
                    std::cerr << "Failed to send CRC Indication after " << maxRetries << " retries." << std::endl;
                }
            }
        }).detach();
    }

    void stopClient() {
        {
            std::lock_guard<std::mutex> lock(mtx);
            stop = true;
        }
        cv.notify_all();
    }

    void enqueueRequest(NFAPICRCIndication request) {
        std::lock_guard<std::mutex> lock(mtx);
        requestQueue.push(request);
        cv.notify_one();
    }
};

int main() {
    NFAPIClient client(5, std::chrono::seconds(2));
    client.start();

    for (int i = 0; i < 10; ++i) {
        NFAPICRCIndication request;
        client.enqueueRequest(request);
        std::this_thread::sleep_for(std::chrono::milliseconds(rand() % 500));
    }

    client.stopClient();
    return 0;
}
```

