#include <iostream>
#include <thread>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>

class NetworkInterfaceManager {
public:
    void addService(const std::string& serviceUrl) {
        std::lock_guard<std::mutex> lock(mutex_);
        services_.push_back(serviceUrl);
    }

    void removeService(const std::string& serviceUrl) {
        std::lock_guard<std::mutex> lock(mutex_);
        services_.erase(std::remove(services_.begin(), services_.end(), serviceUrl), services_.end());
    }

    void start() {
        worker_ = std::thread(&NetworkInterfaceManager::worker, this);
    }

    void stop() {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            running_ = false;
        }
        condition_.notify_all();
        if (worker_.joinable()) {
            worker_.join();
        }
    }

private:
    void worker() {
        while (true) {
            std::string serviceUrl;
            {
                std::unique_lock<std::mutex> lock(mutex_);
                condition_.wait(lock, [this] { return !services_.empty() || !running_; });
                if (!running_) break;
                serviceUrl = services_.front();
                services_.pop_front();
            }
            // Simulate network connection establishment and maintenance
            std::cout << "Establishing connection to: " << serviceUrl << std::endl;
            // Simulate network operation
            std::this_thread::sleep_for(std::chrono::seconds(1));
        }
    }

    std::vector<std::string> services_;
    std::mutex mutex_;
    std::condition_variable condition_;
    std::thread worker_;
    bool running_ = true;
};

int main() {
    NetworkInterfaceManager manager;
    manager.addService("http://service1.example.com");
    manager.addService("http://service2.example.com");

    manager.start();

    // Simulate system operations
    std::this_thread::sleep_for(std::chrono::seconds(5));

    manager.removeService("http://service1.example.com");
    manager.stop();

    return 0;
}
