    // Simulate transient failure
    if (rand() % 3 == 0) {
        return 0; // Success
    } else {
        return -1; // Failure
    }
}

// Thread-safe function with concurrency control
void* manage_memory_thread(void* arg) {
    int *params = (int *)arg;
    int N = params[0];
    float crc_probability = params[1];
    return (void *)(long)manage_memory(N, crc_probability);
}

int main() {
    pthread_t thread1, thread2;
    int params1[] = {10, 0.8};
    int params2[] = {5, 0.5};

