        perror("Thread creation failed");
        return -1;
    }

    if (pthread_create(&thread2, NULL, manage_memory_thread, (void *)params2) != 0) {
        perror("Thread creation failed");
        return -1;
    }

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    return 0;
}
