#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct DataPacket {
    int sourceType; // 0 for base station, 1 for cloud service
    void* data;
    struct DataPacket* next;
} DataPacket;

typedef struct MemoryPool {
    size_t block_size;
    size_t num_blocks;
    void** free_list;
    pthread_mutex_t lock;
} MemoryPool;

void initMemoryPool(MemoryPool* pool, size_t block_size, size_t num_blocks) {
    pool->block_size = block_size;
    pool->num_blocks = num_blocks;
    pool->free_list = (void**)malloc(num_blocks * sizeof(void*));
    for (size_t i = 0; i < num_blocks; ++i) {
        pool->free_list[i] = malloc(block_size);
    }
    pthread_mutex_init(&pool->lock, NULL);
}

void* allocateFromPool(MemoryPool* pool) {
    void* block;
    pthread_mutex_lock(&pool->lock);
    if (pool->free_list[0]) {
        block = pool->free_list[0];
        memmove(pool->free_list, pool->free_list + 1, (pool->num_blocks - 1) * sizeof(void*));
        pool->num_blocks--;
    } else {
        block = malloc(pool->block_size);
    }
    pthread_mutex_unlock(&pool->lock);
    return block;
}

void freeToPool(MemoryPool* pool, void* block) {
    pthread_mutex_lock(&pool->lock);
    if (pool->num_blocks == 0) {
        pool->free_list[0] = block;
        pool->num_blocks++;
    } else {
        memmove(pool->free_list + 1, pool->free_list, pool->num_blocks * sizeof(void*));
        pool->free_list[0] = block;
        pool->num_blocks++;
    }
    pthread_mutex_unlock(&pool->lock);
}

void processRxIndications(MemoryPool* pool) {
    DataPacket* packet = get_next_packet_from_network();
    while (packet != NULL) {
        if (is_critical_source(packet)) {
            NFAPI_CRC_INDICATION_PDU_T* pdu = allocateFromPool(pool);
            validate_and_fill_pdu(pdu, packet->data);
            process_pdu(pdu);
            freeToPool(pool, pdu);
        }
        packet = get_next_packet_from_network();
    }
}

void* thread_func(void* arg) {
    MemoryPool* pool = (MemoryPool*)arg;
    processRxIndications(pool);
    return NULL;
}

int main() {
    MemoryPool pool;
    initMemoryPool(&pool, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1000);

    pthread_t threads[10000];
    for (int i = 0; i < 10000; ++i) {
        pthread_create(&threads[i], NULL, thread_func, &pool);
    }

    for (int i = 0; i < 10000; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
