    NFAPI_CRC_INDICATION_PDU_T pdu;
} ValidatedEvent;

typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    ValidatedEvent* events;
    size_t capacity;
    size_t count;
    int64_t last_event_time;
    int error_count;
    int circuit_breaker_state;
} EventQueue;

void initEventQueue(EventQueue* queue, size_t capacity) {
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->cond, NULL);
    queue->events = (ValidatedEvent*)malloc(capacity * sizeof(ValidatedEvent));
    queue->capacity = capacity;
    queue->count = 0;
    queue->last_event_time = time(NULL);
    queue->error_count = 0;
    queue->circuit_breaker_state = CIRCUIT_BREAKER_CLOSED;
}

void destroyEventQueue(EventQueue* queue) {
    pthread_mutex_destroy(&queue->mutex);
    pthread_cond_destroy(&queue->cond);
    free(queue->events);
}

int enqueueEvent(EventQueue* queue, ValidatedEvent event) {
    pthread_mutex_lock(&queue->mutex);
    while (queue->count >= queue->capacity && queue->circuit_breaker_state == CIRCUIT_BREAKER_OPEN) {
        pthread_cond_wait(&queue->cond, &queue->mutex);
    }
    if (queue->error_count > MAX_ERRORS || queue->circuit_breaker_state == CIRCUIT_BREAKER_OPEN) {
        pthread_mutex_unlock(&queue->mutex);
        return -1;
    }
    for (size_t i = 0; i < queue->count; ++i) {
        if (queue->events[i].RNTI == event.RNTI) {
            pthread_mutex_unlock(&queue->mutex);
            return -1;
        }
    }
    queue->events[queue->count++] = event;
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->mutex);
    return 0;
