// Define a structure for data source
typedef struct {
    char identifier[50];
    int priority;
    pthread_mutex_t lock;
} DataSource_T;

// Define a structure for memory pool
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t size;
    size_t count;
    pthread_mutex_t lock;
} MemoryPool_T;

// Function to initialize the memory pool
void initMemoryPool(MemoryPool_T *pool, size_t size) {
    pool->size = size;
    pool->count = 0;
    pool->pool = (NFAPI_CRC_INDICATION_PDU_T *)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&pool->lock, NULL);
}

// Function to allocate memory from the pool
NFAPI_CRC_INDICATION_PDU_T *allocateFromPool(MemoryPool_T *pool) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = NULL;
    pthread_mutex_lock(&pool->lock);
    if (pool->count < pool->size) {
        pdu = &pool->pool[pool->count++];
    }
    pthread_mutex_unlock(&pool->lock);
    return pdu;
}

// Function to deallocate memory back to the pool
void deallocateToPool(MemoryPool_T *pool, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&pool->lock);
    // Find the index of the freed PDU and move it to the end
    for (size_t i = 0; i < pool->count; ++i) {
        if (&pool->pool[i] == pdu) {
            pool->pool[i] = pool->pool[--pool->count];
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

// Function to process RX indications
void processRxIndications(void *arg) {
    DataSource_T *source = (DataSource_T *)arg;
    NFAPI_CRC_INDICATION_PDU_T *pdu = allocateFromPool(&memoryPool);

    if (pdu != NULL) {
        // Lock the data source for thread safety
        pthread_mutex_lock(&source->lock);

        // Process the RX indication PDU
        // Example: pdu->rnti = getRNTI(source);

        // Unlock the data source after processing
        pthread_mutex_unlock(&source->lock);

        // Free the memory pool
        deallocateToPool(&memoryPool, pdu);
    } else {
        // Handle memory allocation failure
        printf("Memory allocation failed for %s\n", source->identifier);
    }
}

// Initialize the memory pool
MemoryPool_T memoryPool;

// Thread function to simulate processing multiple sources concurrently
void *threadFunction(void *arg) {
    processRxIndications(arg);
    return NULL;
}

int main() {
    // Initialize the memory pool with a size of 1000 PDUs
    initMemoryPool(&memoryPool, 1000);

    // Create an array of data sources and initialize them
    DataSource_T sources[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; ++i) {
        snprintf(sources[i].identifier, sizeof(sources[i].identifier), "Source%d", i);
        sources[i].priority = (i % 2 == 0) ? 1 : 2;
        pthread_mutex_init(&sources[i].lock, NULL);
    }

    // Create threads to simulate concurrent processing
    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_create(&threads[i], NULL, threadFunction, &sources[i]);
    }

    // Wait for all threads to finish
    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

