import org.springframework.web.client.RestTemplate;

@Service
public class PokemonWeaknessService {

    private final Map<String, String> typeCache = new ConcurrentHashMap<>();
    private final RestTemplate restTemplate = new RestTemplate();

    public CompletableFuture<String> getWeakness(String pokemonType) {
        if (typeCache.containsKey(pokemonType)) {
            return CompletableFuture.completedFuture(typeCache.get(pokemonType));
        }

        return CompletableFuture.supplyAsync(() -> fetchFromDataSources(pokemonType))
                              .thenApply(weakness -> {
                                  typeCache.put(pokemonType, weakness);
                                  return weakness;
                              });
    }

    private String fetchFromDataSources(String pokemonType) {
        // Priority-based data retrieval
        String[] sources = {"HighQualitySource", "SecondarySource"};

        for (String source : sources) {
            try {
                String response = restTemplate.getForObject(source + "/" + pokemonType, String.class);
                if (isValidResponse(response)) {
                    return response;
                }
            } catch (Exception e) {
                // Handle exceptions and log
            }
        }

        throw new RuntimeException("Failed to retrieve data from any source");
    }

    private boolean isValidResponse(String response) {
        // Implement validation logic
        return true;
    }
}
