#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/hmac.h>
#include <pthread.h>

#define MAX_CONCURRENT_REQUESTS 10000

typedef struct {
    EVP_MD_CTX *md_ctx;
    int retry_count;
} CryptoContext;

CryptoContext crypto_contexts[MAX_CONCURRENT_REQUESTS];

void* handle_request(void* request_id) {
    // Simulate cryptographic operation
    unsigned char hash[EVP_MAX_MD_SIZE];
    int len;
    EVP_DigestInit_ex(crypto_contexts[*((int*)request_id)].md_ctx, EVP_sha256(), NULL);
    EVP_DigestUpdate(crypto_contexts[*((int*)request_id)].md_ctx, "data", 4);
    EVP_DigestFinal_ex(crypto_contexts[*((int*)request_id)].md_ctx, hash, &len);

    // Simulate retry logic
    while (crypto_contexts[*((int*)request_id)].retry_count < 5) {
        if (EVP_DigestInit_ex(crypto_contexts[*((int*)request_id)].md_ctx, EVP_sha256(), NULL) == 1) {
            crypto_contexts[*((int*)request_id)].retry_count++;
            break;
        }
    }

    pthread_exit(NULL);
}

int main() {
    pthread_t threads[MAX_CONCURRENT_REQUESTS];
    int request_ids[MAX_CONCURRENT_REQUESTS];

    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; i++) {
        crypto_contexts[i].md_ctx = EVP_MD_CTX_new();
        if (!crypto_contexts[i].md_ctx) {
            fprintf(stderr, "Failed to create EVP_MD_CTX\n");
            return 1;
        }
        request_ids[i] = i;
    }

    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; i++) {
        pthread_create(&threads[i], NULL, handle_request, &request_ids[i]);
    }

    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; i++) {
        pthread_join(threads[i], NULL);
        EVP_MD_CTX_free(crypto_contexts[i].md_ctx);
    }

    return 0;
}
