class StreamingDataAggregator {
public:
    // Constructor
    StreamingDataAggregator() : running(false) {}

    // Destructor
    ~StreamingDataAggregator() {
        stop();
    }

    // Start the aggregation process
    void start() {
        if (running) return;
        running = true;
        processingThread = std::thread(&StreamingDataAggregator::process, this);
    }

    // Stop the aggregation process
    void stop() {
        if (!running) return;
        running = false;
        dataQueue.notify_all();
        processingThread.join();
    }

    // Add new data to the queue
    void addData(const std::string& data) {
        std::unique_lock<std::mutex> lock(dataMutex);
        dataQueue.push(data);
        dataQueueCondition.notify_one();
    }

private:
    std::thread processingThread;
    std::atomic<bool> running;
    std::queue<std::string> dataQueue;
    std::mutex dataMutex;
    std::condition_variable dataQueueCondition;

    void process() {
        while (running) {
            std::unique_lock<std::mutex> lock(dataMutex);
            dataQueueCondition.wait(lock, [this] { return !dataQueue.empty() || !running; });

            if (!running && dataQueue.empty()) break;

            std::string data = dataQueue.front();
            dataQueue.pop();

            lock.unlock();

            // Process the data
            processData(data);
        }
    }

    void processData(const std::string& data) {
        // Implement data processing logic here
        std::cout << "Processing data: " << data << std::endl;
    }
};

int main() {
    StreamingDataAggregator aggregator;
    aggregator.start();

    for (int i = 0; i < 10; ++i) {
        aggregator.addData("Sensor Data " + std::to_string(i));
        std::this_thread::sleep_for(std::chrono::milliseconds(500));
    }

    aggregator.stop();
    return 0;
}
