typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG[256];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generateNfaapiCrcIndications(const char* configFilePath, int count) {
    NFAPI_CRC_INDICATION_PDU_T* indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    json_object* root = json_tokener_parse_file(configFilePath);
    if (!root) {
        fprintf(stderr, "Failed to parse JSON configuration file\n");
        free(indications);
        return NULL;
    }

    for (int i = 0; i < count; i++) {
        int RX_UE_INFORMATION_TAG = json_object_get_int(json_object_array_get_idx(root, 2 * i));
        int RNTI = json_object_get_int(json_object_array_get_idx(root, 2 * i + 1));
        char* CRC_INDICATION_REL8_TAG = strdup(json_object_get_string(json_object_array_get_idx(root, 2 * i + 2)));

        indications[i].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        indications[i].RNTI = RNTI;
        strcpy(indications[i].CRC_INDICATION_REL8_TAG, CRC_INDICATION_REL8_TAG);

        unsigned int seed = time(NULL) % (i + 1);
        srand(seed);
        indications[i].CRCFLAG = rand() % 2; // Simplified pseudo-random logic
    }

    json_object_put(root);
    return indications;
}
