public class NfaapiCrcIndicationPdu
{
    public int RX_UE_INFORMATION_TAG { get; set; }
    public int RNTI { get; set; }
    public string CRC_INDICATION_REL8_TAG { get; set; }
    public int CRCFLAG { get; set; }
}

public class DatabaseManager
{
    private readonly string _connectionString;

    public DatabaseManager(string connectionString)
    {
        _connectionString = connectionString;
    }

    public async Task ExecuteSqlWithNfaapiIndications(List<NfaapiCrcIndicationPdu> indications, string sqlCommand)
    {
        using (var connectionPool = new SqlConnection(_connectionString))
        {
            await connectionPool.OpenAsync();

            foreach (var indication in indications)
            {
                using (var command = new SqlCommand(sqlCommand, connectionPool))
                {
                    command.Parameters.AddWithValue("@RX_UE_INFORMATION_TAG", indication.RX_UE_INFORMATION_TAG);
                    command.Parameters.AddWithValue("@RNTI", indication.RNTI);
                    command.Parameters.AddWithValue("@CRC_INDICATION_REL8_TAG", indication.CRC_INDICATION_REL8_TAG);
                    command.Parameters.AddWithValue("@CRCFLAG", indication.CRCFLAG);

                    try
                    {
                        await command.ExecuteNonQueryAsync();
                    }
                    catch (SqlException ex)
                    {
                        Console.WriteLine($"SQL error: {ex.Message}");
                    }
                }
            }
        }
    }
}
