// Include necessary headers
#include <openssl/evp.h>
#include <semaphore.h>
#include <openssl/kdf.h>
#include <stdlib.h>

// Define a structure for cipher context
typedef struct {
    EVP_CIPHER_CTX *ctx;
    sem_t semaphore;
} CipherContext;

// Function to initialize the cipher context based on user-defined parameters
CipherContext* init_cipher_context(const char* algorithm, const unsigned char* key, int mode) {
    CipherContext *cipher_ctx = malloc(sizeof(CipherContext));
    cipher_ctx->ctx = EVP_CIPHER_CTX_new();

    if (!cipher_ctx->ctx) {
        // Handle error
        return NULL;
    }

    if (EVP_EncryptInit_ex(cipher_ctx->ctx, EVP_get_cipherbyname(algorithm), NULL, key, NULL) != 1) {
        // Handle error
        EVP_CIPHER_CTX_free(cipher_ctx->ctx);
        free(cipher_ctx);
        return NULL;
    }

    // Initialize semaphore for concurrency control
    sem_init(&cipher_ctx->semaphore, 0, 1);

    return cipher_ctx;
}

// Function to clean up the cipher context
void cleanup_cipher_context(CipherContext *cipher_ctx) {
    if (cipher_ctx->ctx) {
        EVP_CIPHER_CTX_free(cipher_ctx->ctx);
    }
    sem_destroy(&cipher_ctx->semaphore);
    free(cipher_ctx);
}

// Function to perform encryption using the cipher context
int encrypt_data(CipherContext *cipher_ctx, const unsigned char* plaintext, int plaintext_len, unsigned char* ciphertext) {
    sem_wait(&cipher_ctx->semaphore);

    if (EVP_EncryptUpdate(cipher_ctx->ctx, ciphertext, &ciphertext_len, plaintext, plaintext_len) != 1 ||
        EVP_EncryptFinal_ex(cipher_ctx->ctx, ciphertext + ciphertext_len, &ciphertext_len) != 1) {
        sem_post(&cipher_ctx->semaphore);
        // Handle error
        return -1;
    }

    sem_post(&cipher_ctx->semaphore);
    return ciphertext_len;
}

// Function to perform decryption using the cipher context
int decrypt_data(CipherContext *cipher_ctx, const unsigned char* ciphertext, int ciphertext_len, unsigned char* plaintext) {
    sem_wait(&cipher_ctx->semaphore);

    if (EVP_DecryptUpdate(cipher_ctx->ctx, plaintext, &plaintext_len, ciphertext, ciphertext_len) != 1 ||
        EVP_DecryptFinal_ex(cipher_ctx->ctx, plaintext + plaintext_len, &plaintext_len) != 1) {
        sem_post(&cipher_ctx->semaphore);
        // Handle error
        return -1;
    }

    sem_post(&cipher_ctx->semaphore);
    return plaintext_len;
}
