using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Security.Cryptography;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;

public class CryptoServiceClient
{
    private readonly HttpClient _httpClient;
    private readonly IOptions<CryptoServiceSettings> _settings;
    private readonly ILogger<CryptoServiceClient> _logger;

    public CryptoServiceClient(HttpClient httpClient, IOptions<CryptoServiceSettings> settings, ILogger<CryptoServiceClient> logger)
    {
        _httpClient = httpClient;
        _settings = settings;
        _logger = logger;
    }

    public async Task<string> DecryptAsync(string encryptedMessage)
    {
        try
        {
            var response = await _httpClient.PostAsync(_settings.Value.DecryptionServiceUrl, new StringContent(encryptedMessage));
            response.EnsureSuccessStatusCode();
            return await response.Content.ReadAsStringAsync();
        }
        catch (HttpRequestException ex)
        {
            _logger.LogError(ex, "Decryption failed due to network error.");
            throw;
        }
    }
}

public class MessageProcessor
{
    private readonly ICryptoServiceClient _cryptoServiceClient;
    private readonly ILogger<MessageProcessor> _logger;

    public MessageProcessor(ICryptoServiceClient cryptoServiceClient, ILogger<MessageProcessor> logger)
    {
        _cryptoServiceClient = cryptoServiceClient;
        _logger = logger;
    }

    public async Task<int> ProcessMessageAsync(string encryptedMessage)
    {
        try
        {
            var decryptedMessage = await _cryptoServiceClient.DecryptAsync(encryptedMessage);
            return decryptedMessage.Split(',').Select(int.Parse).Max();
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to process message.");
            throw;
        }
    }
}

public class Program
{
    public static async Task Main(string[] args)
    {
        var config = new ConfigurationBuilder()
            .AddJsonFile("appsettings.json", optional: false, reloadOnChange: true)
            .Build();

        var services = new ServiceCollection();
        services.AddHttpClient<CryptoServiceClient>();
        services.Configure<CryptoServiceSettings>(config.GetSection("CryptoServiceSettings"));
        services.AddSingleton<MessageProcessor>();

        var serviceProvider = services.BuildServiceProvider();

        var messageProcessor = serviceProvider.GetService<MessageProcessor>();

        var encryptedMessages = new List<string>
        {
            "1,2,3",
            "4,5,6",
            "7,8,9"
        };

        var tasks = encryptedMessages.Select(async encryptedMessage => await messageProcessor.ProcessMessageAsync(encryptedMessage));

        var results = await Task.WhenAll(tasks);

        Console.WriteLine("Largest integers: " + string.Join(", ", results));
    }
}

public class CryptoServiceSettings
{
    public string DecryptionServiceUrl { get; set; }
}
