import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.cloud.stream.annotation.EnableBinding;
import org.springframework.cloud.stream.messaging.Sink;
import org.springframework.integration.annotation.ServiceActivator;
import org.springframework.integration.core.MessageHandler;
import org.apache.kafka.clients.consumer.ConsumerConfig;
import org.apache.kafka.common.serialization.StringDeserializer;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.elasticsearch.client.RestHighLevelClient;
import org.elasticsearch.client.RestClientBuilder;
import java.util.HashMap;
import java.util.Map;

@SpringBootApplication
@EnableBinding(Sink.class)
public class DataProcessingServiceApplication {

    public static void main(String[] args) {
        SpringApplication.run(DataProcessingServiceApplication.class, args);
    }
}

@Configuration
class KafkaConfig {

    @Value("${kafka.bootstrap-servers}")
    private String bootstrapServers;

    @Bean
    public Map<String, Object> consumerConfigs() {
        Map<String, Object> props = new HashMap<>();
        props.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, bootstrapServers);
        props.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);
        props.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);
        return props;
    }

    @Bean
    public RestClientBuilder restClientBuilder() {
        return RestClient.builder(
                HttpHost.create("http://localhost:9200")
        );
    }

    @Bean
    public RestHighLevelClient client(RestClientBuilder builder) {
        return new RestHighLevelClient(builder);
    }
}

@ServiceActivator(inputChannel = Sink.INPUT)
public class MessageHandlerService implements MessageHandler {

    @Autowired
    private ElasticsearchOperations elasticsearchTemplate;

    @Override
    public void handleMessage(Message<?> message) throws MessagingException {
        // Process and transform the message
        String data = (String) message.getPayload();
        // Perform operations on data
        processAndStoreData(data);
    }

    private void processAndStoreData(String data) {
        // Logic to process and store data in Elasticsearch
        elasticsearchTemplate.index(new IndexQueryBuilder()
                .withId(UUID.randomUUID().toString())
                .withSource(data, XContentType.JSON)
                .build());
    }
}
