#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define NetworkInterfaceConfiguration struct
typedef struct {
    char ip_address[16];
    char subnet_mask[16];
    char gateway[16];
} NetworkInterfaceConfiguration;

// Define a thread-safe data structure to manage configurations
typedef struct {
    NetworkInterfaceConfiguration* configs;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} NetworkConfigManager;

// Initialize the configuration manager
void init_network_config_manager(NetworkConfigManager* manager, size_t initial_capacity) {
    manager->configs = (NetworkInterfaceConfiguration*)malloc(initial_capacity * sizeof(NetworkInterfaceConfiguration));
    if (!manager->configs) {
        perror("Failed to allocate memory for network configurations");
        exit(EXIT_FAILURE);
    }
    manager->count = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);
}

// Add a new configuration to the manager
void add_network_config(NetworkConfigManager* manager, const NetworkInterfaceConfiguration* config) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->capacity) {
        // Resize the array with mutex protection
        size_t new_capacity = manager->capacity * 2;
        NetworkInterfaceConfiguration* new_configs = (NetworkInterfaceConfiguration*)realloc(manager->configs, new_capacity * sizeof(NetworkInterfaceConfiguration));
        if (!new_configs) {
            perror("Failed to reallocate memory for network configurations");
            pthread_mutex_unlock(&manager->lock);
            exit(EXIT_FAILURE);
        }
        manager->configs = new_configs;
        manager->capacity = new_capacity;
    }
    memcpy(&manager->configs[manager->count], config, sizeof(NetworkInterfaceConfiguration));
    manager->count++;
    pthread_mutex_unlock(&manager->lock);
}

// Remove a configuration from the manager
void remove_network_config(NetworkConfigManager* manager, const char* ip_address) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; i++) {
        if (strcmp(manager->configs[i].ip_address, ip_address) == 0) {
            // Remove the configuration and shift elements
            memmove(&manager->configs[i], &manager->configs[i + 1], (manager->count - i - 1) * sizeof(NetworkInterfaceConfiguration));
            manager->count--;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

// Validate IP address format
int validate_ip_address(const char* ip_address) {
    // Simple validation using sscanf, real-world implementations may require more robust checks
    int parts[4];
    if (sscanf(ip_address, "%d.%d.%d.%d", &parts[0], &parts[1], &parts[2], &parts[3]) != 4 ||
        parts[0] < 0 || parts[0] > 255 ||
        parts[1] < 0 || parts[1] > 255 ||
        parts[2] < 0 || parts[2] > 255 ||
        parts[3] < 0 || parts[3] > 255) {
        return 0; // Invalid IP address
    }
    return 1; // Valid IP address
}

// Detect conflicts in subnet masks and gateways
int detect_subnet_mask_gateway_conflict(NetworkConfigManager* manager, const NetworkInterfaceConfiguration* config) {
    for (size_t i = 0; i < manager->count; i++) {
        if (strcmp(manager->configs[i].subnet_mask, config->subnet_mask) == 0 &&
            strcmp(manager->configs[i].gateway, config->gateway) == 0 && 
            i != manager->count - 1) { // Exclude the current configuration
            return 1; // Conflict detected
        }
    }
    return 0; // No conflict detected
}

// Clean up and free resources
void cleanup_network_config_manager(NetworkConfigManager* manager) {
    pthread_mutex_lock(&manager->lock);
    free(manager->configs);
    manager->configs = NULL;
    manager->count = 0;
    manager->capacity = 0;
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

int main() {
    NetworkConfigManager config_manager;
    init_network_config_manager(&config_manager, 10);

    NetworkInterfaceConfiguration config1 = {"192.168.1.1", "255.255.255.0", "192.168.1.254"};
    add_network_config(&config_manager, &config1);

    NetworkInterfaceConfiguration config2 = {"10.0.0.1", "255.255.0.0", "10.0.0.1"};
    if (!validate_ip_address(config2.ip_address)) {
        printf("Invalid IP address\n");
    } else if (detect_subnet_mask_gateway_conflict(&config_manager, &config2)) {
        printf("Subnet mask and gateway conflict detected\n");
    } else {
        add_network_config(&config_manager, &config2);
    }

    remove_network_config(&config_manager, "192.168.1.1");

    cleanup_network_config_manager(&config_manager);

    return 0;
}
