// Define the DOMTraverser class
class DOMTraverser {
  constructor() {
    this.cache = new Map();
  }

  // Select elements using CSS selector
  select(selector) {
    return document.querySelectorAll(selector);
  }

  // Add event listener to multiple selectors
  on(selector, event, callback) {
    this.select(selector).forEach(element => {
      element.addEventListener(event, callback);
    });
  }

  // Fetch and update metadata asynchronously for each matched element
  async fetchMetadata(selector, url) {
    try {
      const elements = this.select(selector);
      for (let i = 0; i < elements.length; i++) {
        if (!this.cache.has(url)) {
          const response = await fetch(url);
          const data = await response.json();
          this.cache.set(url, data);
        }
        elements[i].dataset.metadata = JSON.stringify(this.cache.get(url));
      }
    } catch (error) {
      console.error(`Error fetching metadata: ${error}`);
      // Implement fallback mechanism
    }
  }

  // Cache strategies to reduce redundant network calls
  clearCache() {
    this.cache.clear();
  }
}

// Usage example:
const traverser = new DOMTraverser();
traverser.on('.my-element', 'click', () => console.log('Clicked!'));
traverser.fetchMetadata('.my-element', 'https://cdn.example.com/data.json');
