// Import necessary modules and libraries
const express = require('express');
const mongoose = require('mongoose');
const bodyParser = require('body-parser');
const cors = require('cors');
const jwt = require('jsonwebtoken');

// Initialize the Express application
const app = express();
app.use(bodyParser.json());
app.use(cors());

// Connect to MongoDB database
mongoose.connect('mongodb://localhost:27017/iot', {
  useNewUrlParser: true,
  useUnifiedTopology: true
});

// Define a Mongoose schema for IoT devices
const deviceSchema = new mongoose.Schema({
  deviceId: String,
  dataFormat: String,
  protocols: [String],
  authentication: String
});

const Device = mongoose.model('Device', deviceSchema);

// Implement role-based access control middleware
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];
  if (token == null) return res.sendStatus(401);
  jwt.verify(token, 'secret_key', (err, user) => {
    if (err) return res.sendStatus(403);
    req.user = user;
    next();
  });
}

// Define API endpoints for IoT device management
app.post('/devices', async (req, res) => {
  const newDevice = new Device(req.body);
  await newDevice.save();
  res.status(201).send(newDevice);
});

app.get('/devices', authenticateToken, async (req, res) => {
  const devices = await Device.find({});
  res.send(devices);
});

// Implement asynchronous data ingestion with retry logic
const axios = require('axios');
const exponentialBackoff = require('exponential-backoff');

async function ingestData(deviceId) {
  let attempt = 0;
  const maxAttempts = 5;

  async function fetchData() {
    try {
      const response = await axios.get(`http://device/${deviceId}/data`);
      // Process the data
      return response.data;
    } catch (error) {
      if (attempt < maxAttempts - 1) {
        attempt++;
        await exponentialBackoff.sleep(1000 * Math.pow(2, attempt));
        return fetchData();
      }
      throw error;
    }
  }

  return fetchData();
}

// Balance data storage efficiency with query performance
const compression = require('compression');
app.use(compression());

// Design a caching layer to optimize API calls
const Redis = require('ioredis');
const redis = new Redis();

app.get('/device-data/:deviceId', async (req, res) => {
  const deviceId = req.params.deviceId;
  const cachedData = await redis.get(deviceId);
  if (cachedData) {
    res.send(JSON.parse(cachedData));
  } else {
    const data = await ingestData(deviceId);
    await redis.setex(deviceId, 3600, JSON.stringify(data)); // Cache for 1 hour
    res.send(data);
  }
});

// Support end-to-end encryption for secure communication
const crypto = require('crypto');
app.use((req, res, next) => {
  const encryptedData = encrypt(req.body.data);
  req.body.data = encryptedData;
  next();
});

function encrypt(text) {
  const iv = crypto.randomBytes(16);
  const cipher = crypto.createCipheriv('aes-256-cbc', Buffer.from('secret_key'), iv);
  let encrypted = cipher.update(text, 'utf8', 'hex');
  encrypted += cipher.final('hex');
  return iv.toString('hex') + ':' + encrypted;
}

// Implement a monitoring dashboard
const prometheus = require('prom-client');
const collectDefaultMetrics = prometheus.collectDefaultMetrics;

collectDefaultMetrics();

app.get('/metrics', (req, res) => {
  res.set('Content-Type', prometheus.register.contentType);
  res.end(prometheus.register.metrics());
});

// Ensure the application is robust and resilient
const cluster = require('cluster');
const numCPUs = require('os').cpus().length;

if (cluster.isMaster) {
  console.log(`Master ${process.pid} is running`);

  // Fork workers.
  for (let i = 0; i < numCPUs; i++) {
    cluster.fork();
  }

  cluster.on('exit', (worker, code, signal) => {
    console.log(`worker ${worker.process.pid} died`);
  });
} else {
  // Workers can share any TCP connection
  // In this case it is an HTTP server
  app.listen(3000, () => {
    console.log('Server is running on port 3000');
  });
}
