// Define DynamicNetworkTopologyManager struct
typedef struct {
    NetworkInterfaceConfiguration** interfaces;
    size_t count;
    pthread_mutex_t mutex;
    sem_t semaphore;
} DynamicNetworkTopologyManager;

// Initialize the manager
DynamicNetworkTopologyManager* dntm_init() {
    DynamicNetworkTopologyManager* manager = (DynamicNetworkTopologyManager*)malloc(sizeof(DynamicNetworkTopologyManager));
    if (manager == NULL) return NULL;
    manager->interfaces = NULL;
    manager->count = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    sem_init(&manager->semaphore, 0, 1);
    return manager;
}

// Add a new configuration
void dntm_add_config(DynamicNetworkTopologyManager* manager, NetworkInterfaceConfiguration* config) {
    pthread_mutex_lock(&manager->mutex);
    manager->interfaces = realloc(manager->interfaces, (manager->count + 1) * sizeof(NetworkInterfaceConfiguration*));
    if (manager->interfaces == NULL) {
        pthread_mutex_unlock(&manager->mutex);
        return;
    }
    manager->interfaces[manager->count++] = config;
    sem_post(&manager->semaphore);
    pthread_mutex_unlock(&manager->mutex);
}

// Remove a configuration
void dntm_remove_config(DynamicNetworkTopologyManager* manager, NetworkInterfaceConfiguration* config) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->interfaces[i] == config) {
            free(config);
            memmove(manager->interfaces + i, manager->interfaces + i + 1, (manager->count - i - 1) * sizeof(NetworkInterfaceConfiguration*));
            manager->count--;
            break;
        }
    }
    sem_post(&manager->semaphore);
    pthread_mutex_unlock(&manager->mutex);
}

// Validate IP address
