    // Simple validation logic here
    return strcmp(ip, "0.0.0.0") != 0;
}

// Detect and resolve subnet mask and gateway conflicts
void resolve_conflicts(DynamicNetworkTopologyManager* manager) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->count; ++i) {
        for (size_t j = i + 1; j < manager->count; ++j) {
            // Conflict resolution logic here
        }
    }
    pthread_mutex_unlock(&manager->mutex);
}

// Adjust configurations based on network changes
void adjust_configurations(DynamicNetworkTopologyManager* manager, NetworkInterfaceConfiguration* new_config) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->count; ++i) {
        // Configuration adjustment logic here
    }
    if (new_config != NULL) dntm_add_config(manager, new_config);
    pthread_mutex_unlock(&manager->mutex);
}

// Cleanup the manager
void dntm_cleanup(DynamicNetworkTopologyManager* manager) {
    sem_wait(&manager->semaphore);
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->count; ++i) free(manager->interfaces[i]);
    free(manager->interfaces);
    pthread_mutex_unlock(&manager->mutex);
    sem_destroy(&manager->semaphore);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}
