#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>
#include <bzlib.h>
#include <lzma.h>
#include <zstd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

// Define compression types
typedef enum {
    COMPRESSION_GZIP,
    COMPRESSION_BZ2,
    COMPRESSION_LZMA,
    COMPRESSION_ZSTD
} CompressionType;

// Function prototypes
void* compress_data(CompressionType type, const void* input, size_t input_size, int level);
int decompress_data(CompressionType type, const void* compressed_data, size_t compressed_size, void** output, size_t* output_size);

// Compress data using specified compression type and level
void* compress_data(CompressionType type, const void* input, size_t input_size, int level) {
    void* output;
    size_t output_size = 0;

    switch (type) {
        case COMPRESSION_GZIP:
            // Allocate memory for compressed data
            output = malloc(ZLIB_COMPRESSION_LEVEL_9 * input_size);
            if (!output) return NULL;

            // Compress using gzip
            int ret = compress2((Bytef*)output, &output_size, (const Bytef*)input, input_size, level);
            if (ret != Z_OK) {
                free(output);
                return NULL;
            }

            break;
        case COMPRESSION_BZ2:
            // Allocate memory for compressed data
            output = malloc(BZ2_maxCompressedLength(input_size));
            if (!output) return NULL;

            // Compress using bzip2
            ret = BZ2_bzBuffToBuffCompress((char*)output, &output_size, (char*)input, input_size, level, 0, 0);
            if (ret != BZ_OK) {
                free(output);
                return NULL;
            }

            break;
        case COMPRESSION_LZMA:
            // Allocate memory for compressed data
            output = malloc(lzma_compress_bound(input_size));
            if (!output) return NULL;

            // Compress using LZMA
            lzma_stream strm = LZMA_STREAM_INIT;
            lzma_ret ret = lzma_easy_encoder(&strm, level, LZMA_PRESET_DEFAULT);
            if (ret != LZMA_OK) {
                free(output);
                return NULL;
            }

            strm.next_in = (uint8_t*)input;
            strm.avail_in = input_size;

            while (strm.avail_out > 0 && ret == LZMA_OK) {
                strm.next_out = (uint8_t*)output + output_size - strm.avail_out;
                ret = lzma_code(&strm, LZMA_FINISH);
                if (ret != LZMA_STREAM_END) {
                    free(output);
                    lzma_end(&strm);
                    return NULL;
                }
            }

            output_size = output_size - strm.avail_out;

            lzma_end(&strm);
            break;
        case COMPRESSION_ZSTD:
            // Allocate memory for compressed data
            output = malloc(ZSTD_compressBound(input_size));
            if (!output) return NULL;

            // Compress using Zstandard
            size_t ret = ZSTD_compress(output, output + input_size, input, input_size, level);
            if (ZSTD_isError(ret)) {
                free(output);
                return NULL;
            }

            output_size = ret;

            break;
        default:
            return NULL;
    }

    // Resize the output buffer to actual size
    void* new_output = realloc(output, output_size);
    if (!new_output) {
        free(output);
        return NULL;
    }

    return new_output;
}

// Decompress data using specified compression type
int decompress_data(CompressionType type, const void* compressed_data, size_t compressed_size, void** output, size_t* output_size) {
    switch (type) {
        case COMPRESSION_GZIP:
            // Allocate memory for uncompressed data
            *output = malloc(compressed_size);
            if (!*output) return -1;

            // Decompress using gzip
            z_stream strm;
            strm.zalloc = Z_NULL;
            strm.zfree = Z_NULL;
            strm.opaque = Z_NULL;
            strm.avail_in = compressed_size;
            strm.next_in = (Bytef*)compressed_data;

            if (inflateInit(&strm) != Z_OK) {
                free(*output);
                *output = NULL;
                return -1;
            }

            int ret;
            do {
                strm.avail_out = compressed_size;
                strm.next_out = (Bytef*)(*output + compressed_size - strm.avail_out);
                ret = inflate(&strm, Z_FINISH);
            } while (ret == Z_OK);

            if (ret != Z_STREAM_END) {
                free(*output);
                *output = NULL;
                inflateEnd(&strm);
                return -1;
            }

            *output_size = compressed_size - strm.avail_out;

            inflateEnd(&strm);
            break;
        case COMPRESSION_BZ2:
            // Allocate memory for uncompressed data
            *output = malloc(compressed_size);
            if (!*output) return -1;

            // Decompress using bzip2
            ret = BZ2_bzBuffToBuffDecompress((char*)*output, output_size, (const char*)compressed_data, compressed_size, 0, 0);
            if (ret != BZ_OK) {
                free(*output);
                *output = NULL;
                return -1;
            }

            break;
        case COMPRESSION_LZMA:
            // Allocate memory for uncompressed data
            *output = malloc(compressed_size);
            if (!*output) return -1;

            // Decompress using LZMA
            lzma_stream strm = LZMA_STREAM_INIT;
            lzma_ret ret = lzma_easy_decoder(&strm, LZMA_PRESET_DEFAULT);
            if (ret != LZMA_OK) {
                free(*output);
                *output = NULL;
                return -1;
            }

            strm.next_in = (uint8_t*)compressed_data;
            strm.avail_in = compressed_size;

            while (strm.avail_out > 0 && ret == LZMA_OK) {
                strm.next_out = (uint8_t*)(*output + *output_size - strm.avail_out);
                ret = lzma_code(&strm, LZMA_FINISH);
            }

            if (ret != LZMA_STREAM_END) {
                free(*output);
                *output = NULL;
                lzma_end(&strm);
                return -1;
            }

            *output_size = *output_size - strm.avail_out;

            lzma_end(&strm);
            break;
        case COMPRESSION_ZSTD:
            // Allocate memory for uncompressed data
            *output = malloc(compressed_size);
            if (!*output) return -1;

            // Decompress using Zstandard
            size_t ret = ZSTD_decompress(*output, compressed_size, compressed_data, compressed_size);
            if (ZSTD_isError(ret)) {
                free(*output);
                *output = NULL;
                return -1;
            }

            *output_size = ret;

            break;
        default:
            return -1;
    }

    return 0;
}
