} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} CRC_Indication_Array;

CRC_Indication_Array* create_crc_indication_array(size_t initial_capacity) {
    CRC_Indication_Array *array = (CRC_Indication_Array*)malloc(sizeof(CRC_Indication_Array));
    if (!array) return NULL;

    array->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) {
        free(array);
        return NULL;
    }

    array->size = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

bool add_crc_indication(CRC_Indication_Array *array, NFAPI_CRC_INDICATION_PDU_T indication) {
    if (array == NULL) return false;

    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&array->mutex);
            return false;
        }
        array->array = new_array;
        array->capacity = new_capacity;
    }

    array->array[array->size++] = indication;
    pthread_mutex_unlock(&array->mutex);

    return true;
}

void destroy_crc_indication_array(CRC_Indication_Array *array) {
    if (array == NULL) return;

    pthread_mutex_lock(&array->mutex);
    free(array->array);
    array->array = NULL;
    array->size = 0;
    array->capacity = 0;
    pthread_mutex_unlock(&array->mutex);

    pthread_mutex_destroy(&array->mutex);
    free(array);
}

// Example usage
int main() {
    CRC_Indication_Array *crc_array = create_crc_indication_array(1000);
    if (!crc_array) {
        fprintf(stderr, "Failed to create CRC indication array\n");
        return 1;
    }

    NFAPI_CRC_INDICATION_PDU_T indication = {0};
    indication.ue_id = 123;

    if (add_crc_indication(crc_array, indication)) {
        printf("Indication added successfully\n");
    } else {
        fprintf(stderr, "Failed to add indication\n");
    }

    destroy_crc_indication_array(crc_array);
    return 0;
}
