        // Initialize components
        apiClient = std::make_shared<APIClient>();
        messageBroker = std::make_shared<MessageBroker>();
        cacheManager = std::make_shared<CacheManager>();
        logger = std::make_shared<Logger>();

        // Start threads for different services
        startAPIThread();
        startMessageBrokerThread();
        startCacheThread();

        // Main loop to process incoming data
        while (running) {
            processIncomingData();
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }
    }

    void stop() {
        running = false;
        apiClient->stop();
        messageBroker->stop();
        cacheManager->stop();
    }

private:
    std::shared_ptr<APIClient> apiClient;
    std::shared_ptr<MessageBroker> messageBroker;
    std::shared_ptr<CacheManager> cacheManager;
    std::shared_ptr<Logger> logger;

    bool running = true;

    void startAPIThread() {
        apiThread = std::thread([this]() {
            while (running) {
                fetchAndProcessData();
                std::this_thread::sleep_for(std::chrono::seconds(1));
            }
        });
    }

    void startMessageBrokerThread() {
        messageBrokerThread = std::thread([this]() {
            while (running) {
                processMessages();
                std::this_thread::sleep_for(std::chrono::milliseconds(500));
            }
        });
    }

    void startCacheThread() {
        cacheThread = std::thread([this]() {
            while (running) {
                updateCache();
                std::this_thread::sleep_for(std::chrono::minutes(10));
            }
        });
    }

    void fetchAndProcessData() {
        auto data = apiClient->fetchData();
