// Define WirelessNetworkCRCHandler structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *crcIndications;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    sem_t semaphore;
} WirelessNetworkCRCHandler;

// Initialize the CRC handler
void WirelessNetworkCRCHandler_Init(WirelessNetworkCRCHandler *handler, size_t initialCapacity) {
    handler->crcIndications = malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    handler->capacity = initialCapacity;
    handler->count = 0;
    pthread_mutex_init(&handler->mutex, NULL);
    sem_init(&handler->semaphore, 0, initialCapacity);
}

// Add a CRC indication
void WirelessNetworkCRCHandler_AddCRC(WirelessNetworkCRCHandler *handler, NFAPI_CRC_INDICATION_PDU_T *crc) {
    sem_wait(&handler->semaphore);
    pthread_mutex_lock(&handler->mutex);

    if (handler->count == handler->capacity) {
        // Resize the array
        handler->capacity *= 2;
        handler->crcIndications = realloc(handler->crcIndications, handler->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    handler->crcIndications[handler->count++] = *crc;

    pthread_mutex_unlock(&handler->mutex);
    sem_post(&handler->semaphore);
}

// Process CRC indications
void WirelessNetworkCRCHandler_ProcessCRCs(WirelessNetworkCRCHandler *handler) {
    for (size_t i = 0; i < handler->count; ++i) {
        // Process each CRC indication
        NFAPI_CRC_INDICATION_PDU_T crc = handler->crcIndications[i];
        // Perform processing here
    }

    sem_wait(&handler->semaphore);
    pthread_mutex_lock(&handler->mutex);

    handler->count = 0;

    pthread_mutex_unlock(&handler->mutex);
    sem_post(handler->semaphore);
}

// Clean up the CRC handler
void WirelessNetworkCRCHandler_Cleanup(WirelessNetworkCRCHandler *handler) {
    free(handler->crcIndications);
    pthread_mutex_destroy(&handler->mutex);
    sem_destroy(&handler->semaphore);
}
