    "legacy_service": {"url": "http://localhost:5001", "health": 1.0},
    "new_cloud_service": {"url": "http://localhost:5002", "health": 0.9}
}

# Dummy function to simulate dynamic service discovery
def discover_services():
    return services

@app.route('/gateway', methods=['GET', 'POST', 'PUT', 'DELETE'])
def gateway():
    # Implement real-time service discovery and dynamic configuration updates
    available_services = discover_services()

    # Implement intelligent routing algorithms based on health and user demand patterns
    selected_service = min(available_services.values(), key=lambda x: (-x['health'], len(request.get_json()) if request.method == 'POST' else 0))

    # Forward the request to the selected backend service
    response = requests.request(
        method=request.method,
        url=selected_service['url'] + request.path,
        headers={key: value for key, value in request.headers if key != 'Host'},
        data=request.data,
        json=request.json
    )

    # Handle potential issues with varying network conditions and adaptive strategies
    response.raise_for_status()

    return jsonify(response.json()), response.status_code

# Implement adaptive rate limiting based on observed traffic patterns
@app.before_request
def limit_requests():
    if request.method == 'GET':
        key = request.remote_addr
        if not rate_limit.check(key):
            return jsonify({"error": "Rate limit exceeded"}), 429

# Handle automatic failover and graceful degradation for backend services
@app.errorhandler(requests.exceptions.RequestException)
def handle_request_exception(e):
    # Log the error and attempt to use a fallback service
    return jsonify({"error": "Service unavailable, using fallback"}), 503

# Provide comprehensive metrics and logging for each request
@app.after_request
def log_request(response):
    app.logger.info(f"Request: {request.method} {request.path} - Response: {response.status_code}")
    return response

if __name__ == '__main__':
    app.run(debug=True)
