class PaymentProcessor:
    def __init__(self, gateways):
        self.gateways = gateways

    def process_payment(self, payment_details):
        for gateway in self.gateways:
            if gateway.supports(payment_details.method, payment_details.currency, payment_details.region):
                return gateway.process(payment_details)
        raise Exception("Unsupported payment method, currency, or region")

# Define the PaymentGateway abstract base class
from abc import ABC, abstractmethod

class PaymentGateway(ABC):
    @abstractmethod
    def supports(self, method, currency, region):
        pass

    @abstractmethod
    def process(self, payment_details):
        pass

# Implement specific payment gateways
class StripeGateway(PaymentGateway):
    def supports(self, method, currency, region):
        return method == "credit_card" and currency in ["USD", "EUR"] and region == "US"

    def process(self, payment_details):
        # Simulate processing with Stripe API
        return f"Processed {payment_details.amount} {payment_details.currency} via credit card"

class PayPalGateway(PaymentGateway):
    def supports(self, method, currency, region):
        return method == "paypal" and currency in ["USD"] and region == "US"

    def process(self, payment_details):
        # Simulate processing with PayPal API
        return f"Processed {payment_details.amount} {payment_details.currency} via PayPal"

# Define the PaymentDetails class
class PaymentDetails:
    def __init__(self, amount, method, currency, region):
        self.amount = amount
        self.method = method
        self.currency = currency
        self.region = region

# Example usage
