#include <atomic>
#include <functional>
#include <chrono>
#include <mutex>
#include <condition_variable>

class Event {
public:
    virtual void handle() = 0;
};

class NetworkEvent : public Event {
public:
    void handle() override {
        // Handle network event logic
    }
};

class RealTimeNetworkHandler {
public:
    RealTimeNetworkHandler(size_t maxEvents) : maxEvents(maxEvents), currentEvents(0), running(true) {
        worker = std::thread(&RealTimeNetworkHandler::processEvents, this);
    }

    ~RealTimeNetworkHandler() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            running = false;
        }
        cv.notify_all();
        if (worker.joinable()) {
            worker.join();
        }
    }

    void addEvent(std::shared_ptr<Event> event) {
        std::unique_lock<std::mutex> lock(mutex);
        if (currentEvents < maxEvents) {
            events.push_back(event);
            currentEvents++;
            cv.notify_one();
        } else {
            // Handle overflow
            std::cerr << "Event overflow!" << std::endl;
        }
    }

private:
    void processEvents() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            cv.wait(lock, [this] { return !events.empty() || !running; });
            if (!running && events.empty()) {
                break;
            }
            auto event = events.front();
            events.pop_front();
            currentEvents--;
            lock.unlock();
            event->handle();
        }
    }

    size_t maxEvents;
    std::atomic<size_t> currentEvents;
    std::vector<std::shared_ptr<Event>> events;
    std::thread worker;
    std::mutex mutex;
    std::condition_variable cv;
    bool running;
};

int main() {
    RealTimeNetworkHandler handler(20000);
    for (size_t i = 0; i < 25000; ++i) {
        auto event = std::make_shared<NetworkEvent>();
        handler.addEvent(event);
    }
    return 0;
}
