using Newtonsoft.Json;

public class DynamicResourceManager
{
    private readonly HttpClient _httpClient;
    private readonly IDistributedCache _cache;
    private readonly ConcurrentDictionary<string, CancellationTokenSource> _cancellationTokens;

    public DynamicResourceManager(HttpClient httpClient, IDistributedCache cache)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _cache = cache ?? throw new ArgumentNullException(nameof(cache));
        _cancellationTokens = new ConcurrentDictionary<string, CancellationTokenSource>();
    }

    public async Task<T> LoadResourceAsync<T>(string key, string serviceUrl, CancellationToken cancellationToken = default)
    {
        if (string.IsNullOrEmpty(key) || string.IsNullOrEmpty(serviceUrl))
            throw new ArgumentException("Key and Service URL must be provided.");

        var cacheEntryOptions = new DistributedCacheEntryOptions
        {
            AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(10),
            SlidingExpirationRelativeToNow = TimeSpan.FromMinutes(5)
        };

        if (_cache.TryGetValue(key, out byte[] cachedData))
        {
            return JsonConvert.DeserializeObject<T>(Encoding.UTF8.GetString(cachedData));
        }

        var requestMessage = new HttpRequestMessage(HttpMethod.Get, serviceUrl);
        requestMessage.Headers.Add("Authorization", $"Bearer {await GetAccessTokenAsync()}");

        using (var response = await _httpClient.SendAsync(requestMessage, HttpCompletionOption.ResponseHeadersRead, cancellationToken))
        {
            response.EnsureSuccessStatusCode();
            var data = await response.Content.ReadAsStringAsync();

            _cache.Set(key, Encoding.UTF8.GetBytes(data), cacheEntryOptions);

            return JsonConvert.DeserializeObject<T>(data);
        }
    }

    private async Task<string> GetAccessTokenAsync()
    {
        // Implement OAuth 2.0 token retrieval with MFA
        // Return the access token
    }

    public void InvalidateCache(string key)
    {
        _cache.Remove(key);
    }
}
