#include <mutex>
#include <condition_variable>
#include <queue>
#include <future>
#include <chrono>

class RealTimeNetworkHandler {
public:
    RealTimeNetworkHandler(size_t maxEventsPerSecond);
    ~RealTimeNetworkHandler();

    void AddEvent(const std::function<void()>& event);

private:
    static const size_t MAX_EVENTS_PER_SECOND = 50000;
    const size_t maxEventsPerSecond;
    std::atomic<size_t> currentEventsProcessed;

    struct Event {
        std::future<void> future;
        std::function<void()> func;
    };

    std::queue<Event> eventQueue;
    std::vector<std::thread> workerThreads;
    std::mutex queueMutex;
    std::condition_variable queueCondition;

    void WorkerThread();
};
```

```cpp
// RealTimeNetworkHandler.cpp
#include "RealTimeNetworkHandler.h"

RealTimeNetworkHandler::RealTimeNetworkHandler(size_t maxEventsPerSecond)
    : maxEventsPerSecond(maxEventsPerSecond), currentEventsProcessed(0) {
    for (size_t i = 0; i < std::thread::hardware_concurrency(); ++i) {
        workerThreads.emplace_back(&RealTimeNetworkHandler::WorkerThread, this);
    }
}

RealTimeNetworkHandler::~RealTimeNetworkHandler() {
    {
        std::unique_lock<std::mutex> lock(queueMutex);
        eventQueue.push({std::future<void>(), []{}});
    }
    queueCondition.notify_all();
    for (auto& thread : workerThreads) {
        if (thread.joinable()) {
            thread.join();
        }
    }
}

void RealTimeNetworkHandler::AddEvent(const std::function<void()>& event) {
    {
        std::unique_lock<std::mutex> lock(queueMutex);
        while (currentEventsProcessed >= maxEventsPerSecond) {
            queueCondition.wait(lock);
        }
        currentEventsProcessed++;
        eventQueue.push({std::async(std::launch::deferred, event), event});
    }
    queueCondition.notify_one();
}

void RealTimeNetworkHandler::WorkerThread() {
    while (true) {
        Event event;
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            queueCondition.wait(lock, [this]{ return !eventQueue.empty(); });
            event = eventQueue.front();
            eventQueue.pop();
        }
        try {
            if (event.func) {
                event.future.get();
            }
        } catch (...) {
            // Handle exceptions without stopping the worker thread
        }
        --currentEventsProcessed;
    }
}
