using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading.Tasks;
using StackExchange.Redis;

namespace RealTimeDataGenerator
{
    public class TenantConfig
    {
        public string ApiUrl { get; set; }
        public int CacheTtl { get; set; } // Time to live for cache entries in seconds
    }

    public interface IDataGenerator
    {
        Task<object> GenerateAsync(string dataType);
    }

    public class RealTimeDataGenerator
    {
        private readonly ConnectionMultiplexer _redis;
        private readonly ConcurrentDictionary<string, TenantConfig> _tenantConfigs;
        private readonly HttpClient _httpClient;

        public RealTimeDataGenerator(ConnectionMultiplexer redis)
        {
            _redis = redis;
            _tenantConfigs = new ConcurrentDictionary<string, TenantConfig>();
            _httpClient = new HttpClient();
        }

        public void AddTenantConfig(string tenantId, TenantConfig config)
        {
            _tenantConfigs.TryAdd(tenantId, config);
        }

        public async Task<IDataGenerator> GetDataGeneratorAsync(string tenantId, string dataType)
        {
            var config = _tenantConfigs[tenantId];
            var cacheKey = $"{tenantId}:{dataType}";

            var cacheClient = _redis.GetDatabase();
            var cachedValue = await cacheClient.StringGetAsync(cacheKey);

            if (cachedValue.IsNullOrEmpty)
            {
                var response = await _httpClient.GetAsync(config.ApiUrl);
                if (response.IsSuccessStatusCode)
                {
                    var dataGeneratorType = response.Content.ReadAsAsync<Type>().Result;
                    await cacheClient.StringSetAsync(cacheKey, dataType, config.CacheTtl);
                    return Activator.CreateInstance(dataGeneratorType) as IDataGenerator;
                }
            }

            // Fallback to a default generator
            return new DefaultDataGenerator();
        }
    }

    public class DefaultDataGenerator : IDataGenerator
    {
        public async Task<object> GenerateAsync(string dataType)
        {
            switch (dataType.ToLower())
            {
                case "int":
                    return Random.Shared.Next();
                case "string":
                    return Guid.NewGuid().ToString();
                default:
                    throw new ArgumentException("Unsupported data type");
            }
        }
    }
}
