#define MAX_TOKENS 1000

sem_t token_semaphore;

void* allocate_token(void* arg) {
    sem_wait(&token_semaphore);
    // Allocate a new token
    printf("Token allocated\n");
    sleep(1); // Simulate token allocation time
    sem_post(&token_semaphore);
    return NULL;
}

int main() {
    sem_init(&token_semaphore, 0, MAX_TOKENS);

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, allocate_token, NULL);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    sem_destroy(&token_semaphore);

    return 0;
}
