void convert_images_to_pdf(const char* input_dir, const char* output_pdf, int tool_index) {
    DIR *dir;
    struct dirent *ent;

    if ((dir = opendir(input_dir)) != NULL) {
        while ((ent = readdir(dir)) != NULL) {
            if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0) continue;
            char input_file[256];
            snprintf(input_file, sizeof(input_file), "%s/%s", input_dir, ent->d_name);
            run_conversion_tool(tool_index, input_file, output_pdf);
        }
        closedir(dir);
    } else {
        perror("opendir");
        exit(EXIT_FAILURE);
    }
}

