#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <curl/curl.h>

#define TOKEN_CACHE_SIZE 100

typedef struct {
    char access_token[256];
    time_t expires_at;
} TokenCacheItem;

TokenCacheItem token_cache[TOKEN_CACHE_SIZE];
int cache_count = 0;
pthread_mutex_t cache_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to validate OAuth2 access token
int validate_oauth_token(const char *json_string) {
    // Parse JSON string for required fields
    // Check for presence and correctness of access_token, expires_in, token_type

    // Extract necessary information from JSON string
    char *access_token = extract_access_token(json_string);
    time_t expires_in = extract_expires_in(json_string);
    const char *token_type = "Bearer"; // Expected value

    if (strcmp(token_type, extract_token_type(json_string)) != 0) {
        return -1; // Invalid token type
    }

    if (expires_in <= 0) {
        return -2; // Invalid expires_in value
    }

    // Check cache for existing valid token
    pthread_mutex_lock(&cache_mutex);
    for (int i = 0; i < cache_count; i++) {
        if (strcmp(token_cache[i].access_token, access_token) == 0 && time(NULL) < token_cache[i].expires_at) {
            pthread_mutex_unlock(&cache_mutex);
            return 1; // Token is valid and cached
        }
    }

    // If not in cache, validate with external service
    CURL *curl;
    CURLcode res;
    struct MemoryStruct chunk = {0};

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, "https://auth.example.com/validate");
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, access_token);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)&chunk);

        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            // Parse response to confirm token validity
            if(strstr(chunk.memory, "\"valid\":true") != NULL) {
                // Store in cache
                store_in_cache(access_token, expires_in);
                return 1; // Token is valid and cached
            }
        }

        free(chunk.memory);  // Free the memory allocated for response data
    }
    curl_easy_cleanup(curl);
    curl_global_cleanup();

    pthread_mutex_unlock(&cache_mutex);
    return -3; // Token validation failed
}

// Function to store token in cache
void store_in_cache(const char *access_token, time_t expires_in) {
    if (cache_count < TOKEN_CACHE_SIZE) {
        strncpy(token_cache[cache_count].access_token, access_token, 256);
        token_cache[cache_count].expires_at = time(NULL) + expires_in;
        cache_count++;
    }
}

// Function to handle memory allocation and write callback for libcurl
size_t WriteMemoryCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    struct MemoryStruct *mem = (struct MemoryStruct *)userp;

    char *ptr = realloc(mem->memory, mem->size + realsize + 1);
    if(ptr == NULL) {
        // out of memory!
        printf("not enough memory (realloc returned NULL)\n");
        return 0;
    }

    mem->memory = ptr;
    memcpy(&(mem->memory[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->memory[mem->size] = 0;

    return realsize;
}

// Example usage
int main() {
    const char *json_token_response = "{\"access_token\":\"abc123\",\"expires_in\":3600,\"token_type\":\"Bearer\"}";
    int result = validate_oauth_token(json_token_response);
    if(result == 1) {
        printf("Token is valid.\n");
    } else {
        printf("Token validation failed: %d\n", result);
    }
    return 0;
}
