#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_UE_CONNECTIONS 10000

typedef struct {
    int id;
    float snr;
    int connection_state;
} UEConnection;

typedef struct {
    UEConnection connections[MAX_UE_CONNECTIONS];
    pthread_mutex_t mutex;
    sem_t available_slots;
} UELibrary;

UELibrary* init_uelib() {
    UELibrary* lib = (UELibrary*)malloc(sizeof(UELibrary));
    if (!lib) return NULL;

    pthread_mutex_init(&lib->mutex, NULL);
    sem_init(&lib->available_slots, 0, MAX_UE_CONNECTIONS);

    for (int i = 0; i < MAX_UE_CONNECTIONS; i++) {
        lib->connections[i].id = -1;
    }

    return lib;
}

void add_ue_connection(UELibrary* lib, int id, float snr) {
    sem_wait(&lib->available_slots);
    pthread_mutex_lock(&lib->mutex);

    for (int i = 0; i < MAX_UE_CONNECTIONS; i++) {
        if (lib->connections[i].id == -1) {
            lib->connections[i].id = id;
            lib->connections[i].snr = snr;
            lib->connections[i].connection_state = 1; // Connected
            break;
        }
    }

    pthread_mutex_unlock(&lib->mutex);
}

void update_ue_connection(UELibrary* lib, int id, float new_snr) {
    pthread_mutex_lock(&lib->mutex);

    for (int i = 0; i < MAX_UE_CONNECTIONS; i++) {
        if (lib->connections[i].id == id) {
            lib->connections[i].snr = new_snr;
            break;
        }
    }

    pthread_mutex_unlock(&lib->mutex);
}

void remove_ue_connection(UELibrary* lib, int id) {
    pthread_mutex_lock(&lib->mutex);

    for (int i = 0; i < MAX_UE_CONNECTIONS; i++) {
        if (lib->connections[i].id == id) {
            lib->connections[i].id = -1;
            sem_post(&lib->available_slots);
            break;
        }
    }

    pthread_mutex_unlock(&lib->mutex);
}

int get_connection_state(UELibrary* lib, int id) {
    pthread_mutex_lock(&lib->mutex);

    for (int i = 0; i < MAX_UE_CONNECTIONS; i++) {
        if (lib->connections[i].id == id) {
            return lib->connections[i].connection_state;
        }
    }

    pthread_mutex_unlock(&lib->mutex);
    return -1; // Connection not found
}

void destroy_uelib(UELibrary* lib) {
    pthread_mutex_destroy(&lib->mutex);
    sem_destroy(&lib->available_slots);
    free(lib);
}
