// Include necessary headers
#include <iostream>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <future>
#include <chrono>

// Define a simple cache interface
class ICache {
public:
    virtual ~ICache() = default;
    virtual void set(const std::string& key, const std::string& value) = 0;
    virtual std::string get(const std::string& key) = 0;
};

// Implement a concurrent hash map based cache with LRU eviction
class LRUCache : public ICache {
private:
    struct Node {
        std::string key;
        std::string value;
        Node* prev;
        Node* next;
        Node(const std::string& k, const std::string& v) : key(k), value(v), prev(nullptr), next(nullptr) {}
    };

    std::unordered_map<std::string, Node*> cache;
    Node* head;
    Node* tail;
    size_t capacity;
    std::mutex mutex;
    std::condition_variable cv;

public:
    LRUCache(size_t cap) : capacity(cap), head(new Node("", "")), tail(new Node("", "")) {
        head->next = tail;
        tail->prev = head;
    }

    ~LRUCache() {
        for (auto it = cache.begin(); it != cache.end(); ++it) {
            delete it->second;
        }
        delete head;
        delete tail;
    }

    void set(const std::string& key, const std::string& value) override {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = cache.find(key);
        if (it != cache.end()) {
            // Move node to the front
            it->second->value = value;
            moveNodeToFront(it->second);
            return;
        }
        if (cache.size() >= capacity) {
            evictLeastRecentlyUsed();
        }
        auto newNode = new Node(key, value);
        addToFront(newNode);
        cache[key] = newNode;
    }

    std::string get(const std::string& key) override {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = cache.find(key);
        if (it == cache.end()) return "";
        // Move node to the front
        moveNodeToFront(it->second);
        return it->second->value;
    }

private:
    void addToFront(Node* node) {
        node->prev = head;
        node->next = head->next;
        head->next->prev = node;
        head->next = node;
    }

    void moveNodeToFront(Node* node) {
        node->prev->next = node->next;
        node->next->prev = node->prev;
        addToFront(node);
    }

    void evictLeastRecentlyUsed() {
        Node* lru = tail->prev;
        cache.erase(lru->key);
        delete lru;
        tail->prev = tail->prev->prev;
        tail->prev->next = tail;
    }
};

