#include <cpprest/http_listener.h>
using namespace web::http;

class CacheService {
private:
    LRUCache cache;
    http_listener listener;

public:
    CacheService(size_t capacity) : cache(capacity), listener(U("http://localhost:8080")) {
        listener.support(methods::POST, [this](http_request request) { handleSet(request); });
        listener.support(methods::GET, [this](http_request request) { handleGet(request); });
    }

    void start() {
        listener.open().wait();
        std::cout << "Cache service started at http://localhost:8080" << std::endl;
        listener.wait();
    }

private:
    void handleSet(http_request request) {
        // Parse the request and set the cache
        request.extract_jsonAsync([this](json::value jvalue, web::http::status_code status, const web::web_exception& e) {
            if (e.has_value()) {
                return;
            }
            std::string key = jvalue[U("key")].as_string();
            std::string value = jvalue[U("value")].as_string();
            cache.set(key, value);
            request.reply(status_codes::OK);
        }).get();
    }

    void handleGet(http_request request) {
        // Parse the request and get the cache
        request.extract_uri().then([this](uri uri) {
            std::string key = uri.query()[U("key")].to_string();
            std::string value = cache.get(key);
            http_response response(status_codes::OK);
            response.set_body(json::value::object({{U("value"), json::value::string(value)}}));
            request.reply(response);
        }).get();
    }
};

int main() {
    CacheService service(1000); // 1000 capacity
    service.start();
    return 0;
}
