// Node.js microservice setup

const express = require('express');
const axios = require('axios');
const { Pool } = require('pg');
const jwt = require('jsonwebtoken');
const { CircuitBreaker } = require('opossum');
const bcrypt = require('bcryptjs');

const app = express();
app.use(express.json());

// Database connection pool
const dbPool = new Pool({
  user: 'yourdbuser',
  host: 'localhost',
  database: 'configstore',
  password: 'yourdbpassword',
  port: 5432,
});

// API client circuit breaker
const apiClientBreaker = new CircuitBreaker(axios, {
  timeout: 1000, // 1 second
  errorThresholdPercentage: 50, // 50% failure rate before opening the circuit
  resetTimeout: 30000, // 30 seconds
});

// Authentication middleware
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];
  if (token == null) return res.sendStatus(401);

  jwt.verify(token, 'your_jwt_secret', (err, user) => {
    if (err) return res.sendStatus(403);
    req.user = user;
    next();
  });
}

// Configuration endpoints
app.post('/config', authenticateToken, async (req, res) => {
  try {
    const { environment, key, value } = req.body;
    await dbPool.query('INSERT INTO config (environment, key, value) VALUES ($1, $2, $3)', [environment, key, value]);
    res.status(201).send({ message: 'Configuration updated successfully' });
  } catch (error) {
    res.status(500).send({ error: 'Failed to update configuration' });
  }
});

app.get('/config', authenticateToken, async (req, res) => {
  try {
    const { environment } = req.query;
    const result = await dbPool.query('SELECT * FROM config WHERE environment = $1', [environment]);
    res.send(result.rows);
  } catch (error) {
    res.status(500).send({ error: 'Failed to fetch configurations' });
  }
});

// API integration
async function fetchConfigFromAPI(environment) {
  const response = await apiClientBreaker.request(`https://api.example.com/config/${environment}`, { method: 'GET' });
  return response.data;
}

app.get('/api-config', authenticateToken, async (req, res) => {
  try {
    const environment = req.query.environment;
    const config = await fetchConfigFromAPI(environment);
    res.send(config);
  } catch (error) {
    res.status(500).send({ error: 'Failed to fetch API configuration' });
  }
});

// Rate limiting middleware
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 1 * 60 * 1000, // 1 minute
  max: 100, // limit each IP to 100 requests per windowMs
});

app.use('/config', limiter);
app.use('/api-config', limiter);

// Error handling
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).send('Something broke!');
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
```

