// Include necessary headers
#include <iostream>
#include <thread>
#include <mutex>
#include <unordered_map>
#include <vector>
#include <atomic>
#include <zlib.h>

// Define a simple key-value pair structure
struct KeyValuePair {
    std::string key;
    std::string value;
};

// Define the distributed cache class
class DistributedCache {
public:
    // Constructor to initialize the cache and external store
    DistributedCache() {}

    // Function to add or update a key-value pair in the cache
    void set(const std::string& key, const std::string& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = cache_.find(key);
        if (it != cache_.end()) {
            it->second.value = compress(value);
        } else {
            cache_[key] = KeyValuePair{key, compress(value)};
        }
    }

    // Function to retrieve a value from the cache
    std::string get(const std::string& key) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = cache_.find(key);
        if (it != cache_.end()) {
            return decompress(it->second.value);
        }
        return "";
    }

private:
    // Mutex for thread-safe operations
    std::mutex mutex_;

    // In-memory cache storage
    std::unordered_map<std::string, KeyValuePair> cache_;

    // Function to compress a string using zlib
    std::string compress(const std::string& value) {
        z_stream stream;
        stream.zalloc = Z_NULL;
        stream.zfree = Z_NULL;
        stream.opaque = Z_NULL;
        deflateInit(&stream, Z_DEFAULT_COMPRESSION);
        stream.next_in = (Bytef*)value.c_str();
        stream.avail_in = value.size();
        std::vector<Byte> output(value.size() + 12);
        stream.next_out = output.data();
        stream.avail_out = output.size();
        deflate(&stream, Z_FINISH);
        deflateEnd(&stream);
        return std::string(output.begin(), output.end() - stream.avail_out);
    }

    // Function to decompress a string using zlib
    std::string decompress(const std::string& value) {
        z_stream stream;
        stream.zalloc = Z_NULL;
        stream.zfree = Z_NULL;
        stream.opaque = Z_NULL;
        inflateInit(&stream);
        stream.next_in = (Bytef*)value.c_str();
        stream.avail_in = value.size();
        std::vector<Byte> output(value.size() * 10); // Increase size for decompression
        stream.next_out = output.data();
        stream.avail_out = output.size();
        inflate(&stream, Z_FINISH);
        inflateEnd(&stream);
        return std::string(output.begin(), output.end() - stream.avail_out);
    }
};

// Function to simulate concurrent read and write operations
void simulateOperations(DistributedCache& cache) {
    for (int i = 0; i < 10000; ++i) {
        cache.set("key" + std::to_string(i), "value" + std::to_string(i));
        std::string result = cache.get("key" + std::to_string(i % 100));
    }
}

int main() {
    DistributedCache cache;
    std::vector<std::thread> threads;
    for (int i = 0; i < 10; ++i) {
        threads.emplace_back(simulateOperations, std::ref(cache));
    }
    for (auto& thread : threads) {
        thread.join();
    }
    return 0;
}
