#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a structure for configuration settings
typedef struct {
    int id;
    char value[256];
} Config;

// Mutex for thread-safe access to the configuration data
pthread_mutex_t config_lock = PTHREAD_MUTEX_INITIALIZER;

// Array to store configuration settings
Config *config_data = NULL;
int config_count = 0;

// Function to add or update a configuration setting
void set_config(int id, char *value) {
    pthread_mutex_lock(&config_lock);

    // Check if the configuration already exists
    for (int i = 0; i < config_count; i++) {
        if (config_data[i].id == id) {
            strcpy(config_data[i].value, value);
            pthread_mutex_unlock(&config_lock);
            return;
        }
    }

    // If it doesn't exist, add a new configuration
    Config new_config = {id, value};
    config_data = realloc(config_data, (config_count + 1) * sizeof(Config));
    config_data[config_count++] = new_config;

    pthread_mutex_unlock(&config_lock);
}

// Function to get a configuration setting
char* get_config(int id) {
    pthread_mutex_lock(&config_lock);

    for (int i = 0; i < config_count; i++) {
        if (config_data[i].id == id) {
            char *value = malloc(strlen(config_data[i].value) + 1);
            strcpy(value, config_data[i].value);
            pthread_mutex_unlock(&config_lock);
            return value;
        }
    }

    pthread_mutex_unlock(&config_lock);
    return NULL;
}

// Function to initialize the configuration data
void init_config() {
    config_data = malloc(sizeof(Config));
    config_count = 0;
}

// Function to clean up the configuration data
void cleanup_config() {
    free(config_data);
}
