struct USER_CONNECTION_RECORD {
    std::string ip_address;
    std::string session_id;
    std::chrono::system_clock::time_point timestamp;
    std::string geolocation_data;
};

class ConnectionPool {
public:
    void addRecord(const USER_CONNECTION_RECORD& record);
    USER_CONNECTION_RECORD getRecord();
private:
    std::vector<USER_CONNECTION_RECORD> pool;
    std::mutex pool_mutex;
    std::condition_variable pool_cv;
};

void ConnectionPool::addRecord(const USER_CONNECTION_RECORD& record) {
    std::lock_guard<std::mutex> lock(pool_mutex);
    pool.push_back(record);
    pool_cv.notify_one();
}

USER_CONNECTION_RECORD ConnectionPool::getRecord() {
    std::unique_lock<std::mutex> lock(pool_mutex);
    while (pool.empty()) {
        pool_cv.wait(lock);
    }
    USER_CONNECTION_RECORD record = pool.back();
    pool.pop_back();
    return record;
}
