#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define PORT 8080
#define MAX_WORKERS 100

// Worker thread function to process data batches
void* worker_thread(void* arg) {
    int batch_id = *(int*)arg;
    // Process the data batch for the given ID
    printf("Processing data batch %d\n", batch_id);
    free(arg); // Free allocated memory
    pthread_exit(NULL);
}

int main() {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    int worker_ids[MAX_WORKERS];
    pthread_t workers[MAX_WORKERS];

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Forcefully attaching socket to the port 8080
    if (bind(server_fd, (struct sockaddr *)&address,
              sizeof(address)) < 0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }
    if (listen(server_fd, MAX_WORKERS) < 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    int i = 0;
    while (1) {
        if ((new_socket = accept(server_fd,
                                 (struct sockaddr *)&address,
                                 (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            continue;
        }

        worker_ids[i] = i; // Assign a unique ID to the data batch
        pthread_create(&workers[i], NULL, worker_thread, &worker_ids[i]);
        i++;
    }

    for (int j = 0; j < i; j++) {
        pthread_join(workers[j], NULL);
    }

    close(server_fd);
    return 0;
}
