import java.io.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ConcurrentHashMap;

public class DeserializationService<T> {
    private final ConcurrentHashMap<String, T> cache = new ConcurrentHashMap<>();
    private final ClassLoader classLoader;

    public DeserializationService(ClassLoader classLoader) {
        this.classLoader = classLoader != null ? classLoader : getClass().getClassLoader();
    }

    public T deserialize(byte[] data, Class<T> clazz) throws CustomDeserializationException {
        try {
            String key = generateChecksum(data);
            if (cache.containsKey(key)) {
                return cache.get(key);
            }

            T instance = loadAndDeserialize(clazz, data);
            cache.putIfAbsent(key, instance);
            return instance;
        } catch (IOException | ClassNotFoundException e) {
            throw new CustomDeserializationException("Failed to deserialize data", e);
        }
    }

    private String generateChecksum(byte[] data) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] hash = digest.digest(data);
        return bytesToHex(hash);
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    @SuppressWarnings("unchecked")
    private T loadAndDeserialize(Class<T> clazz, byte[] data) throws IOException, ClassNotFoundException {
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(data))) {
            Class<?> loadedClass = classLoader.loadClass(clazz.getName());
            if (!loadedClass.isAssignableFrom(clazz)) {
                throw new CustomDeserializationException("Loaded class is not assignable from the specified class");
            }
            return (T) ois.readObject();
        } catch (ClassNotFoundException e) {
            // Fallback to default instance
            try {
                return clazz.getDeclaredConstructor().newInstance();
            } catch (NoSuchMethodException | InstantiationException | IllegalAccessException | InvocationTargetException ex) {
                throw new CustomDeserializationException("Failed to load and instantiate class", ex);
            }
        }
    }

    public static class CustomDeserializationException extends Exception {
        public CustomDeserializationException(String message, Throwable cause) {
            super(message, cause);
        }
    }
}
```

