#include <iostream>
#include <thread>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <vector>

struct MESSAGE_T {
    int id;
    std::string content;
};

class DistributedQueue {
private:
    std::queue<MESSAGE_T> queue;
    std::mutex mutex;
    std::condition_variable cv;
    bool stop;

public:
    DistributedQueue() : stop(false) {}

    void push(const MESSAGE_T& message) {
        std::unique_lock<std::mutex> lock(mutex);
        queue.push(message);
        cv.notify_one();
    }

    MESSAGE_T pop() {
        std::unique_lock<std::mutex> lock(mutex);
        while (queue.empty() && !stop) {
            cv.wait(lock);
        }
        if (queue.empty()) {
            throw std::runtime_error("Queue is empty and stopping");
        }
        MESSAGE_T message = queue.front();
        queue.pop();
        return message;
    }

    void stopProcessing() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stop = true;
        }
        cv.notify_all();
    }
};

class WorkerThread {
private:
    DistributedQueue& queue;
    int id;

public:
    WorkerThread(DistributedQueue& q, int i) : queue(q), id(i) {}

    void operator()() {
        while (true) {
            try {
                MESSAGE_T message = queue.pop();
                processMessage(message);
            } catch (const std::runtime_error& e) {
                if (e.what() == "Queue is empty and stopping") break;
                std::cerr << "Worker " << id << " error: " << e.what() << std::endl;
            }
        }
    }

private:
    void processMessage(const MESSAGE_T& message) {
        // Simulate processing time
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
        std::cout << "Worker " << id << " processed message " << message.id << std::endl;
    }
};

int main() {
    const int numWorkers = 10;
    DistributedQueue queue;

    // Start worker threads
    std::vector<std::thread> workers;
    for (int i = 0; i < numWorkers; ++i) {
        workers.emplace_back(WorkerThread(queue, i));
    }

    // Simulate pushing messages to the queue
    for (int i = 1; i <= 1000000; ++i) {
        MESSAGE_T message{i, "Message " + std::to_string(i)};
        queue.push(message);
    }

    // Stop workers
    queue.stopProcessing();
    for (auto& worker : workers) {
        worker.join();
    }

    return 0;
}
