#define MAX_CONNECTIONS 1024
#define RETRY_DELAY 500

typedef struct {
    SSL_CTX *ctx;
    CURL *curl_handle;
    pthread_mutex_t lock;
} TLSClient;

TLSClient* tls_client_init(const char *ca_file, const char *cert_file, const char *key_file) {
    TLSClient *client = (TLSClient*) malloc(sizeof(TLSClient));
    client->ctx = SSL_CTX_new(TLSv1_2_method());
    SSL_CTX_load_verify_locations(client->ctx, ca_file, NULL);
    SSL_CTX_use_certificate_file(client->ctx, cert_file, SSL_FILETYPE_PEM);
    SSL_CTX_use_PrivateKey_file(client->ctx, key_file, SSL_FILETYPE_PEM);
    pthread_mutex_init(&client->lock, NULL);
    client->curl_handle = curl_easy_init();
    return client;
}

void tls_client_cleanup(TLSClient *client) {
    SSL_CTX_free(client->ctx);
    curl_easy_cleanup(client->curl_handle);
    pthread_mutex_destroy(&client->lock);
    free(client);
}

int tls_client_connect(TLSClient *client, const char *host, int port) {
    pthread_mutex_lock(&client->lock);
    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Accept: application/json");
    curl_easy_setopt(client->curl_handle, CURLOPT_URL, host);
    curl_easy_setopt(client->curl_handle, CURLOPT_PORT, (long)port);
    curl_easy_setopt(client->curl_handle, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(client->curl_handle, CURLOPT_SSL_CTX_DATA, client->ctx);
    CURLcode res = curl_easy_perform(client->curl_handle);
    pthread_mutex_unlock(&client->lock);
    return (res == CURLE_OK) ? 0 : -1;
}

void tls_client_reconnect(TLSClient *client, int delay) {
    sleep(delay / 1000);
    tls_client_connect(client, "example.com", 443);
}
