class GameAttackManager {
private:
    std::unordered_map<std::string, int> attackCooldowns;
    std::mutex cooldownMutex;
    std::condition_variable cooldownCondVar;
    int defaultCooldown = 10; // Default cooldown in milliseconds
    std::mt19937 rng;

public:
    GameAttackManager() : rng(std::random_device{}()) {}

    void setSeed(unsigned seed) {
        rng.seed(seed);
    }

    const char* getAttack(const std::string& attackType, int networkHealth, int serverLoad, int playerBehavior) {
        std::unique_lock<std::mutex> lock(cooldownMutex);
        while (attackCooldowns.find(attackType) != attackCooldowns.end() && 
               attackCooldowns[attackType] > 0) {
            cooldownCondVar.wait(lock);
        }
        // Update cooldown based on real-time data
        int newCooldown = defaultCooldown;
        if (networkHealth < 50) newCooldown *= 2;
        if (serverLoad > 80) newCooldown *= 1.5;
        if (playerBehavior < 30) newCooldown *= 1.2;
        attackCooldowns[attackType] = newCooldown;

        // Simulate attack selection
        return "Selected Attack";
    }

    void decrementCooldowns() {
        std::unique_lock<std::mutex> lock(cooldownMutex);
        for (auto& pair : attackCooldowns) {
            if (pair.second > 0) {
                pair.second--;
            }
        }
        cooldownCondVar.notify_all();
    }

    const char* ensureSlash(const std::string& input, size_t limit) {
        if (input.length() < limit) {
            return (new std::string(input + "/")).c_str();
        } else {
            return nullptr;
        }
    }
};

int main() {
    GameAttackManager manager;
    manager.setSeed(42);
    const char* attack = manager.getAttack("Fireball", 60, 75, 80);
    std::cout << "Selected Attack: " << attack << std::endl;
    return 0;
}
