#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct DoublyLinkedList {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
    sem_t read_semaphore;
    sem_t write_semaphore;
} DoublyLinkedList;

void init_list(DoublyLinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    sem_init(&list->read_semaphore, 0, 1);
    sem_init(&list->write_semaphore, 0, 1);
}

void destroy_list(DoublyLinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    sem_destroy(&list->read_semaphore);
    sem_destroy(&list->write_semaphore);
}

void insert(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    new_node->data = data;
    new_node->prev = list->tail;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    sem_wait(&list->write_semaphore);

    if (list->head == NULL) {
        list->head = new_node;
    } else {
        list->tail->next = new_node;
    }
    list->tail = new_node;

    sem_post(&list->read_semaphore);
    pthread_mutex_unlock(&list->lock);
}

void delete(DoublyLinkedList* list, int RNTI) {
    pthread_mutex_lock(&list->lock);
    sem_wait(&list->write_semaphore);

    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            if (current->prev != NULL) {
                current->prev->next = current->next;
            } else {
                list->head = current->next;
            }
            if (current->next != NULL) {
                current->next->prev = current->prev;
            } else {
                list->tail = current->prev;
            }
            free(current);
            break;
        }
        current = current->next;
    }

    sem_post(&list->read_semaphore);
    pthread_mutex_unlock(&list->lock);
}

void* update_thread(void* arg) {
    DoublyLinkedList* list = (DoublyLinkedList*)arg;
    while (1) {
        // Simulate external data source updates
        NFAPI_CRC_INDICATION_PDU_T new_data = {0, 0, 0, 0};
        insert(list, new_data);
        sleep(1); // Simulate real-time updates every second
    }
    return NULL;
}

int main() {
    DoublyLinkedList list;
    init_list(&list);

    pthread_t update_tid;
    pthread_create(&update_tid, NULL, update_thread, &list);

    // Simulate other operations and concurrency scenarios

    pthread_join(update_tid, NULL);
    destroy_list(&list);

    return 0;
}
