from concurrent.futures import ThreadPoolExecutor
import redis
import logging

# Initialize logger
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# Redis client setup
redis_client = redis.StrictRedis(host='localhost', port=6379, db=0)

class EventProcessor:
    def process_event(self, event):
        raise NotImplementedError("Subclasses should implement this!")

class LogEventProcessor(EventProcessor):
    def process_event(self, event):
        # Process log entry
        logger.info(f"Processing log: {event}")

class AlertEventProcessor(EventProcessor):
    def process_event(self, event):
        # Process alert
        logger.warning(f"Processing alert: {event}")

class PerformanceMetricsProcessor(EventProcessor):
    def process_event(self, event):
        # Process performance metrics
        logger.debug(f"Processing metrics: {event}")

class EventFramework:
    def __init__(self):
        self.processors = {}
        self.executor = ThreadPoolExecutor(max_workers=10)

    def add_processor(self, event_type, processor_instance):
        self.processors[event_type] = processor_instance

    def remove_processor(self, event_type):
        if event_type in self.processors:
            del self.processors[event_type]

    def process_event(self, event_type, event):
        if event_type in self.processors:
            self.executor.submit(self.processors[event_type].process_event, event)
        else:
            logger.error(f"No processor found for event type: {event_type}")

# Example usage
framework = EventFramework()
framework.add_processor('log', LogEventProcessor())
framework.add_processor('alert', AlertEventProcessor())

# Simulate event processing
framework.process_event('log', 'User logged in')
framework.process_event('alert', 'High memory usage detected')
