    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Insert a new node at the end of the list
void insert_node(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    new_node->data = data;
    new_node->prev = list->tail;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        list->tail->next = new_node;
    }
    list->tail = new_node;
    pthread_mutex_unlock(&list->lock);
}

// Delete a node from the list by value
void delete_node(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RX_UE_INFORMATION_TAG == data.RX_UE_INFORMATION_TAG &&
            current->data.RNTI == data.RNTI &&
            current->data.CRC_INDICATION_REL8_TAG == data.CRC_INDICATION_REL8_TAG &&
            current->data.CRCFLAG == data.CRCFLAG) {
            pthread_mutex_lock(&list->lock);
            if (current->prev != NULL) {
                current->prev->next = current->next;
            } else {
                list->head = current->next;
            }
            if (current->next != NULL) {
                current->next->prev = current->prev;
            } else {
                list->tail = current->prev;
            }
            pthread_mutex_unlock(&list->lock);
            free(current);
            return;
        }
        current = current->next;
    }
}

// Free all nodes in the list
void free_list(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}
