import threading
from queue import Queue, Empty
import hashlib
import time

class MD5Hasher:
    def __init__(self, max_workers=4):
        self.queue = Queue()
        self.max_workers = max_workers
        self.workers = [threading.Thread(target=self.worker) for _ in range(max_workers)]
        for worker in self.workers:
            worker.start()

    def hash_data(self, data):
        self.queue.put(data)

    def worker(self):
        while True:
            try:
                data = self.queue.get(timeout=1)
                if data is None:
                    break
                md5_hash = hashlib.md5(data).hexdigest()
                print(f"MD5: {md5_hash}")
            except Empty:
                pass

    def stop(self):
        for _ in range(self.max_workers):
            self.queue.put(None)
        for worker in self.workers:
            worker.join()

# Example usage
hasher = MD5Hasher(max_workers=4)
hasher.hash_data(b"Hello, world!")
time.sleep(2)  # Allow time for the hash to be computed and printed
hasher.stop()
