#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

// Define NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    RX_UE_INFORMATION_TAG rx_tag;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define Node structure for the doubly linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

// Define List structure
typedef struct {
    Node* head;
    Node* tail;
    sem_t mutex;
    sem_t empty;
    sem_t full;
    int count;
} List;

// Initialize the list
void init_list(List* list) {
    list->head = NULL;
    list->tail = NULL;
    sem_init(&list->mutex, 0, 1);
    sem_init(&list->empty, 0, 1);
    sem_init(&list->full, 0, 0);
    list->count = 0;
}

// Insert a node at the end of the list
void insert_node(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    sem_wait(&list->empty);
    sem_wait(&list->mutex);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        // Handle allocation failure
        sem_post(&list->empty);
        sem_post(&list->mutex);
        return;
    }

    new_node->data = data;
    new_node->prev = list->tail;
    new_node->next = NULL;

    if (list->head == NULL) {
        list->head = new_node;
    } else {
        list->tail->next = new_node;
    }
    list->tail = new_node;
    list->count++;

    sem_post(&list->mutex);
    sem_post(&list->full);
}

// Delete a node from the list
void delete_node(List* list, RX_UE_INFORMATION_TAG rx_tag) {
    sem_wait(&list->full);
    sem_wait(&list->mutex);

    Node* current = list->head;
    while (current != NULL) {
        if (current->data.rx_tag == rx_tag) {
            if (current->prev != NULL) {
                current->prev->next = current->next;
            } else {
                list->head = current->next;
            }
            if (current->next != NULL) {
                current->next->prev = current->prev;
            } else {
                list->tail = current->prev;
            }
            free(current);
            list->count--;
            break;
        }
        current = current->next;
    }

    sem_post(&list->mutex);
    sem_post(&list->empty);
}

