// Define the data structure for sensor telemetry
struct SensorData {
    std::string id;
    double value;
    std::time_t timestamp;
};

// Define a thread-safe queue for incoming sensor data
class DataQueue {
public:
    void push(const SensorData& data) {
        std::lock_guard<std::mutex> lock(mutex_);
        queue_.push(data);
        condition_.notify_one();
    }

    bool pop(SensorData& data) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (condition_.wait_for(lock, std::chrono::seconds(1), [this]{ return !queue_.empty(); })) {
            data = queue_.front();
            queue_.pop();
            return true;
        }
        return false;
    }

private:
    std::queue<SensorData> queue_;
    std::mutex mutex_;
    std::condition_variable condition_;
};

// Define a worker thread class to process sensor data
class DataWorker {
public:
    DataWorker(DataQueue& queue, std::atomic<bool>& running) : queue_(queue), running_(running) {}

    void operator()() {
        while (running_) {
            SensorData data;
            if (queue_.pop(data)) {
                // Process the data here
                process_data(data);
            }
        }
    }

private:
    void process_data(const SensorData& data) {
        // Implement data processing logic
    }

    DataQueue& queue_;
    std::atomic<bool>& running_;
};

// Define a class to manage worker threads and memory pools
class WorkerManager {
public:
    WorkerManager(size_t num_threads) : stop_(false), worker_threads_(num_threads) {
        for (size_t i = 0; i < num_threads; ++i) {
            worker_threads_[i] = std::thread(DataWorker(queue_, stop_));
        }
    }

    ~WorkerManager() {
        stop_ = true;
        queue_.push(SensorData()); // Signal all workers to stop
        for (auto& thread : worker_threads_) {
            thread.join();
        }
    }

    void push_data(const SensorData& data) {
        queue_.push(data);
    }

private:
    DataQueue queue_;
    std::vector<std::thread> worker_threads_;
    std::atomic<bool> stop_;
};

int main() {
    WorkerManager manager(10); // Create a worker manager with 10 threads

    // Simulate incoming sensor data
    for (size_t i = 0; i < 500000; ++i) {
        SensorData data;
        data.id = "sensor_" + std::to_string(i);
        data.value = static_cast<double>(i);
        data.timestamp = std::time(nullptr);
        manager.push_data(data);
    }

