        : url(url), rateLimit(rateLimit), lastRequestTime(0) {}

    void fetch() {
        auto now = std::chrono::system_clock::now();
        if (std::chrono::duration_cast<std::chrono::seconds>(now - lastRequestTime).count() < 1.0 / rateLimit) {
            std::this_thread::sleep_for(std::chrono::milliseconds(1000 / rateLimit));
        }
        // Perform API request using cURL or another library
        performRequest();
        lastRequestTime = now;
    }

private:
    std::string url;
    int rateLimit;
    std::chrono::system_clock::time_point lastRequestTime;

    void performRequest() {
        CURL *curl;
        CURLcode res;

        curl_global_init(CURL_GLOBAL_DEFAULT);
        curl = curl_easy_init();
        if(curl) {
            curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
