import io.grpc.ManagedChannel;
import io.grpc.ManagedChannelBuilder;
import com.google.protobuf.Empty;

public class RiskAssessmentClient {
    private final ManagedChannel channel;
    private final RiskAssessmentGrpc.RiskAssessmentBlockingStub blockingStub;

    public RiskAssessmentClient(String host, int port) {
        this(ManagedChannelBuilder.forAddress(host, port)
                .usePlaintext()
                .build());
    }

    RiskAssessmentClient(ManagedChannel channel) {
        this.channel = channel;
        blockingStub = RiskAssessmentGrpc.newBlockingStub(channel);
    }

    public void assessRisk(String data) {
        try {
            RiskAssessmentRequest request = RiskAssessmentRequest.newBuilder().setData(data).build();
            RiskAssessmentResponse response = blockingStub.assessRisk(request);
            System.out.println("Assessment Result: " + response.getResult());
        } catch (Exception e) {
            handleRateLimiting(e);
        }
    }

    private void handleRateLimiting(Exception e) {
        if (e instanceof StatusRuntimeException && ((StatusRuntimeException) e).getStatus().getCode() == Status.Code.RESOURCE_EXHAUSTED) {
            System.out.println("Rate limit exceeded, retrying after 1 second...");
            try {
                Thread.sleep(1000);
            } catch (InterruptedException ie) {
                // Handle interrupt
            }
            assessRisk(e.getMessage());
        } else {
            e.printStackTrace();
        }
    }

    public void shutdown() throws InterruptedException {
        channel.shutdown().awaitTermination(5, TimeUnit.SECONDS);
    }
}
