#include <unordered_map>
#include <vector>
#include <string>
#include <mutex>
#include <atomic>

class DependencyManager {
public:
    static DependencyManager& getInstance() {
        static DependencyManager instance;
        return instance;
    }

    void setApprovedModules(const std::unordered_set<std::string>& approved) {
        std::lock_guard<std::mutex> lock(mutex_);
        approvedModules_ = approved;
    }

    bool isValidModule(const std::string& module) const {
        std::lock_guard<std::mutex> lock(mutex_);
        return approvedModules_.find(module) != approvedModules_.end();
    }

private:
    DependencyManager() {}
    ~DependencyManager() {}

    DependencyManager(const DependencyManager&) = delete;
    DependencyManager& operator=(const DependencyManager&) = delete;

    mutable std::mutex mutex_;
    std::unordered_set<std::string> approvedModules_;
};

void insertOrUpdateDependency(std::unordered_map<std::string, std::vector<std::string>>& dependencyMap,
                             const std::string& targetModule,
                             const std::string& newDependency) {
    static DependencyManager& manager = DependencyManager::getInstance();

    if (!manager.isValidModule(targetModule)) {
        throw std::invalid_argument("Invalid target module");
    }

    if (!manager.isValidModule(newDependency)) {
        throw std::invalid_argument("Invalid new dependency");
    }

    std::lock_guard<std::mutex> lock(mutex_);
    auto& dependencies = dependencyMap[targetModule];
    auto it = std::find(dependencies.begin(), dependencies.end(), newDependency);
    if (it != dependencies.end()) {
        *it = newDependency; // Update existing dependency
    } else {
        dependencies.push_back(newDependency); // Add new dependency
    }
}

// Example usage:
int main() {
    std::unordered_map<std::string, std::vector<std::string>> depMap;
    DependencyManager& manager = DependencyManager::getInstance();
    manager.setApprovedModules({"moduleA", "moduleB", "moduleC"});

    insertOrUpdateDependency(depMap, "moduleA", "moduleB");
    insertOrUpdateDependency(depMap, "moduleA", "moduleD"); // moduleD is not approved

    return 0;
}
```

