#include <fstream>
#include <regex>
#include <memory>

class LogEntry {
public:
    std::string source;
    std::string timestamp;
    std::string message;
};

class LogProcessor {
private:
    std::vector<std::shared_ptr<LogEntry>> entries;
    std::mutex mtx;
    std::condition_variable cv;

public:
    void addLog(const LogEntry& entry) {
        std::lock_guard<std::mutex> lock(mtx);
        entries.push_back(std::make_shared<LogEntry>(entry));
        cv.notify_one();
    }

    std::shared_ptr<LogEntry> getLog() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this] { return !entries.empty(); });
        auto entry = entries.front();
        entries.erase(entries.begin());
        return entry;
    }
};

class ExternalLoggingService {
public:
    virtual void log(const LogEntry& entry) = 0;
};

class ServiceA : public ExternalLoggingService {
public:
    void log(const LogEntry& entry) override {
        // Implementation for logging to service A
    }
};

class ServiceB : public ExternalLoggingService {
public:
    void log(const LogEntry& entry) override {
        // Implementation for logging to service B
    }
};

class ServiceC : public ExternalLoggingService {
public:
    void log(const LogEntry& entry) override {
        // Implementation for logging to service C
    }
};

class LogManager {
private:
    LogProcessor processor;
    std::vector<std::unique_ptr<ExternalLoggingService>> services;

public:
    void addLog(const LogEntry& entry) {
        processor.addLog(entry);
        logToServices(entry);
    }

    void logToServices(const LogEntry& entry) {
        for (auto& service : services) {
            service->log(entry);
        }
    }

    void addService(std::unique_ptr<ExternalLoggingService> service) {
        services.push_back(std::move(service));
    }
};

int main() {
    LogManager manager;
    manager.addService(std::make_unique<ServiceA>());
    manager.addService(std::make_unique<ServiceB>());
    manager.addService(std::make_unique<ServiceC>());

    LogEntry entry{"server1", "2023-04-01T12:00:00Z", "System boot"};
    manager.addLog(entry);

    return 0;
}
