// Define the structure for CRC indication PDU
struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
};

// Global linked list to store CRC indications
std::list<NFAPI_CRC_INDICATION_PDU_T> crcIndicationList;

// Mutex for thread-safe access to the linked list
std::mutex listMutex;

// Condition variable to signal when data is available
std::condition_variable dataAvailableCV;

// Random number generator for CRCFLAG
std::random_device rd;
std::mt19937 gen(rd());
std::bernoulli_distribution dis(0.8); // Probability of CRCFLAG being true

// Function to simulate processing CRC indication requests
void processCRCIndicationRequests() {
    while (true) {
        std::unique_lock<std::mutex> lock(listMutex);
        dataAvailableCV.wait(lock, []{ return !crcIndicationList.empty(); });

        NFAPI_CRC_INDICATION_PDU_T pdu = crcIndicationList.front();
        crcIndicationList.pop_front();
        lock.unlock();

        // Simulate processing the CRC indication request
        std::this_thread::sleep_for(std::chrono::microseconds(10)); // Simulate processing time

        // Log the processed request (simple example)
        std::cout << "Processed CRC Indication Request: RX_UE_INFORMATION_TAG=" << pdu.RX_UE_INFORMATION_TAG 
                  << ", RNTI=" << pdu.RNTI << ", CRC_INDICATION_REL8_TAG=" << pdu.CRC_INDICATION_REL8_TAG 
                  << ", CRCFLAG=" << (pdu.CRCFLAG ? "true" : "false") << std::endl;
    }
}

// Function to add a new CRC indication request to the linked list
void addCRCIndicationRequest(NFAPI_CRC_INDICATION_PDU_T pdu) {
    std::lock_guard<std::mutex> lock(listMutex);
    crcIndicationList.push_back(pdu);
    dataAvailableCV.notify_one();
}

// JavaScript component using N-API
Napi::Value AddCRCIndicationRequest(const Napi::CallbackInfo& info) {
    Napi::Env env = info.Env();

    if (info.Length() < 3 || !info[0].IsNumber() || !info[1].IsNumber() || !info[2].IsNumber()) {
        Napi::TypeError::New(env, "Expected three numbers").ThrowAsJavaScriptException();
        return env.Null();
    }

    int RX_UE_INFORMATION_TAG = info[0].As<Napi::Number>().Int32Value();
    int RNTI = info[1].As<Napi::Number>().Int32Value();
    int CRC_INDICATION_REL8_TAG = info[2].As<Napi::Number>().Int32Value();

    NFAPI_CRC_INDICATION_PDU_T pdu = {
        RX_UE_INFORMATION_TAG,
        RNTI,
        CRC_INDICATION_REL8_TAG,
        dis(gen) // Probabilistically set CRCFLAG
    };

    addCRCIndicationRequest(pdu);

    return env.Null();
}

// Node.js exports using N-API
Napi::Object Init(Napi::Env env, Napi::Object exports) {
    exports.Set(Napi::String::New(env, "addCRCIndicationRequest"), Napi::Function::New(env, AddCRCIndicationRequest));
    return exports;
}

NODE_API_MODULE(crc_indications_module, Init)
