#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define N 100
#define MAX_N 1000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    int size;
    pthread_mutex_t lock;
} LinkedList;

void initLinkedList(LinkedList* list) {
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void insertNode(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = list->head;
    list->head = newNode;
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

void deleteLinkedList(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->size = 0;
    pthread_mutex_unlock(&list->lock);
}

void* threadFunction(void* arg) {
    LinkedList* list = (LinkedList*)arg;
    NFAPI_CRC_INDICATION_PDU_T data;
    // Simulate data retrieval and processing
    insertNode(list, data);
    return NULL;
}

int main() {
    LinkedList list;
    initLinkedList(&list);

    pthread_t threads[MAX_N];
    for (int i = 0; i < MAX_N; i++) {
        pthread_create(&threads[i], NULL, threadFunction, &list);
    }

    for (int i = 0; i < MAX_N; i++) {
        pthread_join(threads[i], NULL);
    }

    deleteLinkedList(&list);

    return 0;
}
