#include "Logging.h"

class BatchProcessor {
public:
    BatchProcessor(const BatchProcessorConfig& config)
        : config_(config), threadPool_(config.maxThreads), stop(false) {}

    void processBatches() {
        std::vector<std::future<void>> futures;
        while (true) {
            std::unique_lock<std::mutex> lock(queueMutex_);
            queueCond_.wait(lock, [this] { return !tasks_.empty() || stop; });
            if (stop && tasks_.empty()) break;

            for (size_t i = 0; i < config_.batchSize && !tasks_.empty(); ++i) {
                auto task = std::move(tasks_.front());
                tasks_.pop();
                futures.emplace_back(threadPool_.enqueue([task]() { task(); }));
            }
        }

        for (auto& future : futures) {
            future.get();
        }
    }

private:
    BatchProcessorConfig config_;
    ThreadPool threadPool_;
    std::atomic<bool> stop;
    std::mutex queueMutex_;
    std::condition_variable queueCond_;
    std::queue<std::function<void()>> tasks_;
};

