#include <iostream>
#include <vector>
#include <functional>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <future>
#include <chrono>
#include <cmath>
#include <openssl/md5.h>
#include <openssl/sha.h>

class DataProcessor {
public:
    void addWorker(std::function<void()> task) {
        std::unique_lock<std::mutex> lock(mutex_);
        queue_.push(task);
        condition_variable_.notify_one();
    }

    void start() {
        for (size_t i = 0; i < num_workers_; ++i) {
            worker_threads_.emplace_back([this]() {
                while (true) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(mutex_);
                        condition_variable_.wait(lock, [this] { return !queue_.empty() || stop_; });
                        if (stop_ && queue_.empty()) {
                            return;
                        }
                        task = std::move(queue_.front());
                        queue_.pop();
                    }
                    task();
                }
            });
        }
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            stop_ = true;
        }
        condition_variable_.notify_all();
        for (std::thread& thread : worker_threads_) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

private:
    std::vector<std::thread> worker_threads_;
    std::queue<std::function<void()>> queue_;
    std::mutex mutex_;
    std::condition_variable condition_variable_;
    bool stop_ = false;
    size_t num_workers_ = std::thread::hardware_concurrency();
};

void reduceAsync(const std::vector<int>& data, const std::function<int(int, int)>& reducer, std::function<void(int)> callback) {
    DataProcessor processor;
    for (int value : data) {
        processor.addWorker([value, &reducer, &callback]() {
            // Perform reduction operation here
            int result = value; // Placeholder for actual reduction logic
            callback(result);
        });
    }
    processor.start();
}

