using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;
using Polly;
using Polly.Retry;
using Newtonsoft.Json;

public class DynamicResourceManager
{
    private readonly HttpClient _httpClient;
    private readonly Dictionary<string, string> _apiEndpoints;
    private readonly RetryPolicy _retryPolicy;

    public DynamicResourceManager()
    {
        _httpClient = new HttpClient();
        _apiEndpoints = new Dictionary<string, string>
        {
            { "CloudApi", "https://api.cloudprovider.com/resources" },
            { "LegacyDb", "https://legacydb.example.com/resources" }
        };

        var waitAndRetryPolicy = Policy
            .Handle<HttpRequestException>()
            .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));

        _retryPolicy = waitAndRetryPolicy;
    }

    public async Task<List<ResourceBundle>> GetResourceBundles()
    {
        var resourceBundles = new List<ResourceBundle>();

        foreach (var endpoint in _apiEndpoints.Values)
        {
            try
            {
                var response = await _httpClient.GetAsync(endpoint);
                response.EnsureSuccessStatusCode();
                var content = await response.Content.ReadAsStringAsync();
                var bundles = JsonConvert.DeserializeObject<List<ResourceBundle>>(content);
                resourceBundles.AddRange(bundles);
            }
            catch (Exception ex)
            {
                // Log the exception and retry
                Console.WriteLine($"Error fetching resources from {endpoint}: {ex.Message}");
            }
        }

        return resourceBundles;
    }
}

public class ResourceBundle
{
    public string Id { get; set; }
    public string Data { get; set; }
}
