#include <iostream>
#include <string>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <future>
#include <chrono>
#include <thread>

class ConfigManager {
public:
    void updateConfig(const std::string& key, const std::string& value) {
        std::unique_lock<std::mutex> lock(mutex_);
        config_[key] = value;
        cv_.notify_all();
    }

    std::string getConfig(const std::string& key) {
        std::unique_lock<std::mutex> lock(mutex_);
        while (config_.find(key) == config_.end()) {
            cv_.wait(lock);
        }
        return config_[key];
    }

private:
    std::unordered_map<std::string, std::string> config_;
    std::mutex mutex_;
    std::condition_variable cv_;
};

class ConfigCache {
public:
    void updateConfig(const std::string& key, const std::string& value) {
        cache_[key] = {value, std::chrono::steady_clock::now()};
    }

    std::string getConfig(const std::string& key) {
        auto now = std::chrono::steady_clock::now();
        if (cache_.find(key) != cache_.end() && 
            now - cache_[key].second <= std::chrono::seconds(60)) {
            return cache_[key].first;
        }
        return "";
    }

private:
    std::unordered_map<std::string, std::pair<std::string, std::chrono::time_point<std::chrono::steady_clock>>> cache_;
};

class ConfigManagerWithCache : public ConfigManager, public ConfigCache {
public:
    void updateConfig(const std::string& key, const std::string& value) override {
        ConfigManager::updateConfig(key, value);
        ConfigCache::updateConfig(key, value);
    }

    std::string getConfig(const std::string& key) override {
        auto value = ConfigCache::getConfig(key);
        if (value.empty()) {
            value = ConfigManager::getConfig(key);
            ConfigCache::updateConfig(key, value);
        }
        return value;
    }
};
