package main

import (
    "context"
    "log"
    "sync"

    "github.com/go-redis/redis/v8"
)

var ctx = context.Background()
var redisClient *redis.Client
var mu sync.Mutex

func init() {
    // Initialize Redis client
    redisClient = redis.NewClient(&redis.Options{
        Addr:     "localhost:6379",
        Password: "", // no password set
        DB:       0,  // use default DB
    })

    // Check connection to Redis
    pong, err := redisClient.Ping(ctx).Result()
    if err != nil {
        log.Fatalf("Failed to connect to Redis: %v", err)
    }
    log.Println("Connected to Redis:", pong)
}

func insertAfterOrLog(target string, newString string) error {
    mu.Lock()
    defer mu.Unlock()

    // Check if target exists
    key := "distributed_strings"
    value, err := redisClient.LIndex(ctx, key, -1).Result()
    if err != nil && err != redis.Nil {
        log.Printf("Failed to fetch last element: %v", err)
        return err
    }

    if value == target {
        // Insert new string after target
        _, err = redisClient.LInsertAfter(ctx, key, target, newString).Result()
        if err != nil {
            log.Printf("Failed to insert after target: %v", err)
            return err
        }
    } else {
        // Append new string at the end
        _, err := redisClient.RPush(ctx, key, newString).Result()
        if err != nil {
            log.Printf("Failed to append to list: %v", err)
            return err
        }
    }

    return nil
}

func main() {
    // Example usage
    err := insertAfterOrLog("example", "new_example")
    if err != nil {
        log.Fatalf("Error inserting string: %v", err)
    }
}
