# Import necessary libraries
import logging
from logging import config
from multiprocessing import Pool
import yaml
import requests
from datetime import datetime

# Define log levels
LOG_LEVELS = {
    'DEBUG': logging.DEBUG,
    'INFO': logging.INFO,
    'WARNING': logging.WARNING,
    'ERROR': logging.ERROR,
    'CRITICAL': logging.CRITICAL
}

# Load configuration from YAML file
with open('logging_config.yaml', 'r') as config_file:
    CONFIG = yaml.safe_load(config_file)

# Configure logging
config.dictConfig(CONFIG)

# Define a logger class
class Logger:
    def __init__(self, name):
        self.logger = logging.getLogger(name)

    def log(self, level, message):
        if level == 'debug':
            self.logger.debug(message)
        elif level == 'info':
            self.logger.info(message)
        elif level == 'warning':
            self.logger.warning(message)
        elif level == 'error':
            self.logger.error(message)
        elif level == 'critical':
            self.logger.critical(message)

# Define an Elasticsearch client class
class ElasticsearchClient:
    def __init__(self, url):
        self.url = url

    def index_log(self, log_entry):
        response = requests.post(f"{self.url}/logs", json=log_entry)
        return response.status_code

# Define a Splunk client class
class SplunkClient:
    def __init__(self, url, token):
        self.url = url
        self.token = token

    def send_log(self, log_entry):
        headers = {'Authorization': f'Splunk {self.token}'}
        response = requests.post(f"{self.url}/services/collector/raw", headers=headers, data=log_entry)
        return response.status_code

# Define a logging manager class
class LoggingManager:
    def __init__(self, loggers, clients):
        self.loggers = loggers
        self.clients = clients

    def log(self, service_name, level, message):
        for logger in self.loggers[service_name]:
            logger.log(level, message)

        for client in self.clients:
            if isinstance(client, ElasticsearchClient):
                log_entry = {'timestamp': datetime.now().isoformat(), 'service': service_name, 'level': level, 'message': message}
                client.index_log(log_entry)
            elif isinstance(client, SplunkClient):
                log_entry = f"{datetime.now().isoformat()} - {service_name} - {level} - {message}"
                client.send_log(log_entry)

# Initialize loggers and clients
loggers = {
    'service1': [Logger('service1_logger')],
    'service2': [Logger('service2_logger')]
}
clients = [
    ElasticsearchClient('http://elasticsearch:9200'),
    SplunkClient('https://splunk.example.com', 'your_splunk_token')
]

# Initialize logging manager
logging_manager = LoggingManager(loggers, clients)

# Example usage
logging_manager.log('service1', 'info', 'This is an info message from service 1.')
logging_manager.log('service2', 'error', 'This is an error message from service 2.')
```

