// DynamicArray structure to manage a dynamic collection of configurations
typedef struct {
    NetworkInterfaceConfiguration *configs;
    size_t size;
    size_t capacity;
} DynamicNetworkTopologyManager;

// Function to initialize the DynamicNetworkTopologyManager
void initDynamicNetworkTopologyManager(DynamicNetworkTopologyManager *manager) {
    manager->configs = NULL;
    manager->size = 0;
    manager->capacity = 0;
}

// Function to add a configuration to the manager
void addConfiguration(DynamicNetworkTopologyManager *manager, NetworkInterfaceConfiguration config) {
    if (manager->size >= manager->capacity) {
        size_t new_capacity = (manager->capacity == 0) ? 1 : manager->capacity * 2;
        manager->configs = realloc(manager->configs, new_capacity * sizeof(NetworkInterfaceConfiguration));
        manager->capacity = new_capacity;
    }
    manager->configs[manager->size++] = config;
}

// Function to remove a configuration from the manager
void removeConfiguration(DynamicNetworkTopologyManager *manager, size_t index) {
    if (index < manager->size) {
        for (size_t i = index; i < manager->size - 1; i++) {
            manager->configs[i] = manager->configs[i + 1];
        }
        manager->size--;
    }
}

