    template <typename Func>
    void executeWithRetry(Func&& func, int maxRetries = 5, double initialDelay = 0.1) {
        for (int attempt = 0; attempt <= maxRetries; ++attempt) {
            try {
                std::invoke(std::forward<Func>(func));
                return;
            } catch (...) {
                if (attempt == maxRetries) throw;
