        # Add an edge node with its location
        self.edge_nodes.append({'id': node_id, 'location': location})

    def get_content(self, request_url):
        # Retrieve content from the most suitable source or edge node
        for source in sorted(self.content_sources.values(), key=lambda x: latency_to_node(x)):
            try:
                response = requests.get(source + request_url)
                if response.status_code == 200:
                    return response.content
            except requests.RequestException:
                continue

        # Fallback to a default content source or edge node
        default_source = list(self.content_sources.values())[0]
        return requests.get(default_source + request_url).content

