pub mod concurrency {
    use tokio::task;
    use std::sync::{Arc, Mutex};
    use std::collections::VecDeque;

    pub struct ConcurrencyManager {
        tasks: Arc<Mutex<VecDeque<tokio::JoinHandle<()>>>>,
    }

    impl ConcurrencyManager {
        pub fn new() -> Self {
            ConcurrencyManager {
                tasks: Arc::new(Mutex::new(VecDeque::new())),
            }
        }

        pub async fn run_parallel<F, I>(&self, items: I)
        where
            F: 'static + Send + Sync,
            I: IntoIterator<Item = F>,
        {
            let tasks = self.tasks.clone();
            for item in items.into_iter() {
                task::spawn(item).await;
                tasks.lock().unwrap().push_back(task);
            }
            while !tasks.lock().unwrap().is_empty() {
                tokio::join!(tasks.lock().unwrap().pop_front().unwrap());
            }
        }
    }
}

