                message: message.to_string(),
            }
        }
    }

    impl Error for GrammarServiceError {}

    impl std::fmt::Display for GrammarServiceError {
        fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            write!(f, "{}", self.message)
        }
    }
}

