import java.util.concurrent.CompletableFuture;
import org.springframework.amqp.core.*;
import org.springframework.amqp.rabbit.connection.ConnectionFactory;
import org.springframework.amqp.rabbit.core.RabbitTemplate;
import org.springframework.amqp.rabbit.listener.SimpleMessageListenerContainer;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration
public class EventBusConfig {

    @Autowired
    private ConnectionFactory connectionFactory;

    @Bean
    public Queue eventQueue() {
        return new TopicExchange("event-exchange");
    }

    @Bean
    public TopicExchange topicExchange() {
        return new TopicExchange("topic-exchange");
    }

    @Bean
    public Binding binding(Queue eventQueue, TopicExchange topicExchange) {
        return BindingBuilder.bind(eventQueue).to(topicExchange).with("event-routing-key");
    }

    @Bean
    public RabbitTemplate rabbitTemplate(ConnectionFactory connectionFactory) {
        RabbitTemplate template = new RabbitTemplate(connectionFactory);
        template.setMessageConverter(new Jackson2JsonMessageConverter());
        return template;
    }

    @Bean
    public SimpleMessageListenerContainer messageListenerContainer(ConnectionFactory connectionFactory, AmqpConsumer consumer) {
        SimpleMessageListenerContainer container = new SimpleMessageListenerContainer();
        container.setConnectionFactory(connectionFactory);
        container.setQueueNames("event-queue");
        container.setMessageListener(consumer);
        return container;
    }

    @Bean
    public AmqpConsumer amqpConsumer() {
        return new AmqpConsumer(rabbitTemplate());
    }
}

class AmqpConsumer {

    private final RabbitTemplate rabbitTemplate;

    public AmqpConsumer(RabbitTemplate rabbitTemplate) {
        this.rabbitTemplate = rabbitTemplate;
    }

    @RabbitListener(queues = "event-queue")
    public void receiveMessage(String message) {
        // Process the event
    }
}
