    public void ConfigureServices(IServiceCollection services)
    {
        // Add API Gateway and Service Discovery
        services.AddControllers();
        services.AddSwaggerGen();

        // Add Circuit Breaker for Resilience
        services.AddSingleton<ICircuitBreakerPolicy>(sp =>
            Policy
                .Handle<Exception>()
                .CircuitBreakerAsync(
                    tripTimespan: TimeSpan.FromSeconds(30),
                    onResetAsync: () => Console.WriteLine("Circuit Reset")
                )
        );

        // Add Distributed Cache for Performance Optimization
        services.AddStackExchangeRedisCache(options =>
        {
            options.Configuration = "your_redis_connection_string";
        });

        // Add Security and Compliance Measures
        services.AddScoped<IFraudDetectionService, FraudDetectionService>();

        // Add Monitoring and Alerting System
        services.AddSingleton<IMonitoringService, MonitoringService>();

        // Add Cost Efficiency Strategies
        services.AddHostedService<ResourceOptimizationService>();
    }

    public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
    {
        if (env.IsDevelopment())
        {
            app.UseDeveloperExceptionPage();
            app.UseSwagger();
            app.UseSwaggerUI(c => c.SwaggerEndpoint("/swagger/v1/swagger.json", "Your API V1"));
        }

        app.UseRouting();

        // Use Middleware for Circuit Breaker and Fraud Detection
        app.Use(async (context, next) =>
        {
            var circuitBreakerPolicy = context.RequestServices.GetRequiredService<ICircuitBreakerPolicy>();
            await circuitBreakerPolicy.ExecuteAsync(next);
        });

        app.UseEndpoints(endpoints =>
        {
            endpoints.MapControllers();
        });
    }
}

