import asyncio
from abc import ABC, abstractmethod
from enum import Enum
from typing import Dict, List

class NotificationType(Enum):
    iOS = "iOS"
    Android = "Android"
    Web = "Web"

class NotificationTemplate:
    def __init__(self, template_id: str, content: dict):
        self.template_id = template_id
        self.content = content

class UserPreference:
    def __init__(self, user_id: str, preferences: Dict[NotificationType, NotificationTemplate]):
        self.user_id = user_id
        self.preferences = preferences

class NotificationProvider(ABC):
    @abstractmethod
    async def send_notification(self, platform: NotificationType, message: dict) -> None:
        pass

class iOSProvider(NotificationProvider):
    async def send_notification(self, platform: NotificationType, message: dict) -> None:
        # Simulate sending a notification to iOS
        print(f"Sending iOS notification: {message}")

class AndroidProvider(NotificationProvider):
    async def send_notification(self, platform: NotificationType, message: dict) -> None:
        # Simulate sending a notification to Android
        print(f"Sending Android notification: {message}")

class WebProvider(NotificationProvider):
    async def send_notification(self, platform: NotificationType, message: dict) -> None:
        # Simulate sending a notification to web
        print(f"Sending Web notification: {message}")

class NotificationService:
    providers: Dict[NotificationType, NotificationProvider] = {
        NotificationType.iOS: iOSProvider(),
        NotificationType.Android: AndroidProvider(),
        NotificationType.Web: WebProvider()
    }

    async def send_notifications(self, user_preferences: List[UserPreference], template_id: str) -> None:
        tasks = []
        for preference in user_preferences:
            if template_id in preference.preferences[NotificationType.iOS].content:
                task = asyncio.create_task(self.send_notification(NotificationType.iOS, preference.preferences[NotificationType.iOS].content[template_id]))
                tasks.append(task)
            if template_id in preference.preferences[NotificationType.Android].content:
                task = asyncio.create_task(self.send_notification(NotificationType.Android, preference.preferences[NotificationType.Android].content[template_id]))
                tasks.append(task)
            if template_id in preference.preferences[NotificationType.Web].content:
                task = asyncio.create_task(self.send_notification(NotificationType.Web, preference.preferences[NotificationType.Web].content[template_id]))
                tasks.append(task)
        await asyncio.gather(*tasks)

    async def send_notification(self, platform: NotificationType, message: dict) -> None:
        provider = self.providers.get(platform)
        if provider:
            await provider.send_notification(platform, message)

# Example usage
async def main():
    user_preferences = [
        UserPreference("user1", {
            NotificationType.iOS: NotificationTemplate("template1", {"message": "Hello iOS"}),
            NotificationType.Android: NotificationTemplate("template2", {"message": "Hello Android"}),
            NotificationType.Web: NotificationTemplate("template3", {"message": "Hello Web"})
        }),
        UserPreference("user2", {
            NotificationType.iOS: NotificationTemplate("template4", {"message": "Hello iOS again"}),
            NotificationType.Android: NotificationTemplate("template5", {"message": "Hello Android again"}),
            NotificationType.Web: NotificationTemplate("template6", {"message": "Hello Web again"})
        })
    ]
    notification_service = NotificationService()
    await notification_service.send_notifications(user_preferences, "template1")

asyncio.run(main())
