// selectAttack.cpp
#include <mutex>
#include <vector>
#include <atomic>
#include <random>
#include <chrono>

std::mutex attackMutex;
std::vector<std::pair<int, int>> attacks; // ID, Cooldown

std::mt19937 gen(std::random_device{}());
std::uniform_int_distribution<> dis(0, attacks.size() - 1);

int selectAttack(int cooldown) {
  std::lock_guard<std::mutex> lock(attackMutex);

  for (auto& [id, cd] : attacks) {
    if (cd <= 0) {
      attacks[id].second = cooldown;
      return id;
    }
  }

  // No available attack, select one with random cooldown
  auto it = attacks.begin() + dis(gen);
  it->second = cooldown;
  return it->first;
}

void updateAttackCooldown(int id, int newCooldown) {
  std::lock_guard<std::mutex> lock(attackMutex);
  attacks[id].second = newCooldown;
}
