  pthread_mutex_init(&cacheMutex, NULL);
  pthread_cond_init(&cacheCond, NULL);

  for (int i = 0; i < cacheSize; ++i) {
    pthread_mutex_init(&cache[i].logMutex, NULL);
    cache[i].logAttempts = 3;
  }
}

void* logPdu(void* arg) {
  int index = *(int*)arg;

  while (1) {
    pthread_mutex_lock(&cache[index].logMutex);
    if (cache[index].logAttempts > 0) {
      --cache[index].logAttempts;
      // Implement logic to log the PDU
      pthread_cond_signal(&cacheCond);
    } else {
      pthread_cond_wait(&cacheCond, &cache[index].logMutex);
    }
    pthread_mutex_unlock(&cache[index].logMutex);
  }

  return NULL;
}

void addPdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
  pthread_mutex_lock(&cacheMutex);

  int index = findFreeSlot();
  if (index != -1) {
    createPdu(pdu);
    pthread_create(&cache[index].logThread, NULL, logPdu, &index);
