// DynamicOrchestrator.js

const express = require('express');
const axios = require('axios');
const retry = require('async-retry');
const tracer = require('opentracing');

const app = express();
const port = 3000;

app.use(express.json());

let testQueue = [];
let inProgressTests = new Set();

async function executeTest(test) {
    try {
        await axios.post(test.metadataUrl, test.data);
        console.log(`Test ${test.id} passed`);
    } catch (error) {
        if (error.response && error.response.status === 504) { // Gateway Timeout
            inProgressTests.delete(test.id);
            setTimeout(() => executeTest(test), Math.pow(2, test.retries) * 1000); // Exponential backoff
            tracer.inject(tracer.activeSpan.context(), tracer.FORMAT_HTTP_HEADERS, error.response.config.headers);
        } else {
            console.error(`Test ${test.id} failed:`, error.message);
        }
    }
}

app.post('/tests', async (req, res) => {
    const tests = req.body;
    testQueue.push(...tests);
    if (!inProgressTests.size) {
        executeNextTest();
    }
    res.sendStatus(202);
});

async function executeNextTest() {
    while (testQueue.length > 0) {
        const test = testQueue.shift();
        if (!inProgressTests.has(test.id)) {
            inProgressTests.add(test.id);
            tracer.startSpan('execute_test', { childOf: tracer.activeSpan }).useAsyncContext(async () => {
                await executeTest(test);
                inProgressTests.delete(test.id);
                executeNextTest();
            });
        }
    }
}

app.listen(port, () => console.log(`DynamicOrchestrator listening at http://localhost:${port}`));
```

