// selectAttack.cpp

#include <mutex>
#include <vector>
#include <thread>
#include <random>
#include <condition_variable>

struct Attack {
    std::string name;
    int cooldown;
};

class AttackSelector {
private:
    std::vector<Attack> attacks;
    std::mutex mtx;
    std::condition_variable cv;

public:
    AttackSelector(const std::vector<Attack>& attacks) : attacks(attacks), currentAttackIndex(0) {}

    void addAttack(const Attack& attack) {
        std::lock_guard<std::mutex> lock(mtx);
        attacks.push_back(attack);
        cv.notify_all();
    }

    Attack selectNextAttack() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this] { return currentAttackIndex < attacks.size(); });
        Attack selected = attacks[currentAttackIndex++];
        if (currentAttackIndex >= attacks.size()) {
            currentAttackIndex = 0;
        }
        lock.unlock();
        std::this_thread::sleep_for(std::chrono::seconds(attacks[selected.name].cooldown));
        return selected;
    }

private:
    int currentAttackIndex;
};

