#include <openssl/evp.h>
#include <openssl/rand.h>
#include <sqlite3.h>

typedef struct {
    EVP_CIPHER_CTX *cipher_ctx;
    EVP_MD_CTX *md_ctx;
} CryptoContext;

CryptoContext* create_crypto_context() {
    CryptoContext *ctx = (CryptoContext*)malloc(sizeof(CryptoContext));
    ctx->cipher_ctx = EVP_CIPHER_CTX_new();
    ctx->md_ctx = EVP_MD_CTX_new();
    return ctx;
}

void free_crypto_context(CryptoContext *ctx) {
    EVP_CIPHER_CTX_free(ctx->cipher_ctx);
    EVP_MD_CTX_free(ctx->md_ctx);
    free(ctx);
}

int encrypt_data(const unsigned char *plaintext, int plaintext_len,
                  const unsigned char *key, const unsigned char *iv,
                  unsigned char *ciphertext) {
    if (!EVP_EncryptInit_ex(ctx->cipher_ctx, EVP_aes_256_cbc(), NULL, key, iv)) return -1;
    if (!EVP_EncryptUpdate(ctx->cipher_ctx, ciphertext, &ciphertext_len, plaintext, plaintext_len)) return -1;
    int final_len;
    if (!EVP_EncryptFinal_ex(ctx->cipher_ctx, ciphertext + ciphertext_len, &final_len)) return -1;
    ciphertext_len += final_len;
    return 0;
}

int decrypt_data(const unsigned char *ciphertext, int ciphertext_len,
                  const unsigned char *key, const unsigned char *iv,
                  unsigned char *plaintext) {
    if (!EVP_DecryptInit_ex(ctx->cipher_ctx, EVP_aes_256_cbc(), NULL, key, iv)) return -1;
    if (!EVP_DecryptUpdate(ctx->cipher_ctx, plaintext, &ciphertext_len, ciphertext, ciphertext_len)) return -1;
    int final_len;
    if (!EVP_DecryptFinal_ex(ctx->cipher_ctx, plaintext + ciphertext_len, &final_len)) return -1;
    ciphertext_len += final_len;
    return 0;
}

int hash_data(const unsigned char *data, size_t len, unsigned char *digest) {
    if (!EVP_DigestInit_ex(ctx->md_ctx, EVP_sha256(), NULL)) return -1;
    if (!EVP_DigestUpdate(ctx->md_ctx, data, len)) return -1;
    if (!EVP_DigestFinal_ex(ctx->md_ctx, digest, NULL)) return -1;
    return 0;
}

int save_data_to_db(const NFAPI_CRC_INDICATION_PDU_T *data) {
    sqlite3 *db;
    char *zErrMsg = 0;
    int rc;

    rc = sqlite3_open("my_database.db", &db);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Cannot open database: %s\n", sqlite3_errmsg(db));
        return -1;
    }

    const char *sql = "INSERT INTO crc_indication_pdu (data) VALUES (?);";
    sqlite3_stmt *stmt;
    rc = sqlite3_prepare_v2(db, sql, -1, &stmt, 0);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "SQL error: %s\n", sqlite3_errmsg(db));
        return -1;
    }

    sqlite3_bind_blob(stmt, 1, data, sizeof(NFAPI_CRC_INDICATION_PDU_T), SQLITE_STATIC);

    rc = sqlite3_step(stmt);
    if (rc != SQLITE_DONE) {
        fprintf(stderr, "SQL error: %s\n", sqlite3_errmsg(db));
        return -1;
    }

    sqlite3_finalize(stmt);
    sqlite3_close(db);
    return 0;
}
