// Linked list node for NFAPI_CRC_INDICATION_PDU_T structures
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct Node* next;
} Node;

// Function to create a new node with given NFAPI_CRC_INDICATION_PDU_T data
Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode != NULL) {
        newNode->pdu = data;
        newNode->next = NULL;
    }
    return newNode;
}

// Function to insert a new node at the end of the linked list
void insertNode(Node** head, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = createNode(data);
    if (newNode != NULL) {
        if (*head == NULL) {
            *head = newNode;
        } else {
            Node* current = *head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = newNode;
        }
    }
}

// Function to delete the linked list
void deleteList(Node** head) {
    Node* current = *head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int main() {
