// DynamicNetworkHandler.h
#pragma once

#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <atomic>

class Event {
    // Define the structure of an event
};

class EventHandler {
public:
    virtual void handle(const Event& event) = 0;
    virtual ~EventHandler() = default;
};

class DynamicNetworkHandler {
public:
    DynamicNetworkHandler(size_t maxEvents);
    ~DynamicNetworkHandler();

    void addEvent(const Event& event);
    void start();
    void stop();

private:
    std::vector<EventHandler*> handlers;
    std::queue<Event> eventQueue;
    std::mutex queueMutex;
    std::condition_variable eventCondition;
    std::atomic<bool> running;
    std::vector<std::thread> workers;
};

// DynamicNetworkHandler.cpp
#include "DynamicNetworkHandler.h"

DynamicNetworkHandler::DynamicNetworkHandler(size_t maxEvents) : running(false) {
    // Initialize the worker threads and other resources
}

DynamicNetworkHandler::~DynamicNetworkHandler() {
    stop();
    for (auto& thread : workers) {
        if (thread.joinable()) {
            thread.join();
        }
    }
}

void DynamicNetworkHandler::addEvent(const Event& event) {
    std::lock_guard<std::mutex> lock(queueMutex);
    eventQueue.push(event);
    eventCondition.notify_one();
}

void DynamicNetworkHandler::start() {
    running = true;
    for (size_t i = 0; i < workers.size(); ++i) {
        workers.emplace_back([this]() {
            while (true) {
                std::unique_lock<std::mutex> lock(queueMutex);
                eventCondition.wait(lock, [this] { return !eventQueue.empty() || !running; });
                if (!running && eventQueue.empty()) {
                    break;
                }
                Event event = eventQueue.front();
                eventQueue.pop();
                lock.unlock();

                for (auto& handler : handlers) {
                    handler->handle(event);
                }
            }
        });
    }
}

void DynamicNetworkHandler::stop() {
    running = false;
    eventCondition.notify_all();
}

