void initialize_pool(int size) {
    pool_size = size;
    pool = (NFAPI_CRC_INDICATION_PDU *)malloc(pool_size * sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!pool) {
        perror("Failed to allocate memory for CRC indication pool");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < pool_size; i++) {
        pthread_mutex_init(&pool[i].lock, NULL);
    }
}

NFAPI_CRC_INDICATION_PDU *get_crc_indication_pdu() {
    NFAPI_CRC_INDICATION_PDU *pdu = NULL;
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < pool_size; i++) {
        if (pthread_mutex_trylock(&pool[i].lock) == 0) {
            pdu = &pool[i];
            break;
        }
    }
    pthread_mutex_unlock(&pool_lock);
    return pdu;
}

void release_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU *pdu) {
    pthread_mutex_lock(&pdu->lock);
    // Reset the PDU data if necessary
    pthread_mutex_unlock(&pdu->lock);
    pthread_mutex_lock(&pool_lock);
