package main

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"time"

	"github.com/aws/aws-sdk-go-v2/aws"
	"github.com/aws/aws-sdk-go-v2/config"
	"github.com/aws/aws-sdk-go-v2/service/sqs"
)

type Event struct {
	ID        string
	Payload   []byte
	Src       string
	Destinations []string
}

type Router struct {
	sqsClient *sqs.Client
	queueURL  string
}

func NewRouter(queueName string) (*Router, error) {
	cfg, err := config.LoadDefaultConfig(context.TODO())
	if err != nil {
		return nil, fmt.Errorf("failed to load AWS config: %w", err)
	}

	sqsClient := sqs.NewFromConfig(cfg)

	queueURL, err := getQueueURL(sqsClient, queueName)
	if err != nil {
		return nil, fmt.Errorf("failed to get SQS queue URL: %w", err)
	}

	return &Router{
		sqsClient: sqsClient,
		queueURL:  queueURL,
	}, nil
}

func (r *Router) routeEvent(event Event) error {
	for _, dest := range event.Destinations {
		err := r.forwardToDestination(event, dest)
		if err != nil {
			return fmt.Errorf("failed to forward event to destination %s: %w", dest, err)
		}
	}

	return nil
}

func (r *Router) forwardToDestination(event Event, destination string) error {
	msg := sqs.SendMessageInput{
		MessageBody: aws.String(string(event.Payload)),
		QueueUrl:    aws.String(r.queueURL),
	}

	_, err := r.sqsClient.SendMessage(context.TODO(), &msg)
	if err != nil {
		return fmt.Errorf("failed to send message to SQS queue: %w", err)
	}

	return nil
}

func getQueueURL(sqsClient *sqs.Client, queueName string) (string, error) {
	queueURLInput := sqs.GetQueueUrlInput{
		QueueName: aws.String(queueName),
	}

	result, err := sqsClient.GetQueueUrl(context.TODO(), &queueURLInput)
	if err != nil {
		return "", fmt.Errorf("failed to get queue URL: %w", err)
	}

	return *result.QueueUrl, nil
}
```

