    std::vector<NFAPI_CRC_INDICATION_PDU_T*> allocateAndProcessPduArray(size_t N) {
        try {
            // Dynamically allocate memory for the array of structures
            auto pdus = std::vector<NFAPI_CRC_INDICATION_PDU_T*>(N);
            for (size_t i = 0; i < N; ++i) {
                pdus[i] = new NFAPI_CRC_INDICATION_PDU_T;
