// Define the class to hold the CRC indication data
public class CrcIndicationPdu implements Serializable {
    public int RX_UE_INFORMATION_TAG;
    public short RNTI;
    public byte CRC_INDICATION_REL8_TAG;
    public boolean CRCFLAG;

    private static final long serialVersionUID = 1L;

    // Constructor for deserialization
    protected CrcIndicationPdu() {}

    // Method to deserialize the byte array
    public static CrcIndicationPdu[] deserialize(byte[] data) {
        try (ByteArrayInputStream bais = new ByteArrayInputStream(data);
             ObjectInputStream ois = new ObjectInputStream(bais)) {

            int length = ByteBuffer.wrap(data).getInt();
            CrcIndicationPdu[] pdus = new CrcIndicationPdu[length];

            for (int i = 0; i < length; ++i) {
                pdus[i] = (CrcIndicationPdu) ois.readObject();
            }

            return pdus;
        } catch (IOException | ClassNotFoundException e) {
            System.err.println("Deserialization error: " + e.getMessage());
            return new CrcIndicationPdu[0];
        }
    }

    // Method to generate random data for testing
    public static CrcIndicationPdu[] generateRandomData(int count) {
        Random rand = new Random();
        CrcIndicationPdu[] pdus = new CrcIndicationPdu[count];

        for (int i = 0; i < count; ++i) {
            CrcIndicationPdu pdu = new CrcIndicationPdu();
            pdu.RX_UE_INFORMATION_TAG = rand.nextInt();
            pdu.RNTI = (short) (rand.nextInt() & 0xFFFF);
            pdu.CRC_INDICATION_REL8_TAG = (byte) (rand.nextInt() & 0xFF);
            pdu.CRCFLAG = rand.nextBoolean();

            pdus[i] = pdu;
        }

        return pdus;
    }
}
