### Example Usage in Java

```java
public class Main {
    public static void main(String[] args) {
        // Generate random data for testing
        CrcIndicationPdu[] testData = CrcIndicationPdu.generateRandomData(10);

        // Serialize the data
        byte[] serializedData = serialize(testData);

        // Deserialize the data
        CrcIndicationPdu[] deserializedData = CrcIndicationPdu.deserialize(serializedData);

        for (CrcIndicationPdu pdu : deserializedData) {
            System.out.println("RX_UE_INFORMATION_TAG: " + pdu.RX_UE_INFORMATION_TAG);
            System.out.println("RNTI: " + pdu.RNTI);
            System.out.println("CRC_INDICATION_REL8_TAG: " + pdu.CRC_INDICATION_REL8_TAG);
            System.out.println("CRCFLAG: " + pdu.CRCFLAG);
        }
    }

    private static byte[] serialize(CrcIndicationPdu[] data) {
        try (ByteArrayOutputStream baos = new ByteArrayOutputStream();
             ObjectOutputStream oos = new ObjectOutputStream(baos)) {

            // Write the length of the array
            oos.writeInt(data.length);

            for (CrcIndicationPdu pdu : data) {
                oos.writeObject(pdu);
            }

            return baos.toByteArray();
        } catch (IOException e) {
            System.err.println("Serialization error: " + e.getMessage());
            return new byte[0];
        }
    }
}
