// Import necessary libraries
use reqwest::{Client, Error};
use std::time::Duration;
use tokio::sync::Mutex;

// Define a struct for the HTTP client
struct HttpClient {
    client: Client,
    base_url: String,
}

impl HttpClient {
    // Constructor to initialize the HTTP client
    fn new(base_url: &str) -> Self {
        HttpClient {
            client: Client::new(),
            base_url: base_url.to_string(),
        }
    }

    // Method to send a GET request with rate limiting and retries
    async fn get(&self, endpoint: &str) -> Result<String, Error> {
        let url = format!("{}{}", self.base_url, endpoint);
        let mut retries = 3; // Maximum number of retries

        while retries > 0 {
            match self.client.get(&url).send().await {
                Ok(response) => {
                    if response.status().is_success() {
                        return response.text().await;
                    } else {
                        retries -= 1;
                        tokio::time::sleep(Duration::from_secs(1)).await; // Wait before retrying
                    }
                }
                Err(e) => {
                    retries -= 1;
                    tokio::time::sleep(Duration::from_secs(1)).await; // Wait before retrying
                }
            }
        }

        Err(Error::new(reqwest::StatusCode::INTERNAL_SERVER_ERROR, "Max retries exceeded"))
    }
}

// Main function to demonstrate the usage of HttpClient
#[tokio::main]
async fn main() {
    let client = HttpClient::new("https://api.example.com/");
    match client.get("/data").await {
        Ok(data) => println!("Response: {}", data),
        Err(e) => eprintln!("Error: {:?}", e),
    }
}
