#include <openssl/evp.h>
#include <zlib.h>

EVP_CIPHER_CTX* performCryptoOperations(const unsigned char* message, size_t length, int mode) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    // Initialize the cipher context with appropriate parameters (e.g., AES-256-CBC)
    if (mode == 0) {
        if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) goto error;
    } else {
        if (!EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) goto error;
    }

    // Perform the encryption/decryption
    unsigned char ciphertext[length];
    int len;
    if (!EVP_EncryptUpdate(ctx, ciphertext, &len, message, length)) goto error;

    // Finalize the operation (if any remaining bytes)
    int final_len;
    if (!EVP_EncryptFinal_ex(ctx, ciphertext + len, &final_len)) goto error;

    // Clean up
    EVP_CIPHER_CTX_free(ctx);
    return ctx;

error:
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

int loadResourceBundle(const char* path, size_t* numItems) {
    FILE* file = fopen(path, "rb");
    if (!file) return -1; // File access error

    z_stream stream;
    memset(&stream, 0, sizeof(stream));
    stream.zalloc = Z_NULL;
    stream.zfree = Z_NULL;
    stream.opaque = Z_NULL;

    if (inflateInit2(&stream, 15 + 32) != Z_OK) {
        fclose(file);
        return -1; // Decompression error
    }

    // Read and decompress the file data
    unsigned char buffer[4096];
    int ret;
    while ((ret = fread(buffer, 1, sizeof(buffer), file)) > 0) {
        if (inflate(&stream, Z_FINISH) != Z_STREAM_END) {
            inflateEnd(&stream);
            fclose(file);
            return -1; // Decompression error
        }
    }

    *numItems = stream.total_out;
    fclose(file);
    return 0;
}
