package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"sync"
	"time"

	"github.com/redis/go-redis/v8"
)

var ctx = context.Background()

type Event struct {
	ID        string `json:"id"`
	Type      string `json:"type"`
	Payload   []byte `json:"payload"`
	Timestamp int64  `json:"timestamp"`
}

type Destination struct {
	URL    string
	Auth   string
	Retry  int
	Backoff time.Duration
}

var (
	subscriptions = make(map[string][]Destination)
	subMu       sync.Mutex
	eventStorage  *redis.Client
)

func init() {
	var err error
	eventStorage, err = redis.NewClient(&redis.Options{
		Addr:     "localhost:6379",
		Password: "", // no password set
		DB:       0,  // use default DB
	})
	if err != nil {
		log.Fatalf("Failed to connect to Redis: %v", err)
	}
}

func routeEvent(event Event) error {
	subMu.Lock()
	destinations, ok := subscriptions[event.Type]
	subMu.Unlock()

	if !ok {
		return fmt.Errorf("no destinations found for event type %s", event.Type)
	}

	var wg sync.WaitGroup
	for _, dest := range destinations {
		wg.Add(1)
		go func(dest Destination) {
			defer wg.Done()
			err := sendEventToDestination(event, dest)
			if err != nil {
				log.Printf("Failed to send event to %s: %v", dest.URL, err)
			}
		}(dest)
	}

	wg.Wait()
	return nil
}

func sendEventToDestination(event Event, dest Destination) error {
	var client http.Client
	req, err := http.NewRequestWithContext(ctx, "POST", dest.URL, bytes.NewBuffer(event.Payload))
	if err != nil {
		return err
	}

	req.Header.Set("Authorization", dest.Auth)
	req.Header.Set("Content-Type", "application/json")

	var resp *http.Response
	for i := 0; i < dest.Retry; i++ {
		resp, err = client.Do(req)
		if err == nil && resp.StatusCode == http.StatusOK {
			return nil
		}
		time.Sleep(dest.Backoff)
	}

	return fmt.Errorf("failed to send event after %d retries", dest.Retry)
}

func subscribe(eventType string, dest Destination) error {
	subMu.Lock()
	destinations := subscriptions[eventType]
	subscriptions[eventType] = append(destinations, dest)
	subMu.Unlock()

	return nil
}

func unsubscribe(eventType string, destURL string) error {
	subMu.Lock()
	destinations := subscriptions[eventType]
	newDestinations := make([]Destination, 0)
	for _, dest := range destinations {
		if dest.URL != destURL {
			newDestinations = append(newDestinations, dest)
		}
	}
	subscriptions[eventType] = newDestinations
	subMu.Unlock()

	return nil
}

func main() {
	// Example usage
	event := Event{
		ID:        "123",
		Type:      "user_registered",
		Payload:   json.RawMessage(`{"user_id": "456", "username": "john_doe"}`),
		Timestamp: time.Now().UnixNano(),
	}

	dest1 := Destination{URL: "http://example.com/events", Auth: "Bearer token1", Retry: 3, Backoff: time.Second}
	dest2 := Destination{URL: "http://another-example.com/events", Auth: "Bearer token2", Retry: 2, Backoff: 500 * time.Millisecond}

	subscribe("user_registered", dest1)
	subscribe("user_registered", dest2)

	err := routeEvent(event)
	if err != nil {
		log.Fatalf("Failed to route event: %v", err)
	}
}
