// Define a simple configuration structure
typedef struct {
    char *key;
    char *value;
} Config;

// Global configuration list
Config config_list[100];
int config_count = 0;

// Lock for thread-safe access to the configuration list
pthread_mutex_t config_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add a configuration key-value pair
void add_config(char *key, char *value) {
    pthread_mutex_lock(&config_lock);
    if (config_count < 100) {
        config_list[config_count].key = strdup(key);
        config_list[config_count].value = strdup(value);
        config_count++;
    }
    pthread_mutex_unlock(&config_lock);
}

// Function to get a configuration value by key
char* get_config(char *key) {
    pthread_mutex_lock(&config_lock);
    for (int i = 0; i < config_count; i++) {
        if (strcmp(config_list[i].key, key) == 0) {
            pthread_mutex_unlock(&config_lock);
            return strdup(config_list[i].value);
        }
    }
    pthread_mutex_unlock(&config_lock);
    return NULL;
}

// Function to initialize the configuration module
void init_config_module() {
    // Load initial configurations from a file or external source
    add_config("api_key", "abc123");
    add_config("db_url", "localhost:5432/mydb");
}

// Example usage of the C library
