import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.AsynchronousChannelGroup;
import java.nio.channels.AsynchronousSocketChannel;
import java.nio.channels.CompletionHandler;
import java.util.concurrent.Executors;

public class SecureDataConnection {

    private final AsynchronousSocketChannel channel;

    public SecureDataConnection(String host, int port) throws IOException {
        this.channel = AsynchronousSocketChannel.open(AsynchronousChannelGroup.withFixedThreadPool(Runtime.getRuntime().availableProcessors()));
        channel.connect(new InetSocketAddress(host, port), null, new CompletionHandler<Void, Void>() {
            @Override
            public void completed(Void result, Void attachment) {
                // Connection established
            }

            @Override
            public void failed(Throwable exc, Void attachment) {
                exc.printStackTrace();
            }
        });
    }

    public void sendData(byte[] data) throws IOException {
        ByteBuffer buffer = ByteBuffer.wrap(data);
        channel.write(buffer).get();
    }

    public byte[] receiveData() throws IOException {
        ByteBuffer buffer = ByteBuffer.allocate(1024);
        channel.read(buffer).get();
        return buffer.array();
    }

    public void close() throws IOException {
        channel.close();
    }
}
