// C++ Function to Manage Concurrent Session States

#include <unordered_map>
#include <mutex>

class SessionManager {
public:
    // Add a new session
    void addSession(const std::string& sessionId, const std::string& userInfo) {
        std::lock_guard<std::mutex> lock(mutex_);
        sessions_[sessionId] = userInfo;
    }

    // Remove an existing session
    bool removeSession(const std::string& sessionId) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (sessions_.find(sessionId) != sessions_.end()) {
            sessions_.erase(sessionId);
            return true;
        }
        return false;
    }

    // Retrieve user info from session
    std::optional<std::string> getSessionInfo(const std::string& sessionId) const {
        std::lock_guard<std::mutex> lock(mutex_);
        if (sessions_.find(sessionId) != sessions_.end()) {
            return sessions_.at(sessionId);
        }
        return std::nullopt;
    }

private:
    mutable std::mutex mutex_;
    std::unordered_map<std::string, std::string> sessions_;
};
```

