    trace::{self, TraceLayer},
    services::ServeDir,
};

pub mod config;
mod data_processor;
mod error_handling;
mod external_sources;
mod memory_profiler;
mod rate_limiter;
mod scheduler;

type SharedState = Arc<RwLock<data_processor::ProcessorState>>;

#[tokio::main]
async fn main() {
    // Initialize configuration and shared state
    let config = config::load_config();
    let shared_state = Arc::new(RwLock::new(data_processor::ProcessorState::new()));

    // Set up error handling and retry mechanisms
    let error_handler = error_handling::ErrorHandler::new();

    // Configure external sources
    let message_broker = external_sources::MessageBroker::new(&config.message_broker);
    let database = external_sources::Database::new(&config.database);
    let rest_api = external_sources::RestApi::new(&config.rest_api);

    // Create a custom, adaptive scheduler
    let scheduler = scheduler::AdaptiveScheduler::new();

    // Set up resource monitoring and control
    let memory_profiler = memory_profiler::MemoryProfiler::new();
    let rate_limiter = rate_limiter::RateLimiter::new(&config.rate_limit);

    // Create a service to handle data processing
    let data_processor_service = ServiceBuilder::new()
        .layer(LoadSheddingLayer)
        .layer(TraceLayer::new_for_http())
        .service_fn(move |req| {
            let shared_state = Arc::clone(&shared_state);
            async move {
                error_handler.handle(data_processor::process_data(
                    req,
                    Arc::clone(&message_broker),
                    Arc::clone(&database),
                    Arc::clone(&rest_api),
                    Arc::clone(&scheduler),
                    Arc::clone(&memory_profiler),
                    Arc::clone(&rate_limiter),
