<?php

class UserPasswordManager {
    private $db;
    private $cache;

    public function __construct($db, $cache) {
        $this->db = $db;
        $this->cache = $cache;
    }

    public function updatePassword($userId, $newPassword, $currentPassword, $twoFactorCode = null) {
        // Password strength validation
        if (!$this->validatePasswordStrength($newPassword)) {
            return ['status' => 'error', 'message' => 'Password must meet complexity criteria.'];
        }

        // Authenticate current password against external service
        if (!$this->authenticateCurrentPassword($userId, $currentPassword)) {
            return ['status' => 'error', 'message' => 'Invalid current password.'];
        }

        // Validate 2FA code if required
        if ($twoFactorCode !== null && !$this->validateTwoFactorCode($userId, $twoFactorCode)) {
            return ['status' => 'error', 'message' => 'Invalid 2FA code.'];
        }

        // Prepare and execute SQL to update password
        try {
            $stmt = $this->db->prepare('UPDATE users SET password = :password WHERE id = :id');
            $hashedPassword = password_hash($newPassword, PASSWORD_DEFAULT);
            $stmt->bindParam(':password', $hashedPassword);
            $stmt->bindParam(':id', $userId);
            $stmt->execute();

            // Invalidate cache for user data
            $this->cache->delete("user:$userId");

            return ['status' => 'success', 'message' => 'Password updated successfully.'];
        } catch (\Exception $e) {
            // Log error and retry mechanism
            error_log('Error updating password: ' . $e->getMessage());
            return ['status' => 'error', 'message' => 'Failed to update password, please try again later.'];
        }
    }

    private function validatePasswordStrength($password) {
        return preg_match('/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,}$/', $password) && !preg_match('/\b' . preg_quote($_SESSION['username'], '/') . '\b', $password);
    }

    private function authenticateCurrentPassword($userId, $currentPassword) {
        // Simulate external authentication service call
        $stmt = $this->db->prepare('SELECT password FROM users WHERE id = :id');
        $stmt->bindParam(':id', $userId);
        $stmt->execute();
        $user = $stmt->fetch();

        return password_verify($currentPassword, $user['password']);
    }

    private function validateTwoFactorCode($userId, $twoFactorCode) {
        // Simulate 2FA verification
        return $this->cache->get("2fa:$userId") == $twoFactorCode;
    }
}

// Usage example
$db = new PDO('mysql:host=localhost;dbname=example', 'user', 'password');
