#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define DataPacket structure
typedef struct {
    int packet_id;
    time_t timestamp;
    size_t data_size;
    char* data;
} DataPacket;

// Define the dynamic pool structure
typedef struct {
    DataPacket** packets;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DataPool;

// Initialize the data pool
void init_data_pool(DataPool* pool, size_t initial_capacity) {
    pool->packets = (DataPacket**)malloc(initial_capacity * sizeof(DataPacket*));
    pool->capacity = initial_capacity;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

// Add a data packet to the pool
void add_data_packet(DataPool* pool, DataPacket* packet) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count == pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        pool->packets = (DataPacket**)realloc(pool->packets, new_capacity * sizeof(DataPacket*));
        pool->capacity = new_capacity;
    }
    pool->packets[pool->count++] = packet;
    pthread_mutex_unlock(&pool->lock);
}

// Retrieve a data packet by ID
DataPacket* get_data_packet_by_id(DataPool* pool, int packet_id) {
    for (size_t i = 0; i < pool->count; ++i) {
        if (pool->packets[i]->packet_id == packet_id) {
            return pool->packets[i];
        }
    }
    return NULL;
}

// Clean up the data pool
void cleanup_data_pool(DataPool* pool) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->count; ++i) {
        free(pool->packets[i]->data);
        free(pool->packets[i]);
    }
    free(pool->packets);
    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
}

// Example usage
int main() {
    DataPool pool;
    init_data_pool(&pool, 10);

    // Simulate adding data packets
    for (int i = 0; i < 20; ++i) {
        DataPacket* packet = (DataPacket*)malloc(sizeof(DataPacket));
        packet->packet_id = i;
        packet->timestamp = time(NULL);
        packet->data_size = 1024 * i;
        packet->data = (char*)malloc(packet->data_size);
        add_data_packet(&pool, packet);
    }

    // Simulate retrieving a data packet
    DataPacket* retrieved_packet = get_data_packet_by_id(&pool, 5);
    if (retrieved_packet) {
        printf("Retrieved packet ID: %d\n", retrieved_packet->packet_id);
    } else {
        printf("Packet not found.\n");
    }

    cleanup_data_pool(&pool);
    return 0;
}
