import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class MetricsAggregator {
    private final ExecutorService executorService = Executors.newFixedThreadPool(10);
    private final MetricsStore metricsStore;
    private final AlertingSystem alertingSystem;
    private final DataIntegrationManager dataIntegrationManager;

    public MetricsAggregator(MetricsStore metricsStore, AlertingSystem alertingSystem, DataIntegrationManager dataIntegrationManager) {
        this.metricsStore = metricsStore;
        this.alertingSystem = alertingSystem;
        this.dataIntegrationManager = dataIntegrationManager;
    }

    public void processMetrics(MetricData metricData) {
        executorService.submit(() -> {
            try {
                metricsStore.store(metricData);
                if (shouldAlert(metricData)) {
                    alertingSystem.sendAlert(metricData);
                }
                dataIntegrationManager.processExternalIntegrations(metricData);
            } catch (Exception e) {
                // Handle exceptions, log errors, and retry or failover as needed
                e.printStackTrace();
            }
        });
    }

    private boolean shouldAlert(MetricData metricData) {
        return alertingSystem.evaluateThresholds(metricData);
    }

    public void shutdown() throws InterruptedException {
        executorService.shutdown();
        executorService.awaitTermination(1, TimeUnit.MINUTES);
    }

    // Additional methods for handling metrics, alerts, and external integrations can be added here
}

interface MetricsStore {
    void store(MetricData metricData) throws Exception;
}

interface AlertingSystem {
    boolean evaluateThresholds(MetricData metricData);
    void sendAlert(MetricData metricData);
}

interface DataIntegrationManager {
    void processExternalIntegrations(MetricData metricData);
}
```

