from concurrent.futures import ThreadPoolExecutor, as_completed
import requests

class RealtimeLogProcessor:
    def __init__(self, api_url, max_retries=5):
        self.api_url = api_url
        self.max_retries = max_retries
        self.executor = ThreadPoolExecutor(max_workers=10)

    def fetch_metadata(self, log_entry):
        for _ in range(self.max_retries):
            try:
                response = requests.get(f"{self.api_url}/{log_entry['id']}", timeout=2)
                if response.status_code == 200:
                    return response.json()
            except (requests.RequestException, ValueError) as e:
                print(f"Failed to fetch metadata for {log_entry['id']}: {e}")
        return None

    def process_log(self, log_entries):
        futures = [self.executor.submit(self.fetch_metadata, entry) for entry in log_entries]
        results = {}
        for future in as_completed(futures):
            log_entry, result = future.result()
            if result:
                results[log_entry['id']] = result
            else:
                print(f"Failed to process log entry: {log_entry}")
        return results

    def run(self, log_entries):
        processed_logs = self.process_log(log_entries)
        # Additional processing or storage logic here
        print("Processed logs:", processed_logs)

# Example usage
if __name__ == "__main__":
    api_url = "https://third-party-api.com/metadata"
    log_entries = [
        {"id": 1, "timestamp": "2023-04-01T12:00:00Z"},
        {"id": 2, "timestamp": "2023-04-01T12:01:00Z"}
    ]

    processor = RealtimeLogProcessor(api_url)
    processor.run(log_entries)
