from abc import ABC, abstractmethod
import time
import threading
import requests

class Cache(ABC):
    @abstractmethod
    def get(self, key: str) -> any:
        pass

    @abstractmethod
    def set(self, key: str, value: any, ttl: int = None) -> None:
        pass

    @abstractmethod
    def delete(self, key: str) -> None:
        pass

class DistributedCache(Cache):
    def __init__(self, nodes: list[str]):
        self.nodes = nodes
        self.cache = {}
        self.locks = {}

    def get(self, key: str) -> any:
        if key in self.cache:
            return self.cache[key]
        for node in self.nodes:
            try:
                response = requests.get(f"{node}/cache/{key}")
                if response.status_code == 200:
                    value = response.json()
                    self.set(key, value)
                    return value
            except requests.RequestException:
                pass
        raise KeyError(f"Key {key} not found in any node")

    def set(self, key: str, value: any, ttl: int = None) -> None:
        if key in self.cache:
            del self.cache[key]
        for node in self.nodes:
            try:
                requests.post(f"{node}/cache", json={"key": key, "value": value})
                break
            except requests.RequestException:
                continue

    def delete(self, key: str) -> None:
        if key in self.cache:
            del self.cache[key]
        for node in self.nodes:
            try:
                requests.delete(f"{node}/cache/{key}")
                break
            except requests.RequestException:
                continue

class RateLimiter:
    def __init__(self, max_requests: int, period: float):
        self.max_requests = max_requests
        self.period = period
        self.requests = []

    def allow_request(self) -> bool:
        current_time = time.time()
        self.requests = [req for req in self.requests if current_time - req < self.period]
        if len(self.requests) >= self.max_requests:
            return False
        self.requests.append(current_time)
        return True

class BackgroundTaskManager:
    def __init__(self):
        self.tasks = []

    def add_task(self, task: callable):
        thread = threading.Thread(target=task)
        thread.start()
        self.tasks.append(thread)

def cache_invalidation(task_manager: BackgroundTaskManager, cache: Cache, key: str) -> None:
    time.sleep(60)  # Invalidate the cache after 1 minute
    cache.delete(key)
    task_manager.add_task(lambda: print(f"Cache invalidated for {key}"))

# Example usage
cache_nodes = ["http://node1", "http://node2"]
cache = DistributedCache(cache_nodes)
rate_limiter = RateLimiter(max_requests=10, period=60)
task_manager = BackgroundTaskManager()

def fetch_data(key: str) -> any:
    if rate_limiter.allow_request():
        try:
            data = cache.get(key)
        except KeyError:
            data = retrieve_data_from_external_source(key)
            cache.set(key, data)
            task_manager.add_task(lambda: cache_invalidation(task_manager, cache, key))
        return data
    else:
        raise RateLimitError("Too many requests")

def retrieve_data_from_external_source(key: str) -> any:
    # Simulate fetching data from an external source
    time.sleep(1)  # Simulate network latency
    return {"key": key, "value": f"data for {key}"}

class RateLimitError(Exception):
    pass

