#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <chrono>
#include <thread>
#include <redis++.h>
#include <cpp_redis/cpp_redis>

class DynamicConfigManager {
private:
    cpp_redis::client redis_client;
    std::mutex cache_mutex;
    std::unordered_map<std::string, std::string> config_cache;
    std::condition_variable refresh_cv;
    std::atomic<bool> running{true};

public:
    DynamicConfigManager(const std::string& redis_host) {
        redis_client.connect(redis_host);
        load_config_from_redis();
        start_refresh_thread();
    }

    ~DynamicConfigManager() {
        running.store(false);
        refresh_cv.notify_all();
    }

    void set_config(const std::string& key, const std::string& value) {
        std::lock_guard<std::mutex> lock(cache_mutex);
        config_cache[key] = value;
        redis_client.set(key, value);
    }

    std::string get_config(const std::string& key) {
        std::lock_guard<std::mutex> lock(cache_mutex);
        auto it = config_cache.find(key);
        if (it != config_cache.end()) return it->second;
        cpp_redis::value val;
        redis_client.get(key, [&val](cpp_redis::client&, cpp_redis::reply& reply) {
            if (reply.is_string()) val = reply.as_string();
        });
        redis_client.sync_commit();
        if (!val.empty()) config_cache[key] = val;
        return val.empty() ? "" : val;
    }

private:
    void load_config_from_redis() {
        cpp_redis::value keys;
        redis_client.keys("*", [&keys](cpp_redis::client&, cpp_redis::reply& reply) {
            if (reply.is_string()) keys = reply.as_string();
        });
        for (const auto& key : keys.get_array()) {
            std::string config_key = key.str();
            cpp_redis::value value;
            redis_client.get(config_key, [&value](cpp_redis::client&, cpp_redis::reply& reply) {
                if (reply.is_string()) value = reply.as_string();
            });
            redis_client.sync_commit();
            std::lock_guard<std::mutex> lock(cache_mutex);
            config_cache[config_key] = value;
        }
    }

    void start_refresh_thread() {
        std::thread([this]() {
            while (running.load()) {
                cpp_redis::value keys;
                redis_client.keys("*", [&keys](cpp_redis::client&, cpp_redis::reply& reply) {
                    if (reply.is_string()) keys = reply.as_string();
                });
                for (const auto& key : keys.get_array()) {
                    std::string config_key = key.str();
                    cpp_redis::value value;
                    redis_client.get(config_key, [&value](cpp_redis::client&, cpp_redis::reply& reply) {
                        if (reply.is_string()) value = reply.as_string();
                    });
                    redis_client.sync_commit();
                    std::lock_guard<std::mutex> lock(cache_mutex);
                    config_cache[config_key] = value;
                }
                std::this_thread::sleep_for(std::chrono::seconds(60));
            }
        }).detach();
    }
};

int main() {
    DynamicConfigManager manager("localhost");
    manager.set_config("api_key", "12345");
    std::cout << "API Key: " << manager.get_config("api_key") << std::endl;
    return 0;
}
