public class AesDecryptionStrategy : IDecryptionStrategy
{
    public string Decrypt(string encryptedData, byte[] key, byte[] iv)
    {
        // Implement AES decryption logic here
        throw new NotImplementedException();
    }
}

public class DecryptionService
{
    private readonly ConcurrentDictionary<string, IDecryptionStrategy> _decryptionStrategies = 
        new ConcurrentDictionary<string, IDecryptionStrategy>();

    public DecryptionService()
    {
        _decryptionStrategies["TripleDES"] = new TripleDesDecryptionStrategy();
        _decryptionStrategies["AES"] = new AesDecryptionStrategy();
    }

    public string DecryptData(string encryptedData, string encryptionType, byte[] key, byte[] iv)
    {
        if (!_decryptionStrategies.TryGetValue(encryptionType, out var strategy))
        {
            throw new ArgumentException("Unsupported encryption type");
        }

        return strategy.Decrypt(encryptedData, key, iv);
    }
}

public class DataProcessor
{
    private readonly DecryptionService _decryptionService;

    public DataProcessor(DecryptionService decryptionService)
    {
        _decryptionService = decryptionService;
    }

    public async Task<int> ProcessDataAsync(string[] encryptedMessages, string encryptionType, byte[] key, byte[] iv)
    {
        var tasks = encryptedMessages.Select(async message =>
        {
            try
            {
                var decryptedData = _decryptionService.DecryptData(message, encryptionType, key, iv);
                var integerList = Convert.ToInt32(decryptedData.Split(',').Select(s => s.Trim()));
                return integerList.Max();
            }
            catch (Exception ex)
            {
                // Log the error and handle it gracefully
                Console.WriteLine($"Error processing message: {ex.Message}");
                return default(int); // Return a default value or rethrow the exception as needed
            }
        }).ToArray();

        var results = await Task.WhenAll(tasks);
        return results.Max();
    }
}

public class Program
{
    public static async Task Main(string[] args)
    {
        var decryptionService = new DecryptionService();
        var dataProcessor = new DataProcessor(decryptionService);

        string[] encryptedMessages = { "encryptedData1", "encryptedData2" };
        byte[] key = { /* Your encryption key here */ };
        byte[] iv = { /* Your initialization vector here */ };
        string encryptionType = "TripleDES"; // or "AES"

        int largestInteger = await dataProcessor.ProcessDataAsync(encryptedMessages, encryptionType, key, iv);
