// Transaction handling and processing
@RestController
@RequestMapping("/transactions")
public class TransactionController {

    @Autowired
    private PaymentGatewayService paymentGatewayService;

    @Autowired
    private FraudDetectionService fraudDetectionService;

    @Autowired
    private TransactionLoggingService transactionLoggingService;

    @PostMapping("/process")
    public ResponseEntity<String> processTransaction(@RequestBody TransactionRequest request) {
        try {
            if (fraudDetectionService.checkFraud(request.getTransaction())) {
                PaymentResponse paymentResponse = paymentGatewayService.processPayment(request);
                request.getTransaction().setStatus(paymentResponse.getStatus());
                transactionLoggingService.logTransaction(request.getTransaction());
                return ResponseEntity.ok("Transaction processed successfully");
            } else {
                request.getTransaction().setStatus(TransactionStatus.FRAUD_DETECTED);
                transactionLoggingService.logTransaction(request.getTransaction());
                return ResponseEntity.status(HttpStatus.PAYMENT_REQUIRED).body("Fraud detected. Transaction rejected.");
            }
        } catch (Exception e) {
            // Handle exceptions and implement retry logic
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body("Failed to process transaction");
        }
    }
}
