#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>

#define MAX_REQUESTS 1024

typedef struct {
    int request_id;
    char image_path[256];
    // Additional fields as needed
} ImageRequest;

ImageRequest request_queue[MAX_REQUESTS];
int front = -1, rear = -1;
sem_t queue_mutex, queue_not_full, queue_not_empty;

void* worker_thread(void* arg) {
    while (1) {
        sem_wait(&queue_not_empty);
        sem_wait(&queue_mutex);

        if (front == -1) {
            printf("Error: Queue is empty\n");
            return NULL;
        }

        ImageRequest request = request_queue[front];
        front = (front + 1) % MAX_REQUESTS;

        sem_post(&queue_mutex);
        sem_post(&queue_not_full);

        // Process image request
        process_image_request(request);

        printf("Processed request %d\n", request.request_id);
    }

    return NULL;
}

void enqueue_request(int request_id, const char* image_path) {
    sem_wait(&queue_not_full);
    sem_wait(&queue_mutex);

    if (front == -1 && rear == -1) {
        front = 0;
    }
    rear = (rear + 1) % MAX_REQUESTS;

    request_queue[rear].request_id = request_id;
    strcpy(request_queue[rear].image_path, image_path);

    sem_post(&queue_mutex);
    sem_post(&queue_not_empty);
}

void init_queue() {
    sem_init(&queue_mutex, 0, 1);
    sem_init(&queue_not_full, 0, MAX_REQUESTS);
    sem_init(&queue_not_empty, 0, 0);
}

int main() {
    pthread_t threads[10];
    int i;

    init_queue();

    for (i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, worker_thread, NULL);
    }

    // Enqueue requests
    enqueue_request(1, "image1.jpg");
    enqueue_request(2, "image2.png");

    for (i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
