// Service classes and functions
class FileCompressor {
public:
    void compress(const std::string& inputPath, const std::string& outputPath) {
        std::ifstream inFile(inputPath, std::ios::binary);
        std::ofstream outFile(outputPath, std::ios::binary);
        // Compression logic using zlib
    }
};

class HealthCheckHandler {
public:
    bool checkHealth() {
        // Check service health
        return true;
    }
};

// Service implementation
class FileCompressionService {
private:
    std::queue<std::pair<std::string, std::string>> taskQueue;
    std::vector<std::thread> workers;
    std::mutex queueMutex;
    std::condition_variable condition;
    bool stop;
    Logger logger;
    ConfigManager configManager;

public:
    FileCompressionService(size_t numThreads) : stop(false) {
        for (size_t i = 0; i < numThreads; ++i) {
            workers.emplace_back(&FileCompressionService::workerThread, this);
        }
    }

    ~FileCompressionService() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread& worker : workers) {
            worker.join();
        }
    }

    void submitTask(const std::string& inputPath, const std::string& outputPath) {
        std::unique_lock<std::mutex> lock(queueMutex);
        taskQueue.emplace(inputPath, outputPath);
        condition.notify_one();
    }

private:
    void workerThread() {
        while (true) {
            std::pair<std::string, std::string> task;
            {
                std::unique_lock<std::mutex> lock(queueMutex);
                condition.wait(lock, [this] { return stop || !taskQueue.empty(); });
                if (stop && taskQueue.empty()) {
                    return;
                }
                task = std::move(taskQueue.front());
                taskQueue.pop();
            }

            try {
                FileCompressor compressor;
                compressor.compress(task.first, task.second);
            } catch (const std::exception& e) {
                logger.log("Compression failed: " + std::string(e.what()));
            }
        }
    }
};

// Example usage
int main() {
    HealthCheckHandler healthCheck;
    if (!healthCheck.checkHealth()) {
        std::cerr << "Service is not healthy." << std::endl;
        return 1;
    }

    FileCompressionService service(10);
    for (size_t i = 0; i < 500; ++i) {
        std::string inputPath = "path/to/input/file" + std::to_string(i) + ".txt";
        std::string outputPath = "path/to/output/file" + std::to_string(i) + ".gz";
        service.submitTask(inputPath, outputPath);
    }

    return 0;
}
