import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;

public class EmployeeService {

    private final ConcurrentHashMap<String, Employee> cache = new ConcurrentHashMap<>();
    private final AsyncDataSource hrDataSource;
    private final AsyncDataSource analyticsDataSource;
    private final AsyncDataSource crmDataSource;

    public EmployeeService(AsyncDataSource hrDataSource, AsyncDataSource analyticsDataSource, AsyncDataSource crmDataSource) {
        this.hrDataSource = hrDataSource;
        this.analyticsDataSource = analyticsDataSource;
        this.crmDataSource = crmDataSource;
    }

    public CompletableFuture<Employee> getEmployee(String employeeId) {
        return cache.computeIfAbsent(employeeId, id -> 
            CompletableFuture.anyOf(
                hrDataSource.fetchEmployee(id),
                analyticsDataSource.fetchEmployee(id),
                crmDataSource.fetchEmployee(id)
            ).thenApply(employee -> {
                if (employee != null) {
                    cache.putIfAbsent(id, employee); // Update cache on successful fetch
                }
                return employee;
            }).exceptionally(ex -> {
                // Handle exceptions and fallback mechanisms
                System.err.println("Failed to fetch employee data: " + ex.getMessage());
                return null; // Return default or fallback value
            })
        );
    }

    public void updateEmployee(Employee updatedEmployee) {
        cache.put(updatedEmployee.getId(), updatedEmployee);
        CompletableFuture.allOf(
            hrDataSource.updateEmployee(updatedEmployee),
            analyticsDataSource.updateEmployee(updatedEmployee),
            crmDataSource.updateEmployee(updatedEmployee)
        ).exceptionally(ex -> {
            System.err.println("Failed to update employee data: " + ex.getMessage());
            return null;
        });
    }
}
