public ref class IoTLoggingLibrary {
private:
    cliext::vector<LogEntry^>^ primaryPool;
    cliext::vector<LogEntry^>^ secondaryPool;
    cliext::map<String^, DateTime>^ lruCache;
    int primaryPoolSize;
    int secondaryPoolSize;
    Object^ poolLock;

public:
    IoTLoggingLibrary(int initialPrimarySize, int initialSecondarySize) {
        primaryPool = gcnew cliext::vector<LogEntry^>(initialPrimarySize);
        secondaryPool = gcnew cliext::vector<LogEntry^>(initialSecondarySize);
        lruCache = gcnew cliext::map<String^, DateTime>();
        primaryPoolSize = initialPrimarySize;
        secondaryPoolSize = initialSecondarySize;
        poolLock = gcnew Object();
    }

    void Log(LogEntry^ entry) {
        lock (poolLock) {
            if (entry->IsCritical) {
                primaryPool->Add(entry);
            } else {
                secondaryPool->Add(entry);
            }
            lruCache[entry->Metadata] = DateTime::Now;
        }
    }

    Task<DataTableReader^>^ SendToDatabase(byte[] data, String^ connectionString, String^ procedureName) {
        return Task.Run(gcnew Action([=]() {
            // Simulate database operation
            Thread::Sleep(100); // Simulate network latency
            DataTable^ dataTable = gcnew DataTable();
            // Populate dataTable with results from stored procedure execution
            return dataTable.CreateDataReader();
        }));
    }
};

public ref class LogEntry {
public:
    String^ Metadata;
    bool IsCritical;

    LogEntry(String^ metadata, bool isCritical) {
        Metadata = metadata;
        IsCritical = isCritical;
    }
};
