from flask import Flask, request, jsonify
from flask_restful import Api, Resource
import requests
from retrying import retry
from concurrent.futures import ThreadPoolExecutor
import json

app = Flask(__name__)
api = Api(app)

# Payment Gateway Integration
@retry(stop_max_attempt_number=5, wait_exponential_multiplier=1000)
def process_payment(transaction_data):
    response = requests.post('https://payment-gateway.com/process', json=transaction_data)
    if response.status_code != 200:
        raise Exception("Payment processing failed")
    return response.json()

# CRM System Integration
executor = ThreadPoolExecutor(max_workers=10)

def update_crm(user_id, data):
    def worker():
        # Simulate async operation with backpressure control
        time.sleep(0.5)
        requests.post('https://crm-system.com/update', json={'user_id': user_id, 'data': data})
    executor.submit(worker)

# Machine Learning Model Integration
def get_recommendations(user_id):
    response = requests.get(f'https://ml-model.com/recommendations?user_id={user_id}')
    if response.status_code == 200:
        return response.json()
    else:
        return None

# Main API Resource
class OrderProcessor(Resource):
    def post(self):
        data = request.json
        user_id = data['user_id']
        transaction_data = {
            'amount': data['amount'],
            'currency': data['currency'],
            'card_details': data['card_details']
        }

        try:
            payment_response = process_payment(transaction_data)
            update_crm(user_id, {'last_purchase': payment_response})
            recommendations = get_recommendations(user_id)
        except Exception as e:
            return {'error': str(e)}, 500

        return {
            'payment_status': payment_response,
            'recommendations': recommendations
        }

api.add_resource(OrderProcessor, '/process_order')

if __name__ == '__main__':
    app.run(debug=True)
```

