#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>

#define MAX_CONCURRENT_ALLOCATIONS 10000
#define STRUCT_ALIGNMENT 64

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define the structure fields here
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct AllocationNode {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct AllocationNode* next;
} AllocationNode;

pthread_mutex_t allocation_lock = PTHREAD_MUTEX_INITIALIZER;
AllocationNode* free_list[MAX_CONCURRENT_ALLOCATIONS];

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu() {
    pthread_mutex_lock(&allocation_lock);
    if (free_list[0] == NULL) {
        // Handle allocation failure
        printf("Memory allocation failed\n");
        return NULL;
    }
    AllocationNode* node = free_list[0];
    free_list[0] = free_list[0]->next;
    pthread_mutex_unlock(&allocation_lock);
    return &node->pdu;
}

void deallocate_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    AllocationNode* node = (AllocationNode*)(((uintptr_t)pdu) - offsetof(AllocationNode, pdu));
    pthread_mutex_lock(&allocation_lock);
    node->next = free_list[0];
    free_list[0] = node;
    pthread_mutex_unlock(&allocation_lock);
}

void initialize_memory_pool() {
    for (int i = 0; i < MAX_CONCURRENT_ALLOCATIONS; i++) {
        AllocationNode* node = (AllocationNode*)malloc(STRUCT_ALIGNMENT + sizeof(AllocationNode));
        if (node == NULL) {
            // Handle allocation failure
            printf("Failed to allocate memory for memory pool\n");
            return;
        }
        node->next = free_list[0];
        free_list[0] = node;
    }
}

void cleanup_memory_pool() {
    pthread_mutex_lock(&allocation_lock);
    for (int i = 0; i < MAX_CONCURRENT_ALLOCATIONS; i++) {
        AllocationNode* node = free_list[i];
        while (node != NULL) {
            AllocationNode* next = node->next;
            free(node);
            node = next;
        }
        free_list[i] = NULL;
    }
    pthread_mutex_unlock(&allocation_lock);
}

// Example usage
int main() {
    initialize_memory_pool();

    NFAPI_CRC_INDICATION_PDU_T* pdu = allocate_pdu();
    if (pdu != NULL) {
        // Use the allocated PDU
        pdu->RX_UE_INFORMATION_TAG = 123;
        pdu->RNTI = 456;
        pdu->CRC_INDICATION_REL8_TAG = 'A';
        pdu->CRCFLAG = true;

        // Deallocate when done
        deallocate_pdu(pdu);
    }

    cleanup_memory_pool();
    return 0;
}
