#include <iostream>
#include <vector>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>

class DynamicMediaStreamingClient {
private:
    std::vector<std::thread> workerThreads;
    std::queue<int> taskQueue;
    std::mutex queueMutex;
    std::condition_variable conditionVariable;
    bool stop;

public:
    DynamicMediaStreamingClient(int numThreads) : stop(false) {
        for (int i = 0; i < numThreads; ++i) {
            workerThreads.emplace_back(&DynamicMediaStreamingClient::workerThread, this);
        }
    }

    ~DynamicMediaStreamingClient() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            stop = true;
        }
        conditionVariable.notify_all();
        for (auto& thread : workerThreads) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    void addTask(int taskID) {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            taskQueue.push(taskID);
        }
        conditionVariable.notify_one();
    }

private:
    void workerThread() {
        while (true) {
            int taskID;
            {
                std::unique_lock<std::mutex> lock(queueMutex);
                conditionVariable.wait(lock, [this] { return stop || !taskQueue.empty(); });
                if (stop && taskQueue.empty()) {
                    return;
                }
                taskID = taskQueue.front();
                taskQueue.pop();
            }
            // Process the task
            processTask(taskID);
        }
    }

    void processTask(int taskID) {
        std::cout << "Processing task: " << taskID << std::endl;
        // Simulate task processing time
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
    }
};

int main() {
    DynamicMediaStreamingClient client(4);
    for (int i = 0; i < 20; ++i) {
        client.addTask(i);
    }
    return 0;
}
```

This code defines a simple `DynamicMediaStreamingClient` class that manages worker threads to process tasks asynchronously. The `addTask` method adds tasks to a queue, and the worker threads pick up these tasks and process them. This setup demonstrates basic concurrency management, which can be extended to handle real-time streaming and other complex operations.']

