// Infrastructure Layer

@Component
@Scope("singleton")
public class MessageQueue implements Queue<String> {

    private final List<String> messages = new ArrayList<>();

    @Override
    public synchronized boolean add(String message) {
        return messages.add(message);
    }

    @Override
    public synchronized boolean offer(String message) {
        return messages.offer(message);
    }

    @Override
    public synchronized String remove() {
        if (messages.isEmpty()) {
            throw new NoSuchElementException();
        }
        return messages.remove(0);
    }

    @Override
    public synchronized String poll() {
        if (messages.isEmpty()) {
            return null;
        }
        return messages.remove(0);
    }

    @Override
    public synchronized String element() {
        if (messages.isEmpty()) {
            throw new NoSuchElementException();
        }
        return messages.get(0);
    }

    @Override
    public synchronized String peek() {
        if (messages.isEmpty()) {
            return null;
        }
        return messages.get(0);
    }

    @Override
    public int size() {
        return messages.size();
    }

    @Override
    public boolean isEmpty() {
        return messages.isEmpty();
    }

    @Override
    public Iterator<String> iterator() {
        return Collections.unmodifiableList(messages).iterator();
    }

    @Override
    public Object[] toArray() {
        return messages.toArray();
    }

    @Override
    public <T> T[] toArray(T[] a) {
        return messages.toArray(a);
    }
}
