    std::mutex cacheMutex;

public:
    void addToCache(const std::string& key, const std::shared_ptr<void>& value) {
        std::lock_guard<std::mutex> lock(cacheMutex);
        cache[key] = value;
    }

    std::shared_ptr<void> getFromCache(const std::string& key) {
        std::lock_guard<std::mutex> lock(cacheMutex);
        auto it = cache.find(key);
        if (it != cache.end()) {
            return it->second;
        }
        return nullptr;
    }
