                    if (cachedData == nullptr) {
                        handler->processRequest();
                        cachedData = std::make_shared<void>(/* result */);
                    }
                    cacheManager.addToCache(handler, cachedData);
                    success = true;
                } catch (...) {
                    attempts++;
                    std::this_thread::sleep_for(std::chrono::seconds(1));
                }
            }

            if (!success) {
