};

// FileProcessor class responsible for processing individual files
class FileProcessor {
public:
    explicit FileProcessor(FileCompressionService* parent)
        : parent(parent), compressionLevel(ConfigurationManager::getInstance().getCompressionLevel()) {}

    void operator()(const std::string& filePath) {
        try {
            std::ifstream file(filePath, std::ios::binary);
            if (!file.is_open()) {
                LoggingFramework::getInstance().log("Failed to open file: " + filePath);
                return;
            }

            // Read the file content
            std::vector<char> fileContent((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());
            file.close();

            // Compress the file content
            std::vector<unsigned char> compressedData(fileContent.size());
            uLongf compressedSize = compressedData.size();
            if (compress2(compressedData.data(), &compressedSize, fileContent.data(), fileContent.size(), compressionLevel) != Z_OK) {
                LoggingFramework::getInstance().log("Compression failed for file: " + filePath);
                return;
            }

            // Save the compressed data using FileManagementAPI
            FileManagementAPI::getInstance().saveFile(filePath + ".gz", compressedData.data(), compressedSize);

            LoggingFramework::getInstance().log("Successfully compressed and saved file: " + filePath);
        } catch (const std::exception& e) {
            LoggingFramework::getInstance().log("Exception in processing file " + filePath + ": " + std::string(e.what()));
        }
    }

private:
    FileCompressionService* parent;
    int compressionLevel;
};

// FileCompressionService class managing the service
class FileCompressionService {
public:
    static FileCompressionService& getInstance() {
        static FileCompressionService instance;
        return instance;
    }

    void addFileToQueue(const std::string& filePath) {
        std::unique_lock<std::mutex> lock(queueMutex);
        fileQueue.push(filePath);
        condition.notify_one();
    }

    void startProcessing() {
        for (int i = 0; i < numThreads; ++i) {
            workerThreads.emplace_back([this]() {
                while (true) {
                    std::string filePath;
                    {
                        std::unique_lock<std::mutex> lock(queueMutex);
                        condition.wait(lock, [this] { return !fileQueue.empty() || stopProcessing; });
                        if (stopProcessing && fileQueue.empty()) break;
                        filePath = fileQueue.front();
                        fileQueue.pop();
                    }

                    FileProcessor processor(this);
                    processor(filePath);
                }
            });
        }
    }

    void stopService() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            stopProcessing = true;
        }
        condition.notify_all();

        for (auto& thread : workerThreads) {
            if (thread.joinable()) thread.join();
        }
    }

private:
    FileCompressionService() : numThreads(5), stopProcessing(false) {}
    int numThreads;
    std::queue<std::string> fileQueue;
    std::vector<std::thread> workerThreads;
    std::mutex queueMutex;
    std::condition_variable condition;
};

int main() {
    // Initialize service
    FileCompressionService& service = FileCompressionService::getInstance();
    service.startProcessing();

    // Example usage: Add files to the processing queue
    service.addFileToQueue("path/to/largefile1.txt");
    service.addFileToQueue("path/to/largefile2.txt");

    // Wait for processing to complete (or handle other tasks)
    std::this_thread::sleep_for(std::chrono::minutes(5));

    // Stop the service
    service.stopService();

    return 0;
}
