import java.util.concurrent.ConcurrentHashMap;
import java.io.ByteArrayInputStream;
import java.io.ObjectInputStream;

public class DeserializationService {
    private final Map<String, Class<? extends SerializableClass>> classLoaderMap = new ConcurrentHashMap<>();
    private final List<String> allowedClasses;
    private final AuditLog auditLog;

    public DeserializationService(List<String> allowedClasses) {
        this.allowedClasses = allowedClasses;
        this.auditLog = new AuditLog();
    }

    public SerializableClass deserialize(byte[] input, String className) throws Exception {
        if (!allowedClasses.contains(className)) {
            throw new SecurityException("Deserialization of " + className + " is not allowed.");
        }

        Class<? extends SerializableClass> clazz = classLoaderMap.get(className);
        if (clazz == null) {
            clazz = loadClassFromExternalService(className);
            classLoaderMap.putIfAbsent(className, clazz);
        }

        ByteArrayInputStream bis = new ByteArrayInputStream(input);
        ObjectInputStream ois = new ObjectInputStream(bis);
        SerializableClass obj = (SerializableClass) ois.readObject();
        ois.close();

        auditLog.logDeserializationAttempt(className, true);

        return obj;
    }

    private Class<? extends SerializableClass> loadClassFromExternalService(String className) throws Exception {
        // Logic to fetch class from external metadata service
        // Return the loaded class
