// Asynchronous reduction function for financial transactions
async function reduceTransactions(transactions, initialBalance, callback) {
  const client = new FinancialApiClient();
  let accumulatedBalance = initialBalance;
  const batchSize = 50; // Batch size to minimize API calls
  const maxAttempts = 3; // Maximum number of retries for external operations

  for (let i = 0; i < transactions.length; i += batchSize) {
    const batch = transactions.slice(i, i + batchSize);
    const promises = batch.map(async (transaction) => {
      let attempt = 0;
      while (attempt < maxAttempts) {
        try {
          if (!await client.validateTransaction(transaction)) {
            throw new Error('Invalid transaction');
          }

          const accountInfo = await client.getAccountInfo(transaction.accountId);
          accumulatedBalance = callback(accumulatedBalance, transaction);

          console.log(`Processed transaction: ${JSON.stringify(transaction)}, New balance: ${accumulatedBalance}`);
          return { transaction, newBalance: accumulatedBalance };
        } catch (error) {
          attempt++;
          if (attempt === maxAttempts) throw error;
          await new Promise(resolve => setTimeout(resolve, 1000)); // Throttle retries
        }
      }
    });

    const results = await Promise.all(promises);
    console.log(`Batch ${Math.floor(i / batchSize) + 1} completed`);
  }

  return accumulatedBalance;
}

