  { accountId: '123', amount: 50 },
  { accountId: '456', amount: -20 },
  // Add more transactions as needed
];

reduceTransactions(transactions, 0, (acc, transaction) => acc + transaction.amount)
  .then(finalBalance => console.log(`Final balance: ${finalBalance}`))
