class RealTimeMarketDataAggregator {
public:
    RealTimeMarketDataAggregator(size_t numThreads = std::thread::hardware_concurrency())
        : stop(false), threads(numThreads) {
        for (size_t i = 0; i < numThreads; ++i) {
            threads[i] = std::thread(&RealTimeMarketDataAggregator::worker, this);
        }
    }

    ~RealTimeMarketDataAggregator() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stop = true;
        }
        condition.notify_all();
        for (auto& thread : threads) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    template <typename Data>
    void pushData(Data&& data) {
        std::unique_lock<std::mutex> lock(mutex);
        queue.push(std::forward<Data>(data));
        condition.notify_one();
    }

private:
    void worker() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            condition.wait(lock, [this] { return stop || !queue.empty(); });
            if (stop && queue.empty()) {
                break;
            }
            auto data = std::move(queue.front());
            queue.pop();
            lock.unlock();

            process(data);
        }
    }

    void process(const std::string& data) {
        // Placeholder for data processing logic
        std::cout << "Processing data: " << data << std::endl;
    }

    std::mutex mutex;
    std::condition_variable condition;
    std::queue<std::string> queue;
    bool stop;
    std::vector<std::thread> threads;
};

int main() {
