#define MAX_THREADS 100
#define BATCH_SIZE 10

typedef struct {
    char* image_data;
    int size;
    pthread_mutex_t lock;
} ImageData;

ImageData images[BATCH_SIZE];

void* process_image(void* arg) {
    int index = *(int*)arg;
    if (images[index].size > 0) {
        pthread_mutex_lock(&images[index].lock);
        // Simulate image processing
        printf("Processing image %d\n", index);
        sleep(1); // Simulate time-consuming operation
        pthread_mutex_unlock(&images[index].lock);
    }
    return NULL;
}

void submit_batch(int* batch) {
    int num_images = 0;
    while (batch[num_images] != -1 && num_images < BATCH_SIZE) {
        pthread_t thread_id[MAX_THREADS];
        for (int i = 0; i < MAX_THREADS && batch[i] != -1; i++) {
            if (pthread_create(&thread_id[i], NULL, process_image, &batch[i]) == 0) {
                pthread_detach(thread_id[i]);
            }
        }
        for (int i = 0; i < MAX_THREADS && batch[i] != -1; i++) {
            pthread_join(thread_id[i], NULL);
        }
        num_images++;
    }
}

int main() {
    int batch[BATCH_SIZE + 1];
    batch[0] = 0;
    batch[1] = 1;
    batch[2] = 2;
    batch[3] = -1; // End of batch marker
    submit_batch(batch);
    return 0;
}
