typedef struct {
    uuid_t id;
    char *data;
    size_t size;
} Record;

// Function to create a new record
Record* record_create(const void *data, size_t size) {
    Record *rec = (Record*)malloc(sizeof(Record));
    if (rec == NULL) return NULL;

    uuid_generate(rec->id);
    rec->data = malloc(size);
    if (rec->data == NULL) {
        free(rec);
        return NULL;
    }
    memcpy(rec->data, data, size);
    rec->size = size;
    return rec;
}

// Function to free a record
void record_free(Record *rec) {
    if (rec != NULL) {
        free(rec->data);
        free(rec);
    }
}

// Function to store a record in a database
int record_store(Record *rec, const char *database) {
    // Implementation of database storage logic here
    printf("Storing record with UUID: %s in database: %s\n", uuid_unparse_lower(rec->id), database);
    return 0;
}

