// Custom buffer pool for efficient data handling
class BufferPool {
public:
    BufferPool(size_t bufferSize, size_t poolSize)
        : bufferSize(bufferSize), poolSize(poolSize), buffers(poolSize, new char[bufferSize]) {}

    ~BufferPool() {
        for (auto& buffer : buffers) {
            delete[] buffer;
        }
    }

    char* getBuffer() {
        std::lock_guard<std::mutex> lock(mutex);
        if (!pool.empty()) {
            auto buffer = pool.back();
            pool.pop_back();
            return buffer;
        } else {
            throw std::runtime_error("No available buffers");
        }
    }

    void releaseBuffer(char* buffer) {
        std::lock_guard<std::mutex> lock(mutex);
        if (pool.size() < poolSize) {
            pool.push_back(buffer);
        } else {
            delete[] buffer;
        }
    }

private:
    size_t bufferSize;
    size_t poolSize;
    std::vector<char*> buffers;
    std::mutex mutex;
};

