class ChannelProcessor {
public:
    void addLogicalChannelGroup(const LogicalChannelGroup& group) {
        std::lock_guard<std::mutex> lock(mutex_);
        channelGroups_.push_back(group);
    }

    void processLogEntries(std::function<void(const LogEntryT&)> callback) {
        std::unique_lock<std::mutex> lock(mutex_);
        cv_.wait(lock, [this] { return !logEntries_.empty(); });

        while (!logEntries_.empty()) {
            auto entry = logEntries_.front();
            logEntries_.pop_front();
            lock.unlock();
            callback(entry);
            lock.lock();
        }
    }

    void addLogEntry(const LogEntryT& entry) {
        std::lock_guard<std::mutex> lock(mutex_);
        logEntries_.push_back(entry);
        cv_.notify_one();
    }

private:
