// Define necessary headers and structures
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct DoublyLinkedListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct DoublyLinkedListNode* prev;
    struct DoublyLinkedListNode* next;
} DoublyLinkedListNode;

typedef struct DoublyLinkedList {
    DoublyLinkedListNode* head;
    DoublyLinkedListNode* tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

// Initialize the doubly linked list
void initDoublyLinkedList(DoublyLinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Add a new node to the doubly linked list
void addNode(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    DoublyLinkedListNode* newNode = (DoublyLinkedListNode*)malloc(sizeof(DoublyLinkedListNode));
    if (!newNode) {
        // Handle memory allocation failure
        return;
    }
    newNode->data = data;
    newNode->prev = list->tail;
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->tail != NULL) {
        list->tail->next = newNode;
    } else {
        list->head = newNode;
    }
    list->tail = newNode;
    pthread_mutex_unlock(&list->lock);
}

// Remove a node from the doubly linked list
void removeNode(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    DoublyLinkedListNode* current = list->head;
    while (current != NULL) {
        if (current->data == data) {
            if (current->prev != NULL) {
                current->prev->next = current->next;
            } else {
                list->head = current->next;
            }
            if (current->next != NULL) {
                current->next->prev = current->prev;
            } else {
                list->tail = current->prev;
            }
            free(current);
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

// Clean up the doubly linked list
void cleanupDoublyLinkedList(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);
    DoublyLinkedListNode* current = list->head;
    while (current != NULL) {
        DoublyLinkedListNode* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_unlock(&list->lock);
}
