using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Polly;
using Polly.Retry;

public class Startup
{
    public Startup(IConfiguration configuration)
    {
        Configuration = configuration;
    }

    public IConfiguration Configuration { get; }

    public void ConfigureServices(IServiceCollection services)
    {
        // Add services to the container.
        services.AddControllers();

        // Configure dependency injection for payment gateways and fraud detection services.
        services.AddTransient<IPaymentGateway, PayPalPaymentGateway>();
        services.AddTransient<IFraudDetectionService, Fraud DetectionService>();

        // Configure dynamic rate-limiting
        var retryPolicy = Policy.Handle<Exception>().RetryAsync(3);
        services.AddSingleton(retryPolicy);

        // Configure OAuth 2.0, JWT, and SAML for authentication.
        services.AddAuthentication(options =>
        {
            options.DefaultAuthenticateScheme = "Bearer";
            options.DefaultChallengeScheme = "Bearer";
        }).AddJwtBearer(options =>
        {
            options.Authority = "https://your-auth-server.com";
            options.Audience = "secure-payment-processing-hub";
        });

        // Configure role-based access control
        services.AddAuthorization(options =>
        {
            options.AddPolicy("MerchantTierAccess", policy => policy.RequireClaim("MerchantTier"));
        });
    }

    public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
    {
        if (env.IsDevelopment())
        {
            app.UseDeveloperExceptionPage();
        }

        app.UseRouting();

        app.UseAuthentication();
        app.UseAuthorization();

        app.UseEndpoints(endpoints =>
        {
            endpoints.MapControllers();
        });
    }
}
