class NetworkDataHandler {
private:
    std::mutex mutex_;
    std::condition_variable cv_;
    size_t capacity_;
    size_t currentSize_;

public:
    NetworkDataHandler(size_t initialCapacity, size_t maxCapacity)
        : capacity_(initialCapacity), currentSize_(0) {}

    bool addNetworkData(const std::string& dataStream, size_t maxSizeLimit, int connectionHandle) {
        std::unique_lock<std::mutex> lock(mutex_);
        cv_.wait(lock, [this] { return currentSize_ < capacity_; });

        if (currentSize_ + dataStream.size() > capacity_) {
            return false;
        }

        NetworkDataProcessor::ErrorCode errorCode = NetworkDataProcessor::processNetworkData(dataStream, maxSizeLimit, connectionHandle);
        if (errorCode == NetworkDataProcessor::NO_ERROR) {
            currentSize_ += dataStream.size();
            AnalyticsEngineClient::addEntity("entityId", "entityData");
        }

        return true;
    }
};
