import json

class JsonParser:
    class Registry:
        factories = {}

        @staticmethod
        def register_factory(id, factory):
            JsonParser.Registry.factories[id] = factory

        @staticmethod
        def create_instance(id, *args, **kwargs):
            factory = JsonParser.Registry.factories.get(id)
            if factory:
                return factory(*args, **kwargs)
            else:
                raise ValueError(f"Factory for ID {id} not found")

    class BaseJsonClass:
        def to_json(self):
            pass

        @classmethod
        def from_json(cls, json_str):
            data = json.loads(json_str)
            return cls(**data)

    def __init__(self, json_str):
        self.data = json.loads(json_str)

    def to_json_string(self) -> str:
        return json.dumps(self.data)

    @staticmethod
    def register_subclass(id, subclass):
        JsonParser.Registry.register_factory(id, subclass.from_json)
