#define MAX_USERS 1000000

typedef struct {
    RX_UE_INFORMATION_TAG ue_tag;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *pdus[MAX_USERS];
pthread_mutex_t pdu_locks[MAX_USERS];

void initialize_pdus() {
    for (int i = 0; i < MAX_USERS; ++i) {
        pdus[i] = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pthread_mutex_init(&pdu_locks[i], NULL);
    }
}

void populate_pdu(int user_id, RX_UE_INFORMATION_TAG ue_tag, uint16_t RNTI) {
    pthread_mutex_lock(&pdu_locks[user_id]);
    pdus[user_id]->ue_tag = ue_tag;
    pdus[user_id]->RNTI = RNTI;
    pdus[user_id]->crc_indication.crcflag = (rand() % 2) == 0 ? 1 : 0; // Randomly set CRCFLAG
    pthread_mutex_unlock(&pdu_locks[user_id]);
}

void *user_thread(void *arg) {
    int user_id = *(int *)arg;
    RX_UE_INFORMATION_TAG ue_tag = /* initialize UE tag */;
    uint16_t RNTI = /* initialize RNTI */;

    populate_pdu(user_id, ue_tag, RNTI);

    return NULL;
}

void cleanup_pdus() {
    for (int i = 0; i < MAX_USERS; ++i) {
        free(pdus[i]);
        pthread_mutex_destroy(&pdu_locks[i]);
    }
}

int main() {
    srand(time(NULL));
    initialize_pdus();

    pthread_t threads[MAX_USERS];
    int user_ids[MAX_USERS];

    for (int i = 0; i < MAX_USERS; ++i) {
        user_ids[i] = i;
        pthread_create(&threads[i], NULL, user_thread, &user_ids[i]);
    }

    for (int i = 0; i < MAX_USERS; ++i) {
        pthread_join(threads[i], NULL);
    }

    cleanup_pdus();
    return 0;
}
