#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <atomic>
#include <functional>

// Forward declaration for clarity
class SensorData;

// Component: AsyncProcessor
class AsyncProcessor {
public:
    AsyncProcessor(size_t numThreads) : stop(false), workerCount(numThreads) {
        for (size_t i = 0; i < numThreads; ++i) {
            workers.emplace_back([this] {
                while (true) {
                    std::function<void(SensorData)> task;
                    {
                        std::unique_lock<std::mutex> lock(queueMutex);
                        condition.wait(lock, [this] { return stop || !tasks.empty(); });
                        if (stop && tasks.empty()) {
                            return;
                        }
                        task = std::move(tasks.front());
                        tasks.pop();
                    }
                    task(SensorData()); // Process the data
                }
            });
        }
    }

    ~AsyncProcessor() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread& worker : workers) {
            worker.join();
        }
    }

    void addTask(const std::function<void(SensorData)>& task) {
        {
            std::lock_guard<std::mutex> lock(queueMutex);
            tasks.push(task);
        }
        condition.notify_one();
    }

private:
    std::vector<std::thread> workers;
    std::queue<std::function<void(SensorData)>> tasks;
    std::mutex queueMutex;
    std::condition_variable condition;
    bool stop;
    size_t workerCount;
};

