import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class AdaptiveCacheManager {
    private final ConcurrentHashMap<String, CacheEntry> cache = new ConcurrentHashMap<>();
    private final AtomicInteger hitCount = new AtomicInteger();
    private final AtomicInteger missCount = new AtomicInteger();

    public Object get(String key) {
        if (cache.containsKey(key)) {
            CacheEntry entry = cache.get(key);
            synchronized (entry.lock) {
                if (!entry.expired()) {
                    hitCount.incrementAndGet();
                    return entry.value;
                }
            }
        }
        missCount.incrementAndGet();
        // Fetch data from primary source and update cache
        Object value = fetchDataFromPrimarySource(key);
        put(key, value);
        return value;
    }

    public void put(String key, Object value) {
        CacheEntry entry = new CacheEntry(value);
        cache.put(key, entry);
    }

    public void remove(String key) {
        cache.remove(key);
    }

    public int getHitCount() {
        return hitCount.get();
    }

    public int getMissCount() {
        return missCount.get();
    }

    private Object fetchDataFromPrimarySource(String key) {
        // Implementation to fetch data from primary source
        return null;
    }

    private static class CacheEntry {
        final Object value;
        final long expiryTime;
        final Object lock = new Object();

        CacheEntry(Object value) {
            this.value = value;
            this.expiryTime = System.currentTimeMillis() + 60000; // 1 minute expiration
        }

        boolean expired() {
            return System.currentTimeMillis() > expiryTime;
        }
    }
}
