public:
    template <typename Func>
    bool retry(Func func, int maxRetries = 5, int initialDelay = 100) const {
        for (int i = 0; i <= maxRetries; ++i) {
            try {
                func();
                return true;
            } catch (...) {
                if (i == maxRetries) throw;
                std::this_thread::sleep_for(std::chrono::milliseconds(initialDelay * (1 << i)));
            }
        }
        return false;
    }
};

