app.use(rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
}));

// Circuit breaker setup for financial exchange API
const circuitBreaker = new CircuitBreaker(axios.get, {
  timeout: 50,
  errorThresholdPercentage: 20,
  resetTimeout: 30 * 1000 // 30 seconds
});

circuitBreaker.on('success', () => console.log('API call succeeded'));
circuitBreaker.on('failure', () => console.log('API call failed'));
circuitBreaker.on('timeout', () => console.log('API call timed out'));
circuitBreaker.on('open', () => console.log('Circuit breaker opened'));
circuitBreaker.on('halfOpen', () => console.log('Circuit breaker half-open'));

// Route to process financial market data
app.get('/process-data', async (req, res) => {
  try {
    const exchangeData = await circuitBreaker.fire('https://api.exchange.com/data');
    const externalData = await axios.get('https://external-api.com/data');

    // Aggregate and validate data
    const aggregatedData = aggregateData(exchangeData.data, externalData.data);
    if (!validateData(aggregatedData)) {
      return res.status(400).json({ error: 'Invalid data' });
    }

    // Store in Elasticsearch
    await client.index({
      index: 'financial-data',
      body: aggregatedData
    });

    // Log and monitor performance metrics
    logPerformanceMetrics();

    res.json({ message: 'Data processed successfully', data: aggregatedData });
  } catch (error) {
    console.error('Error processing data:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

