// C++ Application Framework

#include <iostream>
#include <memory>

class IdentityProvider {
public:
    virtual bool authenticate(const std::string& user, const std::string& password) = 0;
};

class LDAPDirectory {
public:
    virtual bool validateUser(const std::string& user) = 0;
};

class APiGateway {
public:
    virtual void forwardRequest(const std::string& request) = 0;
};

class UserAuthenticator {
private:
    std::vector<std::unique_ptr<IdentityProvider>> providers;
    std::vector<std::unique_ptr<LDAPDirectory>> directories;
    std::vector<std::unique_ptr<APiGateway>> gateways;

public:
    void addProvider(std::unique_ptr<IdentityProvider> provider) {
        providers.push_back(move(provider));
    }

    void addDirectory(std::unique_ptr<LDAPDirectory> directory) {
        directories.push_back(move(directory));
    }

    void addGateway(std::unique_ptr<APiGateway> gateway) {
        gateways.push_back(move(gateway));
    }

    bool authenticateUser(const std::string& user, const std::string& password) {
        for (auto& provider : providers) {
            if (provider->authenticate(user, password)) return true;
        }
        return false;
    }

    void authorizeUser(const std::string& user) {
        for (auto& directory : directories) {
            if (!directory->validateUser(user)) {
                // Handle authorization failure
                break;
            }
        }
    }

    void forwardAuthRequest(const std::string& request) {
        for (auto& gateway : gateways) {
            gateway->forwardRequest(request);
        }
    }
};

int main() {
    UserAuthenticator authSystem;

    // Add providers, directories, and gateways
    authSystem.addProvider(make_unique<IdentityProvider>());
    authSystem.addDirectory(make_unique<LDAPDirectory>());
    authSystem.addGateway(make_unique<APiGateway>());

    // Perform authentication and authorization
    bool isAuthenticated = authSystem.authenticateUser("user", "password");
    if (isAuthenticated) {
        authSystem.authorizeUser("user");
        authSystem.forwardAuthRequest("auth_request");
    }

    return 0;
}
