    void startProcessing() {
        processingThread = std::thread(&SensorDataProcessor::processData, this);
    }

    void stopProcessing() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            running = false;
        }
        condition.notify_all();
        processingThread.join();
    }

    void addData(const std::string& data) {
        {
            std::lock_guard<std::mutex> lock(mutex);
            dataQueue.push(data);
        }
        condition.notify_one();
    }

private:
    void processData() {
        while (true) {
            std::string data;
            {
                std::unique_lock<std::mutex> lock(mutex);
                condition.wait(lock, [this] { return !dataQueue.empty() || !running; });
                if (!running && dataQueue.empty()) break;
                data = dataQueue.front();
                dataQueue.pop();
            }
            computeMD5(data);
        }
    }

    void computeMD5(const std::string& data) {
        unsigned char hash[MD5_DIGEST_LENGTH];
        MD5_CTX md5;
        MD5_Init(&md5);
        MD5_Update(&md5, data.c_str(), data.length());
        MD5_Final(hash, &md5);

        // Convert hash to hex string
        std::stringstream ss;
        for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
            ss << std::hex << std::setw(2) << std::setfill('0') << static_cast<int>(hash[i]);
        }

