// Node.js Service Code Block

const express = require('express');
const bodyParser = require('body-parser');
const crypto = require('crypto');

const app = express();
app.use(bodyParser.json());

app.post('/aggregate', (req, res) => {
    const data = req.body.data;

    if (!data || !Array.isArray(data)) {
        return res.status(400).json({ error: 'Invalid input' });
    }

    let sum = 0;
    for (const num of data) {
        if (typeof num !== 'number') {
            return res.status(400).json({ error: 'Non-numeric value found in array' });
        }
        sum += num;
    }

    res.json({ result: sum, executionTime: process.hrtime.bigint(), memoryUsage: process.memoryUsage() });
});

app.listen(3000, () => {
    console.log('Node.js service is running on port 3000');
});
