package main

import (
    "fmt"
    "sync"
)

type ForwardList struct {
    mu      sync.RWMutex
    elements []string
}

func (fl *ForwardList) insertAfterOrLog(target, newElement string, logFunc func(error)) {
    fl.mu.Lock()
    defer fl.mu.Unlock()

    for i := 0; i < len(fl.elements); i++ {
        if fl.elements[i] == target {
            fl.elements = append(fl.elements[:i+1], append([]string{newElement}, fl.elements[i+1:]...)...)
            return
        }
    }

    fl.elements = append(fl.elements, newElement)
}

func main() {
    list := &ForwardList{}
    list.insertAfterOrLog("example", "inserted", func(err error) {
        if err != nil {
            fmt.Println("Error logging insertion:", err)
        }
    })

    for _, element := range list.elements {
        fmt.Println(element)
    }
}
