    NFAPI_CRC_INDICATION_PDU_T(RX_UE_INFORMATION_TAG info, RNTI rnti, CRC_INDICATION_REL8_TAG crc) 
        : rxUeInfo(info), rnti(rnti), crcIndicationRel8(crc) {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, 1);
