    std::mutex mtx;
    std::condition_variable cv;
    int maxPduCount;

public:
    DynamicMediaStreamingClient(int initialCapacity) : maxPduCount(initialCapacity), pduList(maxPduCount) {
        // Initialize the linked list with default values
        for (auto& pdu : pduList) {
            pdu = NFAPI_CRC_INDICATION_PDU_T(RX_UE_INFORMATION_TAG(), RNTI(), CRC_INDICATION_REL8_TAG());
        }
