class MultimediaDatasetManager {
public:
    void addProvider(CloudStorageProvider* provider) { providers.push_back(provider); }
    void fetchMetadata(const std::string& assetId) {
        for (auto& provider : providers) {
            provider->fetchMetadata(assetId);
        }
    }
    void preprocessAsset(const std::string& assetId) {
        for (auto& provider : providers) {
            provider->preprocessAsset(assetId);
        }
    }
    void storeThumbnail(const std::string& assetId, const std::string& thumbnailData) {
        for (auto& provider : providers) {
            provider->storeThumbnail(assetId, thumbnailData);
        }
    }
    void handleBatchRequest(const std::vector<std::string>& assetIds) {
        for (auto& provider : providers) {
            provider->handleBatchRequest(assetIds);
        }
    }
    void handleRealTimeRequest(const std::string& assetId) {
        for (auto& provider : providers) {
            provider->handleRealTimeRequest(assetId);
        }
    }

private:
    std::vector<CloudStorageProvider*> providers;
};

int main() {
